import { PineconeActivityRecord } from './activities-knowledge';

export const SCRAPED_ACTIVITIES: PineconeActivityRecord[] = [
  {"id":"scraped-altcir-handbook-vocabulary-intro-001","text":"This activity introduces new vocabulary to students. Begin by selecting vocabulary words relevant to your lesson. Prepare picture cards or use gestures to represent each word. Introduce the words one at a time, showing the picture card or demonstrating the gesture, and clearly pronouncing the word. Encourage students to repeat the word after you. Repeat the word multiple times. This activity focuses on spoken English and does not include reading or writing. Target grade levels are 5-7. Materials needed: picture cards or gestures. Classroom tip: Keep it short and energetic.","content_type":"activity","name":"Vocabulary Intro","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Picture cards","Gestures"],"topic_tags":["Vocabulary","Speaking","Elementary"]},
  {"id":"scraped-altcir-handbook-singing-and-role-play-002","text":"This activity combines singing with role-playing to reinforce language learning. First, teach a song a cappella, encouraging students to repeat the lyrics. Once they're comfortable, play the music and sing along. This builds anticipation. Next, incorporate drama by having students role-play scenarios. For example, if teaching \"How much is...?\", set up a mock shop and have students act out buying and selling. Elementary students are often less inhibited, so embrace this. The key is to make it fun and engaging, using games and incorporating Japanese pop culture references to increase student motivation and provide context to their learning. This aims to get kids excited and practicing target language through fun and interactive activities.\n\nTips:\n*   Adapt the role-play to match the lesson's target language (e.g., shopping scenario for price vocabulary).\n*   Use visual aids to help students.\n*   Encourage participation, and praise efforts.\n*   Introduce the \"Losing doesn't mean losing\" concept to foster a positive attitude.","content_type":"activity","name":"Singing and Role Play","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Music (song)","Props for role-play (e.g., toy money, shop items)"],"topic_tags":["songs","role-play","vocabulary","games"]},
  {"id":"scraped-altcir-handbook-number-grouping-003","text":"This is a fun, active warm-up game for practicing numbers and encouraging teamwork. Students run in a circle in the gym. The teacher calls out a number (e.g., \"Five!\"). Students must quickly form groups of that many people. The first group to successfully gather and sit down wins the round. The game continues with different numbers called out. This targets listening comprehension and speaking, as students must understand the number and communicate with each other to form groups. It's suitable for elementary school grades, especially after teaching numbers. No materials are needed, just an open space. Be sure to vary the numbers to keep it challenging and to monitor student safety. Encourage them to shout out the number in English to practice speaking and build confidence. It can also be adapted to include other instructions such as colors or shapes. The teacher can use this to gauge how well the students can work in groups.","content_type":"activity","name":"Number Grouping","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["numbers","games","teamwork"]},
  {"id":"scraped-altcir-handbook-quick-question-race-004","text":"Divide the class into two teams and have them line up. The ALT asks a question to the first student in each line. The first student to answer correctly gets to sit down. The other student goes to the back of their team's line. Continue asking questions rapidly to maintain momentum. The first team where all members are sitting down wins! Questions can be simple and repetitive to help with vocabulary reinforcement and pronunciation. Examples include: \"What's your name?\", \"How old are you?\", \"What's this?\" (pointing to objects), \"What color is this?\" (pointing to colors). Focus on quick recall. This activity targets speaking and listening skills, suitable for elementary and junior high students to practice basic greetings, numbers, colors, and objects. The only material required is a clear space in the classroom. Classroom tip: Vary question difficulty slightly to cater to different levels. Also, provide positive reinforcement.","content_type":"activity","name":"Quick Question Race","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":[],"topic_tags":["Q&A","Vocabulary","Speaking Practice"]},
  {"id":"scraped-altcir-handbook-body-parts-dice-game-005","text":"Before starting, ensure students remember body parts vocabulary. The teacher throws an inflatable die. On each side of the die write a body part (head, shoulders, knees, toes, eyes, ears, etc.).\n\n1.  Teacher throws the die and asks 'What is it?'. Students chorus the body part shown on the die.\n2.  The teacher calls out a command, such as 'Touch your...' and the students follow the command, touching the appropriate body part.\n3.  For a challenge, students can be divided into teams for a point-scoring system. One point per student or team for the correct answer, repeated multiple times. Or, the teacher calls out a body part at random, and students race to touch the correct body part. The first one to do so gets a point.\n\nThis game reinforces body parts vocabulary, listening comprehension, and improves student-teacher interaction. It's best suited for Elementary grades.","content_type":"activity","name":"Body Parts Dice Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":2,"interaction":"Whole class","materials":["Inflatable dice","Optional: Whiteboard/Chalkboard"],"topic_tags":["Body Parts","Vocabulary","Song Reinforcement"]},
  {"id":"scraped-altcir-handbook-build-a-monster-006","text":"Divide the class into six teams. Draw six blank faces and bodies on the board. The front person from each team stands up. The ALT asks a question. The first student to answer correctly rolls an inflatable die. Depending on the number rolled, the team draws a body part on their team's monster (1=eye, 2=ear, 3=nose, 4=mouth, 5=arm, 6=leg). Each team can only have one nose, one mouth, and two each of the ears, eyes, arms and legs. Once the first person sits down, the next person in line stands. Repeat the process. The winning team is the first to complete their monster. If time runs out, the team with the most features wins. Questions can be tailored to the grade level. Elementary examples: \"What's this?\" (pointing to body parts) or \"Show me a...\" Junior high examples: questions related to current grammar points (e.g., \"Which is bigger, China or Japan?\").","content_type":"activity","name":"Build a Monster!","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Whiteboard/Chalkboard","Markers/Chalk","Inflatable Dice"],"topic_tags":["Body parts","Questioning","Competition","Grammar (JH)"]},
  {"id":"scraped-altcir-handbook-introduce-the-game-s-name-007","text":"This short activity focuses on introducing the name of a game to the students, allowing for a cultural point to be introduced. The teacher starts by announcing the game's name clearly, using simple and clear English pronunciation. Then, the teacher should write the name on the board. This allows for visual reinforcement. Next, the teacher should pause, and ask the students if they know anything about the game. This can be followed by a short explanation of the game. For example, the teacher could mention something about the origin of the game. This activity primarily targets listening comprehension, as students need to understand the name and the teacher's brief explanation. It also introduces the game to them in a more culturally relevant way. Suitable for elementary and lower-level junior high school students. Materials needed: Whiteboard or blackboard and markers/chalk. Classroom Tip: Keep it short and engaging, focusing on clear pronunciation and a brief, interesting cultural point related to the game's origin or significance. For younger learners, visuals (pictures of the game or related objects) can be helpful.","content_type":"activity","name":"Introduce the Game's Name","activity_type":"Warm-up","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Whiteboard/Blackboard","Markers/Chalk"],"topic_tags":["games","culture","vocabulary"]},
  {"id":"scraped-altcir-handbook-what-time-is-it-mr-wolf-008","text":"This is a simple speaking game. One student is designated as \"Mr. Wolf\" and stands with their back to the other students. The other students ask, \"What time is it, Mr. Wolf?\" Mr. Wolf responds by saying a time, such as \"It's three o'clock.\" The students then take steps forward, counting the steps. The game continues with the students asking \"What time is it, Mr. Wolf?\" and the wolf responding with different times. At any time the Wolf can yell, \"Dinner Time!\" and turn around. If the wolf tags a student, that student is out. The last student standing becomes the new Mr. Wolf. This activity targets speaking and listening skills, specifically time-telling vocabulary. It is suitable for elementary school grades. Materials needed are none. Classroom tip: Encourage the Wolf to vary the times given to make the game last longer. You can pre-teach time vocabulary before starting.","content_type":"activity","name":"What Time Is It, Mr. Wolf?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["time","games","speaking"]},
  {"id":"scraped-altcir-handbook-clock-steps-009","text":"This activity helps students practice telling time in English and following simple instructions. The teacher calls out a time, e.g., \"It's 2 o'clock!\" and students take the corresponding number of steps forward. For example, the teacher says, \"It's 2 o'clock!\" and students take two steps forward. The teacher can adjust the pace and the times to control the challenge. This activity targets listening comprehension and following directions. Suitable for elementary school. Materials needed: None. Classroom tip: Start with whole numbers of hours and progress to half-past and quarter-past times. You can also vary the direction (forward, backward, left, right) to add a challenge or use actions instead of steps, like \"It's 10 o'clock! Jump 10 times!\"","content_type":"activity","name":"Clock Steps","activity_type":"Warm-up","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Time","Following Directions","Physical Activity"]},
  {"id":"scraped-altcir-handbook-play-again-010","text":"This is a simple variation of the classic game 'What Time Is It, Mr. Wolf?' The activity's goal is to give students a chance to practice basic English commands and listening skills. The teacher begins as Mr. Wolf. Students stand at a 'safe' distance. Mr. Wolf turns his back and calls out a time (e.g., 'It's 2 o'clock!'). Students then take steps forward corresponding to the time called out. When Mr. Wolf turns around, anyone moving is 'out'. If Mr. Wolf is successful in tagging another player, the tagged player(s) become the new Mr. Wolf(s). This cycle repeats until the end of the activity. Students will be practicing listening to the directions (the time called out) and following those directions physically. Ensure students take appropriately sized steps to prevent injury. Limit the number of wolves to prevent chaos. Adapt the time increments to the skill level of the class, starting with small times at first and increasing them. The goal is to maximize participation and keep the game active, and fun. It targets listening and following directions. Materials needed are none, and the activity can be adapted to any open space, or classroom.","content_type":"activity","name":"Play Again!","activity_type":"Main Game","skill":"Listening","duration_minutes":20,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Games","Commands","Following Directions"]},
  {"id":"scraped-altcir-handbook-quick-chat-practice-011","text":"This activity is designed for quick practice of any conversation topic or vocabulary. First, introduce the target language (vocabulary, sentence structure, etc.). Model the conversation with a student. Then, have students practice the conversation in pairs. Circulate and monitor, providing support and correcting errors. This can be adapted to many different topics and skill levels. Encourage students to use the target language confidently. It is great for building confidence and fluency. For lower level learners, provide a simple worksheet with sentence starters or visual aids. For advanced learners, encourage them to expand on the target language and add more detail. \n\nLanguage skills targeted: Speaking, Listening. \nSuitable for grade levels: 5-9. \nMaterials needed: Whiteboard/blackboard, markers/chalk, optional worksheet.\n\nClassroom tips: Keep the activity short and focused. Praise student efforts and focus on communication rather than perfection. Vary the partners frequently. Provide clear instructions and examples. Use this as a warm up to larger activities or as a quick filler at any point.","content_type":"activity","name":"Quick Chat Practice","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Whiteboard/Blackboard","Markers/Chalk","Optional Worksheet"],"topic_tags":["Conversation","Vocabulary","Fluency"]},
  {"id":"scraped-altcir-handbook-row-column-sit-down-012","text":"This is a quick and active game perfect for a warm-up or filler. Students start standing. The teacher asks a question, and students raise their hands to answer. If a student answers correctly, everyone in their row (left and right) sits down. Next question, if a student answers correctly, everyone in their column (front and back) sits down. Continue asking questions until only one student is left standing. Emphasize that the last student standing is not a 'loser' but gets another chance. This activity targets listening comprehension and speaking, encouraging quick thinking and recall. Questions should be tailored to the grade level's current curriculum. Materials needed are only the teacher's prepared questions. Classroom Tip: Vary the types of questions (e.g., simple recall, 'yes/no', open-ended) to keep students engaged. Make it fun!","content_type":"activity","name":"Row & Column Sit Down","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":[]},
  {"id":"scraped-altcir-handbook-cross-cultural-games-013","text":"This activity introduces students to games from different cultures, led by the ALT. The activity begins with the ALT describing a childhood game from their home country. Then, the ALT leads the class in playing the game. This could be adapted to include a discussion of the similarities and differences between the games and those played in Japan, promoting cultural understanding. The ALT can ask questions like, 'What games do you play?' or 'What is different about this game?'\n\nThis activity primarily targets speaking and listening skills as students learn new vocabulary and participate in game play. It's suitable for elementary school and lower junior high levels. Minimal materials are required, often just the students themselves and space to move around. Classroom tips: Be enthusiastic! Explain the rules clearly and demonstrate the game first. Encourage students to participate and have fun. Adapt the game to include a more 'international' angle by including elements from the JET's home country or other cultures.","content_type":"activity","name":"Cross-Cultural Games","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["Culture","Games","Speaking"]},
  {"id":"scraped-altcir-handbook-cat-mouse-and-dog-014","text":"This is a fun chasing game perfect for getting students moving. First, draw three circles on the floor, representing bases. Divide the class into three teams, assigning each team a name: Cat, Mouse, or Dog. Each team has their own base where they are safe. Cats chase Mice, Mice chase Dogs, and Dogs chase Cats. When a team member is caught, they go to the captor's base. They can be freed when a teammate tags them. Students must wear hats or headbands to easily identify their teams. This activity targets listening comprehension (instructions), speaking (calling out names, encouraging teammates), and following directions. It's best suited for upper elementary and junior high students. Materials needed include floor markers (tape or chalk), and hats or hachimaki for each team. A good tip is to circulate and remind students of the rules and which teams chase which. Adjust the size of the bases depending on the class size.","content_type":"activity","name":"Cat, Mouse and Dog","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["floor markers","hats or hachimaki"],"topic_tags":["games","movement","teamwork"]},
  {"id":"scraped-altcir-handbook-fox-and-geese-015","text":"This is a simple running game for the gym or a snowy area. First, mark a large circle on the floor or in the snow. Add a center circle (the hub) and lines (spokes) radiating out from the hub to the outer circle. One student is chosen to be the Fox, and the rest are Geese. The Fox chases the Geese around the circle and across the spokes, trying to tag them. Geese are safe inside the hub, but can only stay for a short time (one minute). When a Goose is tagged, they become the new Fox. This activity focuses on speaking and listening through the students making calls. Also, students will follow directions and work on understanding. This game is suitable for elementary and junior high students, with adaptations. Adaptations: younger students can have a larger hub and shorter time limit, and older students can try to use English when running, like \"Run!\" or \"Go!\" or \"I'm safe!\". \n\nLanguage Skills: Following directions, simple commands, basic vocabulary (run, go, safe).\nMaterials: Gym floor or open space, or chalk to draw circles and lines.\nClassroom Tips: Ensure a large enough playing area to minimize collisions. Emphasize safe running and the need to follow the rules.","content_type":"activity","name":"Fox and Geese","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Gym floor or open space","chalk (optional)"],"topic_tags":["games","movement","instructions"]},
  {"id":"scraped-altcir-handbook-ice-floes-race-016","text":"Divide students into teams of 1-3. Each team gets two sheets of newspaper. The first player stands on one sheet. On \"GO\", they place the second sheet in front of them, step onto it, pick up the first sheet, place it ahead, and repeat. The first team to reach the end of the room and back wins. If a player's foot touches the floor, the team restarts. This activity targets speaking (following instructions, team communication) and listening (understanding instructions). Suitable for grades 5-7. Materials: newspaper sheets. Classroom tips: Emphasize 'on' the paper, and 'off' the floor! Monitor for fairness and ensure all players participate.","content_type":"activity","name":"Ice Floes Race","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":["Newspaper sheets"],"topic_tags":["Games","Teamwork","Following Directions"]},
  {"id":"scraped-altcir-handbook-elephant-tiger-mouse-017","text":"This is a twist on the classic game of Rock, Paper, Scissors, adapted for ESL/EFL learners. Instead of paper, scissors, and rock, students use the gestures of elephant (thumb), tiger (pointer/index finger), and mouse (little finger). The elephant beats the tiger, the tiger beats the mouse, and the mouse beats the elephant. \n\nTo play, the teacher explains the gestures and rules (Elephant > Tiger, Tiger > Mouse, Mouse > Elephant) to the class. Then the teacher instructs students to play \"Janken\" (Rock, Paper, Scissors in Japanese) and on the count of three, they make one of the three animal gestures. Students pair up to play the game until a winner is determined. This activity helps students practice listening, pronunciation, and basic vocabulary related to the animals and the action \"beats\". Suitable for elementary and lower junior high school grades.\n\nClassroom Tips:\n*   Start by modelling the gestures and the sounds the animals make.\n*   Have the students practice the actions several times before playing in pairs.\n*   For younger students, use flashcards with pictures of the animals to aid understanding.\n*   Encourage students to use the target language (e.g., \"Elephant beats tiger!\").","content_type":"activity","name":"Elephant, Tiger, Mouse","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":[],"topic_tags":["games","vocabulary","gestures"]},
  {"id":"scraped-altcir-handbook-pass-the-parcel-018","text":"This is a fun game adaptable for different topics like greetings, capital cities, or cultural customs. Prepare a small prize, such as candy or a small amount of money, and wrap it in 10-12 layers of wrapping paper or newspaper. Students sit in a circle and pass the parcel while music plays. When the music stops, the student holding the parcel unwraps a layer. If the prize isn't reached, they perform a forfeit activity. Forfeits can be simple tasks like singing the ABC song or answering a question related to the topic. Continue playing until someone unwraps the prize. This activity targets listening comprehension (following instructions), speaking (performing forfeits or answering questions), and vocabulary related to the chosen topic. \n\nClassroom Tips:\n*   Choose appropriate forfeits based on the students' English level and the topic.\n*   Vary the music to keep students engaged.\n*   Ensure that all students get a chance to participate.\n*   Adjust the number of layers according to the class time and the students' attention spans.","content_type":"activity","name":"Pass the Parcel","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Wrapped parcel with a prize","Music player and music"],"topic_tags":["games","vocabulary","listening"]},
  {"id":"scraped-altcir-handbook-squirrel-in-the-tree-019","text":"This is a fun and active game for practicing basic English commands and following directions. Students form groups of three. Two students in each group hold hands to create a circle, representing a 'tree'. The third student stands inside the circle, acting as a 'squirrel'.\n\nWhen the teacher blows a whistle, the 'trees' (those holding hands) raise their arms. The 'squirrels' must quickly run around the room to find a new 'tree' to join. The game continues with the squirrels finding new trees.\n\nAfter a few rounds, have some of the 'trees' become squirrels and vice-versa. Focus on simple commands such as, \"Run!\", \"Stop!\", \"Find a tree!\" This game targets listening comprehension and simple speaking (using commands), suitable for Elementary school students. It can also encourage teamwork.\n\nMaterials needed: Whistle. Classroom tips: Ensure there is one squirrel per tree. The teacher can use this game to call out actions, such as 'change trees'.","content_type":"activity","name":"Squirrel in the Tree","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":["Whistle"],"topic_tags":["Games","Commands","Action"]},
  {"id":"scraped-altcir-handbook-seven-up-020","text":"This is a quick warm-up game. Seven students stand at the front of the class. The remaining students put their heads down on their desks, close their eyes, make a fist, and put their thumb up. The seven students walk around the classroom and touch the thumb of one student each. After the seven students have touched a thumb, the students who had their thumbs touched try to guess who touched them. If they guess correctly, they switch places with the student who touched their thumb. If they guess incorrectly, the other person stays. Change the seven students after five rounds. This activity primarily targets listening comprehension and simple speaking skills (e.g., \"Was it [student's name]?\") and is most suitable for elementary to early junior high students. The only material needed is a classroom. Ensure that all students keep their eyes closed.","content_type":"activity","name":"Seven Up","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["games","listening","speaking","warm-up"]},
  {"id":"scraped-altcir-handbook-tunnel-ball-021","text":"Divide students into two teams. Each team forms a single file line with legs apart. The first student rolls a ball (medicine ball recommended, but any large ball works) through the tunnel formed by their teammates' legs. The last student retrieves the ball, runs to the front of the line, and then rolls the ball. The entire team shuffles backwards as the last person runs to the front. The game continues until the first person to roll the ball is back at the front of the line. The first team to finish wins. This activity targets listening and following directions. Suitable for grades 5-7. Requires a ball and a clearly defined start/finish line (chalk or tape). Classroom tip: Emphasize the importance of shuffling back together as a team to keep the game organized and fair.","content_type":"activity","name":"Tunnel Ball","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":["ball","tape or chalk for lines"],"topic_tags":["games","teamwork","sports"]},
  {"id":"scraped-altcir-handbook-poison-ball-022","text":"This is a fun game to practice avoiding and reacting to simple instructions. First, define a large circle on the floor. Choose five students to stand outside the circle with soft balls. The remaining students stand inside the circle. The five students outside the circle roll the balls into the circle, trying to hit the students inside. If a student inside is hit by a ball, they are out and join the students rolling the balls. The last student remaining in the circle wins. Emphasize that students must *roll* the balls, not throw them. This activity targets listening comprehension and physical response. It's suitable for elementary and junior high students, depending on the speed of the game. Materials needed: soft balls, and an open space. Classroom tip: make sure the playing area is safe and that the balls are soft to avoid injury. Adjust the number of people rolling the balls depending on class size. For larger classes, use more balls.","content_type":"activity","name":"Poison Ball","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":1,"interaction":"Whole class","materials":["Soft balls"],"topic_tags":["games","instructions","movement"]},
  {"id":"scraped-altcir-handbook-drop-ball-023","text":"This activity is designed for pair work to improve students' speaking and listening skills. Students form pairs and take turns throwing a ball (a tennis ball works well) back and forth. If a student drops the ball, their partner calls out \"one knee!\" The student who dropped the ball then kneels down on one knee. If the same student drops the ball again, the partner calls out \"two knees!\" The next steps are \"one elbow!\", \"two elbows!\", and finally \"chin!\". If a student drops the ball after having their knees, elbows, and chin on the floor, they are out of the game. Students must stay in the designated position while throwing and catching the ball. The teacher should monitor for correct pronunciation and ensure students are following instructions. Encourage students to use full sentences if possible, e.g., \"I dropped the ball.\" This can be adapted with different body parts or actions for older students.","content_type":"activity","name":"Drop Ball","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["ball (tennis ball size)"],"topic_tags":["body parts","games","speaking practice"]},
  {"id":"scraped-altcir-handbook-circle-tag-024","text":"This is a simple chasing game that promotes speaking and physical activity. First, mark out five circles on the ground using chalk, snow, or dirt. The circles should be about one meter in diameter and spaced about two long paces apart. Choose one student to be the 'Chaser'. The other students must move between the circles, trying to avoid being tagged by the Chaser. Students can only stay in a circle for a maximum of five seconds. If the Chaser tags a player, that player becomes the new Chaser. This activity targets speaking (as students shout and communicate) and physical movement. Classroom Tip: Encourage students to use English phrases like \"Run!\" or \"Look out!\"","content_type":"activity","name":"Circle Tag","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["chalk/snow/dirt","space to play"],"topic_tags":["games","physical activity","commands"]},
  {"id":"scraped-altcir-handbook-everybody-tag-025","text":"In this high-energy game, all students start as 'IT' and attempt to tag their classmates. Anyone who is tagged must freeze in place. The last student remaining untagged yells \"Go!\" to restart the game. This activity primarily targets gross motor skills and promotes simple social interaction and quick thinking. It requires no specific language skills, but can be a fun accompaniment to introducing physical action verbs. Suitable for elementary school students. No materials are needed, just an open space. Be sure to remind students to tag gently and be careful of running into each other. If space is limited, the teacher can designate boundaries.","content_type":"activity","name":"Everybody Tag","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["games","actions","physical activity"]},
  {"id":"scraped-altcir-handbook-scarecrow-tag-026","text":"This is a simple and energetic tag game that gets students moving. One or more students are designated as \"IT\". When \"IT\" tags another student, that student must freeze in a scarecrow pose (legs apart, arms outstretched). The frozen student can be freed by another student crawling between their legs. The person crawling is safe while under the other person's legs. The game continues until time is up or students tire of the activity. For a variation, if a student is tagged a certain number of times (e.g., twice), they become \"IT\".\n\nThis activity primarily targets Speaking and Physical Response. It's suitable for Elementary and early Junior High. No materials are needed, just open space. The game encourages active participation and vocabulary related to actions. Classroom tips: Clearly explain the rules and safe zones. Monitor student interactions and encourage fair play. Adapt the number of \"ITs\" and tag rules based on class size and student energy.","content_type":"activity","name":"Scarecrow Tag","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["games","actions","physical activity"]},
  {"id":"scraped-altcir-handbook-shadow-tag-027","text":"This is a fun outdoor game that encourages speaking and listening. One student is designated as \"IT\". \"IT\" tries to tag other players by stepping on their shadow. When a player is tagged, they become the new \"IT\". Players must remain in the sunlight, adding an element of environmental awareness. This activity targets listening for instructions and quick speaking to declare who is \"IT\".\n\nSteps:\n1. Choose one student to be \"IT\".\n2. The remaining students spread out in the designated play area.\n3. \"IT\" tries to tag other players by stepping on their shadow.\n4. When a player is tagged, they become the new \"IT\".\n\nClassroom Tips: Make sure the area is safe for running. Remind students to stay in the sunlight.  Adapt for indoor use by defining a space as \"sunlight\".","content_type":"activity","name":"Shadow Tag","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["games","outdoor","physical activity"]},
  {"id":"scraped-altcir-handbook-tail-tag-028","text":"This is a fun, active game for practicing following directions and basic physical descriptions. Students form lines of three, holding the waist of the person in front of them. One student is 'IT' and tries to tag the last person in any line. When 'IT' tags the last person, the front person of that line becomes 'IT'. If a student lets go of the person in front of them, they also become 'IT'.\n\nThis activity targets listening comprehension and speaking, as students must understand the rules and react quickly. It's suitable for elementary school grades 5-7. No materials are needed, just an open space in the classroom. Classroom tips: Emphasize the rule about letting go; remind students to hold on tight; start with a demonstration.","content_type":"activity","name":"Tail Tag","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Games","Following Instructions","Active"]},
  {"id":"scraped-altcir-handbook-crows-and-cranes-029","text":"Divide the class into two teams: Crows and Cranes. Each team designates a 'home base.' Students begin by facing each other in the center of the classroom. The teacher calls out either \"Crows!\" or \"Cranes!\". If \"Crows!\" is called, the Crows chase the Cranes. If a Crane is tagged by a Crow, the Crane joins the Crow team. If \"Cranes!\" is called, the Cranes chase the Crows and tagged Crows join the Crane team. The game continues until a time limit is reached, or one team has captured all of the players. This activity targets listening comprehension and speaking. It is best suited for reinforcing vocabulary related to body parts or simple action verbs. Substitute team names like \"Red\" and \"Blue\" if needed to avoid confusion. Make sure to clearly define the boundaries of the play area and the home bases. Encourage students to call out words as they run. The teacher should model the action and language, and monitor to ensure that there is no rough play.","content_type":"activity","name":"Crows and Cranes","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["games","actions","teamwork"]},
  {"id":"scraped-altcir-handbook-red-light-green-light-030","text":"This is a fun, active game perfect for getting students moving and practicing listening skills. One student is chosen to be 'it' and faces away from the other students, standing near a wall. The other students line up at a starting point, a good distance from the wall. The student who is 'it' calls out \"Green light!\" and the other students run towards the wall. At any point, 'it' can shout \"Red light!\" and the other students must freeze in place. 'It' then turns around and tries to catch anyone still moving; if caught, the student returns to the starting line. The first student to tag the wall wins and becomes 'it' for the next round. For extra fun and language practice, introduce actions. When 'it' says \"Crash!\", students must fall to the ground. When 'it' says \"Bridge!\", students must make a bridge shape by touching the ground with their hands and feet. This game targets listening comprehension and basic action vocabulary, and encourages physical activity.","content_type":"activity","name":"Red Light/Green Light","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["games","listening","actions"]},
  {"id":"scraped-altcir-handbook-where-are-you-031","text":"This is a fun chasing game that gets students moving and speaking. One student is blindfolded and stands in the center of the classroom. That student calls out, “Where are you?” The other students, who are free to move around the classroom, reply “Here I am!” The blindfolded student then tries to tag another student. If the blindfolded student tags a student, that student becomes the new blindfolded student. This activity targets listening and speaking skills, as well as following simple instructions. It is best suited for younger students, who enjoy the game. Materials needed: A blindfold. Classroom tip: Make sure the playing area is clear of obstacles. Choose a student to be the first blindfolded player. Remind the students to speak loudly and clearly. Consider assigning the role of blindfolded student to different students to allow everyone to participate.","content_type":"activity","name":"Where are you?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Blindfold"],"topic_tags":["Games","Directions","Classroom"]},
  {"id":"scraped-altcir-handbook-i-spy-032","text":"This activity is a classic guessing game that works well as a warm-up or filler. The teacher starts by saying, \"I spy something [color]\" (e.g., blue). Students then take turns guessing what the teacher is describing. The teacher provides clues to help them, such as size (\"It’s big\"), function (\"You can write with it\"), or location (\"It's on the desk\"). The goal is for students to guess the object correctly. The activity focuses on listening and speaking skills, specifically vocabulary related to colors, size, and functions of objects. Suitable for elementary and lower junior high school grades. Materials needed are only the objects in the classroom. Classroom tip: Encourage the students to use full sentences when guessing (\"Is it a desk?\") and vary the difficulty of the clues based on the students’ proficiency.","content_type":"activity","name":"I Spy","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["colors","objects","vocabulary"]},
  {"id":"scraped-altcir-handbook-noisy-animals-033","text":"This activity teaches animal noises and encourages listening and speaking skills. Divide students into groups of five or six. Assign each group a different animal noise (e.g., \"moo,\" \"oink,\" \"meow\"). Have groups practice their sounds loudly. Next, have students close their eyes or be blindfolded. Scatter the groups around the classroom or gym. On the teacher's signal, students try to find their group by making their assigned animal noise. The first group to reunite wins. This is best for elementary or lower junior high students, and is a fun game to watch.","content_type":"activity","name":"Noisy Animals","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":[],"topic_tags":["Animals","Sounds","Listening"]},
  {"id":"scraped-altcir-handbook-tray-memory-034","text":"Place ten familiar items, like vocabulary words related to food or objects, on a tray. Show the tray to the students for one minute, allowing them to memorize the items. Cover the tray. Students then write down the items they remember. For a variation, remove one item from the tray and ask students to identify which item is missing. This activity reinforces vocabulary recall and short-term memory.\n\nLanguage skills targeted: Vocabulary, memory, writing (or speaking, depending on the variation).\nSuitable grade levels: Elementary and Junior High (adapt the difficulty of the items).\nMaterials needed: Tray, ten+ items (e.g., fruit, school supplies), a cover (e.g., cloth or large paper).\nClassroom tips: Adjust the number of items and the time limit based on the students' proficiency level. Provide a model answer on the board for self-correction. Encourage students to help each other.","content_type":"activity","name":"Tray Memory","activity_type":"Review","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Individual","materials":["Tray","Items","Cover"],"topic_tags":["Vocabulary","Memory","Review"]},
  {"id":"scraped-altcir-handbook-circle-the-letter-035","text":"This quick activity is designed to practice letter recognition and following instructions. First, write a variety of letters on the board, using different sizes and colors. Divide the class into teams. Call out instructions like, \"Big red A!\" or \"Small blue B!\" Students from each team race to circle the correctly identified letter. The first student to correctly circle the letter earns a point for their team. Continue calling out letters and colors, keeping it fast-paced and fun. This activity targets listening comprehension and reading readiness. It's suitable for elementary school students. Materials needed: whiteboard, colored markers or chalk. Classroom tips: Vary the descriptions to keep it challenging. Make sure the teams are of equal size. Consider using different fonts.","content_type":"activity","name":"Circle the Letter","activity_type":"Warm-up","skill":"Mixed","duration_minutes":10,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Groups","materials":["Whiteboard","Colored markers"],"topic_tags":["Letters","Colors","Instructions"]},
  {"id":"scraped-altcir-handbook-valentine-s-day-cards-036","text":"This activity focuses on teaching students about Valentine's Day and practicing simple greetings. Prepare heart-shaped cards by either photocopying pre-made designs for coloring or having students draw their own. Introduce the concept of Valentine's Day in your culture, explaining its traditions. Then, teach students basic Valentine's Day greetings like \"Happy Valentine's Day!\" and \"I love you.\" Students can then write these greetings on their cards and give them to each other, practicing their writing and speaking skills. This activity is perfect for incorporating cultural elements into the lesson.","content_type":"activity","name":"Valentine's Day Cards","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Heart-shaped cards (pre-made or for drawing)","Markers/crayons","Photocopier (optional)"],"topic_tags":["Valentine's Day","Greetings","Culture"]},
  {"id":"scraped-altcir-handbook-colouring-easter-eggs-037","text":"This is a hands-on activity where students learn about Easter traditions while practicing basic instructions and descriptive language. Students will learn about the process of coloring Easter eggs using various methods. The activity targets listening comprehension when the teacher gives instructions, and speaking as they describe the process or ask questions. The class will need to prepare hard-boiled eggs, food coloring (or an Easter egg coloring kit), vinegar, bowls, candles or wax crayons, and potentially coffee grounds and onion skins. Before the lesson, prepare the dye solutions with the food coloring and vinegar. During the activity, the teacher gives step-by-step instructions. Students follow the instructions and color the eggs. They can then describe the process to their classmates, focusing on colors and patterns. Older students can experiment with more advanced techniques. Classroom tips: Ensure the eggs are hard-boiled before the lesson. Consider having examples of finished eggs. Adapt the language to the students' level. Use visual aids such as pictures of the eggs.","content_type":"activity","name":"Colouring Easter Eggs","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["hard-boiled eggs","food coloring","vinegar","bowls","candles or wax crayons","coffee grounds (optional)","onion skins (optional)"],"topic_tags":["Easter","Colors","Instructions","Culture"]},
  {"id":"scraped-altcir-handbook-mother-s-day-cards-038","text":"This activity teaches students how to create a Mother's Day (or Father's Day) card. Students learn how to construct a card with a pocket vase and paper flowers. The flowers are attached to popsicle sticks (acting as stems), and on these stems, students write promises of helpful actions they will do for their mother (or father). This can be a simple card, or a voucher-style card with specified chores or activities. This activity targets both writing (on the flower stems) and following instructions. Students will need to listen to and understand the instructions for creating the card, targeting listening comprehension as well. This activity provides the opportunity for students to review vocabulary and practice sentence structures related to helping and chores, for example 'I will help with the laundry' or 'I will set the table'. Classroom tips: Provide a simple template for the card and pre-cut some of the materials if time is a constraint. Encourage students to be creative with their designs. Also, prepare the vocabulary and simple sentence structures related to helping and chores before the activity. Review instructions. Emphasize pronunciation and intonation when modeling the sentences and instructions.","content_type":"activity","name":"Mother's Day Cards","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["Cardstock","Scissors","Glue","Popsicle sticks","Paper","Markers/Crayons"],"topic_tags":["Holidays","Family","Writing"]},
  {"id":"scraped-altcir-handbook-paper-chain-sukkah-decor-039","text":"This activity has students create paper chains to decorate a Sukkah (a temporary shelter used during the Jewish holiday of Sukkot). First, explain the purpose of the Sukkah and the holiday of Sukkot. Then, demonstrate how to make a paper chain: Cut strips of colored paper (different colors are good) and then loop and glue the paper strips together to form the chain links. Have the students work individually or in pairs to make their chains. Encourage them to be creative with the colors and patterns. The language focus is mainly on following instructions and using basic commands such as 'cut', 'glue', 'loop', 'make'. This activity is suitable for elementary school students (Grades 5-6). Materials needed include colored paper strips, glue sticks or tape, and scissors. Classroom tip: pre-cut the paper strips to save time, and demonstrate the process clearly to the students at the start.","content_type":"activity","name":"Paper Chain Sukkah Decor","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":6,"complexity_max":1,"interaction":"Pairs","materials":["Colored paper strips","Glue sticks/tape","Scissors"],"topic_tags":["Crafts","Culture","Following Instructions"]},
  {"id":"scraped-altcir-handbook-kaki-jack-o-lanterns-040","text":"This activity utilizes the abundance of kaki (persimmons) available in October. The goal is to create jack o'lantern faces on the persimmons. \n\n**Procedure:**\n1.  Provide each student with a kaki. \n2.  Explain (in English) the concept of a jack o'lantern and show examples.  You can pre-draw a few examples for demonstration.\n3.  Instruct students to draw jack o'lantern faces on their persimmons using a black, water-based felt pen.\n4.  Circulate the classroom, providing assistance with vocabulary like \"eyes,\" \"mouth,\" \"triangle,\" etc. in English.\n5.  After completion, students can display their kaki creations. These can be washed and eaten later.\n\n**Skills Targeted:** Listening (following instructions), Speaking (asking for help/vocabulary), and potentially Reading (if you provide written instructions).\n\n**Suitable Grade Levels:** Elementary and Junior High (adapt the difficulty based on grade level).\n\n**Materials:** Kaki (persimmons), black water-based felt pens.\n\n**Classroom Tips:**\n*   Pre-draw examples for visual support.\n*   Focus on simple vocabulary.\n*   Encourage creativity.\n*   Make it a fun activity tied to Halloween.","content_type":"activity","name":"Kaki Jack o'Lanterns","activity_type":"Production","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Individual","materials":["Kaki (persimmons)","Black water-based felt pens"],"topic_tags":["Halloween","Fruits","Art"]},
  {"id":"scraped-altcir-handbook-turkey-puppets-041","text":"This simple craft activity is a fun way to celebrate Thanksgiving or the autumn season. Students trace their hand outline onto a piece of white paper. Their thumb is the turkey's head, and each finger becomes a feather. They can then color the turkey with crayons or markers, using various fall colors to decorate the feathers. This activity targets fine motor skills and simple art directions. The language targeted includes basic vocabulary for colors and body parts. It's best suited for upper elementary students. Materials needed are white paper, pencils, crayons or markers. Classroom tip: Provide a visual example of a finished turkey puppet before starting. Allow students to be creative with their feather colors and designs.","content_type":"activity","name":"Turkey Puppets","activity_type":"Filler","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Individual","materials":["White paper","Pencils","Crayons or markers"],"topic_tags":["Thanksgiving","Crafts","Art","Autumn"]},
  {"id":"scraped-altcir-handbook-advent-calendar-pi-ata-042","text":"This activity combines two separate craft ideas suitable for use during the Christmas/Winter Holiday season. The Advent Calendar activity involves creating a countdown calendar to Christmas. Students draw windows on a Christmas scene and number them from 1 to 24, with #24 being slightly larger. Students open a window each day to count down to their Winter Holidays. The piñata activity focuses on making and using a piñata. Students learn the steps of piñata construction: cutting newspaper strips, dipping them in a flour and water mixture, and layering them around a balloon. After drying, they decorate the piñata with tissue paper. The activity culminates in students taking turns, blindfolded, to hit the piñata with a stick. This is useful for teaching following directions, vocabulary (numbers, Christmas, holiday), and practicing some simple art and craft skills. For the piñata activity, teachers must emphasize safety. \n\nLanguage skills targeted: Following instructions, basic vocabulary (numbers, colors, holiday-related vocabulary), and giving instructions.\n\nSuitable for Grades 5-7.\n\nMaterials needed: Paper, drawing materials, thick paper, newspaper, flour, water, balloons, tissue paper, glue, pens, rope, sweets, peanuts, stick (bamboo or baseball bat).\n\nClassroom tips: Teacher needs to prepare templates ahead of time. Adapt the difficulty of the piñata by adjusting the height and swing distance. Always monitor and emphasize safety during the piñata activity.","content_type":"activity","name":"Advent Calendar/Piñata","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Paper","Drawing materials","Thick paper","Newspaper","Flour","Water","Balloons","Tissue paper","Glue","Pens","Rope","Sweets","Peanuts","Stick (bamboo or baseball bat)"],"topic_tags":["Christmas","Holidays","Crafts","Following Instructions"]},
  {"id":"scraped-altcir-handbook-story-time-043","text":"Choose a non-Japanese fairytale, folktale, or bedtime story like Little Red Riding Hood, a Nordic troll story, a Native American legend, or an Aboriginal Dreamtime story. Prepare the story by either translating it or using an existing English version. Bring the story to life by using drawings, picture books, or props. Consider using Kamishibai, a form of storytelling using illustrated cards, which are often available in libraries. If available, have a translated version in Japanese to help with understanding. This activity targets listening comprehension and vocabulary acquisition. This can be adapted for any grade level, but it is best for Elementary and lower Junior High School. Materials needed include the chosen story, pictures or picture books, and props. During the storytelling, use expressive voices, gestures, and facial expressions to engage the students.","content_type":"activity","name":"Story Time","activity_type":"Production","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Story text","Pictures or picture books","Props (optional)"],"topic_tags":["Storytelling","Culture","Listening Comprehension"]},
  {"id":"scraped-altcir-handbook-scavenger-hunt-044","text":"Organize a simple scavenger hunt activity. Before the class, prepare clues or items for the students to find. For younger students (grades 5-6), use picture flashcards and review the target vocabulary at the start and end of the activity. Adapt the activity based on the students' English proficiency. A variation is a sound scavenger hunt where students record sounds like English phrases spoken by teachers, a dog barking, the school bell, or a flushing toilet. This variation encourages listening and speaking skills while being fun and engaging. The clues can vary from finding physical objects to performing actions.","content_type":"activity","name":"Scavenger Hunt","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Flashcards (with pictures or instructions)","Tape recorder (optional)"],"topic_tags":["Vocabulary","Listening","Speaking","Fun"]},
  {"id":"scraped-altcir-handbook-map-quizzes-045","text":"This activity uses colourful maps to teach size words, colours, and names. The teacher can use gestures and melodies to help students memorize the vocabulary. \n\n**How to Play:**\n1.  **Preparation:** Gather brightly coloured maps of different sizes (A3, A4, or even larger). Prepare vocabulary flashcards with size words (e.g., big, small, tall, short), colours, and names of places or landmarks on the map.\n2.  **Introduction:** Introduce the target vocabulary, using gestures. For example, when teaching 'big,' spread your arms wide. Use actions with the words. Sing a simple song about the vocabulary.\n3.  **Map Activities:**\n    *   **Size:** Point to a place on the map and ask, \"Is this big or small?\" Have students answer, 'It's big!' or 'It's small!' and act out the size.\n    *   **Colour:** Color in the land or use coloured paper, and point to areas and ask students \"what color is this?\" Use gestures to aid comprehension.\n    *   **Names:** Point to a landmark and say its name. Have students repeat it.\n4.  **Drama Component** For a school festival, create a simple story with actions and a few key words related to the map features (mountains, trees, water etc.).\n\n**Language Skills Targeted:** Listening, Speaking\n**Suitable Grade Levels:** Elementary School (Grades 5-7)\n**Materials Needed:** Colourful maps, vocabulary flashcards, optional materials for creating a topographical map (twigs, clay)\n**Classroom Tips:** Use a big topographical map, built by the students for enhanced engagement and to create a more immersive experience for your students.","content_type":"activity","name":"Map Quizzes","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Colourful maps","Vocabulary flashcards"],"topic_tags":["Maps","Vocabulary","Drama"]},
  {"id":"scraped-altcir-handbook-kindergarten-visit-046","text":"Kindergarten visits are often more about interaction and fun than structured lessons. Be prepared for a high-energy environment with children aged 3-6. Your role may be to participate in existing activities like drawing, coloring, singing, or stories, incorporating some simple English. Prepare a repertoire of action songs, games, and activities to fall back on. Action songs such as \"Head Shoulders Knees and Toes\" are a good choice. Embrace the fun, be enthusiastic, and use exaggerated gestures and expressions. Remember to be aware of the children's behavior and set boundaries as needed. Prior preparation includes bringing indoor shoes, having a flexible lesson plan with more activities than needed, and avoiding potentially violent games. Coordinate with the Japanese teacher for crowd control and activity explanations, and use incidental language frequently, repeating phrases and using vocabulary posters to maximize student engagement and recall. Be prepared with some basic materials as necessary.\n\nTips: Use the teacher for crowd control. Make a flexible lesson plan and prepare more activities than you have time for. Avoid games that could get violent. Keep the class student-centred and use incidental language as much as possible.","content_type":"activity","name":"Kindergarten Visit","activity_type":"Filler","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Greetings","Songs","Games"]},
  {"id":"scraped-altcir-handbook-classroom-games-047","text":"This collection of games introduces basic English vocabulary and phrases suitable for elementary school students. These activities focus on greetings, feelings, numbers, birthdays, colors, and basic commands. For the 'Names' activity, write each student's name on a large paper for display. 'Feelings' uses visual aids with faces representing emotions. 'Numbers' uses flashcards, clapping games, and team games like 'Grab the ball' and 'Take...steps'. 'Birthday' incorporates a calendar and the 'Happy Birthday' song. 'Colors' utilizes colored paper for identification and games such as 'Fruit Basket' and 'Catch'. Finally, 'Stop/Go' implements the classic 'Red Light, Green Light', along with a basic movement game when you call go/stop. These activities are designed to be fun and engaging, encouraging active participation and repetition of essential phrases and vocabulary. The games can be adapted in difficulty for each class. Focus on clear pronunciation and providing lots of positive reinforcement. Adjust the size and complexity based on the class size and their current level of understanding.","content_type":"activity","name":"Classroom Games","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":["Large paper or cardboard","Markers","Name cards","Cardboard with faces (happy, O.K., sad)","Flashcards with numbers 1-10","Ball","Colored paper"],"topic_tags":["Names","Feelings","Numbers","Birthday","Colors","Commands","Vocabulary"]},
  {"id":"scraped-altcir-handbook-body-parts-action-games-048","text":"This activity focuses on body parts and action verbs. Start with a review of the \"Head, Shoulders, Knees and Toes\" song. Then, introduce action verbs like \"touch,\" \"clap,\" \"shake,\" \"stamp,\" and \"turn around.\"  Play \"Simon Says\" using the body parts and action verbs (e.g., \"Simon says touch your nose\"). Adapt the classic song \"If You're Happy and You Know It\" to include actions on body parts. Finally, incorporate left and right directions, perhaps using color-coded aids, and sing the Hokey Pokey, focusing on body parts and directions. This activity builds vocabulary, reinforces listening comprehension, and promotes physical engagement. Suitable for grades 5-7. Materials needed: None. Classroom tips: Use a large, clear voice and exaggerated actions. Break the class into smaller groups if necessary for better participation, particularly for the \"Simon Says\" game. Encourage students to create their own \"Simon Says\" instructions.","content_type":"activity","name":"Body Parts Action Games","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["body parts","actions","songs","games","directions"]},
  {"id":"scraped-altcir-handbook-simon-says-please-049","text":"This activity modifies the classic \"Simon Says\" game to focus on politeness. The teacher gives instructions with and without \"please.\" For example, \"Stand up, please\" means students should stand, but \"Stand up!\" means they should not. Use commands like \"Sit down,\" \"Jump,\" \"Spin,\" \"Clap,\" and \"Smile, please!\". If students perform an action without \"please\" (like smiling), they are out. Additionally, incorporate jumping while calling out numbers. The teacher demonstrates the jump and pronunciation first, then the class jumps and calls out the same number. Increase the challenge by jumping continuously without pauses to expend energy.\n\nThis targets listening comprehension and following instructions while practicing basic vocabulary and politeness.","content_type":"activity","name":"Simon Says Please!","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["instructions","listening","games"]},
  {"id":"scraped-altcir-handbook-rocket-launch-050","text":"This activity focuses on number recognition and pronunciation, with a fun, kinesthetic element. Students will practice counting backwards from 12 to 0. Begin by having students crouch down, forming a rocket shape with their bodies and hands above their heads. The teacher counts down from 12, and with each number, students stand up a little higher. On the count of \"zero,\" students launch by jumping up in the air. Emphasize clear and loud pronunciation of the numbers, as a quiet countdown means the rocket fails to launch and the activity must restart. An alternative version involves forming an egg shape with hands and then bursting out as a bird on zero, flapping arms for added effect. The main target language skill is speaking, with an emphasis on pronunciation. The activity is suitable for elementary students in grades 5-7. No materials are required other than the teacher's voice. The key classroom tip is to ensure students speak loudly and clearly.","content_type":"activity","name":"Rocket Launch","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Numbers","Counting","Pronunciation","Kinesthetic"]},
  {"id":"scraped-altcir-handbook-animal-sounds-game-051","text":"This activity teaches animal names and sounds. Start by reviewing animal names and sounds using a picture book. Then, use flashcards to review animals and their sounds. If students struggle with pronunciation, write the sounds in hiragana/katakana. Divide students into groups and assign each group an animal. Provide small animal cards. Have groups practice their animal sounds for about 5 minutes. Explain the game rules: students close their eyes, mix up, then find their group mates by making their animal sounds. The first group to find all members and sit down wins. This activity targets listening and speaking skills, and helps students become familiar with animal names and sounds.","content_type":"activity","name":"Animal Sounds Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Picture book about animals","Animal flashcards","Small animal cards"],"topic_tags":["Animals","Sounds","Vocabulary","Listening","Speaking"]},
  {"id":"scraped-altcir-handbook-animal-charades-052","text":"This activity focuses on animal vocabulary and physical descriptions. Start by introducing large animal flashcards, such as a lion, elephant, and giraffe. Elicit the names and some basic actions associated with each animal. Then, distribute small animal cards to each student (e.g., a cat, dog, bird, etc.). Explain that they will act out their animal, and the class will guess. Begin by modeling the activity; act out an animal (without making any sounds) and have the students guess. Then, call on students one at a time to act out their animal. The rest of the class shouts out guesses. This activity targets listening comprehension and speaking (through guessing and describing the actions). It is suitable for elementary school students. You will need large animal flashcards, a whiteboard, and small animal cards for each student. Classroom tip: encourage students to use actions rather than sounds to make the activity clearer.","content_type":"activity","name":"Animal Charades","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Large animal flashcards","Small animal cards","Whiteboard"],"topic_tags":["Animals","Vocabulary","Action Verbs"]},
  {"id":"scraped-altcir-handbook-forecast-game-053","text":"This game is designed to be a fun way to review animal vocabulary and practice speaking. Start by explaining that the children will turn into animals. Choose a set of animal flashcards. Show each flashcard and have the students repeat the animal name and sound, encouraging exaggerated sounds and gestures. You can model this, being silly to engage the students. The goal is to get the students giggling. Next, play a few rounds of the game, switching up the animals for variety. The rules are not described, but it's implied that the game involves speaking and perhaps guessing. The teacher should encourage JTEs to get involved and be silly with the students. This activity targets speaking and listening skills while providing a fun and engaging environment. The game goes more fluidly when the students are familiar with the rules, and it allows for everyone to have a chance to win. The target of this activity is elementary students from 5th to 7th grade.","content_type":"activity","name":"Forecast Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Animal flashcards"],"topic_tags":["Animals","Vocabulary","Speaking","Sounds"]},
  {"id":"scraped-altcir-handbook-weather-telephone-054","text":"This activity helps students practice weather vocabulary and speaking skills. Divide the class into teams, having students sit in rows. Provide each team's last student with a set of weather cards, face down. The student flips a card, reads the weather type to the student in front. That student repeats the word, passing it down the line until the front student receives the message. The front student then draws the weather type in a designated forecast box on the board. Once complete, that student goes to the back and everyone shifts forward. Repeat to create a five-day weather forecast. Initially, focus on accuracy of the pictures and correct pronunciation. Then, award prizes to the fastest team or best pictures. This activity reinforces vocabulary and develops speaking skills in a fun, competitive way.","content_type":"activity","name":"Weather Telephone","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Weather cards","Whiteboard or chart paper","Markers or whiteboard pens"],"topic_tags":["Weather","Vocabulary","Speaking","Teamwork"]},
  {"id":"scraped-altcir-handbook-weather-karuta-055","text":"This activity combines a classic Japanese game with English vocabulary. Prepare Karuta-style cards featuring weather vocabulary such as \"sunny,\" \"rainy,\" \"cloudy,\" \"hot,\" and \"cold.\" Write the words clearly on the cards, and prepare one card for each student (or more if you plan to play multiple rounds). Arrange the desks in vertical rows. To play, the ALT calls out a weather word in English. Students listen carefully and race to find the matching card. The first student to grab the correct card keeps it. At the end of the round, the student with the most cards wins. This activity practices listening comprehension and vocabulary recognition. It's a fun and engaging way to reinforce weather-related vocabulary, and the competitive element keeps students motivated. Consider using different card sets with vocabulary that is relevant to the curriculum. To increase difficulty, use more cards or more specific weather-related phrases.","content_type":"activity","name":"Weather Karuta","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Karuta cards (weather vocabulary)","Chalk","Blackboard"],"topic_tags":["Weather","Vocabulary","Listening"]},
  {"id":"scraped-altcir-handbook-card-game-056","text":"This activity involves students receiving cards and using English to complete a task. The ALT and JTE should distribute cards to the students in the back row. The ALT can model the activity with a student or the JTE to demonstrate how to play. The JTE can also participate if team numbers are uneven. The ALT and JTE can walk around the classroom to monitor English usage and provide vocabulary reminders. The JTE can also act as the judge for speed, picture quality, or other criteria depending on the specific card game. This activity focuses on speaking skills as students will need to communicate to complete the task. Suitable for grades 5-7. Requires cards or prepared worksheets. Classroom tip: Ensure students only use English.","content_type":"activity","name":"Card Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Cards","Prepared Worksheets (optional)"],"topic_tags":["game","speaking","teamwork"]},
  {"id":"scraped-altcir-handbook-gokiburi-game-057","text":"This game is designed to be used after students have been introduced to new vocabulary. The teacher or a student calls out a word in English. Students then quickly move from their seats to the back of the classroom or another designated spot. One student stays at their desk to be the \"card flipper\" and calls out the word. When the students are at the back of the classroom, the teacher or another student calls out the word in Japanese. If the Japanese word matches the English word, the students in the new spot sit back down in their seats. If the words don't match, they move to a new spot. This repeats until all students are back in their seats. The goal is to be fast and accurate with vocabulary recall and movement. Target skills include speaking (vocabulary recall) and listening (understanding instructions and matching words). Suitable for grade levels 5-7. Materials needed include vocabulary flashcards. Classroom tip: Model the activity first with a few students before starting. Be mindful of students with mobility challenges and adapt the activity as needed.","content_type":"activity","name":"Gokiburi Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Vocabulary flashcards"],"topic_tags":["Vocabulary","Games","Movement"]},
  {"id":"scraped-altcir-handbook-cockroach-janken-058","text":"This activity helps students practice self-introductions or any other target conversation. First, model and practice the target conversation (e.g., \"Hello, my name is…\"). Then, students play janken (rock-paper-scissors). The loser of each round is a cockroach, and the winner is a human. Cockroaches must crawl on the floor and say their introduction in a low voice, while humans stand tall and speak loudly and clearly. Students play multiple rounds, with the goal of evolving from cockroach to human through winning janken. As they win, students should continue introducing themselves to the ALT or other students in the target conversation format. This activity targets speaking and listening skills. Encourage students to use correct pronunciation and intonation. Materials needed are none, and it's best for a classroom with enough space to allow the movement of cockroaches. Classroom tip: keep the pace quick and fun. Encourage students to be creative with their cockroach crawls!","content_type":"activity","name":"Cockroach Janken","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":[],"topic_tags":["Introductions","Games","Speaking"]},
  {"id":"scraped-altcir-handbook-animal-ladder-059","text":"This activity targets speaking and listening skills. The teacher begins by drawing or displaying an animal ladder on the board, with a cockroach at the bottom and a human stick figure at the top. Choose 3-5 animal cards in between. The teacher points at the cockroach and says \"I am a cockroach!\" and the students repeat. Next, the teacher points at the first animal on the ladder and says \"I am a mouse!\" and the students repeat. The teacher then asks \"Who is better, a cockroach or a mouse?\" The students respond, and the teacher moves up the ladder, comparing animals. For example, mouse vs. bird, bird vs. rabbit, rabbit vs. human. Students are encouraged to answer the question using complete sentences. The teacher can provide a model like, \"A bird is better than a mouse.\" This activity encourages comparison and descriptive language. Use a prize for a student answer. If time allows, students can create their own animal ladders in pairs or groups. Suitable for grades 5-7.","content_type":"activity","name":"Animal Ladder","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Animal cards (mouse, bird, rabbit, etc.)","Board markers/chalk","Magnets (optional)","Prizes"],"topic_tags":["Animals","Comparisons","Speaking"]},
  {"id":"scraped-altcir-handbook-janken-boss-060","text":"This activity focuses on basic introductions and simple conversation skills. The ALT begins by explaining the rules of the game in simple English. The JTE can assist with checking for understanding and translating if needed. Students practice introducing themselves using target phrases. The JTE monitors the students, ensuring they use English. The game concludes with the ALT acting as the \"final boss\", and students play janken with the ALT to \"evolve\".\n\n**Steps:**\n1.  The ALT explains the rules: \"Hello. My name is...\" \"What's your name?\" \"Nice to meet you.\" \"Let's play janken!\"\n2.  Students practice introducing themselves to each other.\n3.  The JTE monitors student conversations and provides support as needed.\n4.  Students who master introductions approach the ALT, who responds and plays janken.\n\n**Language Skills:** Speaking (introductions), Listening (instructions).\n**Suitable Grades:** 5-7\n**Materials:** None\n**Classroom Tips:** Encourage the JTE to move among the students to provide support and reinforce the target language. The ALT can model the conversation a few times before students start.","content_type":"activity","name":"Janken Boss","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":[],"topic_tags":["Introductions","Janken","Conversation"]},
  {"id":"scraped-altcir-handbook-animal-janken-061","text":"This activity reviews animal vocabulary while playing rock-paper-scissors (janken). Begin by reviewing animal vocabulary with gestures for each animal (e.g., bunny ears for rabbit). Divide students into pairs. Students play janken, and the winner of each round calls out an animal. The loser must then repeat the animal. Repeat until one student is declared the winner of the pair. For older students, limit the number of winners. This targets speaking and listening skills, reinforcing vocabulary and pronunciation. It also promotes active participation and quick thinking. Classroom tip: Prepare animal flashcards for visual support. Consider adding a reward for winning the final round to motivate students. This can get loud so be prepared to manage the noise level.","content_type":"activity","name":"Animal Janken","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":6,"complexity_max":2,"interaction":"Pairs","materials":[],"topic_tags":["animals","janken","speaking"]},
  {"id":"scraped-altcir-handbook-animal-action-062","text":"This activity introduces and reviews action verbs and animal vocabulary for young learners. The teacher begins by selecting a picture book with animal actions (e.g., \"Wiggle\" which features animals like penguins that waddle). The teacher shows a picture, names the animal, and models the action. For instance, show a picture of a penguin and say, \"Penguin! Penguins waddle!\" Then, encourage students to mimic the action. The teacher can introduce several animals and their actions, then review by showing the cards randomly and having the students say the animal and perform the action. This can also be adapted for other topics and picture books, targeting different vocabulary sets. Classroom tip: Use exaggerated actions and sounds for maximum engagement.","content_type":"activity","name":"Animal Action","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":5,"complexity_max":1,"interaction":"Whole class","materials":["Picture book (e.g., \"Wiggle\")","Picture cards (optional)"],"topic_tags":["Animals","Actions","Vocabulary","Early Learners"]},
  {"id":"scraped-altcir-handbook-picture-book-review-063","text":"This activity reviews vocabulary from a picture book, suitable for younger learners. Begin by showing laminated pages from the book (optional, regular book pages work too). Start with a few pages and review the vocabulary related to the pictures. Encourage students to act out the actions in the pictures. Gradually introduce more pages as the lesson progresses, allowing for repeated review and vocabulary building. Focus on pronunciation and comprehension. This activity is a great way to build vocabulary and keep younger students engaged. The key is to start with a few pages and slowly add more, as needed. Suitable for preschool to elementary students. Materials needed: laminated pages from the picture book (optional), the picture book. Classroom Tip: Have students act out the action.","content_type":"activity","name":"Picture Book Review","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["picture book","laminated pages (optional)"],"topic_tags":["vocabulary","review","picture book"]},
  {"id":"scraped-altcir-handbook-weekday-hopscotch-064","text":"This activity focuses on days of the week vocabulary and simple physical activity. Prepare a hopscotch grid on the floor using tape or chalk, with each square labeled with a day of the week (Monday through Sunday). Students line up and take turns hopping through the grid, saying the day of the week aloud as they land on each square. Encourage them to jump with energy and good pronunciation. The activity targets speaking and listening skills. It is best suited for Elementary grades 5-6, but can be adapted for grade 4. Materials needed are tape or chalk and a space to draw the hopscotch grid. Classroom tips: Ensure the grid is large enough for the students to hop safely. Monitor pronunciation and offer corrections. Consider making it a competition to maintain student engagement. You can modify this activity by calling out a day and having the students hop to it as quickly as possible.","content_type":"activity","name":"Weekday Hopscotch","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":4,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":["Tape or chalk"],"topic_tags":["Days of the week","Vocabulary","Physical activity"]},
  {"id":"scraped-altcir-handbook-days-of-the-week-hopscotch-065","text":"This activity helps students practice the days of the week in English through a fun, kinesthetic game. First, create a hopscotch pattern on the classroom floor using tape or chalk. The pattern should have seven spaces, one for each day of the week. Divide the class into two teams. One student from each team lines up at the starting point. When you say \"Go!\", the first students hop through the hopscotch pattern, reciting the days of the week in order (Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday) as they land on each space. The first student to complete the sequence correctly wins a point for their team. The students then return to their teams to tag the next player. This continues until all students have had a turn. The team with the most points at the end wins. This activity targets speaking and listening skills. Classroom tips: Make it competitive and fun. Encourage students to help each other if they forget the order. You can adjust the difficulty by asking students to say the days of the week backwards or to spell each day as they hop.","content_type":"activity","name":"Days of the Week Hopscotch","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Tape or chalk","Floor space"],"topic_tags":["Days of the Week","Vocabulary","Kinesthetic"]},
  {"id":"scraped-altcir-handbook-board-game-monitoring-066","text":"This activity involves a board game where students practice a specific language skill, such as reciting the days of the week. The ALT prepares the game materials. During the activity, the JTE (Japanese Teacher of English) translates rules, answers student questions, and maintains order. Both the JTE and the JTL (Japanese Teacher Leader) monitor the students' performance, each overseeing a team. If a student makes an error, such as mispronouncing or incorrectly stating the day of the week, the JTE/JTL corrects them and has the team restart the turn. This ensures accuracy and reinforces correct language use. This activity works best when the target language is simple and can be readily reviewed. \n\nLanguage skills targeted include: Speaking, Listening\n\nSuitable Grade Levels: 5-7 (Elementary to Junior High)\n\nMaterials Needed: Board game, game pieces.\n\nClassroom Tips: Clearly explain rules, be patient and encouraging. Focus on accuracy over speed. Keep the game fun and engaging. Consider pairing stronger students with weaker students for support.","content_type":"activity","name":"Board Game Monitoring","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Board game","Game pieces"],"topic_tags":["Days of the week","Board game","Speaking practice"]},
  {"id":"scraped-altcir-handbook-hopscotch-scene-067","text":"This activity aims to get students speaking and moving! The activity requires creating hopscotch grids on the ground, each square labeled with a weekday (Monday, Tuesday, etc.). The students divide into two teams and take turns hopping through the grid. When a student lands on a square, they must say the weekday. If they say it correctly, they get a point for their team. If they say it incorrectly, the other team gets a chance to answer. After the game is complete, the teachers can maximize the use of materials by playing the popular card game \"kurata\", using the weekday labels made. Be sure to have one teacher monitor each team because the students can become excited and disregard the rules. This game targets speaking and listening skills, specifically days of the week. Materials required include chalk (to draw the hopscotch grids) and weekday labels (Monday, Tuesday, etc.).","content_type":"activity","name":"Hopscotch Scene!","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["chalk","weekday labels"],"topic_tags":["days of the week","speaking"]},
  {"id":"scraped-altcir-handbook-scene-it-068","text":"This activity helps students practice new grammar through short theatrical scenes. First, introduce the new grammar point. Next, provide a few simple props like hats, sunglasses, or stuffed animals. Divide the class into groups of 3-4 students. Assign each group a simple scene prompt (e.g., \"At the park,\" \"At the store,\" \"Meeting a friend\"). Students work together to write a short dialogue using the target grammar and incorporating their prop. Give them 10-15 minutes to practice. Finally, have each group perform their scene for the class. This activity targets speaking and encourages creativity. Classroom Tip: Circulate during the preparation time to offer guidance and ensure students are using the target grammar correctly.","content_type":"activity","name":"Scene It!","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Props (hats, sunglasses, etc.)","Scene prompts (written on the board or on cards)"],"topic_tags":["Grammar Practice","Speaking","Drama"]},
  {"id":"scraped-altcir-handbook-classroom-scene-069","text":"After practicing new grammar points as a class and in pairs, students are invited to volunteer to perform in front of the class, usually in groups of two or three. The remaining class members close their eyes while the volunteers adopt new personas and select props to use (sunglasses, hats, etc). When the volunteers are ready, they take their places around the classroom, classmates open their eyes, and the scene begins. This activity requires minimal preparation and can be integrated fluidly into class sessions. It encourages volunteering, imagination, and allows students to personalize grammar by adding their own style.","content_type":"activity","name":"Classroom Scene","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Prop sunglasses","Hats"],"topic_tags":["role-play","grammar","presentation"]},
  {"id":"scraped-altcir-handbook-fun-faces-070","text":"This activity encourages students to use English creatively. The ALT prepares props and utensils. The ALT explains the activity and demonstrates it with the JTE initially. Students then create their own scenes using learned grammar. The JTE offers encouragement. The focus is on student creativity and correct grammar usage, with the ALT and JTE adapting to the students' ideas. This is designed to let students take the lead and showcase their language skills. \n\nLanguage skills targeted: Speaking, Listening. Suitable for grades 5-7. The ALT prepares props and utensils needed for the activity. The ALT explains the activity and models a scene with the JTE. Students create their own scenes. The JTE encourages students.\n\nClassroom tips: Encourage student creativity, correct grammar gently, and let the students be the stars. Remember to adapt to their ideas and adjust on the fly.","content_type":"activity","name":"Fun Faces","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Props","Utensils"],"topic_tags":["Role-play","Grammar practice"]},
  {"id":"scraped-altcir-handbook-fun-faces-bingo-071","text":"This activity focuses on listening and speaking practice. The teacher first draws a fun face on the board (or uses a prepared worksheet). Students then listen to the teacher describe the face, e.g., \"big eyes, small nose, one mouth\". After the description, students draw their own fun face, using the teacher's prompts. The teacher provides increasingly detailed descriptions, allowing students to check off elements as they draw. Alternatively, provide bingo worksheets. The teacher calls out a feature, shape or number and students mark it on their bingo sheet. The first student to complete their bingo sheet, shouts Bingo! This activity helps students learn and recall basic vocabulary related to facial features, shapes, and numbers, and it develops listening comprehension. For higher-level students, the teacher can encourage them to describe their own fun faces. Use larger flashcards to make them more visible. Classroom tip: Use simple and clear language. Adjust the speed of your descriptions to suit the students’ level. Encourage the students to ask questions if they don't understand.","content_type":"activity","name":"Fun Faces Bingo","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Bingo Worksheets (A4)","Completed Fun Faces Worksheet (A3) (Optional)","Fun Faces Worksheets (A4)","Number (1 - 10) Flashcards (A3 or Larger)","Shape Flashcards (A3 or Larger)"],"topic_tags":["Shapes","Numbers","Facial features","Listening Comprehension"]},
  {"id":"scraped-altcir-handbook-number-circle-chase-072","text":"This activity helps students practice numbers 1-10 and their order in a fun, active way. Students and the ALT sit in a circle. One student is the \"Oni\" (tagger) and walks around the circle clockwise, tapping each student on the head. As the Oni taps each student, they must say the numbers in order: 1, 2, 3, and so on, up to 10. If the \"Oni\" makes a mistake and says a number out of order, the tapped student chases the \"Oni\" around the circle. If the \"Oni\" reaches the empty spot in the circle first, the chaser becomes the new \"Oni.\" If the chaser catches the \"Oni\", the original \"Oni\" must try again. This activity targets listening and speaking skills. \n\nMaterials needed: None. \nClassroom tips: Make sure the circle is large enough to move around safely. Encourage students to cheer each other on. To extend the activity, you can increase the number range or add a small reward for a correct round.","content_type":"activity","name":"Number Circle Chase","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Numbers","Games","Speaking"]},
  {"id":"scraped-altcir-handbook-oni-game-073","text":"This activity focuses on listening and speaking practice of numbers. Students stand in a circle. One student is chosen to be the \"Oni\" (demon). The Oni closes their eyes while the other students count out loud together, starting from 1. The Oni then calls out a number (e.g., \"Five!\"). The Oni opens their eyes and tries to tag a student. If the Oni tags a student, that student becomes the new Oni. If the Oni fails to tag anyone before the count gets to ten, a new Oni is chosen. This game helps students practice number recognition and speaking fluency. It is helpful if other students count out loud, especially at first. This gives the \"Oni\" hints, and provides a useful model.\n\nLanguage skills targeted: Listening and Speaking\nSuitable Grade Levels: Elementary (Grade 5-6)\nMaterials Needed: None\nClassroom Tips: Encourage students to speak loudly and clearly. Remind the Oni to say the number with confidence, even if shy. Vary the pace for engagement.","content_type":"activity","name":"Oni Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Numbers","Games"]},
  {"id":"scraped-altcir-handbook-color-magnet-math-074","text":"This activity reviews numbers (1-20), colors, and basic math. Prepare by placing 20 or more colored magnets on the right or left side of the blackboard, divided into color groups (e.g., 5 pink, 5 blue, 5 red, 5 yellow). Write the initial number of each color on the board for reference. Tape a poster or paper over the magnets to hide them. Start the game by slowly moving one magnet behind the paper. Ask, \"How many are behind the paper?\" Students answer with the English number. Vary the game by moving multiple magnets or using subtraction. For subtraction, move magnets behind the paper, then remove some before asking. For increased difficulty, ask questions like \"How many red ones are behind the paper?\" This game targets listening and speaking skills, focusing on number recognition and simple math vocabulary in English.","content_type":"activity","name":"Color Magnet Math","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Colored magnets","Blackboard","Paper or poster","Tape"],"topic_tags":["Numbers","Colors","Math","Review"]},
  {"id":"scraped-altcir-handbook-magnet-directions-075","text":"This activity focuses on giving and following simple directions. Start by placing colored magnets randomly on the left and right sides of the whiteboard. Prepare a poster or paper to use as a target board, taping it to the side opposite the magnets. \n\n1.  **Introduce the concept:** Explain to students that they'll be listening to directions and moving magnets. Model the activity. Give the whole class a simple direction such as, \"Move a red magnet to the right side of the board.\" or \"Move a green magnet to the target poster.\"\n2.  **Guided practice:** Ask students to give each other simple directions. 'Move the blue magnet to the left'. 'Put the yellow magnet on the target paper.' \n3.  **Peer Interaction:** Divide students into pairs. One student gives directions, and the other student follows them. Switch roles. The student who is listening to the directions should be the first person to move the magnets as that will build up their confidence to speak out as well.\n\nThis activity targets listening and speaking skills, focusing on simple prepositions (left, right, on) and color vocabulary. Classroom tips: Keep instructions clear and simple. Use gestures to help clarify directions. Encourage students to repeat the directions before acting on them, such as 'Move the blue magnet to the left? Okay.' Modify the difficulty by increasing the complexity of the directions or adding more colors. For younger students, simplify by only using the left and right sides. For older students, add further prepositions (above, below, next to).","content_type":"activity","name":"Magnet Directions","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["colored magnets","poster or paper","tape"],"topic_tags":["directions","colors","prepositions","classroom objects"]},
  {"id":"scraped-altcir-handbook-magnet-math-076","text":"This activity focuses on practicing basic math and listening comprehension. The JTE or ALT secretly places magnets behind a piece of paper. Students listen and calculate how many magnets are hidden. \n\n1.  **Preparation:** Gather magnets and a piece of paper large enough to hide the magnets. Decide who will hide and reveal the magnets (teacher 1) and who will ask questions (teacher 2). \n2.  **Introduction:** Teacher 1 hides a specific number of magnets behind the paper while Teacher 2 asks the class, \"How many magnets are behind the paper?\" Teacher 1 can add or remove magnets without the students seeing. \n3.  **Gameplay:** Teacher 2 asks the class \"How many magnets now?\" after the first movement of the magnet. Students call out their answers. The teachers can then reveal the actual number of magnets. Repeat, varying the number of magnets and adding/subtracting them behind the paper.\n\nThis game targets listening and speaking skills, as students listen to the questions and speak their answers. It is suitable for grades 5-7. \n\nMaterials needed: Magnets, paper.\n\nClassroom Tips: Use a clear voice when asking questions. Provide simple addition/subtraction, suitable for the students' level.","content_type":"activity","name":"Magnet Math","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Magnets","Paper"],"topic_tags":["Math","Listening Comprehension"]},
  {"id":"scraped-altcir-handbook-number-and-color-chanting-077","text":"This is a simple review activity for numbers and colors. The teacher starts by chanting a number or a color. Students repeat the word. For elementary grades 3 and 4, the teacher can combine numbers and colors, e.g., \"One, Red!\" and the students must repeat. This activity is best used for review and is not recommended as an introduction to the topics. To motivate students, stickers can be awarded for correct answers. Adjust the pace and complexity based on the class's level. Focus on clear pronunciation and encourage active participation. For 1st and 2nd graders, only number review would be best.","content_type":"activity","name":"Number and Color Chanting","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":4,"complexity_max":1,"interaction":"Whole class","materials":["Stickers"],"topic_tags":["Numbers","Colors","Chanting"]},
  {"id":"scraped-altcir-handbook-number-action-game-078","text":"This activity helps students practice numbers 1-20 and incorporates physical actions. First, review numbers 1-20 by showing number cards, having students say the numbers, and repeating after them. Place the cards on the board in order and count again. Randomly point and have students identify the numbers. Next, introduce a chant with clapping, having students stand and participate. Introduce actions like jumping, spinning, or stretching on selected numbers, indicated by colored magnets or symbols. The ALT models the actions during the chant. Gradually, let students choose numbers and actions, ensuring they say the number aloud before selecting it.","content_type":"activity","name":"Number Action Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Magnetic number cards 1-20","Colored magnets/markers"],"topic_tags":["Numbers","Actions","Chants"]},
  {"id":"scraped-altcir-handbook-soccer-game-numbers-079","text":"This activity combines movement and number recognition. First, the teacher calls out a number from 1 to 20. Students must quickly perform an action corresponding to the number (e.g., jumping jacks for 5, touching toes for 10). The teacher can vary the actions or have students suggest them. Encourage students to chant the numbers, especially those they find difficult (like 14-19). If students are too rowdy, incorporate actions and numbers for specific students. For example: \"Taro, 8 push-ups!\" Follow this activity with number bingo for practice. Use a number-related picture book to calm students down after this high-energy activity. The primary goal is to help elementary school students associate numbers with actions, making learning fun and memorable, particularly helping students with spoken numbers.\n\nLanguage skills targeted: Listening and Speaking\nSuitable grade levels: 5-7\nMaterials needed: None\nClassroom tips: Be very energetic. Leave out tricky numbers (14-19) at first.","content_type":"activity","name":"Soccer Game Numbers","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["Numbers","Action","Elementary School"]},
  {"id":"scraped-altcir-handbook-i-can-dice-game-080","text":"Divide the class into two teams. Each team aims to reach the opposing team's goal on the blackboard by rolling a die. If a team's roll allows them to reach or pass the goal, they score a point, and the game restarts. The team with the most points at the end wins. Flashcards with action verbs are placed between the goals. When a team lands on a flashcard space, the student must say 'I can...' followed by the verb on the card. The JTE and the rest of their team then repeat the phrase. This activity targets speaking skills and reinforces the use of 'I can' sentences with different verbs. It promotes teamwork and active participation.","content_type":"activity","name":"I Can… Dice Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Dice","Flashcards with action verbs","Blackboard or whiteboard","Markers"],"topic_tags":["Verbs","Speaking","Games"]},
  {"id":"scraped-altcir-handbook-soccer-verbs-081","text":"This activity reviews verbs using a soccer-themed game. First, the ALT sets up the 'field' by drawing two goals on the board and placing verb flashcards in between. Two soccer player figures (with pictures of famous players) are placed on the goals. The ALT then introduces the game. Students roll a large die. If the die lands on an even number, one team moves a soccer player toward a verb flashcard. If the die lands on an odd number, the other team moves their player. The first team to reach a verb flashcard must make a sentence using the verb (e.g., \"I swim.\"). If the sentence is correct, they 'score' by taking that flashcard, but if incorrect, the flashcard is replaced. The game continues until all the verbs are used. The activity targets speaking and listening skills, specifically verb usage and sentence construction. Classroom tip: encourage teams to help each other with sentence formation.","content_type":"activity","name":"Soccer Verbs","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Soccer player cutouts","Large dice","Verb flashcards","Markers/chalkboard"],"topic_tags":["Verbs","Sports","Game","Sentence building"]},
  {"id":"scraped-altcir-handbook-how-are-you-gesture-game-082","text":"This activity focuses on practicing the question 'How are you?' and related responses with gestures. The class can be divided into two or more teams. Prepare flashcards with various 'How are you?' responses (e.g., 'I'm happy', 'I'm sad', 'I'm sleepy'). Each team takes turns choosing a flashcard. The first student must act out the emotion or feeling on the flashcard using gestures. The team then collectively asks, 'How are you?' and the student responds with the corresponding phrase. When all team members have spoken their lines and made the correct gesture, they advance one space. If the class is large, divide the class into four groups and introduce yellow and red cards to make the game more competitive. If two teams land on the same flashcard, they do a 'janken' (rock-paper-scissors) and the losing team gets a yellow card and must move back a space. A second loss results in a red card and the team must move back to their starting point, chanting all the sentences on the flashcards. Change the flashcards on the board after a goal is scored to add variety. Language skills targeted: Speaking, Listening. This activity is appropriate for Grades 5-7. Materials needed: flashcards with 'How are you?' responses; optional: yellow and red cards. Classroom Tips: Encourage enthusiastic gestures. Make sure students repeat the sentences several times.","content_type":"activity","name":"How Are You? Gesture Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["flashcards","yellow cards (optional)","red cards (optional)"],"topic_tags":["greetings","emotions","games"]},
  {"id":"scraped-altcir-handbook-how-are-you-game-083","text":"This activity helps students practice asking and answering \"How are you?\" while using gestures to express feelings. First, introduce and practice several feeling responses (e.g., \"I'm happy,\" \"I'm sad\") with corresponding gestures (e.g., smiling, crying). Next, students play \"Rock, Paper, Scissors\" in pairs. The winner asks the loser, \"How are you?\" The loser responds with a feeling gesture. The winner guesses the feeling. If the winner guesses correctly, the loser gives the winner a point card. If the winner guesses incorrectly, nothing happens. Students collect point cards throughout the game. The student with the most cards at the end wins. This activity targets speaking and listening skills, reinforcing vocabulary related to feelings and promoting interactive communication. Classroom tip: Pre-teach the feeling vocabulary and gestures clearly. Circulate and provide support. Adjust point card numbers or game time based on class size.","content_type":"activity","name":"How Are You? Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Point cards","None"],"topic_tags":["Feelings","Greetings","Game"]},
  {"id":"scraped-altcir-handbook-emoticon-points-084","text":"This activity involves students collecting point cards with different emoticon faces. Each student receives three point cards. The teacher can use this as a reward system, awarding cards for good behavior, participation, or correct answers during other lessons. Students are motivated by collecting their favorite emoticon faces. The activity targets positive reinforcement and encourages participation in various lessons. The teacher can specify when the cards are given out, thus also allowing for listening and following directions. This game would work well as a reward at the end of a lesson to review key concepts. The game can be adjusted to fit the subject matter in the main lesson. Materials needed are point cards with different emoticon faces, three per student. Classroom tips: Laminate the cards for durability. Consider making multiple decks for larger classes or multiple lessons. Adapt the point system to specific learning objectives, such as awarding points for correct answers or good behavior. The game may be slightly less engaging for students in higher grades.","content_type":"activity","name":"Emoticon Points","activity_type":"Filler","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Point cards with emoticon faces (3 per student)","Laminator (Optional)"],"topic_tags":["Behavior Management","Rewards","Interaction"]},
  {"id":"scraped-altcir-handbook-gesture-guessing-085","text":"This activity focuses on non-verbal communication and vocabulary related to actions. One student silently acts out a gesture while the others guess what it is. The teacher (ALT or JTE) prepares a set of point cards for each student at the beginning of the lesson. The student acting out the gesture earns a point if someone guesses correctly. If nobody guesses correctly, or if the guess is wrong, the person acting out the gesture does not earn a point. The teachers, both the ALT and JTE, actively participate and demonstrate gestures. Students can challenge the teachers for point cards if they run out. Even if a student loses the challenge, the teacher provides a point card for participating. This encourages students to keep playing even when they run out of cards. This can incorporate vocabulary related to body parts (e.g. hand, arm, leg) or action verbs (e.g. run, jump, eat).","content_type":"activity","name":"Gesture Guessing","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Point Cards","Prepared list of gestures (optional)"],"topic_tags":["Actions","Non-verbal communication","Vocabulary"]},
  {"id":"scraped-altcir-handbook-animal-sounds-guessing-086","text":"This activity helps students practice listening comprehension and pronunciation while learning about different animals. The ALT will prepare a list of animals (e.g., dog, cat, cow, bee) and their corresponding sounds. The teacher will then read the animal sounds aloud, and the students, working individually or in pairs, must write down the animal they think is making the sound. \n\nBefore the activity, teach the students how to say the animal names (dog, cat, cow, bee) correctly (not in Katakana English). This is a good opportunity to emphasize correct pronunciation and the differences between Japanese and English phonetics. You could even play the sounds beforehand, and have students try to guess. After the students have had time to write down their answers, review the answers as a whole class, pronouncing the animal names clearly. For extra points, have the students write the animal names in English using a vocabulary worksheet, and create their own animal sound. This can also be done as a warm-up activity. This activity targets listening comprehension and pronunciation. It also helps students learn new vocabulary.\n\nMaterials needed include a list of animals, paper and pencils or worksheets for the students.","content_type":"activity","name":"Animal Sounds Guessing","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["animal sound list","paper/worksheets","pencils"],"topic_tags":["animals","pronunciation","listening comprehension"]},
  {"id":"scraped-altcir-handbook-onomatopoeia-match-087","text":"This activity targets listening and speaking skills through associating English onomatopoeia with corresponding pictures. \n\n**Instructions:**\n1.  Prepare a handout with numbered pictures of animals, objects, or actions that have distinct onomatopoeia (e.g., a dog, a cat, a cow). Include the English onomatopoeia next to the picture.\n2.  Call out an English onomatopoeia sound.\n3.  Students listen and identify the corresponding picture number.\n4.  Students raise their hands or call out the number. The first student to answer correctly gets a point (optional).\n5.  Repeat with different onomatopoeia.\n6.  Review the sounds and pictures as a class.\n\n**Language Skills:** Listening, Speaking\n\n**Suitable Grades:** 5-7\n\n**Classroom Tips:**\n*   Use clear pronunciation and varied intonation.\n*   Encourage students to repeat the onomatopoeia after you.\n*   Adjust the difficulty by using more or less challenging onomatopoeia.\n*   Make it a game with teams for extra motivation.","content_type":"activity","name":"Onomatopoeia Match","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Pictures of objects with onomatopoeia","Pen/pencil (optional)"],"topic_tags":["Animals","Sounds","Listening"]},
  {"id":"scraped-altcir-handbook-mother-may-i-088","text":"This activity focuses on practicing English vocabulary, particularly animal or object names. Begin by ensuring students are familiar with the English names of the chosen items. The activity's length depends on the number of pictures used. Prepare a stopwatch to manage time effectively. Students can work individually, or for added engagement, divide the class into teams to foster a competitive environment. The teacher acts as 'Mother' and calls out 'Mother May I?' followed by a command (e.g., 'Touch the cat.'). If the student(s) perform the action correctly and the teacher responds 'Yes, you may!', the students score a point. If the action is performed without the teacher's permission ('Mother May I?'), the team loses a point. Focus is on listening to the instructions and responding with correct vocabulary.","content_type":"activity","name":"Mother May I","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["Animals","Objects","Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-the-passport-game-089","text":"The Passport Game is a fun activity to get students moving and speaking. First, divide the class into two or more teams. Designate a starting line and a finishing line. Each student gets a 'passport' (a small piece of paper). On your signal, the first student from each team runs (or hops, skips, crawls, etc. - specify beforehand!) to the finish line, where a teacher or designated student checks their passport (e.g., asks \"What's your name?\"). After answering, the student runs back to their team and gives the passport to the next person. The first team to have all members complete the 'journey' wins. This activity targets speaking (answering simple questions), listening (following instructions), and gross motor skills. Suitable for grades 5-7. Materials needed: passport paper, a pen or marker. Classroom tips: demonstrate the actions clearly, and manage potential rowdiness by clearly explaining and enforcing the rules.","content_type":"activity","name":"The Passport Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["passport paper","pen or marker"],"topic_tags":["games","speaking","listening","kinesthetic"]},
  {"id":"scraped-altcir-handbook-passport-stamp-090","text":"This activity helps students practice self-introductions in a fun, game-like format. Students first create their own 'passport' with their name, age, and a simple self-portrait. Next, the teacher or another student asks them three simple questions: \"What's your name?\", \"How old are you?\", and \"Where are you from?\". If the answers are understood, the student receives a stamp. The activity continues until students collect a set number of stamps. This reinforces basic question and answer skills, listening comprehension, and speaking fluency. It's suitable for elementary school students. Classroom Tip: Prepare the passport sheets in advance to save time. Encourage students to help each other with corrections. Provide a model answer for each question beforehand to aid with pronunciation and common responses.","content_type":"activity","name":"Passport Stamp","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Passport sheets","Stamps","Pens/Pencils"],"topic_tags":["Self-introductions","Questions & Answers","Elementary"]},
  {"id":"scraped-altcir-handbook-passport-game-091","text":"This activity helps students practice introducing themselves and answering basic questions about their name, age, and nationality. First, teach the expressions: \"My name is X,\" \"I'm Y,\" and \"I'm from Z.\" Then, students practice each expression with 5 different partners, alternating who asks and answers. For example, Student A asks Student B, \"What's your name?\" Student B answers, \"My name is...\" Repeat for age and nationality. \n\nNext, introduce the \"Passport Game\". Each student receives a \"Passport Game\" worksheet (a simple worksheet with spaces for the name, age, and nationality, and stamp areas). Students mingle and ask each other the questions. When a student correctly answers the question, the asker stamps the passport. Students aim to get stamps from different classmates. This encourages active listening and speaking. The teacher circulates, provides support and corrections. This game focuses on speaking and listening comprehension. It helps solidify basic self-introduction skills. \n\nClassroom Tips: Ensure students understand the target language before starting the game. Model the questions and answers. Monitor student interactions and provide positive reinforcement. Encourage students to use the target language and not switch to Japanese.","content_type":"activity","name":"Passport Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Passport Game worksheet (1/student)","Rubber stamps (2/teacher)"],"topic_tags":["Introductions","Speaking Practice","Listening Comprehension"]},
  {"id":"scraped-altcir-handbook-passport-stamp-hunt-092","text":"This activity encourages students to practice introducing themselves and asking where people are from. First, students create a passport with their name, age, and nationality. The ALT and JTE should model this. Next, students move around the classroom, asking each other \"What's your name?\" and \"Where are you from?\" Upon successfully answering, students stamp each other's passports. The goal is to collect as many stamps as possible. The teacher should monitor and provide corrections and encouragement. JTE participation is vital to create a comfortable atmosphere. The target language skills are speaking and listening. The activity is suitable for 5th to 7th grade. Materials needed: Passports (printed with name, age, and nationality sections), stamps. Classroom tips: Encourage students to not be afraid of mistakes. Have a meeting with the JTE to explain the lesson beforehand.","content_type":"activity","name":"Passport Stamp Hunt","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Passports","Stamps"],"topic_tags":["Introductions","Nationality"]},
  {"id":"scraped-altcir-handbook-how-many-093","text":"This activity focuses on practicing the question 'How many...?' and numbers. First, review 'How many?' and numbers 1-31 with the class. Next, prepare a set of flashcards with pictures of items (e.g., apples, pencils, erasers).  Divide the class into pairs. One student in each pair picks a flashcard and asks their partner, \"How many (apples/pencils/erasers)?\" The partner answers, \"One,\" \"Two,\" etc., up to 31.  Students then switch roles.  For a challenge, you can introduce different units, like 'How many days in a month?' or 'How many fingers on one hand?' Suitable for students who have a basic understanding of numbers and the target question structure. \n\nMaterials: Flashcards with pictures of items, or use drawings on the board.","content_type":"activity","name":"How Many?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Flashcards (pictures of items)"],"topic_tags":["Numbers","Questions","Pair work"]},
  {"id":"scraped-altcir-handbook-chopper-card-game-094","text":"Students are given three cards with varying numbers of Chopper men, where big Chopper represents ten and small Chopper represents one. As a warm-up, students practice counting the numbers on their own cards aloud. Students then mingle to find partners, changing partners frequently. They play 'Rock, Paper, Scissors' to determine who asks the question. The loser asks, \"How many Chopper men?\" The winner answers. If correct, the loser gives a card to the winner. If incorrect, the loser says \"No, Sorry!\" and finds a new partner. The student with the most cards at the end wins. The activity targets listening and speaking skills, and reinforces number recognition. It's suitable for elementary school students. Materials needed: Chopper men cards (pre-made or to be drawn by the students). Classroom tip: Encourage students to use full sentences when asking and answering the questions.","content_type":"activity","name":"Chopper Card Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Chopper cards"],"topic_tags":["Numbers","Games","Speaking"]},
  {"id":"scraped-altcir-handbook-chopper-men-counting-095","text":"This activity focuses on number recognition and counting, ideal for elementary students. Prepare Chopper men cards beforehand by finding images online and photocopying them multiple times. Each card should have a different number of Chopper men. Laminate the cards for durability. The aim is for students to count the Chopper men on each card. \n\n**Activity Steps:**\n1.  Distribute the Chopper men cards to students individually or in pairs.\n2.  Instruct students to count the Chopper men on their cards.\n3.  Students then say the number out loud (e.g., \"Five Chopper men!\").\n4.  You can vary the activity by asking them questions like, \"How many Chopper men?\" or \"Can you count them?\"\n5.  For advanced students, incorporate simple addition or subtraction questions based on the number of Chopper men.\n\nThis targets the listening and speaking skills. Consider focusing on numbers students find difficult. This activity is a great warm-up or filler.","content_type":"activity","name":"Chopper Men Counting","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Chopper men cards","Laminator (optional)","Photocopier"],"topic_tags":["Numbers","Counting","Warm-up","Elementary"]},
  {"id":"scraped-altcir-handbook-alt-jte-collaboration-prep-096","text":"This isn't an activity itself, but a preparation guide for the ALT and JTE. The ALT creates the cards for a game. The ALT demonstrates the game and assists students. The JTE co-demonstrates the game with the ALT and addresses student questions. Both teachers should participate. Before starting, the ALT and JTE should discuss the content for the cards together. This activity doesn't directly target any specific language skills or grade level, but it is a prerequisite for a classroom activity. \n\nClassroom Tips: Communication between the ALT and JTE is crucial. The card content discussion ensures alignment and appropriateness. Participating in the game helps model the behavior and encourages engagement.","content_type":"activity","name":"ALT/JTE Collaboration Prep","activity_type":"Filler","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":1,"interaction":"Pairs","materials":["Cards (created by ALT)","Game materials (determined by the game)"],"topic_tags":["Collaboration","Preparation","ALT/JTE"]},
  {"id":"scraped-altcir-handbook-number-card-game-097","text":"This is a fun game to practice number recognition and listening skills. First, create cards with different numbers written on them (e.g., fifteen, thirty). You can use pictures of characters the students love on the cards to increase engagement. Distribute the cards to the students. The teacher calls out a number, and any student with that number on their card must stand up and say the number. The first student to correctly say the number can give their card to the teacher. Continue calling out numbers until one student has no cards left, or for a set amount of time. You can play along with the students and offer assistance. At the end of the game, praise and reward the student with the fewest cards, and encourage students with no cards to keep trying. This activity targets listening and speaking skills, suitable for grades 5-7. Materials needed: Number cards with pictures of characters.","content_type":"activity","name":"Number Card Game","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Number cards with character pictures"],"topic_tags":["Numbers","Listening","Games"]},
  {"id":"scraped-altcir-handbook-fruits-basket-what-do-you-like-098","text":"This is a fun game to practice asking and answering \"What do you like?\" and \"I like...\". After drilling the target language in pairs and small groups, arrange chairs in a circle. One student stands in the center. Students in the circle are assigned a fruit (e.g., apple, banana, orange). The student in the center asks, \"What fruit do you like?\" Students who are that fruit must stand up and quickly find a new seat. The person in the center tries to sit in an empty chair. The person left standing becomes the new questioner. After a few rounds, switch to different vocabulary, like sports or animals. This activity targets speaking and listening skills. Suitable for grades 5-7. Requires chairs and a list of vocabulary items. Classroom tip: pre-teach the vocabulary and model the target language before playing.","content_type":"activity","name":"Fruits Basket - What do you like?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Chairs","Vocabulary list (fruit, sports, animals)"],"topic_tags":["Likes/Dislikes","Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-i-like-099","text":"This activity focuses on practicing the key sentences \"What fruit do you like?\" and \"I like...\" while also reviewing vocabulary for fruits, sports, or animals. Begin by introducing and practicing the target vocabulary using picture cards. Next, model the key sentences with the JTE, explaining the meaning simply and checking for understanding (with Japanese explanations if needed). Then, have students practice the sentences in pairs, followed by group practice where they move around the classroom, interacting with several classmates. Both the ALT and JTE should participate and offer support. Finally, play a game where the students use the sentences. The ALT explains the rules and ensures understanding with the JTE. The ALT starts in the center of the game.","content_type":"activity","name":"I Like...","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Picture cards (fruits, sports, animals)"],"topic_tags":["Fruits","Animals","Sports","Questioning","Conversation"]},
  {"id":"scraped-altcir-handbook-gesture-feeling-race-100","text":"This activity helps students practice vocabulary related to fruits, sports, or animals, and key sentences. The teacher (ALT or JTE) prepares flashcards or pictures of the chosen vocabulary items. Students are divided into teams. The teacher shows a flashcard to one student from each team. Without speaking, the student must use gestures to act out the item on the card. Their team tries to guess what it is. The first team to guess correctly gets a point. Continue with different vocabulary items, rotating students from each team. If students struggle with the vocabulary or key sentences, practice them beforehand. This game focuses on receptive skills for the team, and production skills for the student gesturing.\n\nSuitable for elementary grades.\n\nMaterials needed: Flashcards or pictures of fruits/sports/animals.\n\nClassroom tips: Encourage the teacher to provide example gestures. Keep the pace quick to maintain engagement.","content_type":"activity","name":"Gesture Feeling Race","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":2,"interaction":"Groups","materials":["Flashcards","Pictures"],"topic_tags":["Vocabulary","Games","Elementary"]},
  {"id":"scraped-altcir-handbook-feeling-charades-101","text":"Divide the class into three groups, with one teacher per group. Students line up. The first student faces the second. The teacher shows the first student a feeling card (e.g., happy). The first student acts out the feeling silently. The teacher asks the second student, \"How are you?\" The second student answers based on the gesture (e.g., \"I'm happy.\"). If correct, the first student goes to the back, and everyone moves up. The second student now gestures. Use different cards each round. To add challenge, set a time limit (e.g., two minutes). Groups count correct answers at the end.","content_type":"activity","name":"Feeling Charades","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Feeling cards"],"topic_tags":["Feelings","Emotions","Charades"]},
  {"id":"scraped-altcir-handbook-anime-character-drawing-game-102","text":"This activity aims to reinforce color and clothing vocabulary while practicing descriptive English. Begin by reviewing colors and clothing items. Draw 4-6 stick figures on the board, depending on the number of teams. Divide the class into teams, and choose two students from each team: one drawer and one explainer. Before the round, take the explainers into the hallway and show them a picture of an anime character with a clear outfit. Review each clothing item. Return to the classroom, start a countdown, and have the explainers describe the outfit in English to their drawers. Students in the audience can raise their hands to guess the anime character. After the character is identified, allow 30 seconds for the drawing to be completed. Award points to teams for the fastest correct guess and the best drawing. Rotate roles until everyone has a chance to participate as a drawer and explainer. This activity targets listening and speaking skills, and improves students’ descriptive abilities.","content_type":"activity","name":"Anime Character Drawing Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Markers","Whiteboard or Blackboard","Pictures of anime characters"],"topic_tags":["Colors","Clothing","Description"]},
  {"id":"scraped-altcir-handbook-character-description-103","text":"This activity helps students practice describing characters using adjectives and color vocabulary. First, prepare printouts of popular anime characters like Mario, Luffy, Naruto, and Sailor Moon. Also, have clothing and color flashcards ready. \n\n1.  **Warm-up (2 minutes):** Review colors and clothing vocabulary with the flashcards. Elicit and drill pronunciation.\n2.  **Introduction (3 minutes):** Display the anime character printouts. Explain that the students will describe the characters. Model the activity, for example: \"Mario is wearing a red hat. He has blue overalls.\" \n3.  **Pair Work (7 minutes):** Divide students into pairs. Give each pair an anime character printout. Students take turns describing the character to their partner using colors and clothing vocabulary. Encourage them to write down what their partner says using the chalk, if possible.\n4.  **Wrap-up (3 minutes):** Invite a few students to share their descriptions with the whole class. Correct any errors and provide positive feedback. This reinforces the learned vocabulary and grammar.\n\nThis activity targets speaking skills and reinforces listening as students listen to their partner's descriptions. It's suitable for elementary school and lower junior high school students. Classroom tip: Encourage students to use full sentences and provide visual aids (pictures).","content_type":"activity","name":"Character Description","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Coloured chalk","Anime character printouts","Clothing and colour flash cards"],"topic_tags":["Adjectives","Colors","Clothing","Characters"]},
  {"id":"scraped-altcir-handbook-clothing-charades-104","text":"This is a fun activity to review clothing vocabulary and practice speaking. \n\n1.  **Preparation**: Before the activity, review clothing vocabulary with the class. Create simple stick figures on the board representing different characters or scenarios. Prepare a list of clothing items and colors.\n2.  **Explanation**: Explain the rules of the game to the students.  Divide the class into groups and select a student from each group to be the 'drawer'. The drawer goes to the hallway with the ALT for a quick training session where the ALT explains the costume/item of clothing that the drawer will draw. Other students in the group act as guessers. The ALT will monitor the drawers to ensure they understand their instructions. \n3.  **Gameplay**: The ALT whispers the name of a clothing item (e.g., \"red hat\") to a 'drawer'. The drawer must draw the clothing item on the stick figure on the board, while their team tries to guess. The drawer cannot speak. The first team to guess correctly wins a point.  The JTE can help clarify any Japanese needed.\n4.  **Wrap-up**: Award points for the fastest guess and the best drawing. Review the vocabulary again at the end.\n\nThis activity targets speaking (vocabulary, describing), listening (understanding instructions, guessing), and basic drawing skills. \n\n**Classroom Tips:** Use simple vocabulary and descriptions at the elementary and early junior high levels. Encourage students to use English as much as possible.","content_type":"activity","name":"Clothing Charades","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Whiteboard","Markers","List of clothing items"],"topic_tags":["clothing","vocabulary","speaking"]},
  {"id":"scraped-altcir-handbook-anime-character-dress-up-105","text":"This activity is a fun way to practice describing clothing and encouraging English use. First, the teacher prepares several drawings of anime characters, each with a unique outfit. One student is selected to be the 'model' and sits in front of the class. The remaining students are divided into teams. The teacher then reveals the anime character drawing to the class (but not the model). Teams discuss and try to describe the character's clothing in English. They must tell their model what to put on (e.g., \"Put on the red hat!\"). The model must follow their instructions. After each instruction, the model sits back down, and the next team gets a turn. The team that correctly guesses the outfit first wins a point. Repeat the activity with different anime characters. This game targets speaking and listening skills, encourages descriptive language, and is suitable for elementary school students. Materials needed are anime character drawings and optional prizes. Classroom tip: Encourage English use by listening for it from both the model and the other students. Pre-teach vocabulary for uncommon clothing items.","content_type":"activity","name":"Anime Character Dress-up","activity_type":"Main Game","skill":"Speaking","duration_minutes":20,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Anime character drawings","Prizes (optional)"],"topic_tags":["Clothing","Description","Anime"]},
  {"id":"scraped-altcir-handbook-my-special-lunch-pizza-making-106","text":"This activity focuses on experiential learning by having students design and 'make' their ideal pizza. First, introduce or review pizza-related vocabulary (e.g., ingredients like cheese, tomato sauce, pepperoni). Students then design their pizzas, either individually or in pairs, by drawing and labeling the ingredients they want. Provide a worksheet or template to guide them. Next, they practice speaking by describing their pizzas to a partner or the whole class: \"My pizza has cheese, tomato sauce, and mushrooms.\" Students can then 'make' the pizzas using provided materials. Finally, they can role-play eating and enjoying their pizzas, practicing expressions like \"It's delicious!\" or \"I love pizza!\" This activity targets speaking and listening skills, builds vocabulary, and encourages creativity. It's best suited for Grade 5-7. Materials needed: paper, pencils/crayons, pizza template worksheet (optional), and vocabulary flashcards. Classroom tip: pre-teach key vocabulary and model the target language. For a more extended activity, consider adding a writing component where students write a short description of their pizza.","content_type":"activity","name":"My Special Lunch: Pizza Making","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["paper","pencils/crayons","pizza template worksheet (optional)","vocabulary flashcards"],"topic_tags":["food","vocabulary","speaking"]},
  {"id":"scraped-altcir-handbook-pizza-restaurant-107","text":"This activity allows students to practice ordering food and following instructions. It's suitable for 5th grade students who have already learned basic food vocabulary and phrases like \"What would you like?\", \"I would like...\", \"Here you are\", and \"Thank you.\" Students are divided into groups (around 6 students). In a previous lesson, they design their ideal pizza (using a concept from the Ego-Noto textbook). In this activity, students come up in groups and 'order' ingredients for their pizza, using the target language practiced in the warm-up. The teacher provides prepared ingredients and gives instructions (e.g., \"Add cheese.\"). Students follow the directions to make their own mini-pizzas. After the pizzas are cooked, the class cleans up and enjoys the pizzas. This approach connects textbook learning with a hands-on activity, enhancing comprehension and engagement.","content_type":"activity","name":"Pizza Restaurant","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":5,"complexity_max":2,"interaction":"Groups","materials":["Pizza dough","Pizza sauce","Toppings (cheese, vegetables, etc.)","Cooking utensils (knives, cutting boards)","Oven or cooking equipment"],"topic_tags":["Food","Ordering","Instructions","Cooking"]},
  {"id":"scraped-altcir-handbook-pizza-making-108","text":"This activity allows students to practice choosing and describing ingredients while making a pizza. Before class, the teacher (ALT/JTE) prepares the dough and sauce. Students are divided into groups and each group chooses two ingredients for their pizza (plus cheese). Students must then describe their pizza to the class using target language, such as 'I want pizza with pepperoni and mushrooms.' The teacher facilitates the activity by helping students with vocabulary and sentence structure. After the pizzas are baked, the class can enjoy the results and discuss them. The activity targets speaking and listening skills while reinforcing food vocabulary. Requires the use of a school kitchen.","content_type":"activity","name":"Pizza Making","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Dough","Pizza Sauce","Pizza toppings","Bowls","Spoons","Rolling Pins","Pizza Cutter","Oven"],"topic_tags":["Food","Cooking","Speaking"]},
  {"id":"scraped-altcir-handbook-where-is-it-109","text":"This activity practices location words and the question word \"where.\" A volunteer closes their eyes while the ALT hides an object in the classroom. When the object is hidden, the student opens their eyes and tries to find the object by listening to the ALT's instructions. The ALT gives clues using location words like \"under,\" \"over,\" and \"beside.\" The student asks \"Where is it?\" to practice the question. The student has three chances to guess the location. This prevents students from randomly searching or simply going to the object based on its name and reinforces listening comprehension. \n\nThis activity targets listening and speaking skills. It's suitable for elementary school grades, especially those focusing on prepositions of place. The only materials needed are a small object to hide. A classroom tip is to vary the difficulty by using different objects and more complex sentence structures as the students improve.","content_type":"activity","name":"Where is it?","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Small object"],"topic_tags":["Prepositions","Locations","Question words"]},
  {"id":"scraped-altcir-handbook-hide-and-seek-review-110","text":"This is a simple review game adaptable for various topics. Before class, hide a small, easily-transportable object somewhere in the classroom. Explain the rules: one student is 'it' and must close their eyes while the other students hide the object. The 'it' student opens their eyes and asks, \"Where is it?\" The other students respond with clues, using the target language you are reviewing (e.g., \"It's on the desk.\", \"It's behind the book.\", \"It's under the chair.\"). Encourage the other students to help the 'it' student find the object using increasingly specific clues. The first student to find the object becomes 'it' for the next round. This can be adapted to review prepositions, vocabulary, or simple sentence structures. For example, if reviewing colors, students can say \"It is red!\" or \"It is near the blue pen!\"","content_type":"activity","name":"Hide and Seek Review","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Small, hideable object"],"topic_tags":["Review","Vocabulary","Prepositions","Classroom objects"]},
  {"id":"scraped-altcir-handbook-classroom-object-commands-111","text":"This activity focuses on teaching and reinforcing basic classroom vocabulary and prepositions. The ALT explains and gives commands while students follow directions. Begin by teaching English names for common classroom objects (desk, table, chair, etc.) and location words (over, under, next to, etc.).\n\n1.  **Preparation:** Introduce classroom object vocabulary and location words. This can be done in a prior lesson or on the same day.\n2.  **Activity:** The ALT gives a command, such as \"Put the pencil *under* the desk!\" Students must quickly follow the direction. Other commands may include \"Touch the *table*!\" or \"Stand *next to* the chair!\" The JTE assists with instructions in Japanese and classroom management. The ALT should give clear commands with exaggerated pronunciation, and repeat as needed. The activity can be made competitive by having students race to follow the commands correctly.\n\nThis activity primarily targets listening comprehension and following instructions. It can also touch on production if the ALT asks students to repeat the instructions.","content_type":"activity","name":"Classroom Object Commands","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Vocabulary","Classroom Objects","Prepositions","Commands"]},
  {"id":"scraped-altcir-handbook-body-parts-bonanza-112","text":"This activity focuses on teaching and reinforcing body part vocabulary through a variety of engaging games.\n\nFirst, introduce the target vocabulary, using the board and your own body for demonstration. Encourage repetition to build comfort. (5 minutes)\n\nNext, conduct a quick quiz where students stand up and sit down based on the teacher's instructions. For example, the teacher says \"nose,\" and students touch their noses. (5 minutes)\n\nThen, play Simon Says using the learned body parts. This gets the students moving and practicing the vocabulary in context. (10 minutes)\n\nFinally, engage students in a collaborative drawing activity. Divide the class into groups. Each student receives a paper and draws a body part according to the teacher's command. Then they pass the picture to the next person in their group, who draws the next part, etc.  Continue until a complete and hopefully funny picture is created. The group with the funniest picture wins. (15 minutes)\n\nConclude by reviewing the vocabulary. Point to various body parts and ask individual students to name them. (5 minutes)\n\nThis activity targets speaking and listening skills while reinforcing vocabulary. It is suitable for elementary students.\n\nMaterials needed: whiteboard or chart paper, markers.","content_type":"activity","name":"Body Parts Bonanza","activity_type":"Main Game","skill":"Speaking","duration_minutes":40,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard or chart paper","Markers"],"topic_tags":["Body Parts","Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-picture-dictation-113","text":"This activity focuses on listening comprehension and speaking. Divide students into groups of 4-5. Each group needs one blank sheet of paper. One student in each group is the 'artist' and the others are 'listeners'. The teacher gives simple instructions (e.g., \"Draw a blue square in the middle of your paper.\", \"Draw a red circle above the square.\")  The listeners listen carefully and tell their artist what to draw. The artist cannot look at the teacher or other students' papers. After a few instructions, the teacher asks the artist to show their picture to the group and compare it to the others.  This promotes listening skills and giving instructions. Adjust complexity by varying sentence length and vocabulary (e.g., using prepositions like 'next to', 'on top of', 'between').","content_type":"activity","name":"Picture Dictation","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Blank paper per group"],"topic_tags":["Instructions","Shapes","Colors"]},
  {"id":"scraped-altcir-handbook-job-interview-114","text":"This two-lesson unit aims to practice listening and speaking job names and basic interview skills. Lesson 1: Students learn English job names (baker, farmer, artist, etc.) and choose one, including creating their own by asking the teacher. They complete a worksheet with their chosen job and a drawing. Lesson 2: Students participate in an interview game. The ALT provides a worksheet with a list of jobs, including some from lesson 1 and blank spots. Students interview classmates, greet them, and ask \"What do you want to be?\" recording their answers. The ALT tailors the interview list to include more challenging job names, and ensures all students participate, including quieter students. This customization makes the activity engaging and inclusive.","content_type":"activity","name":"Job Interview","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheets (job names, interview sheets)","Pencils/pens"],"topic_tags":["Jobs","Interview","Speaking"]},
  {"id":"scraped-altcir-handbook-card-game-greetings-quantifiers-115","text":"This activity reviews and practices English sentence structures, focusing on greetings and quantitative constructions (e.g., \"how many,\" plurals). Students begin with 2-3 playing cards each. They pair up and practice the target grammar with a partner. After practicing, they play rock-paper-scissors; the winner takes a card from the loser. This is one round. After each round, students find new partners and repeat the process for about 5 minutes, aiming for as many rounds as possible. Students without cards continue participating. At the end, the teacher counts the cards to review numbers and identifies the winner(s) who receive a sticker. This warm-up helps students become comfortable speaking English.","content_type":"activity","name":"Card Game Greetings & Quantifiers","activity_type":"Warm-up","skill":"Speaking","duration_minutes":5,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Playing cards","Stickers"],"topic_tags":["Greetings","Quantifiers","Review","Speaking"]},
  {"id":"scraped-altcir-handbook-card-call-out-116","text":"This activity uses playing cards to practice question and answer skills. First, prepare two decks of playing cards. Give each student 2-3 cards, depending on the class size. The students mingle, asking each other questions. The questions should be based on the card's suit and number (e.g., \"Do you have a club?\"). If the other student has the card, they say \"Yes, I do!\" and give the card to the questioner. If they don't have the card, they say \"No, I don't.\" and the questioner moves on. After a set time (e.g., 5-7 minutes), instruct students to count how many cards they have acquired. The student with the most cards at the end is the winner. This activity targets listening and speaking skills, and reinforces question formation and giving short answers. Classroom tip: pre-teach the question and answers using flashcards.","content_type":"activity","name":"Card Call Out","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Playing cards (2 decks)"],"topic_tags":["Questioning","Games","Conversation"]},
  {"id":"scraped-altcir-handbook-watermelon-smash-117","text":"This activity aims to practice sentence production and target grammar points. Before starting, review the target grammar or construction. Model the sentence structure and have students practice a few times. The game involves the JET and JTE participating along with the students. Encourage the JTE to provide feedback on the activity's effectiveness and clarity after the game. The game itself is not described, but it involves English speaking practice in an elementary school setting.\n\n*   **Language Skills:** Speaking\n*   **Suitable for:** Elementary Grades 5-6\n*   **Materials:** None specified\n*   **Classroom Tips:** Pre-teach or review the target grammar. Both JET and JTE participate.","content_type":"activity","name":"Watermelon Smash","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":6,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":[]},
  {"id":"scraped-altcir-handbook-watermelon-directions-118","text":"This activity helps students practice giving and understanding directions using prepositions of place and directional verbs. Divide the class into pairs. One student in each pair is blindfolded (they can also close their eyes), and the other student is the 'leader'. Place a large, soft object (the 'watermelon') in front of each pair. The leader must give directions to the blindfolded student to hit the watermelon with a stick or soft object. Examples of directions include: \"Go forward two steps.\", \"Turn right.\", \"Go left.\", \"Take one step back.\", \"Stop.\", and \"Hit the watermelon!\". Students take turns being the leader and the blindfolded person. This game focuses on listening and speaking skills, requiring students to clearly express themselves and listen carefully to instructions. Use a variety of directional vocabulary and body movement verbs for more advanced students. Consider using a timer to increase the fun and pace of the game. Make sure the playing area is clear of obstacles for safety.","content_type":"activity","name":"Watermelon Directions","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Blindfolds","Soft object (watermelon)","Stick or soft object"],"topic_tags":["Directions","Prepositions","Listening","Speaking"]},
  {"id":"scraped-altcir-handbook-watermelon-baseball-119","text":"This fun game helps students practice listening and speaking skills. Divide the class into two teams. One team lines up, and the other team spreads out in the \"field\". The teacher, or a student, acts as the pitcher. The pitcher rolls the \"watermelon\" (ball) towards the batter. The batter tries to hit the ball with their \"stick\" (rolled-up newspaper). If the batter hits the ball, they run around the bases (cones or designated spots). The fielding team tries to catch the ball and tag the runners. If the batter is tagged before reaching a base, they are out. If the batter makes it around all the bases, they score a run. If the batter misses the ball, they are out. After each batter, the teams switch roles. For an added challenge, blindfold the batter and have them listen for the ball and the \"fielders.\" For younger students, the bases can be closer together and the \"stick\" can be larger. The game targets listening and speaking through following directions and communicating with teammates. It’s also a good way to get students active and moving. The materials are simple and easy to prepare. Classroom tips: emphasize clear communication between teammates; encourage students to use English phrases like \"Run!\" or \"Catch!\"","content_type":"activity","name":"Watermelon Baseball","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Newspapers","Balls","Blindfolds"],"topic_tags":["Sports","Games","Teamwork"]},
  {"id":"scraped-altcir-handbook-blindfolded-watermelon-120","text":"This is a fun game for practicing directional vocabulary. First, the ALT and JTE review the target vocabulary: \"Go straight,\" \"go left,\" \"go right,\" \"go back,\" \"stop,\" and \"hit.\" The ALT explains the activity in English: Students form pairs. One student is blindfolded and holds a \"stick\" (a rolled-up newspaper or similar). The other student must direct their partner to find a \"watermelon\" (a ball or other object). The JTE can reiterate the instructions in Japanese as needed. The pairs take turns, with the non-blindfolded student giving directions and the blindfolded student trying to follow them. The ALT and JTE monitor the pairs, correcting any Japanese usage. Encourage students to use full sentences, e.g., \"Go straight two steps.\" Swap roles after a set time or after the watermelon is \"hit.\"","content_type":"activity","name":"Blindfolded Watermelon","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Blindfolds","Sticks (rolled-up paper)","Watermelon (or ball or object)","Vocabulary list"],"topic_tags":["Directions","Vocabulary","Pair work"]},
  {"id":"scraped-altcir-handbook-blindfolded-watermelon-game-121","text":"This activity focuses on giving and following directions in English. Students work in pairs, with one student blindfolded and the other giving instructions to guide their partner to a target, such as a watermelon. First, set up a course with obstacles. One student is blindfolded, and the other student stands a distance away. The guiding student uses directional vocabulary (e.g., \"Go forward,\" \"Turn left,\" \"Go right,\" \"Stop\") to lead their blindfolded partner towards the target. The goal is to reach the watermelon without touching any obstacles. This targets listening and speaking skills. For team relays, keep score. Encourage the guiding students to use only English. The teacher, along with the JTE, should monitor the students to make sure they are using only English, not Japanese. If needed, provide prompts for directional words. This activity reinforces spatial language and promotes teamwork. It's best if the watermelon is only hit by the end of the round or relay.","content_type":"activity","name":"Blindfolded Watermelon Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Blindfolds","Watermelon or other target","Obstacles"],"topic_tags":["Directions","Teamwork","Games"]},
  {"id":"scraped-altcir-handbook-business-card-exchange-122","text":"This activity aims to boost students' speaking confidence through a low-pressure exchange. First, students create their own business cards, writing their name, a simple 'job' (e.g., 'student', 'soccer player'), and a short phrase about themselves (e.g., 'I like video games').\n\nNext, students mingle and exchange cards. They must then use the information on the card to start a conversation with the card's owner, for example, 'Hello! Are you a student? Do you like video games?' or 'Hi! I like soccer too!'.\n\nThis activity targets speaking and encourages using simple greetings, asking questions, and sharing basic information. Adapt the 'job' and phrase complexity for different grade levels. For lower grades, provide sentence starters or example phrases. For older students, encourage more detailed information.\n\nMaterials needed: Paper or cardstock for business cards, pens/pencils. Classroom Tip: Circulate to help with any pronunciation or vocabulary struggles.","content_type":"activity","name":"Business Card Exchange","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper/cardstock","Pens/pencils"],"topic_tags":["Introductions","Speaking","Conversation"]},
  {"id":"scraped-altcir-handbook-meishi-introduction-123","text":"This activity introduces students to exchanging business cards (meishi) and practicing basic greetings and introductions. First, the ALT and JLT model a short dialogue where they exchange meishi. This demonstrates the correct language and gestures. Next, students receive a blank 'meishi' card template and use colored pencils to write and draw a little about themselves. Encourage them to include their name, a simple illustration, and their favorite color or hobby.  Then, students pair up and practice the modeled dialogue, exchanging their self-made meishi.  They can change partners several times to practice the dialogue with multiple classmates. The activity focuses on Speaking skills and encourages social interaction. Classroom tips: Circulate to provide support and correct pronunciation. Model the gesture of presenting and receiving the card correctly. Keep the dialogue simple and repetitive for younger learners.","content_type":"activity","name":"Meishi Introduction","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["meishi card template (blank)","sample dialogue","colored pencils"],"topic_tags":["greetings","introductions","cultural awareness"]},
  {"id":"scraped-altcir-handbook-meishi-card-introductions-124","text":"This activity focuses on introducing oneself using meishi (business cards). The ALT prepares model meishi cards and blank ones for students to complete. The JTE also prepares model meishi cards and provides translations. The ALT models a self-introduction, followed by the JTE. The JTE checks student understanding. Students then create their own meishi cards with information about themselves, with help from both teachers. Once complete, the ALT and JTE model a simple dialogue using the cards, which the students repeat. Finally, students practice the dialogue with the teachers and each other. This activity targets basic speaking skills and introduces the concept of self-introductions in a formal setting, using correct pronunciation and a simple dialogue. It's suitable for elementary and junior high school students. The JTE should provide Japanese translations as needed. The activity requires preparation of model meishi cards and blank meishi cards, and the dialogue written on the board. Classroom tips: Encourage students to practice good pronunciation. Walk around and offer help and suggestions to the students.","content_type":"activity","name":"Meishi Card Introductions","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Model meishi cards","Blank meishi cards","Whiteboard","Markers"],"topic_tags":["Introductions","Dialogue","Speaking","Meishi"]},
  {"id":"scraped-altcir-handbook-meishi-card-exchange-125","text":"This activity focuses on introducing oneself and exchanging 'meishi' (business cards). First, students prepare their own meishi cards with information they've learned in previous classes (name, age, country, likes/dislikes). This preparation can be done in a previous lesson. In the main activity, students practice a simple dialogue, role-playing as a JTE and ALT. The dialogue includes greetings, asking 'How are you?', and introducing themselves using the information on their cards. The dialogue is followed by the exchange of meishi cards and a handshake. The content of the cards and the dialogue should be adjusted to the specific vocabulary and grammar taught in each class. Encourage students to speak confidently and accept mistakes as a natural part of learning. Depending on class size, preparation and practice could take one lesson, with the actual exchange in the next. The dialogue to be used:\n\nA. JLT B. ALT\nA. Good Morning.\nB. Good Morning\nA. How are you?\nB. I'm fine thank you and you?\nA. I'm good thank you!\nB. My name is [Name]. I'm [age] years old! I'm from [country]! I like [hobby]. I don’t like [food]! Here is my card! Nice to meet you!\nA. My name is [Name]. I'm [age] years old! I'm from [city], [country]. I like [hobby]. I don’t like [food]. Here is my card! Nice to meet you too! (Exchange cards and handshake)","content_type":"activity","name":"Meishi Card Exchange","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Prepared meishi cards","Example meishi card for modeling"],"topic_tags":["Introductions","Greetings","Likes/Dislikes"]},
  {"id":"scraped-altcir-handbook-celebrity-interview-126","text":"This activity encourages students to practice asking and answering questions about daily routines. First, students choose a celebrity they want to be. Next, they brainstorm the celebrity's daily routine, writing down activities like 'wake up,' 'eat breakfast,' 'go to work,' etc. Then, the teacher models a simple interview, asking questions like \"What time do you wake up?\" and \"What do you eat for breakfast?\" Students then pair up and take turns interviewing each other, pretending to be their chosen celebrity. One student asks questions, and the other answers based on their prepared routine. The activity targets speaking and listening skills, focusing on using present simple tense. It is suitable for elementary school students. Materials needed include paper and pencils for brainstorming and writing down questions/answers. Classroom tips: Encourage students to be creative with their celebrity choices. Circulate and assist with vocabulary if needed. Remind students to speak clearly and listen carefully to their partners' responses.","content_type":"activity","name":"Celebrity Interview","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper","Pencils"],"topic_tags":["Daily Routine","Interview","Present Simple"]},
  {"id":"scraped-altcir-handbook-celebrity-routine-127","text":"This activity focuses on practicing daily routine vocabulary and telling time. First, the ALT posts pictures of 4 celebrities across the top of the blackboard. Below each picture, the ALT places 4-5 activity cards related to daily routines (e.g., \"wake up,\" \"eat breakfast,\" \"go to school\"). Next to each activity card, the ALT writes a time. The times should be similar for each celebrity's activities but not identical. The ALT then reads a celebrity's daily routine in the first person, e.g., \"I get up at 7:00.\" The students raise their hands and guess the celebrity's name, responding with \"You are [celebrity's name].\" Start with easy times and clear distinctions between routines. Modify the activity by including more difficult times and by delaying the final activity to increase suspense. Change the celebrities and activities to maintain student engagement. This activity targets listening comprehension and speaking skills, focusing on the vocabulary of daily routines and the ability to express the time. Classroom Tip: Prepare the visual aids (pictures and activity cards) beforehand for efficiency. Encourage students to listen carefully to the entire routine before guessing.","content_type":"activity","name":"Celebrity Routine","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Pictures of celebrities","Cards with daily activities","Markers","Blackboard or whiteboard"],"topic_tags":["Daily Routines","Time","Vocabulary","Listening Comprehension","Speaking"]},
  {"id":"scraped-altcir-handbook-celebrity-daily-routine-128","text":"This activity focuses on practicing daily routine vocabulary and asking/answering questions. First, show the celebrity pictures and briefly review the vocabulary by asking the class what activities they do. For example: \"What does Lady Gaga do in the morning?\" Elicit answers like \"She wakes up,\" \"She eats breakfast,\" etc. Then, stick the daily routine pictures on the board. Divide the class into pairs. One student chooses a celebrity and the other student asks, \"What does [celebrity name] do in the morning?\" The first student answers using the routine pictures as prompts and their previously learned vocab. Students switch roles after each turn. Circulate and monitor the pairs, providing support and correcting pronunciation as needed. For younger students, simplify by having them just use the routine pictures to describe the celebrity's day. For older students, encourage more complex sentences. Class tips: Keep the celebrity choices engaging. Use real-life pictures to make it more personal. Ensure clear pronunciation modeling. Provide sentence starters like \"[Celebrity] wakes up at...\" or \"[Celebrity] eats...\" to support students.","content_type":"activity","name":"Celebrity Daily Routine","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Celebrity pictures","Daily routine picture cards","Magnets (optional)"],"topic_tags":["Daily Routine","Celebrities","Speaking Practice","Questioning"]},
  {"id":"scraped-altcir-handbook-story-recitation-project-129","text":"This long-term project aims to improve simple conversation and narration skills. The ALT simplifies a well-known folk tale into English, breaking it into chapters for each lesson. The lesson begins with a full story recap (5 minutes), followed by rereading the chapter (1-2 minutes). A worksheet with English lines and a blank Japanese translation column is used. The ALT reads a line, students repeat, and try to guess the meaning in Japanese before the answer is revealed. (15-20 minutes). The Japanese meaning is then checked for all lines (5 minutes). Finally, the class reads the chapter together while acting it out (2 minutes). After several lessons, students memorize the story and prepare for group presentations. Groups can recite the story, create semi-original stories, or perform a play for Culture Day. The project is suitable for ES and JHS students as a final project. The materials needed are the simplified English story, worksheets, and optionally costumes and props for presentations. Classroom tips: Encourage teacher enthusiasm to bring the story to life. Focus on clear pronunciation and providing hints to aid comprehension. Adapt the final presentation based on class level, time, and teacher support. This was used with Momotaro in ES 6th year and was very successful.","content_type":"activity","name":"Story Recitation Project","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["simplified English story","worksheets","optional costumes/props"],"topic_tags":["storytelling","speaking","presentation","Japanese Culture"]},
  {"id":"scraped-altcir-handbook-travel-agents-130","text":"This activity practices the grammar point \"Where do you want to go?\" and \"I want to go to ~~.\" Divide the class into groups of four. One group will be the 'Travel Agents,' and the others are the 'Customers.' Place country flags face down on the students' desks randomly. The 'Travel Agents' come to the front, and the 'Customers' move to the back of the room. Model the target language with the agents and customers. Start a timer. The 'Travel Agents' ask the 'Customers' where they want to go and guide them to their 'destination' (the flag they pick). Once a customer is at their desk, the agent finds another customer. Continue this until all customers are at desks. Note the time. Rotate roles until each group has been 'Travel Agents'. The group with the fastest time wins. This focuses on speaking and listening.","content_type":"activity","name":"Travel Agents","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Country Flags","Timer"],"topic_tags":["Travel","Grammar","Speaking"]},
  {"id":"scraped-altcir-handbook-flag-grammar-game-131","text":"This activity focuses on practicing target grammar through a simple, engaging game. Prepare sets of flags (real or drawn) representing different countries. Divide the class into groups. Each group receives a set of flags. The ALT or HRT states a sentence using the target grammar (e.g., \"This flag is from Italy.\"). Students in each group discuss, pointing to the corresponding flag, and repeating the sentence. The first group to correctly identify the flag earns a point. The teachers can circulate, listen to the groups, offering corrections or prompting the use of English. The activity targets speaking and listening skills, reinforcing grammar in a context that requires both. The focus is always on the target grammar. Suitable for grades 5-7. Materials needed: sets of flags (printed or drawn). Classroom tip: Encourage the ALT to use gestures, or props related to the countries to keep the students more engaged.","content_type":"activity","name":"Flag Grammar Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":["Flags (printed or drawn)"],"topic_tags":["Grammar","Countries","Speaking"]},
  {"id":"scraped-altcir-handbook-missing-month-132","text":"This activity helps students practice new vocabulary in a game format. Prepare flashcards with the English names of the months before class. Start with a 5-10 minute pronunciation practice session with the students, then place the flashcards on the chalkboard. Divide the class into two teams. In each round, two students (one from each team) come to the front and close their eyes while the ALT removes one flashcard. The students open their eyes and try to identify the missing month. The first student to answer correctly earns a point for their team. The team with the most points wins. The activity can be adjusted based on the size and enthusiasm of the class. The primary focus is on speaking and listening comprehension of the target vocabulary.","content_type":"activity","name":"Missing Month","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":["Flashcards (months of the year)","Chalkboard/Whiteboard","Markers/Chalk"],"topic_tags":["Months","Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-month-order-133","text":"This activity focuses on ordering months in English. Prepare 12 laminated A4 sheets, each with a month's name and its corresponding number (January = 1, February = 2, etc.). Attach magnets or tape to the back of the sheets. \n\nBefore the game, review the months using flashcards. Show the month flashcards and have students repeat after you. To play the game, scramble the sheets on the chalkboard. Divide the class into teams. Call out a month (e.g., \"May!\"). The first team to correctly send a student to the board to place the month card in the correct order (5th position) earns a point. Continue calling out months randomly until all months are in order. The team with the most points wins. \n\nThis targets listening comprehension and speaking, especially pronunciation. It's suitable for elementary school grades, focusing on vocabulary. Classroom tips: Ensure the months are clearly visible, and provide positive reinforcement for correct answers. Consider modifying it for younger students by focusing only on the first six months.","content_type":"activity","name":"Month Order","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Laminated month cards (A4)","Magnets or tape","Month flashcards"],"topic_tags":["Months","Vocabulary","Speaking","Games"]},
  {"id":"scraped-altcir-handbook-find-your-partner-134","text":"This warm-up activity helps students practice listening and following directions. Before class, prepare sets of cards. Each card in a set has a matching partner card. Prepare the cards by writing simple instructions or questions on each. For example, 'Find someone who likes pizza.' or 'Find someone who has a dog.' During class, distribute the cards randomly to the students. Instruct students to walk around the classroom and ask each other the questions or follow the instructions on their cards. Their goal is to find the person with the matching card. Once they find their partner, they can sit down or raise their hands. The activity can be adapted by using the chalkboard and colored chalk instead of laminated sheets. It is better if the front of the classroom is cleared of desks so the students can comfortably stand while they wait for instructions.","content_type":"activity","name":"Find Your Partner","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Cards","Chalkboard (optional)","Colored chalk (optional)"],"topic_tags":["Pair work","Speaking practice","Elementary"]},
  {"id":"scraped-altcir-handbook-alphabet-pairs-135","text":"This activity helps students practice the question \"Do you have ~?\" and the responses \"Yes I do.\" or \"No I don't.\" while reviewing the alphabet. First, determine the number of students in the class. Divide that number by two and count that many letters down the alphabet. For example, if there are 26 students, use letters A through M. Prepare pairs of alphabet letter cards (A-M) and shuffle them together. Add one extra letter card that doesn't have a matching pair. Distribute the 27 cards to the students and the teacher. Students stand up and mingle, asking each other \"Do you have (letter)?\" If a student has the matching card, they respond \"Yes I do!\" and both students sit down. If not, they respond, \"No I don't\" and continue searching for their partner. The student left without a matching pair wins a sticker and the opportunity to give a short self-introduction in English. This activity targets speaking and listening skills and is suitable for 5th to 7th grade students.","content_type":"activity","name":"Alphabet Pairs","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Alphabet letter cards","Stickers"],"topic_tags":["Alphabet","Questioning","Partner work"]},
  {"id":"scraped-altcir-handbook-alphabet-card-pairs-136","text":"This activity focuses on alphabet recognition and basic conversational practice. Students use laminated alphabet cards (prepared by the teacher) to practice simple question-and-answer exchanges. \n\n1.  **Preparation:** The teacher (HRT and/or JET) prepares a set of laminated alphabet cards. Choose letters students need to practice. A good number is one set per pair of students.\n2.  **Demonstration:** The HRT and JET model the target conversation using two sets of the same letter. Then they show a different set, modeling a different conversation. For example:\n    *   **Same Letter:**\n        *   Student A (holding A): \"What letter is this?\"\n        *   Student B (holding A): \"It's A.\"\n    *   **Different Letters:**\n        *   Student A (holding A): \"Is this A?\"\n        *   Student B (holding B): \"No, it's not. It's B.\"\n3.  **Pair Work:** Students work in pairs, each student holding a card. They take turns asking and answering questions, identifying the letters they hold or comparing letters.\n\nThis activity targets speaking and listening skills. It is suitable for elementary school students (grades 5-7). Materials needed include laminated alphabet cards. Classroom Tip: Circulate to monitor student conversations and offer assistance with pronunciation.","content_type":"activity","name":"Alphabet Card Pairs","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Laminated alphabet cards"],"topic_tags":["Alphabet","Conversation","Letters"]},
  {"id":"scraped-altcir-handbook-who-has-137","text":"This activity focuses on practicing the phrases \"he has,\" \"she has,\" and \"they have\" using descriptive attributes. Prepare by gathering color photographs of familiar characters (anime, manga, or famous people) and creating a list of descriptive attributes for each. Begin by telling the class they will guess who the person is based on your descriptions using \"he has\" or \"she has.\" For example, \"He has a wand. He has a scar. He has many friends.\" (Answer: Harry Potter). Make it a competition by rewarding the first correct guess with a small prize. Students can compete individually or in teams. After a correct guess, reveal the photograph to visually confirm the described attributes. Adjust difficulty by controlling the vocabulary; start with vague clues and become more obvious if needed. Example: President Obama.","content_type":"activity","name":"Who Has?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Color photographs of famous people/characters","List of descriptive attributes","Small prizes (optional)"],"topic_tags":["Describing people","Grammar","Vocabulary"]},
  {"id":"scraped-altcir-handbook-guessing-game-who-am-i-138","text":"This activity helps students practice using the present simple tense with \"he/she has\" and \"they have\" to describe people or groups. First, the teacher prepares a list of people or groups (e.g., a president, a teacher, a baseball team). The teacher then gives clues one by one, using simple sentences. For example, \"He wears a suit.\" \"He is very famous.\" \"He makes many important decisions.\" After each clue, students can raise their hands to guess who it is. The teacher can increase difficulty by introducing the phrase \"they have\" and alternating between \"he/she has\" and \"they have\" to encourage careful listening and differentiation. For example, \"They have gloves.\" \"They are a baseball team.\" The teacher should clearly pronounce \"he\" and \"they\" to aid in comprehension. This activity works best if the clues are simple and progressively reveal the answer. Focus on building sentence structure. Adapt vocabulary to suit your students' level.","content_type":"activity","name":"Guessing Game: Who Am I?","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["Present Simple","Describing People","Guessing Game"]},
  {"id":"scraped-altcir-handbook-celebrity-possessions-139","text":"This activity focuses on practicing the grammar of \"he/she has\" and \"they have.\" Before the activity, print out pictures of various celebrities. Divide the class into pairs. Give each pair a set of celebrity pictures. One student in each pair picks a celebrity and describes what that celebrity has. For example, \"Lady Gaga has a wig.\" The other student guesses the celebrity. Students can alternate roles. The activity targets speaking and listening skills. This is suitable for 1st-year junior high school students, building on vocabulary and grammatical structures previously taught. Classroom tip: Ensure students understand possessive vocabulary before playing. Monitor to encourage correct usage of \"he has,\" \"she has,\" and \"they have.\"","content_type":"activity","name":"Celebrity Possessions","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Color printer","Pictures of celebrities"],"topic_tags":["Possessions","Celebrities","Grammar"]},
  {"id":"scraped-altcir-handbook-animal-quiz-140","text":"This activity is a guessing game designed to reinforce animal vocabulary. Prepare a list of animal clues. The ALT reads clues describing an animal one at a time, gradually revealing information. The clues should be simple and use familiar vocabulary suitable for the target grade level. For example: \"I have four legs.\" \"I eat grass.\" \"I say 'moo'.\" The students listen to the clues and try to guess the animal. Start with easier clues and add more complex ones as needed. The ALT reads the clues, and the JTE can assist with clarifying any confusing vocabulary. This activity targets listening comprehension and vocabulary. The ALT and JTE should collaborate to create clues based on students' prior knowledge. Materials needed are a list of prepared clues. Classroom tip: encourage students to shout out answers to increase engagement.","content_type":"activity","name":"Animal Quiz","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Prepared Clue List"],"topic_tags":["Animals","Vocabulary","Listening Comprehension"]},
  {"id":"scraped-altcir-handbook-can-can-t-listening-141","text":"This activity focuses on listening comprehension of the \"can\" and \"can't\" grammar points, specifically using animal vocabulary. The teacher will prepare a list of sentences, three per animal, describing actions the animal can or cannot do. For example: \"A cat can climb a tree.\" \"A cat can't fly.\" \"A cat can see in the dark.\" The teacher reads the sentences aloud, and students listen and mark a worksheet with a 'O' (can) or an 'X' (can't) for each sentence. After listening, students use the information from the listening exercise to match the description to the correct animal (e.g., cat, dog, bird, etc.). This reinforces listening comprehension and vocabulary related to animals and actions. Suitable for elementary school students. Materials needed include a prepared list of sentences and a worksheet for students to mark their answers and match descriptions to animals. Classroom tip: Vary your tone and use gestures to make the activity more engaging. Pre-teach animal vocabulary if necessary.","content_type":"activity","name":"Can/Can't Listening","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Worksheet","Prepared list of sentences"],"topic_tags":["Animals","Listening Comprehension","Grammar: Can/Can't"]},
  {"id":"scraped-altcir-handbook-can-can-t-statements-142","text":"This activity focuses on practicing the grammar of 'can' and 'can't' while encouraging speaking and listening skills. \n\n1.  **Preparation (5 minutes):** The JTE reviews the grammar of 'can' and 'can't' with the students, explaining their usage and providing example sentences. The ALT and JTE can collaborate on preparing some example sentences to be used during the practice phase. \n2.  **Activity (10 minutes):** The ALT reads out a list of statements using 'can' or 'can't' about various activities or abilities. For example, \"I can swim,\" \"I can't play the guitar,\" or \"I can ride a bike.\" Students listen and respond either by repeating the statement or asking follow-up questions to understand it better. The JTE can also help provide further clarification, if necessary. The JET will be responsible for reading the example sentences and checking student's answers and understanding. The JTE is in charge of grammar review beforehand and explanation as needed.\n\nThis activity is suitable for elementary and junior high school students. Materials needed include pre-prepared statements on paper.\n\nClassroom Tips: Adapt the statements to relate to the students' interests and experiences to increase engagement. The JTE can check for understanding and manage any questions.","content_type":"activity","name":"Can/Can't Statements","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Prepared statements on paper"],"topic_tags":["Ability","Grammar","Speaking"]},
  {"id":"scraped-altcir-handbook-three-hints-animal-quiz-143","text":"This activity focuses on listening comprehension and animal vocabulary. The teacher first presents a table with four actions (run, jump, swim, fly) and six numbered rows. Students listen to the teacher describe six different animals using \"can\" and \"can't\" statements, and fill in the table with \"O\" (can) or \"X\" (can't) for each animal and action. After completing the listening portion, students match the given animal names (Frog, Sparrow, Kangaroo, Turtle) to the numbers they heard. The teacher should repeat the statements multiple times for lower grades. After checking the answers, students can create their own animal quiz using animal flashcards if time allows. This activity helps students practice listening for specific information, vocabulary related to animals and actions, and basic sentence structures using \"can\" and \"can't\".","content_type":"activity","name":"Three Hints Animal Quiz","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Paper","Pencils"],"topic_tags":["Animals","Actions","Listening Comprehension"]},
  {"id":"scraped-altcir-handbook-what-time-do-you-144","text":"This activity helps students practice asking and answering questions about daily routines. Students work in groups to navigate a game board, asking and answering questions about times. \n\n**Procedure:**\n1.  Divide students into groups of 3-4.\n2.  Each student selects a game piece.\n3.  Students play rock-paper-scissors (Jan-ken-pon) to determine the first player.\n4.  On their turn, students move around a pre-made game board (B4 size). The spaces on the board prompt specific activities (e.g., \"wake up,\" \"eat breakfast\").\n5.  When a student lands on a space, they ask the question on the space to the student on their left using \"What time do you...?\" For example, \"What time do you wake up?\"\n6.  The partner answers using \"I...at...\". For example, \"I wake up at seven o'clock.\"\n7.  If the question is asked and answered correctly, the student can continue. If the question is incorrect, the student cannot move. The partner can move an extra space in the board.\n8.  Students receive a token each time they complete the board. \n9.  After a set time (e.g., 10 minutes or more), the student with the most tokens wins.\n\n**Language Skills:** Speaking and Listening (questioning and answering about time and daily routines).\n**Grade Levels:** 5-7 (can be adapted).\n**Materials:** Game board worksheet (B4 size), game pieces, tokens.\n**Classroom Tips:** Pre-teach or review vocabulary related to daily routines and telling time. Model the question and answer format before the activity begins. Adjust the board and activity types to meet students' English proficiency.","content_type":"activity","name":"What Time Do You...?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Game board worksheet (B4)","Game pieces","Tokens"],"topic_tags":["Daily routines","Time","Questioning"]},
  {"id":"scraped-altcir-handbook-daily-routine-race-145","text":"This is a fun game to practice daily routines vocabulary. Prepare a laminated game board with pictures depicting daily activities like 'wake up,' 'eat breakfast,' 'go to school,' 'play outside,' etc. Include instructions on the board, such as 'Go forward one space,' 'Go back two spaces,' or 'Lose a turn.' Students use game pieces (e.g., erasers) and tokens (e.g., marbles) for points. Divide the class into groups of 4-5 students. Each group gets a game board and a set of pieces and tokens. Students take turns rolling a die (or spinning a spinner) to move their piece around the board. When they land on a space, they must say a sentence about that activity, e.g., 'I wake up at 7:00.' or 'I eat breakfast.' If they do not say a correct sentence, they do not get a point. The first group to reach the end of the board, or the group with the most points after 10 minutes (timed), wins. This activity targets speaking and vocabulary related to daily routines. Adapt the vocabulary based on the grade level. For example, older students can include more detailed sentences. Classroom tip: pre-teach the vocabulary and sentence structures before starting the game. Monitor and help students with their pronunciation and sentence structure as they play.","content_type":"activity","name":"Daily Routine Race","activity_type":"Main Game","skill":"Speaking","duration_minutes":10,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Laminated game board with pictures","Game pieces (erasers)","Tokens (marbles)","Clock or Timer","Dice/Spinner"],"topic_tags":["Daily Routines","Vocabulary","Speaking","Game"]},
  {"id":"scraped-altcir-handbook-game-board-activity-146","text":"This activity involves a game board designed for practicing English. The JET creates and laminates the game board, along with providing game pieces and tokens. The JET explains the game rules to the JTE. The JTE brings in a TV and computer with a timer program, or uses a school timer, to visually manage the 10-minute game time. Both teachers demonstrate how to play the game so the students understand the process. The game board can be customized to practice various language skills, making it adaptable for different grade levels. The focus is on speaking and listening while playing the game.","content_type":"activity","name":"Game Board Activity","activity_type":"Main Game","skill":"Speaking","duration_minutes":10,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Game Board","Game Pieces","Tokens","Timer (TV/Computer or school timer)"],"topic_tags":["game","speaking","listening"]},
  {"id":"scraped-altcir-handbook-start-start-start-147","text":"This activity focuses on practicing telling time. Write three questions on the board: \"What time do you get up?\" \"What time do you eat dinner?\" and \"What time do you go to school?\" Divide the class into teams or have them play individually. Students take turns answering the questions, using full sentences. Encourage students to use visual aids like a clock or pictures of daily routines. The first student or team to answer all the questions correctly wins. Encourage students to use a variety of times. It targets speaking skills and helps students practice simple sentence structures related to time. Classroom tip: Prepare students beforehand with the vocabulary of telling time and key verbs. This activity is easily adaptable for different grade levels by varying the complexity of the questions or expected answers. For example, younger students can just say the numbers, while older students can give more detailed responses like \"I get up at seven o'clock in the morning.\" The game can also be modified by adding game board pieces and tokens, as well as maybe adding interesting characters to the sheet. One can also add lying to the game to get more interesting. Have the students receive a reward for successfully lying, and punishment if they get caught. For younger students you can replace the questions with questions such as: What color is the sky? What is your favorite animal? What do you eat for lunch?","content_type":"activity","name":"Start! Start! Start!","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard or Paper","Markers or Pens","Optional: Pictures or Visual Aids (e.g., clocks)"],"topic_tags":["Time","Daily Routines","Speaking"]},
  {"id":"scraped-altcir-handbook-live-action-wheelchair-quest-148","text":"This activity encourages students to practice giving and following directions while navigating a simulated obstacle course using wheelchairs. \n\n1.  **Preparation:** Set up a simple obstacle course in the classroom or gym. This could involve cones, chairs, or other safe objects to maneuver around.\n2.  **Groups:** Divide the students into small groups (3-4 students). Each group will have one student in a wheelchair. \n3.  **Role Assignment:** Within each group, assign roles: the person in the wheelchair, the direction-givers, and an observer (optional).\n4.  **Instructions:** The direction-givers must use clear and concise English to direct the wheelchair user through the obstacle course (e.g., \"Turn right,\" \"Go straight,\" \"Stop!\"). The observer can give feedback on the clarity of the directions.\n5.  **Rotation:** Rotate roles within the groups so that all students have a chance to be in the wheelchair, give directions, and observe.\n6.  **Variations:** To increase the difficulty, add more complex obstacles or introduce time limits. This activity targets listening comprehension and speaking fluency related to giving directions. Classroom tips: Ensure the activity is safe and the wheelchairs are appropriate for the students. Emphasize the importance of clear and precise language.","content_type":"activity","name":"Live Action Wheelchair Quest","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Wheelchairs (provided by school)","Cones/chairs for obstacle course"],"topic_tags":["Directions","Physical Activity","Teamwork"]},
  {"id":"scraped-altcir-handbook-wheelchair-quest-149","text":"This fun speaking activity encourages students to practice giving and following directions. First, set up a simple \"quest\" course in your classroom or gym using chairs, cones, or other classroom objects. One student is in a \"wheelchair\" (a chair) and is the \"explorer.\" Another student is the \"navigator,\" and their job is to guide the explorer through the course using only directions. The navigator can only use the vocabulary: \"Go forward,\" \"Go backward,\" \"Turn left,\" \"Turn right,\" and \"Stop.\" The navigator cannot touch the explorer or their chair. The explorer closes their eyes or wears a blindfold. The other students are the audience, cheering and giving encouragement (in English, of course!). Start by demonstrating the activity with a student, modeling the language. Switch roles for each round so that everyone gets a turn being the explorer and navigator. Adapt the course complexity to the grade level. For example, for younger students, make the course simpler with fewer obstacles and simpler directions. For older students, make the course more complicated, include a timer and penalize errors. Materials needed: chairs, cones or other objects to make a course, blindfolds. This activity works best when students are enthusiastic and have a little bit of energy.","content_type":"activity","name":"Wheelchair Quest","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["chairs","cones","blindfolds"],"topic_tags":["directions","games","speaking"]},
  {"id":"scraped-altcir-handbook-directions-dance-game-150","text":"This activity teaches directional vocabulary through movement and a simple game. First, introduce directional vocabulary (e.g., up, down, left, right) using flashcards and physical actions. Students repeat the words and mimic the movements. Next, play “The Directions Song” video from YouTube, encouraging students to sing and perform actions. For students in wheelchairs, adapt the activity by having them move their wheelchairs in the directions mentioned in the song or ask their assistants to move the wheelchairs. Finally, transform the class into a game! Create a game board with start and goal squares. Students roll a die (by knocking it off their wheelchair table) and move their wheelchairs according to the die's instructions, racing to the goal. The game could be played on the floor with a large board or on desks using smaller boards. Focus on having fun and using the target language. This is great for an inclusive classroom.","content_type":"activity","name":"Directions Dance/Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Vocabulary Cards","YouTube video: \"The Directions Song\"","Game board (large or small)","Dice (1 per group)"],"topic_tags":["directions","movement","game","inclusive"]},
  {"id":"scraped-altcir-handbook-giant-directional-dice-151","text":"This activity helps students practice directional vocabulary. First, introduce the vocabulary words (e.g., up, down, left, right, forward, backward) using \"The Directions Song\" video on YouTube and vocabulary cards in English, Japanese, and Katakana. Next, divide students into groups. One student rolls the giant die and says the word that appears on the top face. The group must then move their designated game piece (student) according to the direction on the die, using the corresponding square on the floor grid. The first group to reach the goal square wins. This activity targets listening and speaking skills, and reinforces vocabulary related to directions. It promotes physical movement and engagement. Adaptations can include using different vocabulary sets or varying the difficulty of the grid. Ensure the grid is accessible for all students, including those using wheelchairs. Monitor student comprehension and provide support as needed.","content_type":"activity","name":"Giant Directional Dice","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Oversized die with directional words and pictures","Large floor grid game board","Vocabulary cards (English, Japanese, Katakana)","TV/Internet access for \"The Directions Song\" video"],"topic_tags":["directions","vocabulary","games","physical activity"]},
  {"id":"scraped-altcir-handbook-blind-snap-152","text":"This game is designed to teach and practice directions (North, South, East, West). Students will use a die to determine their movement on a game board. \n\n1.  **Preparation**: Create a game board with at least 9 squares. Students can begin outside the board (small board) or within a square (large board). Prepare a die with faces representing directions. Consider adding \"Roll Again\" or \"No Move\" faces. Designate a \"goal\" square.\n2.  **Gameplay**: Students roll the die and move their 'wheelchair' (representing themselves) in the corresponding direction. If a direction isn't possible from their current location, the roll is a pass. Students should try to align their facing direction to their next move. Students race to reach the GOAL square\n3.  **Variations**: Add action squares (e.g., quiz, go back to start) for increased difficulty. Incorporate themes (jungle, bakery, etc.) for added engagement.\n\nThis activity targets the language skill of Speaking and Listening and promotes following directions, and vocabulary of directions. \n\n**Suitable Grade Levels:** Junior High School (Year 1-3). \n\n**Materials Needed:** Game board, Dice (with directions), Optional: Theme-related props (e.g., hats, aprons). \n\n**Classroom Tips:** Encourage students to verbalize the directions they are moving. Review directions if necessary. Adjust the board size and complexity based on student ability.","content_type":"activity","name":"Blind Snap","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Game board","Dice"],"topic_tags":["Directions","Games","Junior High"]},
  {"id":"scraped-altcir-handbook-snap-numbers-and-letters-153","text":"This activity focuses on practicing listening and speaking skills using numbers and letters. First, prepare a deck of cards. You can use flashcards with numbers (1-20) and letters (A-Z) or create your own. Divide the cards equally among the players. Players close their eyes and take turns placing cards face up on a shared pile in the center of the table. The teacher then reads aloud the number or letter shown on the revealed card. When a player recognizes a matching number or letter on the pile, they shout \"Snap!\" and slap the card pile. The first player to correctly \"snap\" and identify the match wins the pile. Incorrect \"snaps\" give the cards to the opponents. The winner is the person who accumulates all the cards. The first player to lose all their cards reads for the next game. Classroom tip: Start with a smaller set of numbers/letters for younger students.","content_type":"activity","name":"Snap! Numbers and Letters","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Flashcards (numbers/letters)","Table"],"topic_tags":["Numbers","Letters","Games"]},
  {"id":"scraped-altcir-handbook-card-match-154","text":"This activity helps students practice matching numbers or letters. First, shuffle a deck of cards (remove picture cards for numbers). For letter practice, use alphabet cards. Divide the class into pairs or small groups. Each student receives a set number of cards. Students take turns flipping over a card and trying to find a matching card in their hand or in the central pool of flipped cards, depending on how you've set up the rules. If a match is made, the student pairs up the cards and removes them. The winner is the first student to get rid of all their cards. This focuses on number/letter recognition and simple communication (e.g., \"Do you have a...?\" or \"I have...\" depending on the age group). Adapt the focus by using number cards or alphabet cards. Suitable for grades 5-7. Classroom tip: pre-teach the numbers/letters and vocabulary before playing.","content_type":"activity","name":"Card Match","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Deck of cards (picture cards removed)","Alphabet cards (optional)"],"topic_tags":["Numbers","Letters","Matching"]},
  {"id":"scraped-altcir-handbook-word-puzzle-practice-155","text":"This activity focuses on vocabulary and pronunciation. Students practice identifying words and taking turns reading them aloud. Start with a practice round with eyes open to familiarize students with the process and order of play. The JTE can assist with instructions if needed, but it may not be necessary. Limit groups to a maximum of 5 players plus the reader to avoid confusion. This activity can be adapted by using different vocabulary and word types. Language skills targeted: Speaking, Listening.","content_type":"activity","name":"Word Puzzle Practice","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":[],"topic_tags":["Vocabulary","Pronunciation","Junior High"]},
  {"id":"scraped-altcir-handbook-dash-spelling-156","text":"Divide the students into groups. Write a word or sentence on the board, replacing the letters with dashes. For example, write \"__ __ __ __ __\" for \"hello.\" Groups take turns guessing letters. If a group guesses a correct letter, they earn points equal to the number of times that letter appears in the word. For \"hello\", guessing \"e\" earns one point, while guessing \"l\" earns two points. There's no penalty for wrong guesses. Students can raise their hands to guess the entire word/phrase at any time, earning extra points (e.g., 5 points) for a correct guess. The game duration is flexible, depending on the number of puzzles. This activity targets spelling and vocabulary, making it great for reinforcing previously taught material. It's suitable for various grade levels and can be adapted to difficulty. Classroom tip: Use vocabulary relevant to the current unit of study. Make sure all groups have equal turns and that everyone has a chance to participate. Consider using a point system and keeping score on the board to add competition.","content_type":"activity","name":"Dash Spelling","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Whiteboard or projector","Markers or pens","Point system (optional)"],"topic_tags":["Spelling","Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-hangman-157","text":"Write a Hangman puzzle on the board, using dashes to represent the letters. The class guesses letters one at a time. If a letter is in the word, fill it in. If not, draw a part of the hangman figure. Keep track of correct guesses and incorrect guesses. The class wins if they guess the word before the hangman is complete. Target speaking and spelling. Suitable for grades 5-7. Materials needed: whiteboard or chalkboard, markers or chalk. Classroom tips: Start with shorter words.  Encourage students to say the letters aloud. Adapt the difficulty by selecting more or less common words, or by using themed vocabulary.","content_type":"activity","name":"Hangman","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard or Chalkboard","Markers or Chalk"],"topic_tags":["Vocabulary","Spelling","Games"]},
  {"id":"scraped-altcir-handbook-guess-who-sports-edition-158","text":"Divide the class into groups of four, with two teams of two students. Each team shares a 'Guess Who!' game board (downloadable from Hasbro, or teacher-made). Students use the board, a black marker, and a cloth (or pencil and eraser) to play.  One team thinks of a character on the board. The other team asks yes/no questions to guess the character (e.g., \"Is your character wearing a hat?\"). Students cross off characters as they get information. The game continues until one team guesses the correct character. This activity targets listening, speaking, reading (names), and writing (crossing off characters). It suits JHS students, incorporating international names and sports vocabulary. Classroom tip: Prepare and laminate boards for re-use or provide printouts. The sports theme connects to familiar vocabulary.","content_type":"activity","name":"Guess Who! Sports Edition","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["'Guess Who!' game board (downloadable)","Black marker","Cloth or Pencil and eraser"],"topic_tags":["Games","Sports","Questioning"]},
  {"id":"scraped-altcir-handbook-team-introductions-159","text":"The ALT introduces the game in English, then the JTE translates if needed. Students practice pronouncing names and sports displayed on character costumes. They write difficult words in katakana and kanji. Students ask questions about the characters. The game involves teams, with students focusing on English use. The JTE and ALT monitor, supporting lower-level students and helping with questions. The aim is to create character names and sports teams that the students can communicate about in English.","content_type":"activity","name":"Team Introductions","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":[],"topic_tags":["Sports","Names","Pronunciation"]},
  {"id":"scraped-altcir-handbook-mario-kart-board-game-160","text":"This activity involves a Mario Kart board game played in junior high school classrooms. Students can review previous lessons while having fun playing the game. Before starting, include katakana pronunciation of character names on game boards and translations of sports vocabulary, if needed. Explain the game rules in both English and Japanese. Supervise students to ensure they use English for questions. Timing each game with a stopwatch is helpful. The activity aims to show students that English can be enjoyable and demonstrate their existing English knowledge. This activity takes about 20 minutes to complete. The activity targets everyday English used in \"real-life\" situations and can be used to review a lesson or a series of lessons.","content_type":"activity","name":"Mario Kart Board Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":20,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Mario Kart Board Game","Stopwatch"],"topic_tags":["Review","Game","Vocabulary"]},
  {"id":"scraped-altcir-handbook-dice-game-161","text":"Divide the class into groups. Each group receives a piece of paper, a pair of dice, and a character cut-out with a magnet backing. Place the characters on the magnetic board. The teacher asks a question (e.g., \"What did you do yesterday?\"). Groups take turns rolling the dice, and the number rolled determines the number of points they earn for a correct answer. After answering, the group can choose to draw a \"Special Card\" that offers bonuses (extra points) or penalties (point deductions). A set of pre-written questions should be prepared beforehand, with about 20 questions for a 50-minute class. The group with the most points at the end wins a small prize. This game targets speaking skills, as students practice answering questions and using the target language. It can be adapted to various grammar points and vocabulary by adjusting the question types.","content_type":"activity","name":"Dice Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":50,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Paper","Dice","Character cutouts (magnet-backed)","Magnetic blackboard","Special cards","Question cards","Prizes (stickers, badges)"],"topic_tags":["game","speaking","grammar","vocabulary"]},
  {"id":"scraped-altcir-handbook-super-mario-board-game-162","text":"This activity utilizes a Super Mario-themed board game to review vocabulary or grammar. Students move along a game board, encountering various cards with special effects. For instance, a red mushroom allows an extra dice roll, a green turtle shell enables an attack on another team (moving them back), and a banana card slows down the next player. The game reinforces vocabulary and provides opportunities for interaction and strategic thinking. Students can also be required to use target language such as \"I am going to attack Team B!\" The game is ideal for reviewing previously taught material. \n\nSteps:\n1.  Divide students into teams.\n2.  Explain the game rules and card effects.\n3.  Students take turns rolling the dice and moving their game pieces.\n4.  When landing on a special card, students follow the card's instruction. This may involve answering a question or performing an action in English.\n5.  The first team to reach the finish line wins.","content_type":"activity","name":"Super Mario Board Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Game board","Dice","Game pieces","Cards with special effects"],"topic_tags":["games","review","vocabulary","grammar"]},
  {"id":"scraped-altcir-handbook-jeopardy-review-game-163","text":"This activity is designed to review previously taught material in a fun, competitive format, perfect for exam preparation. The game is based on the popular American trivia game, Jeopardy. First, prepare a Jeopardy board with categories and point values, displayed either on a PowerPoint presentation or written on the blackboard. Divide students into groups of approximately 4 (adjust based on class size). Have groups play rock-paper-scissors to determine the starting order. The winning group selects a category and point value. The ALT then reveals the question (via PowerPoint click or by turning over a corresponding paper). The ALT reads the question aloud. Groups raise their hands to answer. The first group to raise their hand answers. If correct, the group earns the points and chooses the next question. If incorrect, the question goes to the next group. Keep track of points on the board. The group with the most points at the end wins. This activity targets listening and speaking skills, as students listen to the questions and formulate answers, and it's suitable for reviewing vocabulary, grammar, and general knowledge. Classroom tip: pre-teach any challenging vocabulary in the questions.","content_type":"activity","name":"Jeopardy Review Game","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["PowerPoint (optional)","Blackboard/Paper","Markers/Pens"],"topic_tags":["Review","Game","Competition"]},
  {"id":"scraped-altcir-handbook-egg-hunt-164","text":"This activity helps students practice prepositions of place (under, on, in, by) and the question 'Where is/are...?'.\n\n1.  Prepare paper eggs and hide them around the classroom. On each egg, write a noun (e.g., table, desk, box) and a color (e.g., blue).\n2.  Prepare worksheets with sentences like: \"The [color] egg is ______ the [noun].\" Leave a blank space for the preposition.\n3.  Students search for the eggs. When they find an egg, they fill in the preposition on their worksheet. They can work individually or in pairs to fill in the blanks.\n4.  Circulate and monitor their work, providing assistance as needed.\n5.  Check answers as a whole class at the end, reviewing correct preposition usage. For example: \"The blue egg is *on* the desk.\"\n\nThis activity targets listening and writing skills. Suitable for grades 5-7. Materials needed: paper eggs, markers/pens, worksheets. Classroom Tip: Have students say the complete sentence aloud after writing.","content_type":"activity","name":"Egg Hunt","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["paper eggs","pens/markers","worksheets"],"topic_tags":["prepositions","grammar","classroom objects"]},
  {"id":"scraped-altcir-handbook-easter-egg-hunt-165","text":"This activity focuses on practicing the question 'Where is/are...?' and related vocabulary. Before class, hide the laminated egg cutouts around the classroom using Blu-tack. On each egg, write a target sentence or vocabulary word related to Easter or eggs. Begin by introducing the topic with pictures and key vocabulary. Review 'Where is/are...?' and the target vocabulary. Divide students into pairs or small groups and give each group a worksheet with the target sentences/vocab. Students must find the eggs, read what's written, and then write the sentence on their worksheet. For example, if an egg says 'The chick', they write 'The chick is on the table.' This activity is adaptable: use different grammar points or vocabulary depending on the grade. Keep eggs small for easy concealment.","content_type":"activity","name":"Easter Egg Hunt","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Colored/patterned paper eggs (laminated)","Blu-tack","Worksheets with target sentences/vocab","Pictures of Easter/Eggs"],"topic_tags":["Easter","Questioning","Vocabulary","Speaking","Grammar"]},
  {"id":"scraped-altcir-handbook-trash-can-game-166","text":"This activity can be played in pairs or individually. The teacher prepares paper 'eggs' (laminated for durability) with clues written on them, such as \"The spotty blue egg is under the desk.\" Students work to find the eggs based on the clues. In pairs, one student moves to find the egg and relays the information back to their partner, who writes it down. Roles switch every two sentences. Alternatively, students can do the activity individually or as a whole class competition to reduce noise. For younger students (Elementary), the focus can be on colors, numbers, and basic conversation like \"I have two yellow eggs.\" For 2nd/3rd graders, start with a simple example sentence and have them memorize locations. Afterwards, mini whiteboards can be used for writing practice. Adapting the eggs' patterns can aid differentiation.","content_type":"activity","name":"Trash Can Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper eggs (laminated)","Worksheet (optional)","Mini whiteboards (optional)","Pens/Pencils"],"topic_tags":["Location","Instructions","Colors","Numbers"]},
  {"id":"scraped-altcir-handbook-quick-review-relay-167","text":"This activity is a fast-paced review game perfect for any lesson. Divide the class into teams. Write review questions on the board, or prepare flashcards. If using flashcards, tape them on the board. One student from each team runs to the board, reads or hears the question (depending on whether you are focusing on reading/listening), and writes/says the answer. Once they are done, they run back and tag the next student. The first team to correctly answer all questions (or a predetermined number) wins. This is a great way to practice previously taught vocabulary and grammar in a fun, competitive way. It's easily adaptable to different grade levels by adjusting the difficulty of the questions. \n\nLanguage skills targeted include reading (if reading questions), writing (if written answers), and speaking. Listening skills can be integrated if you read the questions aloud. Suitable for grades 5-7. \n\nClassroom tips: Make sure the questions are clear and relevant to the lesson's learning objectives. Have a quick answer key ready. Consider offering prizes to the winning team to boost motivation.","content_type":"activity","name":"Quick Review Relay","activity_type":"Review","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Whiteboard/Blackboard or Flashcards","Markers/Chalk","Answer Key (optional)"],"topic_tags":["Review","Grammar","Vocabulary","Game"]},
  {"id":"scraped-altcir-handbook-trashketball-168","text":"Divide the class into teams and give each team a different color of paper. Place two trash cans at the front of the room (one on a desk for 1 point, and the other on a chair on top of another desk for 2 points). Teams are split into three roles: shooters, writers, and picker-uppers. Show a question (fill-in-the-blank, unscramble, etc.). Writers have one minute to write the answer on their paper. Shooters then have one minute to crumple their paper and try to throw it into the trash cans. Picker-uppers gather any missed papers for 15 seconds. The last minute is a repeat of all steps. Only correct answers get points. Repeat the question/answer and throwing process until the end of the class. This activity targets both writing and speaking skills while reinforcing vocabulary or grammar. Suitable for grades 5-7. Materials needed: colored paper, trash cans, questions (written or displayed). Classroom Tip: Encourage student interaction and friendly competition. Vary the difficulty of the questions based on the grade level.","content_type":"activity","name":"Trashketball","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Colored paper","Trash cans","Questions (written or displayed)"],"topic_tags":["Grammar","Vocabulary","Teamwork"]},
  {"id":"scraped-altcir-handbook-what-are-you-doing-circle-169","text":"This activity focuses on practicing present continuous questions and answers. Divide the class into groups. Each group needs a piece of paper and a pen/pencil. One student from each group starts by writing \"What are you doing?\" at the top of their paper. The paper is then passed to another student in the group. This student writes an answer, e.g., \"I am eating a sandwich.\" They then write another \"What are you doing?\" question below their answer, before passing the paper on. Continue this process, alternating between questions and answers within each group. The activity can be stopped after a set time. Groups then share some of their question/answer chains with the class. This activity targets both speaking and writing skills. It is best suited for reinforcing grammar learned in class. Classroom tip: Encourage students to be creative with their answers and ask each other to clarify any strange vocabulary or grammar choices. To save paper, reuse the same piece and make sure the writing is relatively small.","content_type":"activity","name":"What Are You Doing Circle","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Paper","Pens/Pencils"],"topic_tags":["Present Continuous","Questions","Answers","Grammar"]},
  {"id":"scraped-altcir-handbook-present-progressive-action-game-170","text":"This activity focuses on practicing the present progressive tense with the verb 'to be'. Begin by writing a list of 10 action verbs on the board (6 familiar, 4 new). Write the base form and present progressive form (e.g., Play => Playing). Review the words with students, having them repeat after you and perform the actions. Model the sentence structure: \"I am... (verb-ing)\". After practice, have students form a semi-circle. Write \"You are...\" on the board. The teacher says the base form and does the action; students respond with \"You are... (verb-ing)\". Repeat this, then have a student lead. Finally, introduce \"Mieko is...\" and \"He/She is...\". Each student performs an action and says, \"I am (verb-ing).\" The class repeats, \"He/She is (verb-ing), Mieko is (verb-ing).\" Finish with \"We are having fun!\"","content_type":"activity","name":"Present Progressive Action Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Board","Markers","List of verbs"],"topic_tags":["Verbs","Present Progressive","Actions","Grammar"]},
  {"id":"scraped-altcir-handbook-word-association-warm-up-171","text":"This warm-up activity helps students practice vocabulary and speaking skills. Begin by writing a target vocabulary word on the board, such as 'happy.' Ask students to brainstorm words that are associated with 'happy'. Students can shout out words, and the teacher writes them on the board. Encourage participation from all students. Continue with several different words to expand vocabulary and activate prior knowledge. Adapt the difficulty by choosing more or less challenging words depending on the class's level. The game helps with fluency and quick thinking, as well as reinforcing word associations. If no board is available, prepare word cards in advance to display on the wall. This activity is best for introducing or reviewing vocabulary.","content_type":"activity","name":"Word Association Warm-up","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Chalk/Whiteboard or Markers","Word Cards (optional)"],"topic_tags":["Vocabulary","Warm-up","Speaking"]},
  {"id":"scraped-altcir-handbook-collaborative-modeling-172","text":"The ALT and JTE collaborate to introduce and facilitate the activity. First, they model the target sentence structures and game outline together. For small classes, the ALT and JTE participate directly within the student circle, taking turns leading. For larger classes, split the students into two groups, with the ALT leading one and the JTE the other. At the beginning, the JTE writes key vocabulary words on the board as the ALT says them, and students repeat. If words are difficult, the JTE can add Japanese meanings or pronunciations. Throughout the activity, the ALT and JTE should actively interact with each other, demonstrating the target language through questions and answers, and occasionally re-engaging the students by modeling the activity amongst themselves.","content_type":"activity","name":"Collaborative Modeling","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard","Markers"],"topic_tags":["Collaboration","Vocabulary"]},
  {"id":"scraped-altcir-handbook-whisper-relay-173","text":"This activity focuses on listening and speaking practice for a specific grammar point. Divide the class into groups (rows of students work well). One teacher takes the last student from each group into the hallway and provides them with a word, phrase, or sentence (WPS) related to the target grammar or a review item. The teacher should ensure the WPS is age-appropriate. When the teacher says \"Go!\", the students race to whisper the WPS down the line to the next student. They can repeat the WPS as many times as needed, but they must whisper. When the WPS reaches the final student, they either write it down on paper or whisper it to the teacher. Correct groups earn points based on speed (5, 4, 3, 2, and 1 point). If a WPS is incorrect, the student goes back to their group to correct the mistake. Rotate the 'last person' for each round. This activity targets listening and speaking skills, and reinforces vocabulary and grammar.","content_type":"activity","name":"Whisper Relay","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Scratch paper (optional)"],"topic_tags":["Listening","Speaking","Grammar","Vocabulary","Teamwork"]},
  {"id":"scraped-altcir-handbook-sentence-practice-174","text":"This activity focuses on practicing or reviewing a specific grammar point using sentences. First, prepare a list of sentences that exemplify the target grammar. These sentences should be age-appropriate and relevant to the students' current learning. \n\n**Step-by-step instructions:**\n1.  **Introduce the Grammar:** Briefly review or introduce the grammar point (e.g., present simple, past tense, etc.). Write an example sentence on the board.\n2.  **Sentence Reading (Whole Class):** Read the first sentence aloud clearly, emphasizing the target grammar. Students repeat chorally.\n3.  **Individual Practice:** Have individual students read the sentence aloud. Choose students at random to say the sentences or call on volunteers.\n4.  **Pair Work (Optional):** Students can practice the sentences in pairs, taking turns reading them and offering corrections. This can be extended to asking each other questions related to the sentences.\n5.  **Error Correction:** Throughout the activity, provide feedback and correct any pronunciation or grammatical errors. Write down common errors on the board for later review.\n\nThis activity directly targets speaking and listening skills, reinforcing correct pronunciation and grammar. It works best for practicing previously taught grammar points.\n\n**Classroom Tips:** Keep it short and lively. Use a variety of voices and intonations. Adjust the number of sentences depending on the time available and the difficulty of the grammar point.","content_type":"activity","name":"Sentence Practice","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["List of sentences"],"topic_tags":["grammar","speaking","pronunciation"]},
  {"id":"scraped-altcir-handbook-whisper-sentence-game-175","text":"This activity focuses on listening and speaking skills. Students form teams. Each team lines up. The teacher whispers a sentence (e.g., \"The cat is under the table.\") to the first student in each line. That student whispers the sentence to the next student in line, and so on. The last student in line writes the sentence on the board or says it aloud. The first team to correctly repeat the sentence wins. The teacher should monitor for correct pronunciation and ensure students use English only. If a team makes a mistake, they must work back down the line to find where the sentence was changed. This promotes careful listening and accurate pronunciation. Practice is key to improving fluency and reducing reliance on Japanese.","content_type":"activity","name":"Whisper Sentence Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":[],"topic_tags":["listening","speaking","pronunciation"]},
  {"id":"scraped-altcir-handbook-chain-sentences-176","text":"Students stand in a circle and practice target grammar while improving listening and memorization skills. The first student starts with a sentence using the target grammar (e.g., \"I like playing soccer\") and passes a soft ball to another student. The second student repeats the first student's sentence and adds their own phrase (e.g., \"I like playing soccer and playing piano.\") before passing the ball. Each subsequent student repeats the entire chain and adds their own phrase. Students are eliminated for forgetting, repeating, or taking too long. The last student remaining starts a new chain. Target grammar is flexible based on the lesson's focus. Suitable for Grades 5-7. Materials needed: a soft ball. Classroom tip: encourage students to speak clearly and help each other with memory. Consider using actions with the sentences to help memorize.","content_type":"activity","name":"Chain Sentences","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["soft ball"],"topic_tags":["grammar","listening","speaking"]},
  {"id":"scraped-altcir-handbook-pass-the-ball-177","text":"This warm-up activity focuses on speaking and listening while reviewing basic vocabulary or practicing sentence structures. The teacher starts by explaining the target language, such as asking and answering \"What's your favorite...?\" questions. Students stand in a circle. The teacher initiates by asking a student a question and tossing them the ball. That student answers the question, then asks the next student a question while tossing the ball to them. The activity continues around the circle. If students struggle, the teacher provides support. For added fun (and potential liability issues), the teacher can use a pico pico hammer for students who answer incorrectly, or can ask a question as a substitute.","content_type":"activity","name":"Pass the Ball","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Soft ball or stuffed animal","Pico pico hammer (optional)"],"topic_tags":["Speaking","Warm-up","Vocabulary Review"]},
  {"id":"scraped-altcir-handbook-spelling-race-178","text":"This game focuses on listening and speaking skills, suitable for smaller groups of students (15 or less). Students sit in a circle. The teacher starts by saying a word. The next student in the circle spells the word, then says a new word. The next student spells the new word and says a new word, and so on. Students must listen carefully to each other and remember the words. If a student makes a spelling mistake or hesitates for too long, they are out. The game continues until only one student remains. In this game, there are no clear winners and only clear losers, but if there should be a winner, then it should be the person who remembered the longest chain by the end of the game.","content_type":"activity","name":"Spelling Race","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":[],"topic_tags":["spelling","listening","speaking","games"]},
  {"id":"scraped-altcir-handbook-spelling-bee-179","text":"Divide students into teams of 4-6. Each team receives a set of letter cards. The teacher calls out an English word. Students must work together to spell the word using their letter cards. The first team to correctly spell the word wins a point. Continue calling out words. The team with the most points at the end wins. This activity targets listening comprehension and spelling skills. Suitable for grades 5-7. Materials needed: Letter cards (one set per team), word list. Classroom tips: Vary the difficulty of the words based on the students' proficiency. Encourage teamwork and communication within the groups. Consider using a timer to add excitement.","content_type":"activity","name":"Spelling Bee","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Letter cards","Word list"],"topic_tags":["Spelling","Listening","Teamwork"]},
  {"id":"scraped-altcir-handbook-card-spelling-180","text":"This activity helps students practice spelling and vocabulary using letter cards. Prepare sets of letter cards, including consonants (red), vowels (yellow), consonant combinations (blue), and vowel combinations (green). The phonetic combinations from New Crown textbooks are included. Do not give students a full set; select cards based on the vocabulary focus. You can choose vocabulary sets based on textbook lessons, categories (e.g., words with 'l' or 'r'), or phonetic rules (e.g., words with the 'ai' vowel combination or those with silent 'e').\n\nTo play, distribute a set of relevant letter cards to each student or pair. Instruct them to spell as many words as they can using the provided cards within a set time limit (e.g., 10 minutes). Circulate and monitor, providing support if needed. This activity targets vocabulary, spelling, and phonetic awareness. It is best used for reviewing vocabulary. The activity develops students' ability to spell words and match sounds to their written form.","content_type":"activity","name":"Card Spelling","activity_type":"Review","skill":"Writing","duration_minutes":10,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Letter cards (consonants, vowels, combinations) in color-coded sets","Timer"],"topic_tags":["Spelling","Vocabulary","Phonics","Review"]},
  {"id":"scraped-altcir-handbook-word-race-181","text":"This is a quick activity to review vocabulary or target specific language. First, divide the class into two or more teams. The ALT calls out a word or phrase related to a topic. The teams race to write the word or phrase correctly on the board. The first team to write the word/phrase correctly earns a point. The JTE keeps score. This activity targets listening comprehension and writing skills. It's suitable for reinforcing previously taught vocabulary. Use a white board or chalkboard for teams to write on. Make sure the words are appropriate for the students' level. Adjust the difficulty of the words based on the grade level and topic. Ensure each team has a designated writer. Make it fun by offering a small prize for the winning team.","content_type":"activity","name":"Word Race","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Whiteboard or Chalkboard","Markers or Chalk"],"topic_tags":["Vocabulary Review","Teamwork","Competition"]},
  {"id":"scraped-altcir-handbook-whisper-challenge-182","text":"This activity aims to practice speaking, listening, and writing skills in a competitive group setting. First, prepare slips of paper with simple sentences (e.g., \"The cat is on the mat.\", \"I like to eat pizza.\"). Divide the class into small groups. Students line up, and the last student in each line runs to the back of the room, selects a slip of paper, and reads the sentence silently. They then return to the group and whisper the sentence to the student in front of them. This continues down the line. The first student writes the sentence on the board. The teacher checks the sentence and awards a point if correct. The students rotate positions in the line, and the game continues until all the sentences are used or the time runs out. Focus is on clear pronunciation and accurate listening.\n\nThis activity helps students practice listening comprehension, speaking (pronunciation and conveying information), and writing sentences. It's suitable for grades 5-7. You'll need paper, a pen/pencil for each group, and a whiteboard or blackboard for each group. Ensure students speak clearly and quietly to avoid other groups hearing the sentence.","content_type":"activity","name":"Whisper Challenge","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Paper slips with sentences","Pen/pencil","Whiteboard/Blackboard"],"topic_tags":["Communication","Listening","Speaking","Writing","Group Work"]},
  {"id":"scraped-altcir-handbook-sentence-relay-183","text":"Prepare slips of paper with simple sentences related to a target grammar point or vocabulary set. Divide the class into teams. Write the beginning of a sentence on the blackboard. One student from each team runs to the board, completes the sentence based on the slip of paper they have, and runs back to tag the next teammate. The next student repeats the process, adding the next piece of information or sentence element. Continue until all sentences are completed or time runs out. The first team to correctly complete all sentences wins. This activity targets both reading and writing skills, while also encouraging speaking as students will likely discuss the answers in their teams. Suitable for upper elementary and lower junior high school. \n\nClassroom Tips: Keep sentences short and use simple vocabulary. Make sure all sentences are readable from all parts of the classroom. Consider using different colours to mark the sentences of different teams.","content_type":"activity","name":"Sentence Relay","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["blackboard","chalk","slips of paper with sentences"],"topic_tags":["grammar","vocabulary","teamwork"]},
  {"id":"scraped-altcir-handbook-vocabulary-card-game-184","text":"This activity aims to build vocabulary and awareness of word categories and sentence structure. Before starting, review the target vocabulary. Students receive worksheets with Japanese vocabulary divided by category and space for English translations. Allow time for completion, with or without dictionaries. Divide students into groups and distribute Vocabulary Card decks (one deck per group), with one card per word. Each student receives an equal number of cards, representing a mix of categories. Students discard one card to their left simultaneously. The goal is to collect all words from a single category. Once a student completes a category, they shout \"SLOW!\" and show their cards. If correct, they win the round. Losers receive a letter from \"SLOW\" (Hangman style) with the aim of having no letters. Stop the game to check who hasn't completed the letters, or play until only one student is left.","content_type":"activity","name":"Vocabulary Card Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Worksheets","Vocabulary Cards"],"topic_tags":["vocabulary","categories","games"]},
  {"id":"scraped-altcir-handbook-janken-talk-185","text":"This activity focuses on practicing target vocabulary or grammar through the classic game of rock-paper-scissors (janken). First, select the specific vocabulary or grammar points you want to review. Prepare vocabulary cards or a worksheet with the terms. The JTE can select the grammar/vocabulary, while the ALT can categorize the terms and prepare the materials. In class, the JTE reviews the target language, perhaps providing example sentences or explanations. The ALT assists students with translation if needed. Divide the class into pairs. Students play janken. The winner of each round uses the target language, for example, saying \"I have a (noun)\" or using the target grammar structure to describe something. The ALT and JTE circulate, monitoring and assisting students. This game improves speaking and listening skills through repetition and active participation. Suitable for Junior High School students.","content_type":"activity","name":"Janken Talk","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Vocabulary cards or worksheet","Rock-paper-scissors (optional)"],"topic_tags":["Vocabulary","Grammar","Games","Speaking","Janken"]},
  {"id":"scraped-altcir-handbook-janken-talk-comedian-edition-186","text":"This activity encourages speaking and listening skills while incorporating a fun element. Students collect cards based on categories and can then practice reading and speaking.  \n\n**How it works:** \n1.  Prepare cards with vocabulary words categorized into different groups (e.g., Colors, Foods, Animals, Days). \n2.  Students play rock, paper, scissors (janken). \n3.  The winner of each janken round gets to collect a card. \n4.  The game continues until time is up, or until a student completes a set of cards (e.g., one card from each category).\n5.  Winners read their cards out loud and state the categories.  \n\n**Difficulty adjustments:** \n*   **Lower Difficulty (Elementary):** Focus on nouns only, use images to help with vocabulary.\n*   **Higher Difficulty:**  Students collect words to build a sentence instead of category cards. The first student to complete a sentence reads it aloud.\n\n**Targeted Skills:** Speaking and Listening\n\n**Suitable Grades:** 5-7 (can be adapted for elementary)\n\n**Materials:** Vocabulary cards, images (optional)\n\n**Classroom Tips:** Ensure clear explanations and smooth execution. Encourage fun and creativity with the sentence-building variation.","content_type":"activity","name":"Janken Talk: Comedian Edition","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Vocabulary cards","Images (optional)"],"topic_tags":["games","speaking","vocabulary"]},
  {"id":"scraped-altcir-handbook-rock-paper-scissors-adjectives-187","text":"This activity helps students practice modifying adjectives to express different degrees of intensity. First, students play \"Rock Paper Scissors.\" The total number of fingers shown by both players determines the adjective modifier used in their conversation. For example, if the total is 4 fingers, the students use \"kind of.\" The focus of the conversation is rating comedians, asking, and answering questions like, \"How funny is [comedian's name]?\" Students discuss various comedians and how funny they think they are, using phrases like \"very funny,\" \"kind of funny,\" \"not very funny,\" or \"not funny at all.\" For instance, Student A might say, \"I think DOWNTOWN is kind of funny.\" Student B responds based on the total. This activity targets speaking and listening skills, promoting fluency and comprehension of adjective modifiers.","content_type":"activity","name":"Rock Paper Scissors Adjectives","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":[],"topic_tags":["adjectives","speaking","games"]},
  {"id":"scraped-altcir-handbook-how-funny-188","text":"Students will practice expressing opinions about comedians (or any topic). First, students fill in a worksheet with a table. The table has columns for comedian's names and a scale for how funny they are (e.g., \"so funny,\" \"really funny,\" etc.). During the activity, students mingle, asking each other \"I think [comedian's name] is [level of funniness] funny.\" Students record their partner's answers in their tables. The activity targets speaking and listening skills. The activity is adaptable; for higher levels, include follow-up questions (e.g., \"Why?\") or have students agree or disagree with each other. Materials include a worksheet with a table. Classroom tip: allow students to wander the classroom to talk to whoever they please (depending on class management).","content_type":"activity","name":"How Funny?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet with a table"],"topic_tags":["Opinion","Celebrities"]},
  {"id":"scraped-altcir-handbook-where-s-pikachu-189","text":"This activity focuses on practicing location questions and answers. First, prepare character flashcards (e.g., Pikachu, Doraemon) and location flashcards (e.g., library, park, classroom). Hide the smaller character cards behind the larger location cards on the board. The JTE holds up a large character card and asks \"Where is [character]?\"  Students then raise their hands to guess the location. The first student to answer correctly gets to reveal the hidden card, and a point for their team. Encourage students to use full sentences. Target language: \"Where is...?\" and \"He/She's in...\" and location vocabulary. Suitable for Grades 5-7. Materials needed: character flashcards, location flashcards, board. Classroom tip: Use teams to increase engagement.","content_type":"activity","name":"Where's Pikachu?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["character flashcards","location flashcards","board"],"topic_tags":["location","characters","questioning"]},
  {"id":"scraped-altcir-handbook-where-s-the-character-190","text":"This speaking and listening game is a fun way to practice location vocabulary and introduce simple sentences. First, prepare six flashcards depicting different locations (e.g., park, school, home). Prepare two sets of character cards. One set should be small enough to be concealed by the location cards. The other set can be larger to display on the board. \n\nTo play, divide the class into teams. Place the location cards on the board. Secretly place one small character card behind one of the location cards. One student from the first team comes to the front and asks, \"Where is [character]?\" using the target language. The teacher answers, \"[Character] is at the [location].\" If the team guesses the correct location, they get a point. If they are incorrect, they can get a chance to ask again (or, the next team gets a chance). Repeat with different characters and locations. Encourage students to use full sentences and vary their questions. \n\nThis activity is suitable for practicing 'Where is...?' questions and prepositions of place. \n\nClassroom tips: Make sure the character cards are engaging and related to the students' interests. Use a simple point system to keep track of scores. You can modify this activity by having the character cards describe an action, like 'is reading'.","content_type":"activity","name":"Where's the Character?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Location Flash Cards","Character Cards","Magnets"],"topic_tags":["Locations","Questioning","Speaking"]},
  {"id":"scraped-altcir-handbook-flash-card-guessing-game-191","text":"This activity involves flashcards with vocabulary or images. The ALT prepares three sets of flashcards. The ALT hides the cards around the classroom. The ALT then asks the students a question related to the flashcard content, e.g., \"Where is the apple?\" or \"What color is the car?\" Students guess where the cards are hidden. The JTE assists by first demonstrating the activity with the ALT, and then assisting students with their guesses and holding the flashcards. The activity targets listening comprehension and speaking, and can reinforce vocabulary and sentence structures. It is suitable for elementary school students. Materials needed include the flashcards, and the classroom itself (to hide the cards!). Classroom tip: Keep it fun and dynamic, and provide plenty of encouragement for the students.","content_type":"activity","name":"Flash Card Guessing Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":2,"interaction":"Whole class","materials":["Flashcards (3 sets)"],"topic_tags":["Vocabulary","Classroom objects","Locations"]},
  {"id":"scraped-altcir-handbook-what-did-you-hear-192","text":"This activity is designed to improve listening comprehension and speaking skills. The teacher prepares character cards (e.g., animals, people, objects) and hides them. The teacher says a phrase related to one of the characters, such as \"It's big and strong.\" Students then ask questions like \"Is it a lion?\" until they guess the hidden character. The activity targets listening and speaking skills, suitable for Junior High School students (grades 7-9). A seating list or check sheet can be used to ensure all students participate equally. Once familiar, the class can be split into teams, with one hiding the cards and the other guessing. Materials: Character cards, seating list (optional).","content_type":"activity","name":"What Did You Hear?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Character cards","Seating list (optional)"],"topic_tags":["Listening","Speaking","Guessing Game"]},
  {"id":"scraped-altcir-handbook-introduction-quiz-193","text":"The objective is to improve listening comprehension through an introductory presentation and follow-up quiz. The ALT gives a presentation about themselves using a PowerPoint with images. During the presentation, the ALT asks simple questions to encourage student participation, even if the answers are in Japanese. The ALT should ask the JTE for the English translation when necessary and write new vocabulary on the board. Before the presentation, students receive a handout to take notes on. Following the presentation, the ALT quizzes students on the information presented. The ALT provides complete sentences when affirming correct answers. This activity targets listening comprehension and speaking. The activity works best by mixing visual and audio elements. The main element here is listening, then the following response, even if in Japanese is important for engagement. Suitable for Grades 5-7. Materials needed: PowerPoint presentation with images, handout for note-taking, and whiteboard markers. Classroom tips: Encourage participation, provide clear pronunciation, and repeat key vocabulary. Encourage the JTE to help with new vocabulary and Japanese to English translations.","content_type":"activity","name":"Introduction Quiz","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["PowerPoint","Handout","Whiteboard Markers"],"topic_tags":["self-introduction","listening comprehension","speaking"]},
  {"id":"scraped-altcir-handbook-my-home-country-194","text":"This activity introduces students to the teacher's home country and family. First, the teacher shows images representing their home country, followed by images of their family, pets, and home. A PowerPoint presentation works well. Next, the teacher presents a simple question sheet with two options per question. For example: 'Are you 25 or 21 years old?' or 'Do you have 1 or 2 pets?' Students listen to the questions and answer the questions on their worksheet. Prepare bonus questions for extra time. This activity targets listening comprehension and provides a speaking opportunity for the teacher. It helps students learn about the teacher and their background, fostering a sense of connection and understanding.","content_type":"activity","name":"My Home Country","activity_type":"Production","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Images (country, self, family)","Projector/Laptop","Question Sheet/Handout"],"topic_tags":["Culture","Personal Information","Listening Comprehension"]},
  {"id":"scraped-altcir-handbook-shark-chase-adaptation-195","text":"This activity is an adaptation of the \"Shark Chase\" game, suitable for introducing yourself and encouraging active listening. Before starting, have students stretch and do a drum roll to build anticipation. Begin by asking simple questions, starting with \"Question 1,\" then having the students call out the subsequent numbers as you proceed. For instance, ask students to raise their hands for a poll: \"Do you think A is right or B?\" Reward participation with high fives, fist bumps, and class applause to keep students engaged. The goal is to make the introduction interactive and fun while practicing listening skills. Remember to speak slowly and clearly.","content_type":"activity","name":"Shark Chase Adaptation","activity_type":"Warm-up","skill":"Listening","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["introduction","listening","games","classroom management"]},
  {"id":"scraped-altcir-handbook-sentence-race-196","text":"This activity is designed for passive sentence practice, but can be adapted for other grammatical structures. Divide students into teams. Each team is given a partial sentence challenge, such as '... was built in...'. Teams write a complete sentence to fulfill the challenge. The order of completion determines the order to move on a game board (teams roll a die to move a number of spaces). Once a sentence is written and checked by the teacher, the team moves. The teacher then models the correct answer, and students repeat it. A bonus quiz question allows one team to earn an extra move. Repeat this process for each turn.","content_type":"activity","name":"Sentence Race","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Game board","Dice","Paper","Pens/Pencils"],"topic_tags":["grammar","sentence structure","passive voice"]},
  {"id":"scraped-altcir-handbook-shark-race-197","text":"Draw a racetrack on the board with starting points for each team, and give each team a colored 'shark' game piece. Provide each team with a sheet of paper. The teacher prepares cards with sentence starters (e.g., '... was written by...').\n\n1.  Show a sentence starter card to the students.\n2.  Teams write complete sentences on their papers.\n3.  The first student on each team to raise their hand with a correct sentence gets to move their shark around the track clockwise.\n4.  Bonus cards, like 'Harry Potter', can be added for additional points. The first to answer correctly wins an extra move.\n5.  Teams advance based on dice rolls (or a set number of spaces).\n6.  Points are awarded for landing on the same space as or overtaking the shark in front of them.\n\nThis activity targets speaking and writing skills. It's suitable for elementary and junior high school students. Materials needed include the board, markers, shark game pieces, sentence starter cards, and paper. Classroom tip: make sure all students understand the question at the start.","content_type":"activity","name":"Shark Race","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Board and markers","Colored shark pieces","Sentence starter cards","Paper"],"topic_tags":["Grammar","Teamwork","Speaking","Writing"]},
  {"id":"scraped-altcir-handbook-challenge-card-game-198","text":"This is a whole-class activity where the ALT and JTE work together. First, the ALT and JTE explain the activity in English and demonstrate it for the students. The activity uses challenge cards with prompts or questions, dice rolls to move around a game board, and bonus cards. Each turn, the ALT reads a challenge card aloud in English. Then, the ALT and JTE check the students' answers, and the dice rolls determine movement on a game board (not described here). The JTE or ALT gives a model answer, which students repeat. Finally, the ALT adds a bonus card for the round. The activity targets listening and speaking skills, and also encourages students to practice the target language through repetition and responding to challenges. Materials needed are challenge cards, dice, a game board (not described here), and bonus cards. It's crucial for the ALT and JTE to work in tandem. This activity is a great review tool.","content_type":"activity","name":"Challenge Card Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Challenge cards","Dice","Game board (not described)","Bonus cards"],"topic_tags":["games","speaking practice","review"]},
  {"id":"scraped-altcir-handbook-looks-happy-199","text":"This warm-up activity focuses on describing appearances using \"looks\" (singular and plural). The ALT starts by showing a picture of Mickey Mouse and asking \"Who is this?\" to warm up listening skills. The ALT then models the target sentence, \"Mickey Mouse looks happy,\" repeating it three times. The sentence is then broken down and written on the board (e.g., \"Mickey Mouse\" on red, \"looks\" on blue, \"happy\" on green), with students repeating each part as a class. This process is repeated with Goku, using the sentence \"Goku looks sad.\" Next, SpongeBob's picture is introduced, and the ALT changes \"looks\" to \"look\" to demonstrate the plural form. The same is done with other characters. The students discuss the changes in the verb form and finally the sentences are reviewed again. Finally, students do a worksheet to reinforce the concept. The activity targets listening and speaking skills, focusing on sentence structure and vocabulary related to emotions.","content_type":"activity","name":"Looks Happy","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Pictures of characters (Mickey Mouse, Goku, SpongeBob, etc.)","Colored construction paper","Markers","Magnets","Worksheet"],"topic_tags":["Appearance","Emotions","Verbs","Grammar"]},
  {"id":"scraped-altcir-handbook-picture-emotion-sentences-200","text":"This activity helps students practice sentence construction using nouns, verbs, and adjectives while exploring emotional expressions. \n\n1.  **Preparation:** Print out pictures of characters displaying different emotions (happy, sad). Print each picture on a different color of construction paper to represent different parts of speech, and prepare sentence components on separate construction paper.\n2.  **Introduction:** Show the pictures of the characters. Elicit the emotions being displayed by the characters (e.g., \"Happy!\", \"Sad!\").\n3.  **Sentence Building:** Explain the three sentence parts: *Nouns*, *Verbs*, and *Adjectives*. Show example sentences. Write the parts on the different colors of construction paper.\n4.  **Activity:** Students volunteer or are chosen to build sentences on the board. They choose a picture and then combine the construction paper to create a descriptive sentence (e.g., \"Goku is sad.\", \"Mickey Mouse is happy.\"). \n5.  **Variations:** You can expand this by having students write their sentences in their notebooks after making one on the board.\n\nThis activity targets speaking and simple writing skills, and improves their vocabulary and understanding of basic sentence structure.\n\n**Classroom Tips:** Use magnets to attach the sentence components to the board and consider pre-writing sentence parts on the construction paper to ensure students can make sentences.","content_type":"activity","name":"Picture Emotion Sentences","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Pictures of characters (happy and sad)","Construction paper (various colors)","Markers","Magnets"],"topic_tags":["Emotions","Sentence Structure","Vocabulary"]},
  {"id":"scraped-altcir-handbook-adjective-review-grammar-intro-201","text":"This activity is designed to introduce or review adjective usage. Begin by saying a simple sentence like \"Mickey Mouse is happy.\" Ask students what the sentence means in Japanese. Once understanding is confirmed, introduce the new grammar point, prompting students to identify the differences from the initial sentence. Before explaining the grammar, review the meaning of the adjectives using flashcards or prepared visuals. Create or use character cards (e.g., Pikachu, Mukku) depicting different emotions. Varying the adjectives used in example sentences allows students to expand their understanding of the grammar point's application. Focus on speaking and listening skills. The activity helps to build vocabulary and understand sentence structure.","content_type":"activity","name":"Adjective Review & Grammar Intro","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Adjective flashcards","Character cards (Pikachu, Mukku, etc.)","Whiteboard or projector"],"topic_tags":["Grammar","Adjectives","Review","Warm-up"]},
  {"id":"scraped-altcir-handbook-halloween-trick-or-treat-202","text":"Divide students into groups of five or six. Each student gets a number within their group. The activity reviews grammar and vocabulary while incorporating Halloween culture. Start by asking a question; only students with number 1 can answer. Other group members can support. The first to raise their hand and answer correctly gets to pick a card from the 'Trick or Treat' bag. 'Treat' cards award points. 'Trick' cards require a member to perform a Halloween-themed action (e.g., wear devil ears) to earn higher points. Use Halloween props. Switch speakers for each question. End the game five minutes before the end of class. Award stickers to the winning group and students who performed tricks. This activity focuses on speaking while incorporating cultural elements and reviewing previously taught material.","content_type":"activity","name":"Halloween Trick or Treat","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Question cards","'Trick or Treat' cards","Halloween costume props","Stickers"],"topic_tags":["Halloween","Review","Speaking","Groups"]},
  {"id":"scraped-altcir-handbook-draw-a-monster-203","text":"This activity reviews targeted grammar points through a fun, engaging game. The ALT prepares the materials, including a list of \"tricks\" approved by the JTE. First, the ALT explains the instructions in basic English with gestures. The ALT then starts the game by orally asking questions related to the grammar point and selecting students to answer. After a correct answer, the student draws a \"trick\" card from a bag. The JTE provides translations for any unclear tricks, gives props or costumes, and tallies scores. The JTE also manages student behavior. This activity targets speaking and listening skills, reinforces grammar, and encourages group interaction.","content_type":"activity","name":"Draw a Monster","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Trick or Treat bag of cards","Props/costumes"],"topic_tags":["grammar review","speaking practice","games"]},
  {"id":"scraped-altcir-handbook-body-parts-sentences-204","text":"This activity helps students practice writing sentences using third person pronouns (he/she/it) with different verbs. Begin by reviewing body parts vocabulary, plurals, and numbers (e.g., one nose, two eyes). Next, elicit verbs that can be used with body parts, such as 'see,' 'have,' 'touch,' 'eat,' 'kick'. Write example sentences on the board: 'He has two eyes.' 'She sees a cat.'  Provide each student with a worksheet or notebook.  Give them a set of prompts or have them choose from a selection. The prompts could be pictures or simple questions. Students write sentences based on the prompts, using 'he,' 'she,' or 'it' and the target verbs and vocabulary. Circulate and assist with any grammar or vocabulary questions. Examples:  'She is touching her nose.' 'It has four legs.' Encourage students to try various sentence structures and include number and plural vocabulary. This activity targets sentence construction, vocabulary, and grammar related to third person singular pronouns and body parts.","content_type":"activity","name":"Body Parts Sentences","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["Worksheets or notebooks","Pencils/pens","Picture prompts (optional)"],"topic_tags":["Body parts","Grammar","Writing","Pronouns"]},
  {"id":"scraped-altcir-handbook-monster-introduction-205","text":"This activity reviews body parts and encourages creative speaking. Begin by reviewing body parts and plural forms. Introduce your example monster, including its age, likes/dislikes, and hobbies using sentences like \"This is Alex. He is 14 years old. He has 4 eyes, 5 ears, 2 legs, 10 arms and 1 nose. He likes apples and oranges. He does not like carrots. He plays the piano and soccer.\" Distribute a worksheet with a monster template. Announce a body part (e.g., \"eyes\") and give students 30 seconds to draw as many eyes as they wish. Repeat with other body parts. Finally, students introduce their monsters, using the number of body parts they drew. Encourage creativity and assist students as they introduce their monsters.","content_type":"activity","name":"Monster Introduction","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Monster template worksheet","Markers or crayons","Example monster description"],"topic_tags":["body parts","describing","creative speaking"]},
  {"id":"scraped-altcir-handbook-monster-drawing-description-206","text":"This activity focuses on body part vocabulary and simple descriptive writing. Students draw a monster based on randomly selected body parts, then write a short description of their monster. \n\n**Procedure:**\n1.  **Warm-up/Review:** Use flashcards or magnetic body part cards to review vocabulary (eyes, ears, arms, etc.).\n2.  **Introduction:** Show a pre-drawn monster as an example and model a simple description (e.g., \"My monster has one eye and two arms.\").\n3.  **Drawing:** Students receive a worksheet with a monster outline. The JTE draws body part slips from a container (e.g., \"one eye!\"). Students draw the body part on their monster within a time limit (e.g., 2 minutes). Repeat drawing, announcing a body part each round. Allow time for additional accessories, hair, clothing etc., if time allows.\n4.  **Writing:** After drawing, students write a description of their monster using simple sentences.\n\n**Language Skills:** Speaking (review), Writing (description).\n\n**Suitable Grades:** 5-7\n\n**Materials:** Worksheet with monster template and writing space, timer, paper strips with body parts written on them, example monster drawing, magnetic body part cards (optional).\n\n**Classroom Tips:** Emphasize time limits, focusing on using the vocabulary rather than artistic skill.  The JTE can explain instructions and clarify the concept of adding 's' to verbs for third-person descriptions. Involve students by having them draw out the body part cards and announce it to the class.","content_type":"activity","name":"Monster Drawing & Description","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet with monster template and writing space","Timer","Paper strips with body parts written on them","Example monster drawing","Magnetic body part cards (optional)"],"topic_tags":["body parts","description","writing","drawing"]},
  {"id":"scraped-altcir-handbook-are-you-from-207","text":"This activity focuses on practicing questions and answers using \"are\" and \"am\" while introducing cultural awareness. Start by showing a short video where you and your JTE role-play being from different countries (e.g., Indonesia, India), focusing on the target language: \"Are you from...?\" and responses like \"Yes, I am.\" and \"No, I'm not.\" Play the video twice, then review the questions in Japanese. Following this, use a PowerPoint presentation to show pictures of people from different countries, emphasizing their clothing and cultural cues. Students guess the person's origin using \"Are you from...?\" Then, distribute a \"Guess Who\"-style worksheet that incorporates the target grammar. Finally, students write and translate sentences on lined paper using the learned grammar. Classroom Tip: Emphasize pronunciation and encourage students to guess the countries. Use visual aids to support vocabulary.","content_type":"activity","name":"Are You From...?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Video (teacher-made)","PowerPoint with country images","Worksheet (Guess Who style)","Lined paper"],"topic_tags":["Countries","Grammar","Culture","Questions and Answers"]},
  {"id":"scraped-altcir-handbook-global-guess-who-208","text":"This activity combines listening, speaking, and writing to reinforce the 'be' verb and introduce countries and nationalities. First, play a short video (made by the students previously) using the 'be' verb to practice listening comprehension. Then, use a PowerPoint presentation featuring images of people from different countries. Students practice asking \"Where are they from?\" and answering with the correct country, using the 'be' verb (e.g., \"They are from Japan.\"). The main activity is a modified 'Guess Who' game. Provide each student with a worksheet containing pictures and details (name, age, gender, country) of several classmates. Students ask each other questions like \"Is he/she from Japan?\" or \"Is he/she a boy?\" to guess who the person is. Finally, students write down what they learned in the target language and translate it into Japanese, consolidating their understanding.","content_type":"activity","name":"Global Guess Who","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Video camera","PowerPoint","Guess Who worksheet","Lined paper"],"topic_tags":["Countries","Nationalities","be verb"]},
  {"id":"scraped-altcir-handbook-interview-game-do-you-like-play-209","text":"This activity focuses on practicing the phrases \"Do you like...?\" and \"Do you play...?\" Students pair up to interview each other using these questions based on a pre-selected vocabulary list (e.g., food, sports, hobbies). Student A asks Student B, \"Do you like/play...?\" If Student B answers \"Yes, I do,\" Student A gets Student B to sign their worksheet next to that question. If Student B answers \"No, I don't,\" Student A moves on to another student and asks the same question. The first three students to get all their lines signed on their worksheet sit down, and they win a small prize. This game targets speaking and listening skills, as students must understand and respond to the questions. It is suitable for elementary and junior high school students. The main materials needed are worksheets with the key phrases and vocabulary and a prize for the winners. A good classroom tip is to pre-teach the vocabulary and expected responses. Also, make sure to circulate around the class to monitor student responses and offer assistance.","content_type":"activity","name":"Interview Game: Do you like/play...?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet","Prizes"],"topic_tags":["Questioning","Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-letter-people-210","text":"Students consolidate their understanding of upper and lowercase letters while fostering creativity and social interaction.  The activity begins with a demonstration on the blackboard, showing examples of how to draw people using only alphabet letters (e.g., 'O' for a face, 'P' for a mouth). Students then use a worksheet to create their own 'letter people' within a 5-minute time limit. After this, students walk around the classroom to view each other's creations. Finally, a short period is given for finishing touches. The resulting drawings provide a great talking point and can be used to decorate the English room.\n\nThis activity primarily targets the skill of writing and visual communication. The use of letters to create images provides a simple, fun method to reinforce letter recognition. The classroom interaction strengthens the social bonds. \n\nMaterials needed: Worksheets, pencils, blackboard (or whiteboard), markers or chalk.\n\nClassroom Tips: Encourage students to be creative. Circulate and provide positive feedback.  Display the finished work prominently.","content_type":"activity","name":"Letter People","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheets","Pencils","Blackboard/Whiteboard","Markers/Chalk"],"topic_tags":["Letters","Creativity","Art"]},
  {"id":"scraped-altcir-handbook-alphabet-worksheet-211","text":"This simple activity reinforces alphabet recognition. Distribute the worksheets and pencils. Have students write the uppercase version of the letter beside the lowercase letter (or vice versa) on the worksheet. The worksheets should contain a series of letter pairs to complete. This activity targets both reading and writing, specifically letter recognition and writing skills. Suitable for elementary and early junior high grades. Classroom tip: Circulate the class to provide support for students having difficulty. Make it a race and offer a small reward for students finishing the worksheet with all answers correct.","content_type":"activity","name":"Alphabet Worksheet","activity_type":"Review","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Individual","materials":["Worksheets","Pencils"],"topic_tags":["Alphabet","Writing","Letters"]},
  {"id":"scraped-altcir-handbook-classroom-creations-212","text":"This activity encourages students to consolidate their learning through a fun, creative task. Students are tasked with creating something (the prompt is not specified in the given text) individually or in pairs. After the creation period, the ALT and JTE circulate the classroom, observing and commenting on the students' work. The focus is on using previously learned language to describe and discuss the creations, not on direct teaching. This activity provides an opportunity for the ALT and JTE to build rapport with the students. Suitable for grades 5-7. Materials are not specified, but could include paper, art supplies, or other relevant materials depending on the creation task. Classroom tip: Encourage students to be creative and use English as much as possible to describe their creations. The ALT and JTE can model the target language and provide positive feedback.","content_type":"activity","name":"Classroom Creations","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":[],"topic_tags":[]},
  {"id":"scraped-altcir-handbook-silly-self-portrait-213","text":"This activity aims to break the ice and encourage creativity in the first week of school. Students are tasked with drawing a silly self-portrait. \n\n1.  **Introduction (2 minutes):** Explain the activity and emphasize that the goal is to be silly, not necessarily artistic.  \n2.  **Drawing (7 minutes):** Students draw a picture of themselves, as silly as possible. Encourage them to be creative with their appearance.\n3.  **Gallery Walk (4 minutes):** After drawing, students walk around the classroom to look at their classmates' drawings.  This provides inspiration and reduces anxiety about drawing something 'wrong' by showing that everyone's drawing is unique and often humorous.\n4.  **Wrap-up (2 minutes):** Briefly discuss the activity, highlighting the fun and encouraging further creative expression. This activity targets speaking (as students often chat while drawing and during the gallery walk), listening (to the instructions and each other), and mixed creative skills. \n\nSuitable for Grades 5-7.  Materials needed: paper, pencils/crayons. Classroom tips: Emphasize the silliness aspect and reassure students that everyone's drawings will be different and funny. The gallery walk is crucial for building confidence. Provide examples of silly drawings (Appendix 2 mentioned in the original text, but not provided).","content_type":"activity","name":"Silly Self Portrait","activity_type":"Warm-up","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Paper","Pencils/Crayons"],"topic_tags":["Self","Art","Icebreaker"]},
  {"id":"scraped-altcir-handbook-but-practice-214","text":"This activity focuses on practicing the conjunction \"but.\" Start by writing example sentences on the board using \"but\" to connect contrasting ideas (e.g., \"I like pizza, but I don't like burgers.\"). Explain the meaning of \"but\" to students, emphasizing its role in showing contrast. Next, model a few example sentences aloud, encouraging students to repeat them. Divide students into pairs. Provide students with sentence starters (e.g., \"I am happy...but...\"; \"My favorite color is...but...\") written on the board or on handouts. Students take turns completing the sentences with their own ideas, using \"but\" to create a contrasting statement. Monitor and assist students while they are working in pairs, providing corrective feedback on pronunciation and grammar as needed. Then, have pairs share their sentences with the whole class. As a variation, provide picture prompts or topic prompts to give students more focused practice (e.g., \"I like cats, but...\"; \"I want to go to the park, but...\"). This activity targets speaking and grammatical accuracy. It is suitable for Junior High School Year 1 (Grade 7). The only materials needed are a whiteboard or paper for writing example sentences and prompts. Classroom tips include providing scaffolding by offering sentence starters and modeling pronunciation.","content_type":"activity","name":"'But' Practice","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Whiteboard/Paper","Markers/Pens"],"topic_tags":["Grammar","Speaking","Conjunctions"]},
  {"id":"scraped-altcir-handbook-but-questions-215","text":"This activity helps students practice the conjunction 'but' and review 'like' questions and answers. First, prepare a worksheet with 'like' questions, each missing a subject (e.g., 'What does ____ like to eat?'). Provide a list of subject choices (e.g., 'your mother', 'your father', 'your friend'). Students choose a subject and complete the questions. Next, in pairs, students ask and answer the completed questions. Students write down the answers given by their partner, including a 'but' statement to add detail (e.g., 'My friend likes pizza, but he doesn't like salad.'). This activity targets both speaking and writing skills. It is best suited for grades 5-7. Materials needed are worksheets and pencils. Classroom tip: model the activity with a student before pair work.","content_type":"activity","name":"But Questions","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheets","Pencils"],"topic_tags":["Question Formation","Conjunctions","Likes/Dislikes"]},
  {"id":"scraped-altcir-handbook-question-and-answer-drill-216","text":"This activity focuses on practicing question and answer skills. The ALT reviews how to ask and answer specific questions in simple English. The JTE acts as a demonstration partner and provides Japanese explanations if needed. \n\n**How to Play:**\n1.  The ALT introduces or reviews the target questions and answers (e.g., \"What's your name?\", \"My name is...\").\n2.  The JTE demonstrates the interaction by asking and answering the questions. The JTE provides Japanese translation as necessary to ensure understanding.\n3. Both the ALT and JTE circulate throughout the classroom, listening to student pronunciation and offering corrections.\n4. Students practice asking and answering the questions in pairs or small groups.\n\n**Language Skills:** Speaking and Listening are the primary focus, with some Reading and Writing based on the written questions. \n\n**Suitable Grades:** Primarily for grades 5-7. \n\n**Materials:** None needed.\n\n**Classroom Tips:**\n*   Keep it simple and focus on clear pronunciation.\n*   Encourage students to use full sentences.\n*   Have the JTE and ALT monitor and help as needed.","content_type":"activity","name":"Question and Answer Drill","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":[],"topic_tags":["Q&A","Greetings","Basic English"]},
  {"id":"scraped-altcir-handbook-sports-rules-q-a-217","text":"This activity encourages students to ask and answer questions about sports rules, promoting speaking and listening skills. Students are divided into pre-assigned groups (e.g., lunch groups). Each group is given a task to find out more about the rules of a sport. Students earn points for asking teachers and classmates questions about the rules. The more they interact and seek information, the more points they earn. Teachers can provide points depending on the correctness of the rules as well as the variety of people they talk to (discouraging cliques). At the end of the activity, each group's average score is calculated. Give the students a few minutes to collaborate in their groups at the end and review each other's work. This collaborative approach encourages participation and peer support. Prizes can be awarded for the highest team and individual scores. Suitable for Junior High School students.","content_type":"activity","name":"Sports Rules Q&A","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":[],"topic_tags":["sports","rules","questioning"]},
  {"id":"scraped-altcir-handbook-sports-rules-card-game-218","text":"This activity targets listening comprehension and the grammatical use of 'must' and 'have to' in the context of sports rules. Divide the class into groups of four and distribute a set of cards related to various sports to each group. The ALT reads aloud a short passage describing the rules of a sport, using 'must' and 'have to'. Students listen and try to identify the sport and grab the corresponding card from their group's set. The first student in each group to grab the correct card keeps it. The student with the most cards at the end wins. Suitable for junior high school students. Materials needed: sets of sports cards, passages describing sports rules. Classroom tip: Vary the passages for different sports. Adjust difficulty based on student level.","content_type":"activity","name":"Sports Rules Card Game","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Sports cards","Passages with sports rules"],"topic_tags":["Sports","Rules","Grammar: must/have to"]},
  {"id":"scraped-altcir-handbook-sports-card-game-219","text":"This activity focuses on speaking about sports and understanding their descriptions. Prepare sets of fourteen cards, each with a picture of a sport. Create a list describing each sport and its rules. \n\n1.  Introduce the sports vocabulary to the students if needed. You can show them flashcards. \n2.  Divide students into groups of four. Distribute a set of cards to each group. \n3.  One student picks up a card and describes the sport shown (without saying the sport's name) based on the provided list of descriptions. \n4.  Other students try to guess the sport. The first student to guess correctly gets to pick the next card and describe the sport. \n5.  Encourage students to use target language for describing actions, locations, and rules. \n\nThis game targets speaking and listening skills. It is best suited for 5th to 7th grade, or even higher, depending on the students' levels. The main materials are the sports cards and the descriptions list. Classroom tip: Vary the complexity by providing students with more or less descriptive language to use or require the use of specific sentence structures.","content_type":"activity","name":"Sports Card Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Sport picture cards","Sport description list"],"topic_tags":["Sports","Vocabulary","Describing"]},
  {"id":"scraped-altcir-handbook-game-card-instructions-220","text":"This activity focuses on giving and following instructions, which can be adapted for a variety of games using game cards. The ALT prepares game cards with instructions or prompts. The ALT and JTE jointly introduce the game, model how to play, and clarify rules. The JTE may translate instructions to ensure comprehension, especially for younger learners. Encourage students to communicate with each other in English during gameplay. This reinforces speaking and listening skills. Make sure to circulate around the classroom and provide support where needed. Adapt the difficulty of the instructions according to student abilities. This can also be adapted to review previously learned vocabulary and grammar. Ensure the ALT prepares materials according to the student abilities, and be prepared to assist the JTE in modeling the activity.","content_type":"activity","name":"Game Card Instructions","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Game Cards","Instructions"],"topic_tags":["instructions","games","speaking","listening"]},
  {"id":"scraped-altcir-handbook-card-grab-221","text":"Card Grab is a fast-paced activity to get students moving and listening attentively. Prepare a set of cards with pictures or words related to a specific topic (e.g., animals, food, actions). The ALT describes one card at a time, providing clues. For example, the ALT might describe a 'dog' by saying, \"It has four legs. It barks. It is a pet.\" Students listen carefully and, when they think they know what card the ALT is describing, try to grab the correct card. The ALT should finish the description and say \"Go!\" before the students can grab the card. This encourages careful listening. The first student to grab the correct card gets a point (or other reward). This targets listening and speaking skills, suitable for Junior High School 1st and 2nd years. Materials needed include the cards. Classroom tip: Set a clear rule for when students can grab the card to ensure fair play.","content_type":"activity","name":"Card Grab","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":8,"complexity_max":2,"interaction":"Whole class","materials":["Cards with pictures/words"],"topic_tags":[]},
  {"id":"scraped-altcir-handbook-sports-descriptions-222","text":"This activity focuses on reading and comprehension of simple descriptions. Students read short paragraphs about various sports, identifying key features. \n\n**How it works:**\n1.  **Preparation:** Prepare short descriptions of various sports (baseball, soccer, swimming, etc.). The provided text can be used directly or adapted. Ensure descriptions include key vocabulary related to the sport (e.g., racket, bat, court, goal).  \n2.  **Introduction (Warm-up - 5 minutes):** Briefly review sports vocabulary. Write a few key sports terms on the board (e.g., \"ball,\" \"team,\" \"score\") and elicit their meanings.\n3.  **Reading and Matching (Main Game - 7 minutes):** Give each student a printed description of a sport. Have them silently read the description. Then, provide a set of picture cards or sport names. Students must match the description with the correct sport. Alternatively, students can write down the sport's name after reading.\n4.  **Pair/Group Discussion (Production/Review - 3 minutes):**  Students can pair up to discuss the sports, comparing them. They can share what they know, what they like or dislike, and compare any similarities or differences.\n\n**Targeted Skills:** Reading comprehension, vocabulary recognition, speaking (in the follow-up). \n\n**Suitable Grade Levels:** 5-7 (can be modified for lower grades with simpler descriptions). \n\n**Materials:** Printed descriptions of sports, pictures or names of different sports, worksheets, the board for vocabulary.","content_type":"activity","name":"Sports Descriptions","activity_type":"Main Game","skill":"Reading","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["printed descriptions of sports","pictures or names of different sports"],"topic_tags":["sports","reading comprehension","vocabulary"]},
  {"id":"scraped-altcir-handbook-there-be-verb-sentences-223","text":"This activity focuses on teaching the grammatical structure 'There BE VERB' to describe objects and locations. The activity spans a full 50-minute class, progressing from simple to complex sentence structures.  \n\n**Procedure:**\n1.  **Introduction (PowerPoint & Handout):** Begin by showing simple pictures (e.g., a princess) and prompting students to respond with 'There BE VERB...' sentences (e.g., \"There is a princess.\").\n2.  **Adding Adjectives:** Introduce adjectives to the sentences (e.g., \"There is a beautiful princess.\").\n3.  **Complex Pictures (Group Work):** Present a more complex picture with multiple objects (e.g., a park). Students work in pairs to describe what they see, using \"There are...\" and \"There is...\". (e.g., \"There are many big trees\", \"There is a big pond\"). \n4.  **Hidden Object Picture (Partner and Individual Work):** Show a 'hidden objects' picture (e.g., a kitchen). Students first speak with a partner, taking turns describing objects using 'There' sentences.  Then, they individually write up to 5 sentences.\n5.  **Location Descriptions (Partner and Individual Work):** Show a picture emphasizing location. Students, again in pairs, point out objects and their location, using sentences like \"There is an old hat on the table.\". They then write 5 sentences individually.\n6.  **Sentence Comparison (Partner and Individual Work):** For the final slide, students say and write two sentences: a 'There' sentence and a 'non-there' sentence. (e.g., \" There is an expensive watch near the lamp\" and \" An expensive watch is near the lamp\"). Students then write both versions down.\n\nThis activity develops speaking and writing skills, allowing students to build fluency with 'There BE VERB' structures in various contexts.","content_type":"activity","name":"There BE VERB Sentences","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Pictures (PowerPoint Slides)","Handouts"],"topic_tags":["grammar","sentence structure","description"]},
  {"id":"scraped-altcir-handbook-describe-the-picture-224","text":"This activity encourages students to create sentences without relying on written words. The ALT and JTE model the activity for student pairs, demonstrating how to describe a picture or scene, taking turns speaking. The instructions can be given by either teacher, preferably in English, using modeling to clarify. The students will work in pairs to describe the given picture. While students are working, the ALT and JTE circulate to provide assistance and help students express their ideas in English. This promotes spoken fluency and descriptive vocabulary.\n\nLanguage skills targeted: Speaking\nSuitable Grade Levels: Elementary/Junior High\nMaterials Needed: Pictures, picture cards\nClassroom Tips: Avoid Japanese explanations. Encourage students to help each other.","content_type":"activity","name":"Describe the Picture","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Pictures","Picture cards"],"topic_tags":["Describing","Speaking","Pairs"]},
  {"id":"scraped-altcir-handbook-you-look-like-a-monkey-225","text":"This activity reinforces sentence structure and descriptive vocabulary using the textbook as a foundation. Start with a simple picture from the textbook and have students describe it using simple words. Encourage students to build more complete sentences, adding adjectives and prepositions to create a descriptive sentence like \"There is a pink T-shirt on the bed.\" Provide a cheat sheet or translations for vocabulary gaps. This game is designed to build practical vocabulary and improve sentence structure. Encourage students to create lists, use dictionaries or provide translations for words they do not know. This activity builds on textbook content.","content_type":"activity","name":"You Look Like a Monkey","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Textbook pictures","Cheat sheets (optional)","Dictionaries (optional)"],"topic_tags":["Descriptive language","Vocabulary","Sentence structure"]},
  {"id":"scraped-altcir-handbook-gesture-guessing-game-226","text":"This speaking activity helps students practice the grammar point 'You look (adjective)' or 'You look like a (noun)'. Students form groups of four and are given fifteen face-down slips of paper with adjectives and nouns. One student at a time secretly looks at a slip, then acts out the word using gestures only. The other students in the group try to guess the word, using the target grammar. For example, if the word is 'sleepy,' the student acting should mime being tired. If a student guesses correctly, they earn a point. The student must use the correct grammar to get the point, saying something like, 'You look sleepy!' The student with the most points at the end wins. The JET and JTE should demonstrate the game beforehand to ensure understanding. Suitable for reinforcing vocabulary and grammar in a fun, interactive way. Materials needed: slips of paper with adjectives/nouns. Classroom Tip: Prepare the words on the slips ahead of time and ensure they are age-appropriate and familiar to the students.","content_type":"activity","name":"Gesture Guessing Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["slips of paper with adjectives/nouns"],"topic_tags":["grammar","vocabulary","gestures"]},
  {"id":"scraped-altcir-handbook-adjective-noun-mix-up-227","text":"This activity aims to boost speaking and vocabulary skills. Students will work in groups to create silly sentences. First, prepare slips of paper with a list of adjectives and nouns (e.g., \"sleepy,\" \"sumo wrestler\"). Each group receives a set of these word slips. Students take turns drawing one adjective and one noun. They then create a sentence using the words they picked. For example, if they draw \"sleepy\" and \"sumo wrestler,\" they might say, \"The sleepy sumo wrestler is tired.\" The sillier the sentence, the better! This activity encourages creative thinking and language production. Classroom tip: encourage students to use different sentence structures. It's a fun way to review adjectives and nouns. Ensure all groups have a set of words. This can be adapted with a time limit for each sentence creation, or points awarded for creative sentences.","content_type":"activity","name":"Adjective-Noun Mix-Up","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Paper","Scissors","List of Adjectives and Nouns (printed)"],"topic_tags":["Adjectives","Nouns","Sentence construction","Vocabulary"]},
  {"id":"scraped-altcir-handbook-find-your-match-228","text":"This activity is a whole-class game designed to practice vocabulary and listening comprehension. Before the activity, prepare sets of cards with words or phrases written on them. Each card should have a corresponding match. The teacher distributes the cards to the students, making sure each student receives one. The students' task is to find their match by acting out clues or making gestures related to the vocabulary on their card. Students can mingle around the classroom, presenting their clues and finding their partners. Once a student finds their match, they can check with the teacher to confirm. This activity targets listening and speaking skills and is suitable for junior high school students. The main material needed is the set of vocabulary cards. Classroom tips include walking around the class to monitor student engagement and adjust the difficulty depending on the class.","content_type":"activity","name":"Find Your Match","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Vocabulary cards"],"topic_tags":["Vocabulary","Games","Listening"]},
  {"id":"scraped-altcir-handbook-describe-it-229","text":"Divide students into groups of 4-6. Give each group a deck of cards, each with a vocabulary word the students already know. One student picks a card and describes the word without saying it or using gestures/noises. The other students guess. Students take turns describing words. This targets speaking and listening skills by encouraging students to use different words and phrases to explain a concept. Suitable for elementary and junior high students, with simpler vocabulary suitable for lower grades. Materials needed: Vocabulary cards. Classroom tip: pre-teach/review the vocabulary.","content_type":"activity","name":"Describe It!","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Vocabulary cards"],"topic_tags":["Vocabulary","Speaking","Describing"]},
  {"id":"scraped-altcir-handbook-grammar-auction-230","text":"The JTE and ALT should demonstrate the game a few times before the students play. Write key phrases on the blackboard such as, \"This is a…\" and \"This is similar to…\" along with descriptor words like \"Close\" and \"Different.\" The JTE and ALT should offer support when needed and participate when not. Students can keep score individually or as teams to add motivation and competition.","content_type":"activity","name":"Grammar Auction","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":[]},
  {"id":"scraped-altcir-handbook-grammar-bidding-231","text":"Divide the class into their usual lunch groups. Provide each group with a set amount of play money (e.g., $1000). Prepare a mix of English sentences on the blackboard, half grammatically correct and half with errors. Present one sentence at a time, reading it slowly and having students repeat it. Initiate bidding by saying \"Start the bidding!\" Groups then bid on the sentence in English, competing against each other. After a set time or when only one group remains, award the sentence to the highest bidder, collecting their bid. Continue until all sentences are bid on. Afterwards, have students read their sentences aloud and translate them into Japanese. Award 1 point for each correct sentence and deduct 1 point for each incorrect sentence. The group with the most points wins. In case of a tie, the group with the most points and remaining money wins. This activity targets listening and speaking skills, focusing on sentence structure and grammar recognition. Suitable for upper elementary and junior high students.","content_type":"activity","name":"Grammar Bidding","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Play money","Prepared English sentences","Blackboard or whiteboard marker"],"topic_tags":["grammar","bidding","speaking","games"]},
  {"id":"scraped-altcir-handbook-auction-game-232","text":"This activity involves an auction using \"money\" and English sentences. The ALT prepares the money and sentences, focusing on specific grammar points agreed upon with the JTE. The ALT explains the rules in English, with the JTE translating as necessary. The JTE leads the auction, selecting and reading sentences for students to repeat. The ALT monitors correctness, awarding points for successful sentences. At the end, the JTE facilitates Japanese translations, while the ALT reviews sentence accuracy and announces group scores. This activity targets listening and speaking skills, with a review of basic grammar. \n\nMaterials: Fake money, prepared English sentences, white board or paper for scoring.\n\nClassroom Tips: Ensure sentences are age-appropriate and grammar points are reviewed beforehand. Encourage students to actively participate in repeating the sentences and working with their groups.","content_type":"activity","name":"Auction Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Fake money","Prepared English sentences"],"topic_tags":["Grammar Review","Speaking Practice","Group Work"]},
  {"id":"scraped-altcir-handbook-lost-and-found-233","text":"This activity focuses on practicing descriptions and the different forms of \"have\". The teacher (ALT/JTE) begins by showing a unique object or picture to the whole class, describing it and asking questions. Students take notes. Then, students form pairs and repeat the process with different items. The pairs switch roles. This is repeated multiple times with different items and new partners, focusing on giving directions and asking questions. The remaining time is used to address any problems or praise students' work. This encourages students to work with a variety of partners.\n\nLanguage skills targeted include speaking and listening comprehension. The activity is suitable for Junior High School students. \n\nMaterials needed are unique objects or pictures, and a model dialog/note handout. \n\nClassroom tips: Gradually introduce more challenging items to keep the activity engaging. If the bidding for one sentence is taking a long time, the JLT can stop the bids when they deem it appropriate, or set a time limit for the bidding of each sentence.","content_type":"activity","name":"Lost and Found","activity_type":"Main Game","skill":"Speaking","duration_minutes":34,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Unique objects or pictures","Model dialog and note handout"],"topic_tags":["Descriptions","Have","Speaking practice"]},
  {"id":"scraped-altcir-handbook-around-the-world-travel-planner-234","text":"This activity focuses on present and future tense usage while incorporating time calculations and introducing time zones. First, students are given a departure city (e.g., Tokyo) and a destination city (e.g., New York). Using provided time zone information, students calculate the arrival time in the destination city, writing the time in their notebooks. Students then create a short travel plan, including what they are doing at the time of arrival (e.g., \"When I arrive in New York, I will go to a hotel.\"). This activity targets speaking and writing, reinforcing present and future tense structures while implicitly introducing the concept of time zones. The teacher circulates to offer corrections and support.\n\nSuitable for grades 5-7. Requires time zone charts and a list of cities. Classroom tip: Encourage students to be creative with their travel plans. Consider providing a template to support writing.","content_type":"activity","name":"Around the World Travel Planner","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Time zone charts","City list","Notebooks"],"topic_tags":["Travel","Time","Grammar","Future Tense","Present Tense"]},
  {"id":"scraped-altcir-handbook-time-zone-challenge-235","text":"Divide students into groups and provide each group with a time zone map and a set of instructions. Collaborate with the JTE to prepare the classroom. Review the target questions as a class: \"What time is it in (city) now?\" and \"When will you arrive in (city)?\" Practice related grammatical questions and answers. The activity's goal is to complete as many time zone assignments as possible. When a group finds an answer, they send a representative to the ALT/JTE. The ALT/JTE will quiz the representative using the target questions. A correct answer earns the group the next assignment. There are ten assignments in total. This targets both speaking and listening skills. Helpful tips include pre-teaching vocabulary like 'arrive,' and ensuring students understand the map. Adapt the complexity of assignments based on grade level, starting with easy cities and times. Consider making the activity competitive, e.g., points awarded for speed and accuracy, to increase student engagement.","content_type":"activity","name":"Time Zone Challenge","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Time zone map","Assignment sheets"],"topic_tags":["Time","Geography","Speaking"]},
  {"id":"scraped-altcir-handbook-time-zone-traveler-236","text":"This activity helps students practice telling time in different time zones and understanding time differences. Prepare envelopes with instructions for students. For the first half of the envelopes (#1-5), students must call a city and report the local time when the call will be received. For instance, the envelope might say, \"Please call Delhi at 4:00 PM.\" The time should be in Japanese local time (GMT+9). For the second half of the envelopes (#6-10), students are promoted and must account for time zone differences and flight duration. The envelopes could say something like, \"Please fly from Tokyo to Seoul. You will depart at 9:00 AM. The flight will take 2 hours.\" Explain to students that they have a job in a global company. Their first task is to report the correct time in other global offices based on instructions given in the envelopes. Students should consult a world map to identify time zones. The teacher may want to provide a quick review of time zones before the activity. This activity targets listening, speaking (reporting time), and reading comprehension, and promotes critical thinking about time zones. Suitable for grade levels 5-7. Classroom tips: Start with simpler time zone differences. Provide the answer key. This will enhance the ability of the students to grasp the context of the activity.","content_type":"activity","name":"Time Zone Traveler","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["World map","Envelopes with instructions"],"topic_tags":["Time","Travel","Culture"]},
  {"id":"scraped-altcir-handbook-time-zone-race-237","text":"This activity focuses on practicing the future tense and understanding time zones. \n\nBefore the activity, the JTE should review the future tense grammar. Divide the class into groups. Each group receives a starting location (e.g., Tokyo) and a destination (e.g., New York). Groups must determine the time difference between the two locations using a world map or online resource, and then calculate what time it will be in the destination city at a specific future time in the origin city (e.g., \"What time will it be in New York at 3 PM in Tokyo?\"). The ALT will pose the target questions to the group representatives, or the JTE if the class size necessitates. The ALT gives out the next assignment after each group finishes their calculation. The JTE translates difficult words and explains how to use the map. Either teacher should track group progress on the board to encourage competition.\n\nLanguage skills targeted: Speaking (answering questions), Listening (understanding instructions), Reading (using the map). \n\nSuitable for: Junior High School students (grades 7-9)\n\nMaterials needed: World map, assignment cards with start/end city pairs.\n\nClassroom tips: Encourage the JTE to wander the class if the class struggles, offering help to individual students.","content_type":"activity","name":"Time Zone Race","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["World map","Assignment cards"],"topic_tags":["Time","Future Tense","Geography"]},
  {"id":"scraped-altcir-handbook-sales-team-time-zones-238","text":"This activity simulates a sales team communicating with international branches. Start with an enthusiastic introduction, explaining the context of a Japanese company with global operations. Divide students into groups. Each group represents a sales team. Provide each group with a set of envelopes, each containing a task. The first envelope might involve simple introductions in English. Subsequent envelopes can involve tasks like calculating time differences between Japan and other locations. To encourage participation, change the team representative reporting to the ALT after each task. Focus on the introduction to build interest, and remember that students will likely need some help calculating time zones. This activity combines math and English, which appeals to students with varying academic strengths.","content_type":"activity","name":"Sales Team Time Zones","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Envelopes","Task Sheets (in envelopes)"],"topic_tags":["Time Zones","Communication","Teamwork"]},
  {"id":"scraped-altcir-handbook-sales-pitch-239","text":"This activity focuses on persuasive speaking skills. The JET introduces the concept of sales pitches, explaining that the goal is to convince the audience to buy a product. The ALT and JTE model a sample sales presentation. Next, students are divided into groups of 4-5. Each group receives a physical object (or a picture) to 'sell'. Students write a short sales pitch in their notebooks, which the ALT checks for language accuracy. They then memorize and practice their presentations. Finally, each group delivers their presentation. The ALT, JTE, and students rank the presentations, and the most persuasive group wins a prize. This activity targets speaking and writing skills, encouraging students to use persuasive language and practice presentation techniques.","content_type":"activity","name":"Sales Pitch","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["objects to sell (or pictures)","notebooks or paper","prizes (optional)"],"topic_tags":["persuasion","sales","presentation"]},
  {"id":"scraped-altcir-handbook-classroom-shop-240","text":"This activity focuses on speaking and listening while practicing descriptive language and negotiation. \n\n1. **Preparation:** Gather pictures or actual objects to sell. Prepare journals or paper for students to write on. Create a points sheet for each group or individual, with spaces for points (1-5) to be circled. Consider having prizes for the winning team or individual.\n2. **Introduction:** Introduce the concept of a shop. Show the objects or pictures. Explain that students will be \"selling\" and \"buying\" items.\n3. **Activity:** Divide the class into groups or have students work individually. Assign roles: some students are shopkeepers, others are customers. Shopkeepers choose an item to sell and describe it to potential customers. Customers ask questions about the item (price, size, color, etc.). Students can negotiate the price and quantity. Shopkeepers aim to \"sell\" their item to the customer.\n4. **Assessment:** After each sale, the customer (or the teacher) can award points (1-5) for clarity of description, effective questioning, and successful negotiation skills. Rotate roles after a set time. Tally points at the end.\n\nThis activity helps students practice describing objects, asking and answering questions, and negotiating. It's suitable for elementary or junior high students. \n\nClassroom Tips: Use simple language. Pre-teach useful phrases like 'How much is it?', 'It's...', 'I want to buy...'.","content_type":"activity","name":"Classroom Shop","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Journals/Paper","Pictures/Objects","Points Sheet","Prizes (Optional)"],"topic_tags":["Shopping","Describing Objects","Negotiation"]},
  {"id":"scraped-altcir-handbook-sales-speech-241","text":"This activity focuses on practicing persuasive speaking skills. The ALT and JTE collaborate to choose items for students to 'sell'. First, the ALT and JTE model a successful sales speech together, highlighting key phrases and persuasive techniques. The ALT then explains what constitutes a good speech, perhaps focusing on clarity, enthusiasm, and relevant vocabulary. The JTE can then check for student understanding and provide Japanese explanations if needed. Students, working individually or in pairs, then write their own short sales speeches for their assigned item. The ALT can offer feedback on the written drafts, correcting major grammatical errors outside of class time. Finally, each sales team delivers their speech, and the ALT, JTE, and the class score each presentation based on pre-determined criteria (e.g., clarity, persuasion, use of target language). The ALT compiles the scores to determine a winner. This activity is a great way to improve speaking and listening skills while also incorporating writing and vocabulary development. It allows for differentiation and collaboration, making it engaging for students of varying abilities.","content_type":"activity","name":"Sales Speech","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Items to be sold","Paper or worksheets for writing","Score sheets"],"topic_tags":["Sales","Speaking","Persuasion","Collaboration"]},
  {"id":"scraped-altcir-handbook-the-boy-who-lived-project-242","text":"This activity involves students working on a multi-class project inspired by the book title, 'The Boy Who Lived', likely focusing on creative writing and potentially speaking/presentation. Students will form groups and work towards specific goals, such as creating a group name and writing sentences. The project's duration is flexible, lasting at least three class periods. The specific tasks and the time allotted should be adjusted based on the students' proficiency level. Encourage students by setting achievable goals for each class session. This activity targets multiple skills including writing, teamwork, and potentially speaking if a presentation component is included. Ensure students have clear understanding of the goals for each stage of the project. The activity is very open ended and can be adapted to all level junior high students.","content_type":"activity","name":"The Boy Who Lived - Project","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":[],"topic_tags":["Project","Creative Writing","Junior High"]},
  {"id":"scraped-altcir-handbook-relative-pronoun-movie-clip-243","text":"This activity helps students practice recognizing and using relative pronouns through short movie clips. First, review relative pronouns with the class. Then, divide students into small groups and provide each group with a worksheet. Play a short English movie clip. Groups try to identify a sentence using a relative pronoun. Replay the clip as needed. Groups write the sentence on their worksheet. Check the group answers, and write the correct sentence on the board. Play the clip again for listening practice. Groups translate the sentence into Japanese. Have groups share their translations, then reiterate the correct English sentence and Japanese translation. Repeat with another clip.","content_type":"activity","name":"Relative Pronoun Movie Clip","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Movie clips (with relative pronouns)","Worksheets","Projector/screen"],"topic_tags":["grammar","relative pronouns","listening","speaking","movie clips"]},
  {"id":"scraped-altcir-handbook-movie-scene-description-244","text":"This activity reviews relative pronouns by having students describe a movie scene. First, select a well-known movie that students are likely familiar with. Then, show a short scene (2-3 minutes) from the movie without sound. After watching, have students work in pairs. Each pair discusses what they saw and writes a short description of the scene, using relative pronouns (who, which, that, where, whose). For example, \"The man *who* is wearing a hat is the main character.\" \"The place *where* they are fighting is a forest.\" Circulate and assist with vocabulary and grammar. Finally, have a few pairs share their descriptions with the whole class. This allows for peer correction and provides opportunities to review common mistakes. The primary goal is to practice using relative pronouns in context, while encouraging students to engage with English media. The selection of a popular movie helps to engage student interest. This activity works best if students have a basic understanding of relative pronouns.","content_type":"activity","name":"Movie Scene Description","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Movie clip","Projector or screen","Paper and pencils"],"topic_tags":["Relative Pronouns","Movies","Describing"]},
  {"id":"scraped-altcir-handbook-location-advice-245","text":"This activity helps students practice \"there is/are\" and plurals while giving advice about a location. \n\n1.  **Preparation**: Before class, draw a simple map of a fictional location (e.g., a park, a school, a shopping mall) on the whiteboard. Include several objects or features (e.g., a tree, a playground, a bench). Prepare some example sentence starters (e.g., \"There is a…\", \"There are…\", \"You should…\", “You shouldn’t…\")\n2.  **Introduction (Warm-up - 5 minutes)**: Review \"there is/are\" and plurals with quick examples. Elicit example sentences from students about classroom objects. Write the sentence starters on the board.\n3.  **Activity (Main Game - 10 minutes)**: Point to different features on the map. Ask students to describe them using \"there is/are.\" Then, have students take turns giving advice about the location. Example: \"There is a playground. You should play there. There are many trees. You shouldn’t litter.\"\n\n**Classroom Tips**: Keep the map simple to avoid confusion. Encourage students to use various vocabulary related to location and activities.","content_type":"activity","name":"Location Advice","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard/Paper","Markers/Pens","Map (drawn in advance)"],"topic_tags":["Location","Grammar: There is/are","Plurals","Advice"]},
  {"id":"scraped-altcir-handbook-town-description-246","text":"This activity helps students practice describing locations in their town. First, the teacher prepares a drawing of a town scene on a large piece of paper, leaving parts incomplete. The teacher will also write target vocabulary words (e.g., 'next to,' 'across from,' 'between') and a list of town locations (e.g., post office, police station, train station) on the board or on the pre-drawn paper. Students are given a worksheet with questions and prompts to guide their descriptions. In pairs, students use the worksheet, vocabulary, and town location list to describe their town. One student describes a location and the other student tries to guess what place their partner is talking about. Students can use dictionaries for support. The teacher can then have students create their own town scenes on their individual blank papers based on what they heard. This activity targets speaking and listening skills and helps reinforce vocabulary related to location and description.","content_type":"activity","name":"Town Description","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Large paper with pre-drawn town scene","Blank paper for students","Target vocabulary list (on board or pre-drawn paper)","Worksheet with questions/prompts","Town location list","Dictionaries (English/Japanese and Total English 3)"],"topic_tags":["location","description","vocabulary","speaking"]},
  {"id":"scraped-altcir-handbook-drawing-dictation-247","text":"This activity focuses on descriptive language and listening comprehension. The teacher (JET) prepares a large drawing incorporating target vocabulary (e.g., house, cat, tree, next to, above). The JTE and JET model the activity. The JET describes the picture, and the JTE attempts to draw it based on the description. Students then receive blank paper. They draw a picture on the top half using provided target vocabulary (written on the board or handout). Students pair up. Partner A describes their picture, and Partner B attempts to draw it on the bottom half of their paper, without seeing A's original picture. Partners switch roles.  The JET and JTE should model the use of 'There is' vs 'There are' as a review, using examples on the board. Students can then share their drawings and descriptions. Focus is on accurate use of prepositions and spatial vocabulary.","content_type":"activity","name":"Drawing Dictation","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Blank paper","Markers/pencils","Target vocabulary list/handout","Example drawing (prepared by JET)"],"topic_tags":["Spatial relations","Prepositions","Descriptive language","Drawing"]},
  {"id":"scraped-altcir-handbook-preposition-drawing-248","text":"This activity focuses on prepositions of place. First, the teacher introduces target vocabulary related to prepositions (e.g., on, in, under, next to) and nouns (e.g., house, tree, car). The teacher models the language: \"The cat is in the car.\" Students then secretly draw an image incorporating the target vocabulary. For the guided practice, students work in pairs. One student describes their drawing using the target prepositions and nouns, while the partner attempts to draw it based on the description. Students can be creative with their drawings. The activity targets both listening and speaking skills. For the independent practice, modify to suit student ability, providing extra vocabulary or doing one topic together. Suitable for Grade 5-7. Materials include paper and pencils/crayons. Classroom tip: emphasize the importance of listening carefully and using the target prepositions correctly.","content_type":"activity","name":"Preposition Drawing","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper","Pencils/Crayons"],"topic_tags":["Prepositions","Describing","Drawing"]},
  {"id":"scraped-altcir-handbook-loan-word-translation-249","text":"This activity aims to show students that making mistakes is a natural part of language learning while practicing vocabulary and translation skills. Prepare a handout with 20 numbered loan words and a word bank of 20 corresponding words in either English or Japanese. Divide students into groups of four. Students must match the words in the word bank to the numbered words without using dictionaries for the first 15 minutes. The loan words are selected to encourage mistakes. For example, the Japanese word \"マンション\" (manshon) will be matched with \"mansion,\" leading students to realize their initial assumptions are incorrect. Other examples include \"アイス\" (aisu) with \"ice\" and \"バイキング\" (baikingu) with \"Viking.\" As students use more words, they'll start to reconsider their matches. Allow dictionary use near the end to help students complete the task. Finally, review each word as a whole class for 10-15 minutes, discussing the correct meanings and common mistakes. This helps reinforce the learning process and highlights the value of error correction.","content_type":"activity","name":"Loan Word Translation","activity_type":"Main Game","skill":"Reading","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Handout with numbered words","Word bank","Dictionaries (optional)"],"topic_tags":["Vocabulary","Translation","Loan Words","Mistakes"]},
  {"id":"scraped-altcir-handbook-janglish-worksheet-250","text":"This activity focuses on correcting common English errors made by Japanese speakers. First, distribute the worksheet, which contains sentences with typical Janglish mistakes. Students work individually or in pairs to identify and correct the errors. Encourage students to think about the meaning and grammatical rules. After a set time, review the answers as a whole class, eliciting corrections from students and explaining the correct grammar. As a follow-up, students can write their own Janglish sentences for their classmates to correct. This reinforces understanding of common errors and improves overall English accuracy. This activity is a great way to improve grammar and writing skills, promoting critical thinking about English usage.","content_type":"activity","name":"Janglish Worksheet","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Janglish worksheet","dictionary (optional)"],"topic_tags":["grammar","writing","errors"]},
  {"id":"scraped-altcir-handbook-group-problem-solving-251","text":"Divide the class into groups of 3-4 students. Present a worksheet or a series of questions that require problem-solving or knowledge application. The activity is designed to be student-centered; the JTE and ALT should circulate and offer general guidance without directly providing answers. The focus is on encouraging students to collaborate, discuss, and support each other in finding solutions. Teachers should observe group dynamics and note common challenges or misunderstandings. Near the end of the allotted time, students can use dictionaries if needed. The ALT can then provide the correct answers and offer explanations.\n\nLanguage skills targeted include listening (to each other’s ideas), speaking (discussing), and reading (interpreting the questions). The activity suits grades 5-7. No specific materials are needed beyond the worksheet and writing implements. Classroom tip: pre-teach the key vocabulary or sentence structures required for the task. Ensure groups are mixed-ability to promote peer support and provide a clear time limit to manage classroom flow.","content_type":"activity","name":"Group Problem Solving","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Worksheet","Pens/Pencils","Dictionaries (optional)"],"topic_tags":["Collaboration","Problem Solving","Group Work"]},
  {"id":"scraped-altcir-handbook-name-that-adjective-252","text":"This activity helps students learn and apply adjective vocabulary to describe objects. The teacher begins by introducing adjective vocabulary related to touch, size, shape, and color using flashcards. Students repeat the words. Then, students are given a handout with an adjective word bank and a table listing various objects. Students form small groups of 4-5 and are given a different object to examine and describe using four adjectives from the word bank. The objects rotate until each group has seen them all. If groups finish early, they can write descriptive sentences. The ALT and JTE can model the activity. This activity targets vocabulary related to describing objects. It can be adapted for any level. Materials include adjective flashcards, a handout, and various objects like a fake flower, stuff animal, magnet, bubble wrap, seashells, cloth, and picture frame. Classroom tips include pre-determining groups, establishing rules for handling objects, using a timer, and providing support for struggling students.","content_type":"activity","name":"Name that Adjective","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Adjective flashcards","Handout","Fake flower","Stuff animal","Magnet","Bubble wrap","Seashells","Cloth","Picture frame"],"topic_tags":["Adjectives","Vocabulary","Describing objects"]},
  {"id":"scraped-altcir-handbook-price-is-right-numbers-253","text":"This activity focuses on reading and writing large numbers, culminating in a fun game show format. Begin by providing students with a hint sheet explaining how to read large numbers (e.g., thousands, millions). Then, students pair up. One student looks at a number displayed on the screen (projected via PowerPoint or whiteboard) and reads it aloud. The other student, without looking, writes the number down on a memo sheet. They switch roles and repeat a few times, increasing the size of the numbers. Next, students form groups of four and are given a whiteboard and marker. The teacher displays pictures of various items (e.g., an Arashi concert DVD, a new game console) and their prices. Groups must guess the price, write it on their whiteboard, and read it out loud. The group with the closest guess wins a point. The group with the most points at the end wins a small prize. This activity targets listening, speaking, reading, and writing skills, while integrating vocabulary and number recognition.\n\nClassroom Tips: Prepare a good selection of item pictures and their corresponding prices. Vary the difficulty of the numbers depending on the students' ability. Encourage clear pronunciation and writing.","content_type":"activity","name":"Price is Right - Numbers","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Hint sheet (big numbers)","Memo sheets","Projector (or whiteboard)","Pictures of items & prices","Whiteboards","Markers","Small prize for the winning group"],"topic_tags":["Numbers","Listening","Speaking","Reading","Writing","Game"]},
  {"id":"scraped-altcir-handbook-memo-match-254","text":"This activity focuses on listening and speaking. Start by preparing a PowerPoint presentation with vocabulary words and simple sentences related to a specific topic. Show the PowerPoint slides one by one, reading the word/sentence aloud clearly. Students listen and then write the word/sentence on their memo sheets. After all slides are shown, divide the class into pairs. One student in each pair has their memo sheet. The other student has a blank whiteboard. One student says a word or sentence from the lesson. The other student writes the word or sentence on their whiteboard. If the sentence is correct, the students get a point. If it is incorrect, their partner corrects them. They switch roles after a few turns. This activity targets listening and speaking skills, reinforcing vocabulary and pronunciation. Suitable for grades 5-7. Requires a PowerPoint file, projector, PC/laptop, memo sheets, and small whiteboards and markers. Tip: Encourage students to speak clearly and listen carefully. Adjust the complexity of the sentences to suit the students' proficiency level.","content_type":"activity","name":"Memo Match","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Memo sheets","PowerPoint file","Projector","PC/laptop","Small whiteboards","Markers"],"topic_tags":["Vocabulary","Listening","Speaking"]},
  {"id":"scraped-altcir-handbook-overpopulation-simulation-255","text":"This activity simulates the effects of overpopulation. First, students form a circle with their desks, representing the Earth. The teacher writes \"overpopulation\" on the board and elicits the Japanese translation. Then, the teacher uses a talking ball to discuss the headline \"7 Billionth Person Born on Halloween\" and student reactions. Next, students are told each represents 200,000,000 people. Over 11 minutes, students enter the circle (Earth), representing population growth. The teacher provides limited resources (water and KitKats) to represent scarcity. As students enter, they take a resource until the supply runs out. The teacher asks questions to prompt students to think about space, food, and cost of living. Finally, students return to their seats for a worksheet. This game targets listening comprehension and encourages critical thinking about overpopulation and its effects.","content_type":"activity","name":"Overpopulation Simulation","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Desks","Water","KitKats","Talking ball","Worksheet"],"topic_tags":["Environment","Social Studies","Global Issues"]},
  {"id":"scraped-altcir-handbook-kitkat-water-256","text":"This activity focuses on listening comprehension and reaction, suitable for upper elementary and lower junior high school students. Arrange desks in the center of the room to represent \"Earth.\" Give each student a worksheet with questions and space to write or draw their reactions. Begin by pouring water from the jug into some of the paper cups, not all of them. Explain that you will be giving out KitKats and water, but not to everyone. Read a short story or give instructions related to environmental topics. After each instruction or piece of information, students who received water or KitKats (or both) can raise their hands. After the reading, ask comprehension questions based on the story, and have students write or draw their reactions on the worksheet. This activity can be adapted depending on the topics for students to practice listening and reaction skills.","content_type":"activity","name":"KitKat & Water","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["KitKats","Jug of water","Paper drinking cups","Worksheets","Desks"],"topic_tags":["Environment","Listening Comprehension","Reaction"]},
  {"id":"scraped-altcir-handbook-circle-time-257","text":"This activity focuses on following instructions and understanding numbers. The ALT explains the activity and calls out a number, such as \"Five students!\" Students then move into the center of the classroom to form a circle with that many members. The JTE can assist with instructions in Japanese or encourage students to participate. This activity targets listening comprehension and basic numerical understanding. The ALT should monitor time and ensure all students participate. It can be easily adapted by changing the number called out or adding a thematic component. For example, if the topic is families, the ALT could say \"Three children!\" or \"Five family members!\" This activity is appropriate for a variety of English levels. The JTE should also help explain the significance of the activity and its connection to population growth if needed.","content_type":"activity","name":"Circle Time","activity_type":"Warm-up","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["numbers","instructions","population"]},
  {"id":"scraped-altcir-handbook-detective-present-perfect-258","text":"This activity focuses on practicing the present perfect tense with 'for' and 'since' through a detective game. The teacher begins by announcing a theft and assigning students the role of detectives. Each student receives a card with prompts like '[be a member of soccer club] [2 years]'. Students interview three classmates, using the prompts to construct present perfect sentences in the third person (e.g., \"He has played baseball since last year\"). After interviews, the teacher reveals the thieves' details. Students then identify the thieves, who are brought forward and questioned using the present perfect tense. This activity targets speaking and listening, specifically focusing on present perfect sentence construction and comprehension.","content_type":"activity","name":"Detective Present Perfect","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Cards with prompts"],"topic_tags":["Present Perfect","Speaking","Listening","Games"]},
  {"id":"scraped-altcir-handbook-present-perfect-detective-259","text":"This activity is designed to practice the present perfect tense in a fun, engaging way.  \n\n**How to Play:**\n\n1.  Prepare 40 cards with various actions (e.g., eaten pizza, broken a window, visited Kyoto) written on them.  Make 5 cards that specifically match details the teachers will provide about the thief.  \n2.  Distribute interview sheets to the students.  \n3.  Divide the class into groups of 4-5 students, assigning each a number.  \n4.  Tell a story about a thief, giving details about the crimes using present perfect (e.g., \"The thief has eaten all the pizza!\").  Students listen carefully. \n5.  Each group sends one representative to collect a card from you.  The representative quickly returns to their group. \n6.  Groups discuss the card and decide if their card describes the thief based on the teacher’s story. They can use the present perfect tense to discuss: \"Has the thief eaten pizza?  Yes, the thief *has* eaten pizza!\" or \"Has the thief visited Kyoto? No, the thief *hasn't* visited Kyoto!\" \n7.  If a group believes their card matches the thief's actions, they write the matching phrase on their interview sheet. \n8.  After 5 rounds (or a time limit), the teacher reveals which cards match. Groups get a point for each correct match.  \n9. The group with the most correct matches wins.\n\n**Language Skills:** Speaking and Listening (present perfect grammar practice)\n**Suitable Grades:** 5-7 (can be adapted)\n**Classroom Tips:** Pre-teach the target grammar (present perfect). Consider having students write the answers down first. Make sure your details match only one or two cards at a time.","content_type":"activity","name":"Present Perfect Detective","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["40 cards with actions","Interview sheets","Thieves sheet (teacher's clues)"],"topic_tags":["present perfect","grammar","game","speaking"]},
  {"id":"scraped-altcir-handbook-detective-game-260","text":"This activity is a role-playing game where students become detectives trying to identify thieves. First, prepare cards with descriptions. Some cards will be 'thieves' and have matching information to a few students. Distribute the cards. Students raise their hands if they match any information on their cards. The 'detectives' (non-thieves) try to identify the thieves by asking questions and listening to the answers. During the information phase, all students begin with their hands raised. They lower their hands only when they do not have a matching answer. This helps build suspense. The questions will be prepared. Most of the information on the cards matches until the last question. This keeps students engaged as they try to 'catch' the thieves. This activity targets listening and speaking skills. It's suitable for elementary school and lower junior high school grades. Materials needed are pre-made cards with descriptions. Classroom tips: emphasize the role-playing aspect. Stress that they are detectives and their classmates are the thieves.","content_type":"activity","name":"Detective Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Pre-made cards with descriptions"],"topic_tags":["Role-playing","Listening comprehension"]},
  {"id":"scraped-altcir-handbook-relative-pronoun-questions-261","text":"This activity focuses on relative pronouns (who, which, whose) and vocabulary review. First, review new vocabulary with flashcards and choral repetition. Then, present example sentences using relative pronouns, explaining their function. Divide students into groups. Each group creates 12 questions using relative pronouns, spread across three sheets with varying point values based on difficulty: Sheet A (new vocabulary, 3 points), Sheet B (previous lessons, 2 points), and Sheet C (general knowledge, 1 point). Students have 12 minutes to write questions and answers. Check the questions for accuracy. Each team then selects 6 questions to ask the class, choosing another team to answer. Points are awarded to both the question-posing and answering teams based on the sheet used. Finally, tally points and award a prize to the winning team. This activity encourages collaborative question creation and reinforces language usage.","content_type":"activity","name":"Relative Pronoun Questions","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Flashcards","Paper sheets (A, B, C)","Pens/Pencils","Prize (optional)"],"topic_tags":["Grammar","Vocabulary","Questioning","Collaboration"]},
  {"id":"scraped-altcir-handbook-flashcard-challenge-262","text":"This activity is a fun way to review vocabulary or grammar. Divide the class into groups and give each group a set of flashcards and a sheet (A, B, or C - the sheet type should vary to differentiate questions between groups, but all questions must test the same language target, e.g. 'What's this?' for vocabulary; or 'Can you...?' for functions.)\n\nShow a flashcard to a group and have them discuss the answer for a few moments. Then, call on the first group to raise their team flag (or some similar indicator). If the group's answer is correct, award them a point. If they are incorrect, move on to the next group until you get a correct answer.\n\nAfter each question, show the flashcard again, and repeat the correct answer for reinforcement. Continue until all the flashcards have been used, or you run out of time. At the end, tally the points and award prizes to the winning team.\n\nThis activity is useful for reinforcing vocabulary, sentence structures and question forms. The competitive element increases student engagement. Ensure that the flashcards match the target language of your textbook.","content_type":"activity","name":"Flashcard Challenge","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Flashcards","Sheets A, B, and C","Team flags","Prizes"],"topic_tags":["Vocabulary","Grammar","Review","Games"]},
  {"id":"scraped-altcir-handbook-relative-pronoun-sentence-race-263","text":"This activity focuses on practicing relative pronouns. \n\n1.  **Preparation:** The ALT prepares example sentences using relative pronouns, writing them on the board. The flashcards should contain the new English words and Kanji. \n2.  **Explanation:** The JTE explains the grammatical rules of relative pronouns.  \n3.  **Group Work:** Students are divided into groups. The ALT gives instructions (using gestures) and students create their own sentences using relative pronouns. The ALT and JTE circulate, offering assistance and correcting errors.  \n4.  **Assessment and Scoring:** The ALT collects the students’ sentences and awards points for correct sentences and answers. The JTE records the scores on the board.\n5.  **Review and Q&A:** The ALT encourages students to ask questions about the sentences, helping with pronunciation if needed and selecting teams to provide answers. The JTE keeps score on the board. \n6.  **Wrap-up:** Prizes are awarded, and the ALT and JTE thank the students.\n\nThis activity targets speaking and writing skills. Suitable for grades 5-7. Requires flashcards, example sentences on the board, and a way to track team scores (board/paper).","content_type":"activity","name":"Relative Pronoun Sentence Race","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Flashcards (words/kanji)","Board or paper for scores","Prizes"],"topic_tags":["Grammar","Sentence Structure","Relative Pronouns","Teamwork"]},
  {"id":"scraped-altcir-handbook-to-infinitive-sentence-builder-264","text":"This activity focuses on understanding and using the infinitive form of verbs. \n\n1.  **Introduction (2 minutes):** Briefly explain what an infinitive verb is (e.g., to go, to eat, to play). Write some example sentences on the board.\n2.  **Sentence Building (8 minutes):** Provide students with a set of action verbs written on small cards (e.g., eat, play, run, read). Give each student (or pair/group) a card with a 'to' infinitive, written on it. Students then need to create their own sentences using their provided \"to\" verb card. Encourage them to be creative with their sentences.\n3.  **Sharing (5 minutes):** Have students share their sentences with the class. Monitor and offer feedback, correcting any grammatical errors, and praising strong sentence construction. Write selected sentences on the board.\n\nThis activity targets the production of sentences and listening comprehension as students listen to the example sentences created by their classmates. It's suitable for elementary school grades 5-7. \n\nMaterials needed: Paper and pens/pencils or small cards with verbs. \nClassroom Tip: Encourage students to use a variety of nouns and adjectives to make their sentences more interesting. Pair weaker students with stronger ones.","content_type":"activity","name":"To-Infinitive Sentence Builder","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper","Pens/Pencils or Small verb cards"],"topic_tags":["Grammar","Verbs","Sentence building"]},
  {"id":"scraped-altcir-handbook-infinitive-battleship-265","text":"This activity reviews the infinitive verb form using a Battleship game. First, review the target grammar point (infinitives) with the JTE. The ALT reads the first part of sentences from the game board columns, and students repeat. The second parts of sentences from the rows are read and repeated. Review the grammar again, emphasizing how the sentence parts combine to make complete sentences. Explain Battleship game rules: students get three ships (1, 2, and 3 spaces long) to place on their grid. Students take turns attacking squares, trying to sink their partner's ships. Explain the terms: \"Hit,\" \"Miss,\" \"Attack,\" and \"You sunk my battleship.\" Students play in pairs. The winner is the first to sink all their opponent's ships. If there's an odd number of students, the JTE or ALT can participate. Afterwards, randomly call on students to create their own sentences using the infinitive form.","content_type":"activity","name":"Infinitive Battleship","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Battleship game boards (prepared beforehand)","Pencils","Markers (optional)"],"topic_tags":["Grammar","Infinitive Verbs","Game","Pair Work"]},
  {"id":"scraped-altcir-handbook-battleship-grammar-game-266","text":"This activity uses a Battleship game format to practice grammar points. The ALT prepares the game boards in advance, creating a grid and placing 'ships' (e.g., in a 2x1, 1x1, 3x1 format) on them. The sentences to be used on the game board are created by the ALT and JTE to target specific grammar points. The JTE first reviews the target grammar point in Japanese. Students then work in pairs, taking turns to call out grid coordinates (e.g., 'A2'). When a coordinate is called, the opponent reads the sentence at that location, e.g. \"I have a pen.\". If the sentence is correct, the first student marks a 'hit'. If the sentence is incorrect or the coordinate is empty, it's a 'miss'. The ALT and JTE circulate, providing support. The first student to sink all of the opponent's 'ships' wins. This activity targets speaking and listening skills, reinforces grammar, and provides a fun way to practice sentence construction. The ALT and JTE assist as needed, and participate if there's an odd number of students.","content_type":"activity","name":"Battleship Grammar Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Battleship game boards (prepared)","Pencils/pens"],"topic_tags":["grammar","games","speaking"]},
  {"id":"scraped-altcir-handbook-synonym-showdown-267","text":"Divide students into groups of 6-7. Each group receives a set of Synonym cards with words like 'intelligent' and 'clever'. The ALT says a word (e.g., 'Intelligent'), and students race to find the matching synonym on their cards. The first group to choose the correct card scores a point. Dictionaries are not allowed. To aid understanding, the ALT reads example sentences using the target word, like, 'Tom is intelligent. Although he did not study, he scored full marks for his English test.' The group that correctly identifies the synonym then provides the Japanese translation of the word, which the JTE verifies. This activity targets vocabulary expansion and the ability to apply new words in context. The activity focuses on spoken words and is designed to improve students' listening comprehension.","content_type":"activity","name":"Synonym Showdown","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Synonym Cards","Example Sentences"],"topic_tags":["Vocabulary","Words","Meaning"]},
  {"id":"scraped-altcir-handbook-synonym-match-268","text":"This activity is a great way to reinforce vocabulary and understanding of synonyms. Prepare a list of words and their synonyms. For each group of students, create a set of cards. On each card, write a synonym for one word from your list. Include some 'invalid' cards with unrelated words to make it more challenging. \n\nTo play, read a word aloud to the class, or show it written on the board. Students in their groups must find the corresponding synonym card from their set. The first group to correctly identify the card and hold it up wins a point. Repeat with different words from your list. For younger students or lower proficiency levels, you might write the original word on the board as a visual aid. For more advanced learners, they can also write their own synonym card and have others guess the original word. \n\nThis activity mainly targets vocabulary and listening, with some writing involved depending on how you choose to play. It's suitable for elementary school students and can be adapted to different levels by choosing easier or more difficult vocabulary words.","content_type":"activity","name":"Synonym Match","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Synonym List","Blank Cards"],"topic_tags":["Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-synonym-matching-269","text":"This activity focuses on vocabulary acquisition and comprehension through synonym matching. The JTE and ALT collaboratively create a list of target vocabulary and their synonyms, considering the students' English proficiency. The ALT prepares cards with the target words and sample sentences. In class, the class is divided into groups. The ALT reads the target words and example sentences aloud, while the JTE provides Japanese translations for clarification. This helps students understand the meaning and context of the new words. The activity promotes listening comprehension and vocabulary development.\n\nSuitable for Grades 5-7. \n\nMaterials needed: Synonym cards with target words, example sentences, and Japanese translations.\n\nClassroom tips: Ensure clear pronunciation and pacing by the ALT. Encourage active listening and note-taking. The JTE's translations are crucial to support understanding. Consider different group sizes for variation.","content_type":"activity","name":"Synonym Matching","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Synonym Cards","Sample Sentences"],"topic_tags":["Vocabulary","Listening Comprehension","Synonyms"]},
  {"id":"scraped-altcir-handbook-haiku-time-270","text":"This activity introduces students to haikus in English. Begin by distributing worksheets and explaining what a syllable is, relating it to the Japanese concept. Provide examples of different syllable counts, emphasizing each beat with clapping. Encourage students to share their own examples. Next, have students complete a worksheet activity to practice identifying syllables. Circulate and assist students, addressing common misunderstandings. After, facilitate sharing and offer a light competition, if appropriate. Introduce the haiku format, comparing Japanese and English styles and providing examples. Guide students in writing their own haikus, potentially offering a topic. Students diagram their haikus by marking syllables.","content_type":"activity","name":"Haiku Time","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["Worksheets","Examples of haikus (English and Japanese)"],"topic_tags":["poetry","writing","syllables"]},
  {"id":"scraped-altcir-handbook-haiku-creation-271","text":"This activity introduces students to haiku poetry in English. First, distribute the worksheet. The worksheet explains syllables in English, how to count them, and what a haiku is, including examples of haiku and the differences between Japanese and English versions. Next, review the worksheet as a whole class, clarifying any questions about syllables or haiku structure (5-7-5). Finally, students write their own haiku poems in the space provided on the worksheet, aiming for the 5-7-5 syllable structure. Encourage creative word choice and simple themes. Circulate around the classroom, providing assistance and feedback. This activity targets writing skills, specifically sentence structure and creative writing. It also reinforces vocabulary and pronunciation skills related to counting syllables. Focus on having fun with the structure rather than perfect English. For elementary students, the topic could be animals or things in nature. For Junior High students, this could include things about school, favorite sports, or dreams. Classroom tips: Provide a word bank for less experienced students to help with vocabulary. Model the activity by writing an example haiku on the board. Emphasize that the meaning of the poem is important and that there is no need to be perfect when writing the first time. For extra time, have students share their poems with a partner or the class.","content_type":"activity","name":"Haiku Creation","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["Worksheet (provided by teacher or school)"],"topic_tags":["Poetry","Writing","Syllables"]},
  {"id":"scraped-altcir-handbook-syllable-count-272","text":"This activity focuses on understanding English syllables. The ALT introduces and explains what syllables are, providing examples of words with varying syllable counts. The JTE supports by explaining the concept of 'syllables' in Japanese (音) and offering a familiar example like a haiku. The students learn to identify syllables in English words and relate them to the Japanese concept. This activity enhances pronunciation and builds awareness of the structure of English words. The ALT will say the words and the students count the syllables, clapping for each syllable heard. Use flashcards with pictures to support vocabulary acquisition and comprehension. \n\nMaterials needed: Whiteboard or projector, markers or pens, flashcards with pictures (optional).","content_type":"activity","name":"Syllable Count","activity_type":"Warm-up","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Whiteboard or projector","Markers or pens","Flashcards (optional)"],"topic_tags":["Phonics","Pronunciation","Vocabulary"]},
  {"id":"scraped-altcir-handbook-haiku-syllable-practice-273","text":"This activity introduces students to the concept of syllables, preparing them for writing haiku poems. Begin by explaining what a syllable is: a beat in a word. Provide examples of one, two, three, and four-syllable words, having students clap out the syllables to help them understand. Then, present a haiku framework: 3 lines, with 5, 7, and 5 syllables respectively. Explain that haiku are traditionally about nature. Show an example Japanese haiku alongside its English translation. Students then practice identifying and counting syllables in single words (e.g., dog, Japan, animal). Encourage students to not stress too much about where each syllable begins and ends, just that they count them correctly. This activity reinforces phonological awareness and sets the stage for poetry writing. Focus on the syllable counts in the words. They can write at least one word from one of the following syllable count groups: one, two, three, four. Bonus: five syllable words.","content_type":"activity","name":"Haiku Syllable Practice","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Individual","materials":[],"topic_tags":["poetry","syllables","writing","haiku"]},
  {"id":"scraped-altcir-handbook-guessing-game-274","text":"Divide the class into groups of 4-5 students. Number each group and create a scoreboard. The ALT will give 3 hints about a person or thing. Students listen carefully and try to guess by raising their hands (or taking turns). Correct answers earn points: 30 points for Hint 1, 20 points for Hint 2, 10 points for Hint 3, and 5 points for Hint 4. Focus on 10 questions about topics like food or sports, or review past content. Increase point values near the end for excitement. The group with the most points wins.","content_type":"activity","name":"Guessing Game","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Scoreboard","Hints (prepared beforehand)"],"topic_tags":["listening","speaking","games","review"]},
  {"id":"scraped-altcir-handbook-team-challenge-275","text":"Divide students into groups with the JTE and ALT. The JTE creates a scoreboard, and the ALT explains the game using an example question. The ALT gives hints while both teachers monitor for raised hands to determine which group answers first. The JTE tracks scores and updates the scoreboard. For the final three questions, the JTE decides how many points to award based on the scores. This activity targets listening comprehension and speaking. The ALT gives hints while the students work as a team to answer the questions. \n\nMaterials needed: Whiteboard/Blackboard, markers/chalk, prepared questions.\n\nClassroom tips: Make sure the questions are appropriate for the students' level. Adjust the number of points for the final questions to create a close finish and maximize engagement.","content_type":"activity","name":"Team Challenge","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Whiteboard/Blackboard","Markers/Chalk","Prepared questions"],"topic_tags":["Teamwork","Quiz","Speaking"]},
  {"id":"scraped-altcir-handbook-pets-are-people-too-276","text":"This activity reviews vocabulary related to pets and encourages speaking and listening skills. The teacher prepares a set of questions, each with several clues. Students form groups. One student from each group stands for each round, and their group guesses. The teacher provides hints, starting with less obvious clues and gradually becoming more explicit. The teacher can use the blackboard to draw or write clues if students struggle with vocabulary. Extra questions can be prepared for tiebreakers. Prizes like stickers or candy can be used to incentivize participation. An example question should be simple enough for students to understand. The hints should be neither too easy nor too difficult.\n\nLanguage Skills Targeted: Speaking, Listening, Vocabulary\n\nSuitable Grade Levels: Elementary/Junior High (adapt hints accordingly).\n\nMaterials Needed: Prepared questions, blackboard or whiteboard, markers or chalk, prizes (stickers, candy).\n\nClassroom Tips: Manage rowdy classes by having one student per group guess. Constantly monitor student understanding and provide visual clues if needed. Ensure the example question is easy to understand. Prepare extra questions as tiebreakers.","content_type":"activity","name":"Pets Are People Too!","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Prepared questions","Blackboard/Whiteboard & Markers","Prizes"],"topic_tags":["pets","vocabulary","review"]},
  {"id":"scraped-altcir-handbook-interview-and-discussion-277","text":"This activity is designed to review previously learned material, practice interviewing skills, and facilitate opinion sharing and discussion. \n\n**Procedure:**\n\n1.  **Review (Exercise 1):** Play a short audio passage or present a short reading passage. Students listen/read and then answer True/False questions related to the content.\n2.  **Interview (Exercise 2):** Students individually write their own answers to a set of questions (related to the topic). Then, students pair up and interview their partner, taking notes on their partner's responses. Call out \"kaiten-zushi\" (rotating sushi) to signal a partner change. Students repeat the interviewing process with new partners.\n3.  **Discussion (Exercise 3):** Students individually write their answers to a new set of questions related to the topic. Next, students pair up and share their opinions with their partner, discussing their answers. \n\nThis activity targets listening, reading, writing, and speaking skills. It is best suited for students in grades 5-7. \n\n**Materials:** Audio recording or short reading passage, worksheets with questions, pens or pencils.\n\n**Classroom Tips:** Pre-teach key vocabulary relevant to the topic. Ensure the questions are clear and age-appropriate. Monitor student pairs during the interview and discussion phases to provide assistance as needed. Encourage active listening and respectful communication.","content_type":"activity","name":"Interview and Discussion","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Audio recording or short reading passage","Worksheets with questions","Pens or pencils"],"topic_tags":["Interviewing","Discussion","Review"]},
  {"id":"scraped-altcir-handbook-kaiten-zushi-seat-change-278","text":"This activity focuses on quick seat changes triggered by a key phrase, encouraging listening and reaction skills. The ALT explains the activity and calls on students to answer questions. The JTE can assist with classroom management. To initiate seat changes, the ALT shouts \"kaiten-zushi!\" (rotating sushi). Students must immediately move to a new seat. The focus is not on the content, but on listening carefully for the cue. This activity is effective as a short review or filler, promoting active participation and breaking up the lesson rhythm. Encourage the ALT and JTE to circulate during the activity to assist students and monitor the room.","content_type":"activity","name":"Kaiten-Zushi Seat Change","activity_type":"Filler","skill":"Listening","duration_minutes":5,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Classroom Management","Listening Skills","Movement"]},
  {"id":"scraped-altcir-handbook-natural-disasters-279","text":"This activity aims to teach students about different natural disasters and the Tohoku earthquake and tsunami. It uses a variety of methods to engage students and improve their language skills.\n\n1.  **Picture Introduction (Whole Class):** Use a PowerPoint with pictures of ten different natural disasters (typhoon, hurricane, tornado, volcanic eruption, earthquake, tsunami, avalanche, flood, wildfire, and heat wave). Show each picture and ask students for the Japanese word. Then, have them repeat the English word after you.\n2.  **Word Review (Whole Class):** Give students three minutes to review the vocabulary. Show new pictures of the natural disasters and have students quickly raise their hands when they know the word. This is a quick word recognition game.\n3.  **Dialogue Practice (Pairs):** Read a sample dialogue with the target language, \"Which natural disaster are you most scared of and why?\" The JTE can explain any new vocabulary. Students then practice the dialogue in pairs. Invite volunteers to perform the dialogue for the class.\n4.  **Listening (Whole Class):** Play pre-recorded videos of ALTs answering the question, \"Which are you most scared of, earthquakes, tsunamis or radiation?\" Before the listening activity, briefly explain radiation and the Fukushima Daiichi Plant incident using simple English. Play the videos twice. Ask students: \"Which disaster is the ALT most scared of?\" and \"Why?\" Encourage students to listen carefully to the different accents and answers.\n5.  **Writing & Sharing (Individual & Whole Class):** Have students write a short response to the question: \"Which are you most scared of, earthquakes, tsunamis or radiation? And, why?\" Model the activity by asking the JTE and the ALT to answer the question first. Allow time for writing, and then have students share their responses with the class. This helps them express their feelings about the tragedy.\n\nThis activity targets speaking, listening, reading, and writing skills and is suitable for grades 5-7. Materials needed include a PowerPoint presentation with pictures of natural disasters and pre-recorded videos.","content_type":"activity","name":"Natural Disasters","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["PowerPoint presentation","Pictures of natural disasters","Pre-recorded videos"],"topic_tags":["Natural Disasters","Tohoku Earthquake","Speaking","Listening","Writing"]},
  {"id":"scraped-altcir-handbook-paper-debate-280","text":"This activity involves students debating a topic using prepared arguments on paper. The lesson can be divided into two parts based on the students' English proficiency. Students earn 'money' for volunteering and the student with the most money at the end of the semester gets extra points on their oral exam. To prepare, create visually appealing handouts to capture the students' attention. This activity focuses on preparing arguments, presenting them, and debating using the English language.","content_type":"activity","name":"Paper Debate","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":9,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["handouts","fake money"],"topic_tags":["debate","speaking","high school"]},
  {"id":"scraped-altcir-handbook-building-blocks-of-debate-281","text":"This activity introduces students to the basic structure of a debate. Students work in groups of three. The first group brainstorms a debate topic and provides two reasons to support their viewpoint. The second group receives the topic and reasons from the first group, then brainstorms two reasons to oppose the same topic. The third group reviews both sets of reasons and explains which side presents the most well-reasoned arguments. This activity helps students understand the different roles in a debate. This focuses on building basic argumentation skills, not winning a debate. Suitable for Grade 5-7. Materials needed: paper, pens/pencils. Classroom Tip: Circulate to assist groups, especially with formulating reasons. Make sure students understand the concept of viewpoint.  Vary the debate topics to keep things interesting.  Encourage clear and concise language.","content_type":"activity","name":"Building Blocks of Debate","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["paper","pens/pencils"],"topic_tags":["debate","speaking","argumentation"]},
  {"id":"scraped-altcir-handbook-debate-worksheet-282","text":"This activity utilizes a worksheet to facilitate a debate exercise. The activity is divided into three units of students, each with a specific role: supporter, opposer, and evaluator. The first unit selects a debate topic and provides two supporting reasons on the top third of the worksheet. They then pass the worksheet to the second unit, who write a contradictory viewpoint and two supporting reasons on the middle third. Finally, the third unit reviews the provided information, determines the best constructed reasons and provides their judgment and reasoning on the bottom third. The third unit passes the worksheet back to the first unit. All units then evaluate their work and the work of their partners. This activity targets the language skill of formulating reasons and counterarguments, understanding viewpoints, and evaluating arguments. This activity provides practice in constructing arguments, understanding opposing viewpoints, and judging the strength of arguments. The teacher needs to prepare a worksheet for each group. The activity reinforces critical thinking skills. It is suited for groups of students. Classroom tip: pre-teach key vocabulary related to debate and arguments.","content_type":"activity","name":"Debate Worksheet","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":6,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Worksheets"],"topic_tags":["Debate","Argumentation","Critical Thinking"]},
  {"id":"scraped-altcir-handbook-debate-intro-283","text":"This activity introduces students to the basic structure of a debate. First, divide students into pairs. Assign one student the role of 'Pro' and the other 'Con'. Present a simple debate topic like 'Do you like pizza?' Then, students brainstorm reasons to support their assigned side. Encourage them to create at least two reasons. Next, each pair briefly presents their reasons to the class, taking turns. The teacher monitors for correct pronunciation and provides feedback. The activity targets speaking skills and helps students formulate simple arguments. Suitable for grades 5-7, it requires no specific materials beyond the teacher's instructions and a whiteboard or projector to display the debate topic. Classroom tips: Pair stronger students with those who need more help, and be forgiving of grammatical errors. Review the structure of the debate and examples at the end.","content_type":"activity","name":"Debate Intro","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":[],"topic_tags":["debate","speaking","argumentation"]},
  {"id":"scraped-altcir-handbook-hello-song-introductions-284","text":"This activity introduces students to basic greetings and self-introductions. Start with the 'Hello' song, using simple gestures to accompany each line. Next, teach the phrases 'My name is...' and 'Nice to meet you'. Students then practice in pairs, taking turns introducing themselves. After a few minutes, have students introduce their partner to the class. This reinforces listening and speaking skills. Consider using flashcards with pictures of common greetings and actions to help with understanding. Classroom tip: keep the language simple and repeat phrases multiple times.","content_type":"activity","name":"Hello Song & Introductions","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Greetings","Introductions","Basic English"]},
  {"id":"scraped-altcir-handbook-greeting-bingo-285","text":"This activity helps students practice greeting words and build confidence in speaking English.  It is divided into two main parts. First, introduce and practice greeting vocabulary such as \"Hello, my name is...\" using a PowerPoint presentation. Ensure accurate pronunciation. Next, each student receives nine paper squares and writes their name on each one. Then, model the target dialogue on the board, such as \"Hello, my name is [student's name]\" and \"Nice to meet you. How are you?\". Students then practice the dialogue, exchanging name cards to meet nine other students.  After the dialogue practice, the students arrange their name cards in a 3x3 grid for a Bingo game. The teacher models a new dialogue, filling in blanks with names and greetings. Students flip over the corresponding name card if they hear it and try to get bingo by flipping over the name cards on their desk. This activity targets speaking and listening skills, reinforcing both vocabulary and social interaction.","content_type":"activity","name":"Greeting Bingo","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper squares","Markers/pens","PowerPoint Presentation (optional)"],"topic_tags":["Greetings","Names","Bingo"]},
  {"id":"scraped-altcir-handbook-song-sequencing-286","text":"This activity uses a song to practice listening comprehension and sequencing. First, play the song for the class. Next, distribute worksheets with the song lyrics that have been jumbled up, or incomplete. Students listen to the song again while they read along, trying to fill in the missing words or rearrange the lyrics in the correct order. For younger students, the teacher can pre-cut the lyrics into strips, and students arrange the strips in order. For a follow-up, students can write their own verses for the song or act out the song. This targets listening and reading skills and reinforces vocabulary and sentence structure. Materials needed: Song and accompanying worksheet; CD player; computer with projector; paper squares the size of business cards (9 per student). Classroom tip: Choose a song with simple, repetitive lyrics for younger learners, or a more complex song for older students.","content_type":"activity","name":"Song & Sequencing","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Song and accompanying worksheet","CD player","computer with projector","paper squares the size of business cards (9 per student)"],"topic_tags":[]},
  {"id":"scraped-altcir-handbook-greeting-vocabulary-bingo-287","text":"This activity focuses on practicing greeting vocabulary in a fun, engaging way. \n\n**How to Play:**\n1.  **Preparation:** Create a PowerPoint presentation or flashcards featuring common greetings like \"Hello,\" \"Good morning,\" \"Goodbye,\" \"How are you?\" and their respective Japanese translations. Prepare bingo cards for each student with a grid (e.g., 3x3 or 4x4) filled with the greeting vocabulary words. \n2.  **Introduction (Warm-up - 5 minutes):** Review the target vocabulary. Show the PowerPoint slides or flashcards. Pronounce each greeting clearly and have students repeat after you as a whole class or in pairs. \n3.  **Game (Main Game - 10 minutes):** Call out the English greetings one by one. Students listen and find the matching word on their bingo card. If they have the word, they mark it (e.g., flip it over if using flashcards, or mark with a pencil). The first student to get three in a row (or all cards, depending on the game time) shouts \"Bingo!\" and wins. Check their card to ensure the called-out words match those marked. \n4. **Classroom Tips:** Use a timer to keep the pace of the game. Encourage students to help each other and have them say the greeting loudly for reinforcement.\n\n**Language Skills:** Listening, Speaking\n**Suitable Grade Levels:** 5-7","content_type":"activity","name":"Greeting Vocabulary Bingo","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["PowerPoint slides/Flashcards","Bingo cards","Markers/Pencils"],"topic_tags":["Greetings","Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-guess-the-price-288","text":"This activity focuses on speaking and listening while practicing numbers and asking questions. Prepare a worksheet with six pictures of different items (e.g., car, iPod, cell phone). Divide students into small groups. Each group views each picture and discusses what they think the price of the item is. Encourage them to use phrases like \"How much is it?\" and \"I think it's...\" They should write their guesses on the worksheet next to each picture. After a set time for each item, have groups share their guesses and explain their reasoning. The teacher can then reveal the actual prices (which they'll need to research beforehand). Award points for the closest guesses. This promotes teamwork, vocabulary recall, and number comprehension. Adjust the difficulty by selecting items familiar to the students.","content_type":"activity","name":"Guess the Price","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Worksheet with pictures","Pencils","Answer Key (Prices)"],"topic_tags":["Numbers","Shopping","Vocabulary"]},
  {"id":"scraped-altcir-handbook-price-guessing-game-289","text":"This activity focuses on listening and speaking practice related to numbers and money. Students are divided into teams. The teacher (either the ALT or JTE) holds up an item (e.g., a pencil, a toy, a snack) and announces its price in English. Teams discuss the price and write down their guess. The teacher reveals the actual price. The team closest to the correct price wins a point. Repeat with different items. The game reinforces listening comprehension, vocabulary related to prices, and provides opportunities for collaborative discussion. The ALT and JTE should share responsibilities, with one announcing prices and the other keeping score. Adapt the difficulty by using simple prices (e.g., whole yen amounts) or more complex ones (e.g., including sen). Suitable for 5th to 7th grade, but can be adapted. Materials needed include various inexpensive items with visible price tags (or that can be priced by the teacher), and a whiteboard/paper for scorekeeping.","content_type":"activity","name":"Price Guessing Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["various inexpensive items","whiteboard/paper"],"topic_tags":["numbers","money","listening comprehension"]},
  {"id":"scraped-altcir-handbook-food-ordering-prices-290","text":"This activity focuses on reading comprehension and price recognition. Students are presented with menus or price lists from various food establishments. The teacher can provide a worksheet with different scenarios, such as 'You have ¥500, what can you buy?' or 'Order a meal within your budget'. Students read the menu, calculate prices, and select items. This helps students practice reading numbers, understanding prices, and making choices based on constraints. The activity can be adapted for lower levels by simplifying the menus and offering fewer choices. For higher levels, more complex menus and scenarios can be introduced, including tax calculations. Encourage students to work independently to promote reading comprehension. \n\nLanguage skills targeted include reading comprehension, vocabulary related to food and prices, and basic math skills. Suitable for grades 5-7. Materials needed: Menu printouts or price lists, worksheets with scenarios, pencils. Classroom tips: Circulate to assist and clarify vocabulary. Encourage students to help each other and check their answers. Adapt the difficulty to suit the students' levels.","content_type":"activity","name":"Food Ordering Prices","activity_type":"Main Game","skill":"Reading","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["Menu printouts or price lists","Worksheets with scenarios","Pencils"],"topic_tags":["Food","Prices","Reading"]},
  {"id":"scraped-altcir-handbook-ordering-food-role-play-291","text":"This activity aims to teach students how to order food in English. Start with a quick warm-up: divide students into groups and have them brainstorm as many food words as possible in one minute.  Write the words on the board.  Next, distribute menus and script sheets to each student. Explain any unfamiliar menu items. Demonstrate a role play with the JTE: the JTE plays the waiter, the ALT the customer. The waiter 'takes' the customer's order, noting down items and prices. At the end, the waiter repeats the order and totals the cost.  Students then practice the role play in pairs, using the menus and scripts. Encourage them to practice without notes after a few rounds. This activity targets speaking and listening skills, allowing students to practice useful phrases in a realistic context. \n\nClassroom tips: Ensure clear pronunciation of food names. Pre-teach key phrases like 'I'd like...' and 'How much is...?'. Encourage students to be creative with their orders!","content_type":"activity","name":"Ordering Food Role Play","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Menus","Script sheets","Whiteboard","Markers"],"topic_tags":["Food","Role Play","Speaking"]},
  {"id":"scraped-altcir-handbook-food-ordering-practice-292","text":"This activity focuses on practicing food vocabulary and ordering food. Begin with a warm-up. Divide students into groups and give each group a numbered worksheet. Students write down as many food items as they can in English (e.g., pizza, rice). After 5 minutes, review the answers as a class, writing them on the board. Next, pair the students. Provide each student with a practice script of a customer ordering food and a menu. Students take turns being the customer and the server, practicing the dialogue and ordering food items from the menu. This activity targets speaking and listening skills, reinforcing food vocabulary. Adapt the menu items and complexity to suit the grade level. Classroom tip: encourage students to use polite language.","content_type":"activity","name":"Food Ordering Practice","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet","Practice script","Menu","Whiteboard or Blackboard"],"topic_tags":["Food","Speaking Practice"]},
  {"id":"scraped-altcir-handbook-mcdonalds-menu-role-play-293","text":"This activity involves students practicing ordering food at a restaurant using a menu from a familiar setting (e.g., McDonald's).  The JET and JTE should work together to model the conversation, using questions like, \"Have you tried (food name) before?\" and \"Do you like (food name)?\"  If the class is lower level, start by having students repeat the conversation after the teachers. The activity uses a menu, such as the provided New Zealand McDonald's menu, and a conversation worksheet. Students work in pairs, one taking the role of the waiter and the other the customer, practicing ordering different meals and calculating the prices.  The goal is to practice basic conversational phrases related to ordering food. The activity culminates with pairs taking an order and calculating the price. The students complete a worksheet by selecting the items, writing down prices, and practice conversational English.","content_type":"activity","name":"McDonalds Menu Role Play","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["McDonalds menu (or similar)","Conversation worksheet"],"topic_tags":["Food","Role Play","Conversation"]},
  {"id":"scraped-altcir-handbook-circumlocution-challenge-294","text":"This activity focuses on teaching students how to describe words they don't know or have forgotten using circumlocution. The lesson begins with a demonstration by the JET and JTE, where the JET describes words, and the JTE guesses them. Students then listen and write down what they think the JET is describing. Next, students practice writing their own circumlocutions for three given English words. Finally, in pairs, students take turns describing a list of words to their partner without saying the word itself. The partner guesses the word. This involves two rounds, with two word lists per student (four per pair). The best examples can be demonstrated to the class at the end to reinforce learning.\n\nThis activity targets speaking and listening skills, as students must both describe and understand descriptions. It encourages creative use of language and helps students overcome the barrier of not knowing a specific word. Focus on encouraging a variety of descriptive language and body language as aids. Ensure students understand that guessing is ok, and not knowing the answer is part of the learning process. The provided word lists should be appropriate for the target grade level's vocabulary.","content_type":"activity","name":"Circumlocution Challenge","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Word lists (prepared in advance)","Whiteboard or projector (optional for demonstration)"],"topic_tags":["Vocabulary","Speaking","Describing","Communication"]},
  {"id":"scraped-altcir-handbook-word-lists-295","text":"This activity focuses on vocabulary and speaking. Students work in pairs to describe words without saying them. Prepare word lists on small paper strips. Lists A and B contain 6 common words each. Lists C and D have 9 intermediate words. Divide the class into A and B columns. Pairs are formed between A and B columns. In Round 1, A columns receive Word List A, and B columns receive Word List B. Students take turns choosing a word, and describing it to their partner, who tries to guess the word. In Round 2, A columns receive Word List C, and B columns receive Word List D. This round increases the vocabulary challenge. Focus on using different descriptive words and phrases.","content_type":"activity","name":"Word Lists","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper strips with word lists (A, B, C, D)","Pens/Pencils"],"topic_tags":["Vocabulary","Describing","Pair work"]},
  {"id":"scraped-altcir-handbook-circumlocution-practice-296","text":"This activity focuses on improving students' speaking skills through circumlocution (describing a word without saying it). The JET prepares word lists and a worksheet with prompts. The JET and JTE introduce the activity, modeling examples of how to describe words using descriptions, lists, examples, and opposites. The JTE clarifies the lesson's goal with the students. Students then work in pairs, practicing circumlocution. The JET and JTE circulate, ensuring students use English and offering assistance. The teachers listen for strong examples to share at the end, providing peer learning. This activity targets speaking and vocabulary expansion. Suitable for junior high school students. Materials needed: worksheet, word lists. Classroom tips: Encourage students to use various description methods. Actively monitor pairs, correcting Japanese or gesture use, and praise strong examples. This is intended for SHS but can be modified for JH.","content_type":"activity","name":"Circumlocution Practice","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet","Word Lists"],"topic_tags":["Speaking","Vocabulary","Pair Work"]},
  {"id":"scraped-altcir-handbook-circumlocution-297","text":"This activity focuses on building speaking skills through circumlocution. Students are given a word and must describe it without using the word itself or related words. This targets vocabulary and descriptive language skills. Before starting, provide examples of how to describe verbs using body parts, location, time, and manner. Encourage the use of full, simple sentences. Students work in pairs to create descriptions. To add challenge, the JTE can provide difficult Japanese words for the students to explain to the ALT. The JTE can then confirm the ALT's understanding. Award participation points to the fastest pairs. Minimize dictionary use; the focus is on utilizing existing English knowledge.","content_type":"activity","name":"Circumlocution","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":3,"interaction":"Pairs","materials":[],"topic_tags":["vocabulary","speaking","description","pair work"]},
  {"id":"scraped-altcir-handbook-wh-question-bingo-298","text":"This activity reviews and reinforces Wh- question usage through a dynamic interview game.  Prior to the game, the ALT leads students in repeating different Wh- question formats, and the ALT and JTE demonstrate the target dialogue. The activity starts with a brief review of vocabulary related to the questions. Students then pair up and engage in short interviews, practicing the target language. Each pair plays Rock, Paper, Scissors; the winner selects a question from their Bingo sheet and asks their partner. Both students write down the answer and the speaker's name. After a set time (e.g., 5 minutes), the class reconvenes. The ALT/JTE calls out student names at random.  Students who have the named student's answer on their sheet circle it.  Prizes are awarded to the first students to get Bingo. This focuses on practicing asking and answering Wh- questions. The students use eye contact and clear voices. The activity is designed to maximize student speaking time in an engaging way.","content_type":"activity","name":"Wh- Question Bingo","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Bingo sheets with Wh- questions","Prizes or Stacey Dollars"],"topic_tags":["questions","interview","speaking practice","game"]},
  {"id":"scraped-altcir-handbook-sleeping-partners-299","text":"This activity is designed to review vocabulary and encourage descriptive language. Divide students into pairs. One student in each pair closes their eyes or rests their head on the desk, pretending to be asleep. The ALT writes a vocabulary word on the board (e.g., a word from the current unit). Only the 'awake' students can see the word. After a moment, the ALT erases the word. Both partners 'wake up'. The students who saw the word must describe it to their partner in English. They cannot use actions, spelling, or Japanese. Encourage the use of synonyms and descriptive phrases. The partners then switch roles, with the other student going to sleep and a new word being written on the board. Repeat this process as many times as desired. This activity targets speaking and listening skills.","content_type":"activity","name":"Sleeping Partners","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Whiteboard","Markers"],"topic_tags":["Vocabulary","Descriptive language","Pair work"]},
  {"id":"scraped-altcir-handbook-vocabulary-chain-300","text":"This quick activity reinforces recently learned vocabulary. Start by saying a word, for example, \"apple.\" The first student must say a word that begins with the last letter of your word, so \"elephant.\" The next student continues by saying a word that starts with the last letter of the previous word: \"tiger.\" Continue the chain until a student hesitates or gives an incorrect word. If a student is stuck, gently prompt them. It's fine to allow students to pass if they cannot think of a word. This activity is effective for reviewing vocabulary and practicing pronunciation in a fun, fast-paced way. It targets speaking skills and helps improve fluency. Suitable for grades 5-7. No materials are needed; the teacher and students will simply use the target language. Classroom Tip: Prepare a list of acceptable words in case of disputes, especially for younger learners. You can also vary the activity by using categories (e.g., foods, animals) to further focus the vocabulary.","content_type":"activity","name":"Vocabulary Chain","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Vocabulary","Speaking","Review"]},
  {"id":"scraped-altcir-handbook-conjunction-builders-301","text":"This activity focuses on conjunctions. Pairs of students receive a set of sentence fragments (e.g., \"I like pizza.\", \"It is cheap.\"). Their task is to combine the fragments using conjunctions like \"and,\" \"but,\" or \"so\" to create grammatically correct sentences. The teacher can provide a list of target conjunctions or let students choose. For a warmer activity, the teacher calls out two sentence fragments and students work together to say the full sentence. Students can then write the new sentences in their notebooks. For a competitive game, set a time limit and award points for correct sentences, with bonus points for using more complex conjunctions or for speed. The game can be adjusted for a variety of difficulty levels. Suitable for Junior High School. Materials needed: Sentence fragments (written on cards or the board).","content_type":"activity","name":"Conjunction Builders","activity_type":"Warm-up","skill":"Writing","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Sentence fragments"],"topic_tags":["Grammar","Conjunctions","Sentence building"]},
  {"id":"scraped-altcir-handbook-conjunction-completion-302","text":"This activity aims to improve students' understanding and use of conjunctions in sentences. Start by writing a simple sentence on the board, like \"I can fly.\" Provide a vocabulary box with conjunctions (e.g., and, but, so, because). Model how to use the conjunctions to extend the sentence, focusing on correct grammar and meaning. Next, write several new opening sentences on the board. Students work individually, selecting a conjunction and completing each sentence. Once students are comfortable, have them work in pairs. Each student writes an opening sentence and then trades with their partner. Partners complete each other's sentences, using the target conjunctions they've learned throughout the lesson. This helps build both production and receptive skills related to grammar.","content_type":"activity","name":"Conjunction Completion","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard/Blackboard","Markers/Chalk","Vocabulary list of conjunctions"],"topic_tags":["Grammar","Conjunctions","Sentence Building"]},
  {"id":"scraped-altcir-handbook-conjunction-match-write-303","text":"This activity focuses on teaching and practicing the use of conjunctions to connect sentences. First, introduce and model conjunctions on the whiteboard, perhaps using different colored markers for emphasis. Provide a worksheet with a vocabulary box of conjunctions (e.g., and, but, so, because). Next, students complete structured activities on the worksheet, such as matching sentence halves with appropriate conjunctions. After this, transition to pair work. Students receive a separate worksheet or lined paper and create their own sentences using the learned conjunctions, sharing and editing their work together. This reinforces understanding of sentence structure and improves both writing and speaking. \n\nLanguage skills targeted: Reading, Writing, Speaking. \n\nSuitable Grade Levels: 5-7. \n\nClassroom Tips: Use varied examples. Circulate to provide support and feedback during pair work. Encourage students to read their sentences aloud to each other. Emphasize the meaning of the conjunctions.","content_type":"activity","name":"Conjunction Match & Write","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Whiteboard","Whiteboard Markers","Worksheet with conjunction vocabulary box","Separate worksheet/Lined paper"],"topic_tags":["Grammar","Writing","Conjunctions"]},
  {"id":"scraped-altcir-handbook-conjunction-chain-304","text":"This activity focuses on understanding and using conjunctions to build sentences. Start with simple sentences using vocabulary students already know. For example: \"My hair is on fire.\" or \"I am an elephant.\" Students then add a conjunction and another sentence, building a chain. If students struggle, allow them to work in pairs. The activity can be adapted for groups, where groups exchange sets of sentences and add to them, with a competition based on speed or creativity. This can be used as a warm-up activity to practice sentence building.\n\nLanguage skills targeted: Writing and speaking. \nSuitable grade levels: Grade 5-7. \nMaterials needed: Paper/whiteboard for writing. \nClassroom tips: Start with easy sentences and familiar vocabulary. Encourage creativity.","content_type":"activity","name":"Conjunction Chain","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper","Whiteboard"],"topic_tags":["Grammar","Sentence Building","Conjunctions"]},
  {"id":"scraped-altcir-handbook-weekly-plans-janken-305","text":"This activity helps students practice asking and answering about weekly plans using \"What are you doing on...?\" and \"I'm going to...\".\n\n**Procedure:**\n1.  **Worksheet Preparation:** Provide each student with a worksheet containing a blank weekly plan grid (one column per day). Students write an activity for each day of the week under the corresponding day. (e.g., Monday: go to the park, Tuesday: play video games).\n2.  **Key Expressions:** Write the key questions and answers on the board: \"Are you doing anything this (day)?\" and \"I'm going to (~).\". The ALT models the expressions and students repeat them.\n3.  **Janken and Information Gathering:** Students stand up and play janken to determine who is Student A (asking) and Student B (answering). Student A asks Student B about their plan for a given day using the target language. Student B answers. Student A writes Student B's name and plan under the corresponding day on their worksheet.\n4.  **Targeted Interactions:** Students are instructed to collect the weekly plans of three girls, three boys, and the ALT. This encourages them to interact with a variety of classmates.\n\n**Language Skills:** Speaking and Listening\n**Suitable Grade Levels:** 5-7 (can be adapted)\n**Materials:** Worksheets with weekly plan grid, pen or pencils\n**Classroom Tips:** Circulate and monitor student conversations. Provide support with vocabulary if needed. Encourage students to vary their responses beyond the examples.","content_type":"activity","name":"Weekly Plans Janken","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheets","Pens/Pencils"],"topic_tags":["Plans","Daily Activities","Janken"]},
  {"id":"scraped-altcir-handbook-weekly-plan-practice-306","text":"This activity helps students practice talking about their weekly plans. First, the teacher writes key phrases on the blackboard, such as \"On Monday, I...\", \"Then, I...\", \"After that, I...\". Students receive a weekly plan grid. Students then walk around the classroom and ask their classmates about their plans using the key phrases. Students fill in the grid based on their classmates’ responses. This focuses on speaking and listening comprehension while reinforcing days of the week and schedule vocabulary. It is suitable for 5th to 7th grade, and the teacher should review days of the week beforehand. No special materials beyond the provided grid and blackboard are required. Make sure to circulate the class to provide support and correct pronunciation, and encourage students to ask follow-up questions to elicit more information.","content_type":"activity","name":"Weekly Plan Practice","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Weekly plan grid (printed or drawn)","Blackboard"],"topic_tags":["Daily Routine","Speaking Practice","Days of the Week"]},
  {"id":"scraped-altcir-handbook-weekly-plan-interviews-307","text":"This activity focuses on practicing asking about and recording classmates' weekly plans. First, the ALT introduces the activity and explains the goal: to complete a weekly plan worksheet based on information gathered from classmates.  The ALT gives examples of how to fill the plan. Students use their textbooks as a resource and can ask the teachers for help. Next, the JTE writes the key expressions (e.g., 'What do you do on...?') on the board and explains their meaning in Japanese. The ALT leads students in repeating the expressions and writing them on their worksheet. Finally, the ALT explains that students interview their classmates, asking about their weekly plans and recording the information on their worksheets. The ALT and JTE can model a short interview, possibly using rock-paper-scissors (janken) to determine roles (interviewer/interviewee). This helps students understand the interactive nature of the task.","content_type":"activity","name":"Weekly Plan Interviews","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheets with weekly plan templates","Textbooks","Blackboard or whiteboard"],"topic_tags":["Daily routine","Classroom interaction","Questioning"]},
  {"id":"scraped-altcir-handbook-shopping-role-play-308","text":"This activity allows students to practice shopping dialogue in two different settings: a clothing store and a restaurant. First, divide students into pairs. One student is the customer and the other is the shopkeeper/server. Provide each pair with a scenario card for either the clothing store or the restaurant. The clothing store card might include a specific item the customer wants to buy and a price range. The restaurant card could detail a specific food order and any dietary restrictions. Students then role-play their scenario, using target language like \"How much is this?\" or \"I'd like...\" and \"Can I see...?\" Circulate the classroom, listening in and offering help with vocabulary or grammar. Afterwards, swap roles and scenarios. This activity focuses on speaking skills, specifically functional language used in a shopping context. This activity is appropriate for elementary and early junior high students. Materials needed include scenario cards. Consider pre-teaching key vocabulary or phrases relevant to each scenario, and model the role-play before the activity begins. Adjust the complexity of the scenarios depending on the student's level, adding more descriptive language or more complicated requests. It is a good activity to do after teaching \"Can I have...\", \"How much is it?\", \"I'd like to...\", or \"This/That is...\"","content_type":"activity","name":"Shopping Role-Play","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Scenario cards"],"topic_tags":["Shopping","Role-play","Speaking"]},
  {"id":"scraped-altcir-handbook-size-shopping-309","text":"This activity focuses on describing size and practicing shopping dialogue. Begin by showing pictures of foods and asking students to identify them and where they are found. Introduce key vocabulary related to fast food (fast food, fatty, sugary, unhealthy, desert, sweet tooth, soul food) with the JTE's help. Display pictures and actual cups in small, medium, and large sizes. Students will practice identifying and stating the sizes of cups and food items ('I have a large cup'). Provide a role-play script (prepared by the JTE) simulating a fast-food exchange. Model the role-play with the JTE, then have students practice in pairs. Extend the size vocabulary to clothing, asking students about their sizes (small, medium, large). Use the dialogue from their textbook to practice shopping in clothing stores. Finally, play 'Pass the Ball' to select students to role-play shopping scenarios without scripts. This activity targets speaking and listening skills, vocabulary related to sizes, and practicing functional language for shopping.","content_type":"activity","name":"Size Shopping","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Pictures of food","Pictures/cups (small, medium, large)","Role-play scripts","Textbooks (Birdland Communication Book)"],"topic_tags":["Shopping","Food","Sizes","Role-play"]},
  {"id":"scraped-altcir-handbook-fast-food-apparel-role-play-310","text":"This activity focuses on practicing the \"May I help you?\" dialogue in a realistic context. First, show pictures of fast food and apparel, and review relevant vocabulary (sizes, food items). Next, divide the class into pairs. One student is the customer and the other is the shop assistant. The customer orders a food item or clothing, specifying the size. Students use the dialogue from the textbook and the vocabulary learned. Use real-life props (cups, clothes) to add authenticity. Circulate and monitor, providing support. For added challenge, include a short dialogue script for students to follow. This encourages fluency and natural language use. Language skills targeted: Speaking and Listening. Suitable for grades 5-7. Materials: pictures of fast food and apparel, real fast food cups and clothing, ball, PowerPoint, textbook dialogue, example dialogue script. Classroom Tip: Encourage students to act out the scene with enthusiasm.","content_type":"activity","name":"Fast Food & Apparel Role Play","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["pictures of fast food","pictures of apparel","real fast food cups","real clothing","ball","PowerPoint","textbook","example dialogue script"],"topic_tags":["role play","food","clothing","dialogue"]},
  {"id":"scraped-altcir-handbook-yes-no-follow-up-311","text":"This activity helps students practice asking and answering follow-up questions to extend conversations. First, students move around the classroom, asking their classmates a set of yes/no questions (e.g., \"Do you like soccer?\"). If a classmate answers \"yes,\" the student writes the classmate's name on their worksheet or a piece of paper and then asks a follow-up question related to the initial question (e.g., \"What do you like about soccer?\"). This encourages students to keep the conversation going and practice open-ended questions. This activity targets speaking and listening skills. Suitable for grades 5-7. No specific materials needed other than paper/worksheet and a pen/pencil for each student. To keep students engaged, provide a list of yes/no questions on the board or on a worksheet and circulate to monitor and help with follow-up questions.","content_type":"activity","name":"Yes/No Follow-up","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper/Worksheet","Pens/Pencils"],"topic_tags":["Conversation","Questions","Speaking"]},
  {"id":"scraped-altcir-handbook-find-someone-312","text":"This speaking activity gets students moving and interacting with each other. Students receive a worksheet with prompts like \"Find someone who likes pizza.\" Students mingle and ask each other the questions, writing down the names of classmates who answer affirmatively. After the time limit (10 minutes) the teacher calls out questions, and students share answers, reinforcing the target language. This targets speaking and listening skills. Suitable for grades 5-7. Requires worksheets with prompts and a timer. Classroom tip: pre-teach key vocabulary or sentence structures relevant to the worksheet prompts to aid student success. Adjust the time depending on class size and student proficiency.","content_type":"activity","name":"Find Someone!","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet: \"Find Someone!\"","Timer"],"topic_tags":["Speaking","Interaction"]},
  {"id":"scraped-altcir-handbook-follow-up-question-chain-313","text":"This activity reinforces the use of follow-up questions in conversation. Start by explaining the different types of follow-up questions (e.g., clarification, elaboration). Model an example conversation with the JTE, asking and answering follow-up questions to each other. Divide students into pairs. Give each pair a simple topic or statement. Student A makes a statement related to the topic. Student B then asks a follow-up question. Student A answers the question and then Student B asks another follow-up question. Continue the chain, switching roles after a few turns. The aim is to generate a natural flow of conversation through follow-up questions. This targets Speaking and Listening skills. Suitable for Grades 5-7. Materials needed: Topic cards (optional). Classroom tip: Circulate and assist pairs needing help, focusing on proper questioning. Remind students to listen carefully to answers to generate meaningful follow up questions. Both the ALT and JTE should explain the activity. The JTE can also support less confident learners.","content_type":"activity","name":"Follow-up Question Chain","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Topic cards (optional)"],"topic_tags":["Conversation","Questioning","Speaking"]},
  {"id":"scraped-altcir-handbook-restaurant-role-play-314","text":"This activity focuses on practicing English related to ordering food in a restaurant. First, start with an English Shiritori warm-up, where students in teams write words in a chain, using the last letter of the previous word to start the next (5 minutes). For a food-related variation, have students use restaurant vocabulary. Next, students complete restaurant-themed sentences such as \"My favorite restaurant is...\" (8 minutes). Then, have students brainstorm a name for their own restaurant. Introduce common restaurant vocabulary. After, discuss typical actions in a restaurant, such as ordering food and asking for the bill. (7 minutes). The teacher then demonstrates example dialogues in a restaurant setting with a waiter and a customer, asking students to fill in the blanks on their worksheets (10 minutes). Finally, students practice the restaurant dialogues in pairs, taking turns as the waiter and the customer (10 minutes). Encourage volunteers to role-play the dialogues for the class. Total time is approximately 50 minutes.","content_type":"activity","name":"Restaurant Role Play","activity_type":"Main Game","skill":"Speaking","duration_minutes":50,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet with restaurant dialogue blanks","Apron","Plate","Knife","Fork","Flowers"],"topic_tags":["Restaurant","Role-play","Food","Conversation"]},
  {"id":"scraped-altcir-handbook-food-card-game-315","text":"This is a card game designed to practice food vocabulary and simple conversation. First, the ALT prepares food cards with pictures of different dishes (e.g., pizza, sushi, curry rice). The JTE vets the food choices. The game can start by the ALT modeling the conversation, using the food cards. Students are split into pairs. One student picks a card and asks, \"What is this?\" The other student answers, \"It's pizza.\" or \"It's sushi.\" depending on the card. The students then switch roles. If the class has lower English proficiency, the JTE can assist by explaining rules or vocabulary in Japanese. This game targets speaking and listening skills and is suitable for elementary and junior high school students. It requires food cards and can be projected using a PowerPoint presentation. The ALT and JTE can model the conversation to set a good example.","content_type":"activity","name":"Food Card Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Food cards","PowerPoint presentation"],"topic_tags":["food","vocabulary","conversation"]},
  {"id":"scraped-altcir-handbook-do-you-know-how-to-316","text":"This activity focuses on practicing the question \"Do you know how to...?\" Students begin by learning and practicing the key expression. They then circulate the classroom, asking their classmates questions like \"Do you know how to play the guitar?\" and writing down their classmates' answers. After the questioning period, students use the collected answers to write full sentences, such as \"Yes, I know how to play the guitar.\" This activity targets speaking and writing skills, allowing students to practice both question formation and answer comprehension. This activity is appropriate for elementary and early junior high students. Materials needed include worksheets for students to write on. A classroom tip is to model the activity and provide example questions before students begin. Also, consider pre-teaching any vocabulary relevant to the topics the students might choose to ask about.","content_type":"activity","name":"Do You Know How To...?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheets"],"topic_tags":["Questioning","Conversation","Grammar"]},
  {"id":"scraped-altcir-handbook-question-and-answer-worksheet-317","text":"This activity focuses on practicing a key expression by asking and answering questions. The ALT and JTE should collaborate to create a worksheet. Part A of the worksheet includes the key expression, example questions, space for students to write their own questions, and a section for recording answers (student names and Yes/No). Part B provides space for writing full sentences using the key expression. Students circulate and ask the prepared questions to their classmates, recording the answers. Students then use the information gathered to complete Part B. This activity targets speaking and writing skills, allowing students to both practice asking and answering questions and to apply the key expression in a communicative context. This is suitable for elementary and junior high school students. The main material is a worksheet prepared in advance. Classroom tip: Review the key expression and example questions as a whole class before beginning the activity to ensure students understand the target language.","content_type":"activity","name":"Question and Answer Worksheet","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet (prepared by ALT and JTE)","Pens/Pencils"],"topic_tags":["Questioning","Grammar Practice","Speaking Practice"]},
  {"id":"scraped-altcir-handbook-question-and-answer-318","text":"This activity focuses on practicing question formation and short answers using a pre-determined set of vocabulary. The ALT prepares a worksheet with questions and vocabulary, ensuring each student has a copy. The ALT introduces the activity in English, explaining the goal and key expression to be used. The ALT and JTE demonstrate the activity, modeling how to ask and answer the questions. The ALT and JTE check the students' understanding of the vocabulary on the worksheet. The ALT reads out each question clearly, and students repeat for pronunciation practice. Students then work individually or in pairs to ask and answer the questions on the worksheet. The ALT and JTE circulate to provide assistance and ensure correct English usage. When students finish the questioning phase (Part A), the ALT and JTE can then explain Part B, a writing activity based on the same vocabulary and expressions. Both teachers then circulate, assisting students with their writing.\n\nThis activity targets speaking and listening skills. It is suitable for elementary to lower-level junior high school students.\n\nMaterials needed: Worksheets with questions and vocabulary. \nClassroom tips: Encourage students to speak loudly and clearly. Pre-teach difficult vocabulary. Model the correct pronunciation of key phrases.  Circulate actively to provide support. Adjust the complexity of the questions based on student level.","content_type":"activity","name":"Question and Answer","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheets"],"topic_tags":["Q&A","Vocabulary","Speaking"]},
  {"id":"scraped-altcir-handbook-katakana-syllable-sensei-319","text":"This activity aims to familiarize students with syllables and their contrast to mora, crucial for pronunciation and rhythm in English. First, play a Katakana karuta game. Prepare cards with common Katakana words and images. Students listen to the Katakana word spoken and race to find the matching picture card. Next, explain the concept of syllables. Have students clap out the syllables in words. Provide words of varying syllable counts, starting simple (e.g., \"cat\") and progressing to more complex words (e.g., \"television\"). Finally, introduce haiku. Demonstrate the 5-7-5 syllable structure. Students then compose their own short haiku poems in English. This activity targets listening, speaking, and writing skills, allowing students to understand and practice English rhythm. Classroom tips: Use visual aids for syllables, like clapping or jumping. Ensure clear pronunciation during the Katakana karuta game. Vary word difficulty during syllable counting.","content_type":"activity","name":"Katakana Syllable Sensei","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Katakana karuta cards","Pictures","Whiteboard or paper"],"topic_tags":["Syllables","Pronunciation","Haiku"]},
  {"id":"scraped-altcir-handbook-katakana-karuta-and-haiku-320","text":"This activity combines Katakana recognition with creative writing. First, the teacher prepares Katakana karuta cards (cards with Katakana characters) and matching picture/English word cards. Students are divided into groups. The teacher calls out a Katakana sound, and students try to find the corresponding Katakana card. This targets listening comprehension and reading. Next, students use the picture/word cards to create short haiku poems. Provide a worksheet that guides students to write a three-line poem with a 5-7-5 syllable structure, using words from the picture/word cards or other vocabulary they know. Students read their haikus aloud for speaking practice. This is a great activity for solidifying Katakana recognition and encouraging creativity.\n\nLanguage skills targeted: Listening, Reading, Writing, Speaking.\n\nSuitable for: Grade 5-7.\n\nClassroom Tips: Make sure the picture/word cards and Katakana cards match the pronunciation. Encourage fun and creativity during the haiku writing phase. Provide example haikus on the board to help get them started.","content_type":"activity","name":"Katakana Karuta and Haiku","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Katakana karuta cards","Cards with English words and pictures","Syllable counting and haiku composition worksheet"],"topic_tags":["Katakana","Reading","Writing","Speaking","Haiku"]},
  {"id":"scraped-altcir-handbook-katakana-karuta-syllable-game-321","text":"This activity focuses on syllable recognition and pronunciation. Begin by the ALT explaining what a syllable is and contrasting it with a mora, highlighting its importance in English. The JTE can assist with drawing out the differences. (5 minutes). Next, divide students into groups of 3-5 and give each group a deck of ~20 self-made katakana karuta cards. The ALT should explain the rules: students slap the card when they hear the syllabic pronunciation (e.g., \"coffee\"), not the katakana pronunciation (e.g., 「コーヒ」). The JTE can demonstrate the difference between the syllabic and katakana pronunciation. (15 minutes). Following the game, distribute a worksheet focused on syllable counting and haiku composition. Students, in their groups, will count syllables in unfamiliar words (e.g., \"trisyllabic\"). Check the answers together. (15 minutes). Lastly, the ALT explains the English 5-7-5 syllable haiku structure, and students write haikus. The JTE can assist with suggestions. If time permits, students can present their haikus. This activity targets listening, speaking, and writing skills and can be adapted for grades 5-7.","content_type":"activity","name":"Katakana Karuta Syllable Game","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Katakana Karuta cards (~20 per group)","Worksheet (syllable counting/haiku)"],"topic_tags":["syllables","pronunciation","haiku","katakana"]},
  {"id":"scraped-altcir-handbook-english-haiku-322","text":"This activity introduces students to English haiku, focusing on syllables. First, students learn about syllables through examples. Then, they count syllables in given words. Finally, students write two haiku using the correct syllable structure (5-7-5). This activity targets writing and vocabulary. For struggling students, provide suggestions, pre-written lines, or shorten the activity. This activity is designed for 5th to 7th grade students.","content_type":"activity","name":"English Haiku","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":[],"topic_tags":["poetry","writing","syllables"]},
  {"id":"scraped-altcir-handbook-murder-mystery-323","text":"Divide the class into groups of 3-4 students. Each group gets a shuffled deck of cards (except for 3 in a separate envelope: a suspect, a weapon, and a location). The ALT explains that a stuffed animal has been murdered, and the students must solve the mystery. Each group receives a checklist with suspects, weapons, and locations, along with an example sentence: \"I think (stuffed animal) was murdered by (suspect) in the (location) with the (object).\" Students take turns guessing the combination. The student to the left reveals a card if they have one matching the guess; otherwise, the next student to the left reveals one. Students mark off cards on the checklist as they are revealed. The ALT can make it a race or give each group different cards, leading to a class discussion (using passive voice).","content_type":"activity","name":"Murder Mystery","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Cards (suspects, weapons, locations)","Checklist for each group","Envelope for each group (suspect, weapon, location)"],"topic_tags":["Passive Voice","Mystery","Speaking"]},
  {"id":"scraped-altcir-handbook-clue-mystery-game-324","text":"This \"whodunnit\" game is a fun way to practice question formation and deduction. The teacher, with the JTE's help, prepares character cards, location cards (e.g., library, gym, classroom), and weapon cards (e.g., toothbrush, pen). One student is secretly chosen as the 'murderer,' another as the 'victim,' and the rest of the students are investigators. The 'murderer' secretly selects a character, location, and weapon. Investigators ask yes/no questions to solve the mystery. For example: \"Did the murderer use a toothbrush?\" or \"Was the victim killed in the library?\" Students can work in pairs or small groups to discuss and formulate questions. The game continues until someone guesses correctly. This targets speaking and listening skills, as well as critical thinking. The activity is suitable for grades 5-7. Materials needed are character cards, location cards, and weapon cards. Adapt the game to avoid sensitive topics that the school may take issue with.","content_type":"activity","name":"Clue Mystery Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["character cards","location cards","weapon cards"],"topic_tags":["Mystery","Questioning","Speaking"]},
  {"id":"scraped-altcir-handbook-food-around-the-world-325","text":"This activity introduces students to different foods from around the world. First, present a PowerPoint with pictures and names of various dishes (e.g., Mac and Cheese, Chicken Kebabs, Sushi). The PowerPoint should also outline the activity rules and the target conversation format. Next, divide students into pairs. Provide each pair with cards displaying pictures of the foods. Students take turns choosing a card, describing the food and asking their partner if they like it. For example, Student A: \"This is sushi. Do you like sushi?\" Student B: \"Yes, I like sushi\" or \"No, I don't like sushi.\" The activity targets speaking and listening skills, specifically food vocabulary and simple conversation prompts. Classroom tip: Encourage students to use expanded responses. The cards will reinforce vocabulary and make it easier to participate.","content_type":"activity","name":"Food Around the World","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["PowerPoint presentation","Food picture cards"],"topic_tags":["food","vocabulary","speaking"]},
  {"id":"scraped-altcir-handbook-royal-family-tree-326","text":"This activity aims to practice family vocabulary, reading, speaking, and listening skills while also introducing students to UK culture. Divide the class into groups of 5-6 students, with 2 designated writers and 3-4 reporters per group. The writers stay at their desks with a family tree of Queen Elizabeth (pictures with a few names) and a blank piece of paper. The reporters circulate the classroom, reading 12 'hints' posted on A4 paper (e.g., \"Queen Elizabeth is married to Prince Philip\"). Reporters must memorize each hint and relay it to their writers without writing anything down. The writers listen to the reporters and use the information to fill in the family tree, using the blank paper for notes. The first group to correctly complete their family tree wins. Suitable for grades 5-7. Requires printed family trees, A4 hints, and blank paper. Encourage reporters to speak clearly and writers to actively listen and clarify any confusion. Consider pre-teaching key vocabulary or providing simplified hints for lower-level students.","content_type":"activity","name":"Royal Family Tree","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Printed family trees","A4 paper with hints","Blank paper"],"topic_tags":["Family","Vocabulary","UK Culture"]},
  {"id":"scraped-altcir-handbook-queen-s-family-tree-327","text":"This activity focuses on listening and speaking skills through a collaborative group task. Divide students into groups. Each group receives a \"Queen's Family Tree\" template and a sheet of blank paper. Scatter \"hints\" around the classroom. One student in each group is the \"reporter,\" whose job is to read and interpret the hints posted around the room and report the information back to their group. The other students in the group act as \"writers,\" filling in the family tree based on the reporter's information. The hints provide clues about family relationships, requiring students to listen carefully and communicate effectively to complete the tree. If the writers struggle with a hint, they can write it down on the blank paper for later reference or further clarification. Encourage students to help each other and use English throughout the activity. This activity is designed to promote teamwork, critical thinking, and English language comprehension.\n\nLanguage Skills: Listening, Speaking\nGrade Level: 5-7\nMaterials: \"Queen's Family Tree\" template, Hints, Blank paper\nClassroom Tips: Ensure hints are placed in locations accessible to all students. Encourage the teacher to move around, and assist students with vocabulary and sentence structure if needed.","content_type":"activity","name":"Queen's Family Tree","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["\"Queen's Family Tree\" Template","Hints","Blank paper"],"topic_tags":["Family","Listening Comprehension","Speaking"]},
  {"id":"scraped-altcir-handbook-the-queen-s-family-328","text":"This activity involves students working in groups to reconstruct the Queen's family tree using hints. First, the ALT explains the activity in simple English, with the JTE assisting with any comprehension difficulties. The ALT prepares and places hints around the classroom, while the JTE distributes a Queen's Family Tree template and blank paper to each group. Groups then work together to read the hints and write down the family relationships. The ALT and JTE circulate, providing pronunciation help and assistance with any misunderstanding of the hints. Once a group completes their tree, they ask the ALT to check their answers. The ALT provides feedback, and stickers can be awarded to winning groups. The activity targets reading and writing skills, with a focus on understanding relationships and using vocabulary related to family members.","content_type":"activity","name":"The Queen's Family","activity_type":"Main Game","skill":"Reading","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Queen's Family Tree Template","Blank paper","Hints","Stickers"],"topic_tags":["Family","Reading Comprehension","Writing"]},
  {"id":"scraped-altcir-handbook-how-to-speeches-329","text":"Students will learn how to explain a process in English. First, students choose a process to explain, such as cooking a dish or playing an instrument. Then, they write a 3-minute, 4-step speech, preparing the language necessary for a clear explanation (e.g., \"First,...\"). They create a simple prop like a storyboard. In class, students deliver their speeches to the class. Students will evaluate their partner's speech using a provided worksheet. The first lesson introduces the activity and allows time to begin writing. The speech delivery and partner evaluation should take two or three subsequent lessons. This activity targets sequential language and presentation skills. Students will gain experience speaking and listening while providing feedback.","content_type":"activity","name":"How to... Speeches","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper","Markers/Crayons","Worksheet","Optional: various art supplies for props"],"topic_tags":["Process","Speaking","Presentations"]},
  {"id":"scraped-altcir-handbook-speech-evaluation-330","text":"This activity focuses on speech practice and peer evaluation. Students prepare a short speech on a given topic, using one B4 sheet for writing. They then deliver their speech to a partner. During the speech, the partner uses a separate B4 sheet to evaluate the speaker based on pre-determined criteria (e.g., clarity, pronunciation). After the speeches, partners provide feedback. Finally, the ALT evaluates each student using a third B4 sheet, focusing on their delivery and understanding of the language. This activity targets speaking and listening skills. Suitable for grades 5-7. Requires three B4 worksheets per student, pre-printed with the speech outline, peer evaluation rubric, and ALT evaluation rubric. Classroom tip: Provide clear instructions and examples beforehand. Encourage positive and constructive feedback. Monitor the pairs and provide support as needed.","content_type":"activity","name":"Speech & Evaluation","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["B4 worksheets (3 per student)","Speech outline worksheet","Peer evaluation rubric","ALT evaluation rubric"],"topic_tags":["speech","evaluation","speaking"]},
  {"id":"scraped-altcir-handbook-how-to-speech-331","text":"This activity focuses on teaching students to explain a process or how-to guide. Students prepare a speech explaining how to do something, ensuring at least four steps and a reason for the explanation. The speech should be approximately 3 minutes long. Before the presentation, the ALT can review the speeches to ensure grammatical accuracy and clarity. The class then evaluates the speeches using a provided chart, assessing the inclusion of steps and a reason, clarity and grammar, and the speech duration. This activity can take 3-5 weeks depending on class size. Flexibility can be incorporated by adjusting the number of steps and time allocation based on class size.\n\nInstructions Speech Evaluation\nCriteria: \n1. Does it have at least 4 steps and a reason why you are explaining this process?\n2. Is the explanation clear, easily understood, and using correct grammar?\n3. Is the speech around 3 minutes long?","content_type":"activity","name":"How To Speech","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Paper","Pencils/Pens","Evaluation chart"],"topic_tags":["Speaking","Presentation","Instructions"]},
  {"id":"scraped-altcir-handbook-news-story-presentation-332","text":"This activity aims to improve writing and speaking skills through a collaborative news story presentation.  First, divide the class into groups of 3-4 students.  Provide each group with an image representing a news event.  Their task is to create a news story based on the picture, including a title, image caption, and main story content.  Each student must contribute at least 2-3 sentences. Next, each group will present their news story to the class, assigning roles like news broadcaster, interviewer, and interviewee.  Encourage creativity and clear communication. Finally, record the presentations.  Afterward, have different groups analyze and evaluate the presentations of other groups.  Facilitate a peer-to-peer discussion focused on areas for improvement and future goals for writing and presentation skills.  This activity targets sentence construction, vocabulary usage, and public speaking in a fun, collaborative context. Materials needed include images for the news stories, paper, pens/pencils, and a recording device (optional). Classroom tips: Ensure clear instructions and provide a model story example. Encourage students to use descriptive language. Circulate the classroom during the writing and rehearsal phases to offer support and feedback. Manage time effectively. Encourage JTE involvement for language support.","content_type":"activity","name":"News Story Presentation","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Images for news stories","Paper","Pens/Pencils","Recording device (optional)"],"topic_tags":["News","Writing","Speaking","Presentations","Collaboration"]},
  {"id":"scraped-altcir-handbook-news-report-creation-333","text":"This activity helps students practice speaking and writing skills by creating their own news reports. First, students are given an A3 piece of paper. On this paper, students glue newspaper images that have been cut out. They can choose whatever images they want. Next, students use colored pens to write their own news report based on the images. The teacher can provide some key vocabulary beforehand or let the students come up with their own. Students will use the images to explain what is happening, who is involved, where the event took place, and when. Once the news reports are finished, students present their reports to the class. A video camera can be used to record the reports for later review. The activity targets both speaking and writing skills, allowing students to practice forming sentences and presenting information in a clear and concise manner.","content_type":"activity","name":"News Report Creation","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["A3 paper","Newspaper images (cut out)","Glue","Colored pens","Video camera (optional)"],"topic_tags":["News","Speaking","Writing"]},
  {"id":"scraped-altcir-handbook-newspaper-story-334","text":"This activity focuses on writing a simple newspaper story. The ALT prepares example materials such as a model newspaper story with titles, captions, and vocabulary. The ALT explains the activity in English, while the JTE supports students by providing Japanese explanations for new vocabulary and offering guidance during the writing process. The JTE also facilitates recording the presentations. Both teachers may demonstrate a sample presentation. Students write their own short newspaper stories, using the provided example as a guide. This targets writing and can also practice speaking when presenting. The goal is to provide a structured writing experience with scaffolding for vocabulary and story structure.\n\nMaterials needed: Example newspaper story, paper/worksheets, pens/pencils, recording device (e.g., phone, tablet).\n\nClassroom tips: Encourage students to brainstorm ideas before writing. Provide sentence starters or vocabulary lists to assist struggling learners. Give students opportunities to share and give feedback.","content_type":"activity","name":"Newspaper Story","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Example newspaper story","Paper/worksheets","Pens/pencils","Recording device"],"topic_tags":["Writing","News","Vocabulary","Presentation"]},
  {"id":"scraped-altcir-handbook-explaining-japanese-culture-335","text":"This activity aims to help students explain the significance of Japanese cultural icons to others. First, review or introduce vocabulary related to culture and tradition. Next, brainstorm with the whole class a list of Japanese cultural items, professions, and people (e.g., rice, Tokyo Skytree, miko). Write these on the board. Divide students into groups of 3-4. Each group selects 5 items from the list and writes them on their paper. For each item, they write a single sentence explaining its importance. (e.g., \"Rice is important in Japan because we eat it every day.\") Then, the group chooses one item to explain in more detail using multiple sentences. Finally, each group presents their chosen item (or a picture) to the class, explaining its significance. This activity targets speaking and writing skills, promotes cultural understanding, and encourages collaborative learning.","content_type":"activity","name":"Explaining Japanese Culture","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Chalkboard or Whiteboard","Paper","Pens/Pencils","Pictures of cultural items (optional)"],"topic_tags":["Culture","Speaking","Writing","Japan"]},
  {"id":"scraped-altcir-handbook-division-of-labour-336","text":"This activity focuses on dividing responsibilities between the ALT and JTE to ensure effective English instruction. The ALT prepares materials, directs the activity, writes examples on the board, and facilitates English conversation. The JTE assists in teaching the activity, clarifies instructions, provides translations when needed, and helps students complete the task. This collaborative approach enhances student understanding and provides different levels of support. The goal is to maximize the English input from the ALT while providing accessible support from the JTE. Activities will vary depending on the target language skill and activity type chosen by the teacher. Classroom Tip: Ensure clear role definitions at the beginning. Regularly check in with both the ALT and JTE to ensure a good workflow. Consider rotating these roles for variety.","content_type":"activity","name":"Division of Labour","activity_type":"Filler","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["classroom management","team teaching","ALT/JTE collaboration"]},
  {"id":"scraped-altcir-handbook-about-my-culture-337","text":"This activity helps students practice writing sentences and expressing opinions about Japanese culture. First, students list five important items in Japan that they believe foreigners should know about. Next, they write a sentence about each item using the sentence frame: \"____ is/are important in Japan because ____.\"  After writing the initial sentences, students select one sentence and write four more sentences expanding on the chosen topic. This reinforces sentence construction, vocabulary, and descriptive writing. For lower-level students, provide more examples and sentence patterns. This activity works well with junior high school students, but can be adapted for elementary grades by simplifying the vocabulary and sentence structures.","content_type":"activity","name":"About My Culture","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Individual","materials":[],"topic_tags":["culture","writing","sentences","Japan"]},
  {"id":"scraped-altcir-handbook-alt-car-game-338","text":"This activity focuses on practicing giving directions and using directional phrases.  Begin by reviewing key vocabulary and pronunciation from a sample dialogue related to giving directions. Model the dialogue with a co-teacher to provide a clear example. Students then practice giving directions in pairs, using the vocabulary and phrases they have reviewed. The main activity is the 'ALT Car' game. Set up the classroom as a 'town,' with destinations marked. One student acts as the 'driver' and gives directions to another student, the 'ALT car,' to navigate the 'town'.  The 'driver' must use correct directional phrases (e.g., 'Go straight,' 'Turn left,' 'Go past the…'). The activity targets speaking skills and reinforces vocabulary related to directions and location. This activity can be adapted for different levels by adjusting the complexity of the directions and the vocabulary used. Remember to circulate and provide feedback on pronunciation and sentence structure.","content_type":"activity","name":"ALT Car Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Markers","Paper (for map of town, optionally)","Printed Dialogue"],"topic_tags":["Directions","Speaking","Vocabulary"]},
  {"id":"scraped-altcir-handbook-town-directions-339","text":"This activity helps students practice giving and understanding directions. First, prepare location cards for a classroom town (e.g., library, park, school). Students get a handout with key phrases like \"Go straight,\" \"Turn left,\" and \"next to.\" Model the dialogue using a student as a guide. Then, students pair up. One student gets a location card and the other gets a starting point (e.g., the school). The student with the card must describe the location's place in the town. The other student must listen and try to guess which location. The key phrases and the sample dialogue help the students get the gist. The handout's additional practice exercises solidify learning. It targets speaking and listening skills. The activity suits elementary and lower junior high levels. The location cards and handouts are the materials needed. Classroom tips: Encourage students to use gestures alongside the verbal instructions. Circulate and provide support. For younger learners, simplify the town layout. For older ones, increase the complexity of the directions.","content_type":"activity","name":"Town Directions","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Handouts","Location cards"],"topic_tags":["directions","speaking","vocabulary"]},
  {"id":"scraped-altcir-handbook-small-group-communication-340","text":"Divide students into pairs or small groups (3-4 students). The activity involves giving the groups a task or problem to solve using English. This could be anything from completing a worksheet together, discussing a topic, creating a short dialogue, or solving a puzzle. The teacher monitors the groups, offering guidance and support as needed. The focus is on communication and collaboration. The teacher should circulate and listen to each group to ensure all students are participating, and provide feedback as needed. Pair work is easier to organize and ensures all students participate. In slightly larger groups, encourage all students to contribute equally. This activity allows for increased student speaking time, regardless of class size. The teacher can use this opportunity to identify students who are struggling and offer support.","content_type":"activity","name":"Small Group Communication","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":[],"topic_tags":["Communication","Group work"]},
  {"id":"scraped-altcir-handbook-pair-work-setup-341","text":"This activity focuses on preparing students for pair work activities, a common practice in ESL/EFL classrooms. The first step involves establishing a clear routine for small-group activities, which may take a few weeks. The teacher and JTE circulate to monitor correct language usage. It's crucial to pre-teach the necessary language for the activity. The main goal is to review previously learned vocabulary and concepts through pair interaction. The teacher needs to teach and consistently use phrases like: “Work in pairs/twos/threes,” “Work with the person sitting next to you,” “Get/split into pairs,” and “If you want any help, raise your hand.” Team demonstrations can be effective. Grouping students can be done alphabetically or numerically around the class. Clarify instructions by including yourself and the JTE in the demonstration. Alternative grouping methods include working with the nearest student, or lining up by height or birthdate. Consider the appropriateness of the task if grouping boys and girls together. The teacher needs to prevent cheating by circulating the classroom. Preventative measures include using barriers (bags) or having students sit back-to-back. Encourage participation with a competitive element by awarding points.","content_type":"activity","name":"Pair Work Setup","activity_type":"Warm-up","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["classroom management","group work","instructional language"]},
  {"id":"scraped-altcir-handbook-word-challenge-342","text":"Write a long word on the blackboard, such as \"DICTIONARY\" or \"GENERALISATIONS.\" Students then work individually to create as many new words as possible using only the letters from the original word, and not using any letter more times than it appears in the original word. For example, if the original word is \"DICTIONARY\" students can use up to two \"i\"s, but not three. The winner can be determined by the most words found, or by awarding extra points for unique words. Suitable for grades 5-7. This activity targets vocabulary and spelling. Materials needed: Blackboard & chalk, pencil & paper. For more advanced students, dictionaries can be used. Consider using seasonal themes (e.g. \"Happy New Year\").","content_type":"activity","name":"Word Challenge","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["Blackboard & chalk","pencil & paper","dictionaries (optional)"],"topic_tags":["Vocabulary","Spelling","Games"]},
  {"id":"scraped-altcir-handbook-word-associations-343","text":"Choose a topic like seasons (WINTER, SPRING, SUMMER, AUTUMN). Begin by saying a related word (e.g., \"swimming\"). Students respond with the associated season (\"SUMMER\"). This can be expanded with sentence patterns or grammar practice. Example: \"Do you go skiing in the winter?\" or \"What do you do in the summer?\" For advanced students, announce the topic (e.g., WINTER) and have students provide related words, changing the topic per row.","content_type":"activity","name":"Word Associations","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["vocabulary","seasons","speaking"]},
  {"id":"scraped-altcir-handbook-fizz-buzz-344","text":"This is a simple counting game that reinforces number recognition and quick mental calculations. Students take turns counting in sequence, but instead of saying 'three' or any multiple of three, they say \"fizz\". Similarly, they say \"buzz\" for the number seven, or multiples of seven. For numbers that are multiples of three AND contain seven, like 21 or 27, they say \"fizz-buzz\". The activity targets listening and speaking skills, and works on numerical fluency. The ALT should write down the correct answers ahead of time for the game to make sure that everything is correct. Suitable for elementary school and early junior high students. The only materials needed are a list of the numbers. Classroom tip: Encourage students to play enthusiastically, and demonstrate the first few rounds to clarify rules.","content_type":"activity","name":"Fizz-Buzz","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Number list"],"topic_tags":["Numbers","Counting","Games"]},
  {"id":"scraped-altcir-handbook-alphabet-race-345","text":"Prepare two sets of alphabet cards (different colors recommended). Divide students into two teams, giving each student a card (distribute any extras). Call out a word or short sentence. Teams line up in correct order to spell the word or sentence. The first team to shout \"Got it!\" wins. Check for correct spelling and punctuation. Ensure all students get a chance to participate. \n\nExample: \"I like English.\" requires these cards: D(1), E(2), F(2), G(1), H(1), I(3), K(1), L(2), N(2), O(2), S(2), T(1), U(1), Y(1), !(1), ?(1), .(1). \n\nClassroom Tips: Push desks aside for more space. In smaller classes, mix cards face-up in two designated areas for each team. For large classes, hand out cards. You can play this in the gym as a grade-against-grade competition.","content_type":"activity","name":"Alphabet Race","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Alphabet cards","List of possible sentences with letter sets (optional)"],"topic_tags":["Alphabet","Spelling","Sentence building"]},
  {"id":"scraped-altcir-handbook-unrelated-words-346","text":"The teacher calls out a set of four words, and students must identify the word that doesn't belong. This activity adapts well to different levels by varying the vocabulary and categories. \n\nFor example, the teacher might say \"dog, cat, paper, horse\" (paper is unrelated) or \"cow, horse, elephant, chicken\" (all farm animals except one). You could also use colours, numbers, or other categories appropriate for the students' level.\n\nTo make it more engaging, play in teams and award points to the first team to correctly identify the unrelated word. You can have students call it out or write it on the board.\n\nPrepare a list of word sets in advance.","content_type":"activity","name":"Unrelated Words","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Prepared list of word sets"],"topic_tags":["Vocabulary","Categorization"]},
  {"id":"scraped-altcir-handbook-english-poetry-347","text":"Introduce students to English poetry, focusing on Haiku and Tanka forms. Explain the syllable structure: 5/7/5 for Haiku and 5/7/5/7/7 for Tanka. Guide students to use a dictionary for syllable checking. Encourage simplicity and familiar vocabulary to ease the creative process.  Suggest alternative poetic forms like Limericks (humorous, rhyming structure) and Diamond poems (structured around antonyms). Offer example vocabulary to get them started with Diamond poems.","content_type":"activity","name":"English Poetry","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Individual","materials":["Dictionaries","Paper"],"topic_tags":["Poetry","Writing","Creativity"]},
  {"id":"scraped-altcir-handbook-classroom-library-books-348","text":"This activity encourages students to write and illustrate their own simple books. Students choose a topic, such as \"My Life,\" \"My Dream,\" or a fictional story, and write a few sentences for each page. They then create illustrations to accompany the text, arranged as pages in a booklet. Students design a cover with a title, their name, and the date. Once each student completes a book, the class creates a library where students can read each other's stories. This promotes reading outside of the textbook. \n\nThis activity targets writing and reading skills. Students practice sentence construction, vocabulary, and creative expression through writing. Reading others' work enhances reading comprehension and provides exposure to different writing styles and topics. \n\nThis is suitable for grades 5-7. \n\nMaterials needed: Paper, pencils, colored pencils or crayons, markers, stapler (optional). \n\nClassroom tips: Encourage students to help each other with spelling and grammar. Provide sentence starters or vocabulary lists for support. Celebrate the completion of the books by organizing a \"book fair\" or reading session.","content_type":"activity","name":"Classroom Library Books","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Individual","materials":["Paper","Pencils","Colored pencils/crayons","Markers","Stapler (optional)"],"topic_tags":["Writing","Reading","Creative expression"]},
  {"id":"scraped-altcir-handbook-picture-description-349","text":"This activity helps students practice sentence construction and descriptive language. Prepare or have students create pictures, either of themselves or other relevant subjects. Divide the class into small teams. Students write sentences about the picture, adjusting the number of sentences based on their language level. After writing, students take turns describing the picture using their sentences. An oral version is also possible where students describe the picture aloud. Suitable for intermediate and advanced learners. The activity targets both writing and speaking skills.","content_type":"activity","name":"Picture Description","activity_type":"Production","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Pictures","Paper","Pencils"],"topic_tags":["Descriptive Language","Sentence Structure","Writing","Speaking"]},
  {"id":"scraped-altcir-handbook-my-dictionary-350","text":"This activity encourages students to create their own English-Japanese dictionaries using words they encounter daily. Students select an English word from any source (songs, commercials, etc., excluding the textbook) and introduce it to the class. Over the course of the term, students build their personal dictionaries. At the term's end, a vocabulary test is administered using the student-chosen words. This promotes student-centered learning and exposure to contemporary English vocabulary.","content_type":"activity","name":"My Dictionary","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Dictionary worksheet"],"topic_tags":["vocabulary","student-centered learning","real-world English"]},
  {"id":"scraped-altcir-handbook-dictionary-sheet-351","text":"This activity helps students learn and record new vocabulary. Each student creates their own 'Dictionary Sheet' for new words they encounter. The sheet has four columns: 'Word' for the new English word, 'Meaning' where they write the Japanese meaning, 'Sentence' for an example sentence using the word, and 'Notes' for where they found the word and any other personal notes. The teacher introduces the format and provides examples. Students can fill out these sheets individually as they encounter new vocabulary during lessons, reading activities, or even outside of class. The focus is on vocabulary acquisition and comprehension. This targets vocabulary and writing skills, helping students practice how to define a word and use it in a sentence. It’s suitable for upper elementary and junior high school students to record and study new vocabulary. No specific materials are needed beyond paper and writing utensils. The teacher should model the process and provide support to the students as needed. You can check the sheets regularly to provide feedback.","content_type":"activity","name":"Dictionary Sheet","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":1,"interaction":"Individual","materials":["Paper","Pens/Pencils"],"topic_tags":["Vocabulary","Writing","Dictionary"]},
  {"id":"scraped-altcir-handbook-words-from-pictures-352","text":"This activity focuses on vocabulary and spelling using visual prompts. First, select 5-10 detailed pictures from magazines and label them A, B, C, etc. Divide the class into groups of 8-10 students, ideally arranged so they can easily see each other and the picture. Assign each group a picture. Instruct students to write down as many words as they can find in the picture that begin with the letter assigned to it. Set a time limit. After the time is up, the group leader checks the word lists for accuracy. The student with the longest correct list wins within their group.  Options: Play as a group activity, where groups compete against each other. You can also repeat the activity by changing the pictures or the starting letter.","content_type":"activity","name":"Words From Pictures","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Pictures","Paper","Pencils"],"topic_tags":["Vocabulary","Spelling","Pictures"]},
  {"id":"scraped-altcir-handbook-what-s-missing-353","text":"This activity reviews simple vocabulary. Divide the class into two teams. Place about twenty familiar objects (e.g., pencil, pen, fruit) on the teacher's desk. One student from each team comes to the front. The teacher removes an object without them seeing. Student A turns around and identifies the missing object. Meanwhile, student B sings the alphabet song repeatedly. When Student A correctly identifies the object, Student B stops singing. Student B's team gets a point for each time the song was sung. The team with the most points wins. This game targets vocabulary recall and auditory processing, while incorporating a time-based element for added challenge. It can be adapted to any vocabulary set. Classroom tip: Vary the objects to keep the game engaging. You can also adjust the difficulty by changing the number of objects or the time limit.","content_type":"activity","name":"What's Missing?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Teacher's desk","Various objects"],"topic_tags":["Vocabulary","Review","Game"]},
  {"id":"scraped-altcir-handbook-observe-and-remember-354","text":"This activity is designed for first-year JHS students to practice vocabulary and memory skills. Prepare either a chart with pictures of familiar objects (about six at a time) or a collection of small objects easily identified by the students. You can also use flashcards to review vocabulary before the main activity. Show the chart or objects to the students for a set time (e.g., two minutes). Students then return to their seats and, individually or in groups, write down the names of as many items as they can remember from the chart or objects. The chart or objects should be covered during this part. After a set time (e.g., five minutes), students check their lists to see who remembers the most. You can check the lists by having students read their lists, pull out each item as called, or by holding up each item and having students identify it. Adjust the number of items and time according to the students’ level (Beginner: 12-15 items, Intermediate: 15-20 items, Advanced: 25-30 items). This targets vocabulary acquisition, listening, and memory. Suitable for JHS1 students.","content_type":"activity","name":"Observe and Remember","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Chart with pictures or objects","Paper","Pencil"],"topic_tags":["Vocabulary","Memory","Review"]},
  {"id":"scraped-altcir-handbook-true-false-355","text":"Write YES and NO (or TRUE and FALSE) on the board or attach signs. Divide the class in half and have them move their desks to the side or back of the room. Give the first person at the head of each line a piece of chalk. Ask a YES or NO question. For example: “Is today Friday?” or a true/false statement: “I am a boy.” The first person to circle the correct answer wins a point for his/her team. This game can be made very simple for beginners (e.g. “This is a book” or “Is this a pig?”) or it can be made more difficult for advanced students (e.g. “Is the capital of England New York?”). Useful for practicing recently acquired vocabulary. \n\nAlternatively, try minimal pairs such as cap/cup, bat/bag, rabbit/racquet, etc. Instead of YES and NO, use TRUE and FALSE. Have students sitting. They raise hands to answer. The first to do so can give the answer.","content_type":"activity","name":"True/False","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Blackboard & chalk"],"topic_tags":["Vocabulary","Games"]},
  {"id":"scraped-altcir-handbook-circle-the-word-number-356","text":"Write words or numbers on the blackboard related to classroom objects, animals, fruit, or minimal pairs, depending on the class level. Divide the class into teams and give the first student in each row a piece of chalk. Call out a word or number from the board. The first student to circle the correct word or number wins a point for their team. You can provide hints if needed. For example, say \"I ___ to school at eight\" to elicit the word \"come\". When using minimal pairs, clearly pronounce the word. For higher levels, use minimal pairs to focus on pronunciation. Alternatively, use numbers, and mix numerals with spelled-out numbers like \"1, 2, 3, four, five\". This activity aims to help students recognize words and numbers, and connect sounds with spelling or visual representations.","content_type":"activity","name":"Circle the Word/Number","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Blackboard","Chalk"],"topic_tags":["Vocabulary","Pronunciation","Numbers"]},
  {"id":"scraped-altcir-handbook-number-game-357","text":"Prepare a number diagram and make enough copies for all students. The diagram should have numbers arranged in a way that, when connected in the order called out, form a picture. Start by calling out the first number (next to the starting point). Students circle (or connect) the numbers on their worksheets as you call them out. Students can guess the picture at any time. Clearly explain the rules. Demonstrate an example on the blackboard to show how to check for the next number (check all sides of the previously called-out number). This is a listening comprehension activity that tests students' ability to differentiate minimal number pairs such as 30 and 13. This activity is particularly effective when themed to the season and is most successful with interesting visuals to maintain student engagement.","content_type":"activity","name":"Number Game","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Diagram copies for students","Pencils","Erasers"],"topic_tags":["Numbers","Listening Comprehension","Seasonal"]},
  {"id":"scraped-altcir-handbook-english-karuta-358","text":"Divide the class into teams of five or six members. Provide each team with an identical set of picture cards. Students spread out the cards so every team member can see them. The teacher calls out a word, sentence, or letter, and students race to find the corresponding card. For beginners, the word can be written under the picture, with the first letter on the back. For more advanced students, use cards with only pictures. This activity targets listening comprehension and vocabulary recognition. It can be played as a team or individual competition, awarding points for finding the correct card first. The activity aims to improve listening skills and vocabulary acquisition through a fun, competitive format.","content_type":"activity","name":"English Karuta","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Picture cards"],"topic_tags":["Vocabulary","Listening Comprehension","Games"]},
  {"id":"scraped-altcir-handbook-whisper-down-the-alley-359","text":"Divide the class into teams by rows. Ensure teams have equal numbers. Depending on the students' level, provide a word, phrase, or sentence to the last student in each row. Repeat the word or sentence two or three times, speaking quietly so other students cannot hear. Ideally, explain the sentence outside the classroom to enhance anticipation. Students whisper the message forward to the next student in their row. The student at the front of each row writes down what they heard. Scoring is based on speed and accuracy. Incorporate vocabulary, minimal pairs, or tongue twisters to make the activity engaging. Prepare sentences in advance for greater effectiveness. Materials: paper and pencil. Consider using tongue twisters.","content_type":"activity","name":"Whisper Down the Alley","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Paper","Pencil"],"topic_tags":["Listening","Teams","Vocabulary"]},
  {"id":"scraped-altcir-handbook-tongue-twister-fun-360","text":"This activity focuses on pronunciation and fluency through the use of tongue twisters. Start by writing several tongue twisters on the board (or projecting them). Begin by having students listen to you read a tongue twister clearly, emphasizing the difficult sounds. Then, have the students repeat the tongue twister as a whole class, focusing on pronunciation. Next, divide students into pairs or small groups and have them take turns reading the tongue twisters to each other, encouraging them to try to say them faster and with fewer mistakes. You can award points for accuracy and speed. This is a great warm-up or filler activity. Suitable grade levels are elementary and junior high, as it improves pronunciation and listening skills.\n\nMaterials needed: Whiteboard or projector, markers or pens.\n\nClassroom tips: Start slowly. Encourage students to listen carefully to the sounds. Provide ample time for repetition. Make it a fun and engaging competition! Consider having students write down their own tongue twisters or create a tongue twister contest.","content_type":"activity","name":"Tongue Twister Fun","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Whiteboard or projector","Markers or pens"],"topic_tags":["Pronunciation","Fluency","Speaking"]},
  {"id":"scraped-altcir-handbook-draw-the-picture-361","text":"This activity focuses on listening and speaking skills. Select one student to be the artist at the blackboard. The other students receive a copy of a simple picture. Students take turns describing parts of the picture and their locations to the student at the board, who must recreate the picture based on their instructions. For example, a student might say, \"There is a house,\" followed by, \"There is a tree to the right of the house,\" and so on. The teacher should encourage students to use descriptive language. If the students finish early, they can go back and refine the picture with more descriptive language. For example, a student could say \"The house has a red roof.\"\n\nThis activity is great for building listening comprehension and speaking fluency.","content_type":"activity","name":"Draw the Picture","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Blackboard & chalk","Copies of picture for each student"],"topic_tags":["Describing","Following Instructions","Art"]},
  {"id":"scraped-altcir-handbook-draw-a-face-362","text":"This activity focuses on describing and drawing the parts of a face. Begin by reviewing or introducing face vocabulary such as 'eyes,' 'nose,' 'ears,' 'mouth,' and directional terms like 'left,' 'right,' 'up,' and 'down.' Write these words on the board for reference, especially for beginner students. Select one student to be blindfolded and stand in front of the board. The ALT will draw a large circle on the board to represent the face. Then, ask other students to instruct the blindfolded student where to draw the face parts. Students can call out instructions such as, “Draw the eyes above the nose!” or “Left, a little bit down!”. The blindfolded student attempts to draw the face parts based on the instructions. This activity targets listening comprehension and speaking as students use directional vocabulary and face vocabulary to instruct the drawer. The activity is suitable for elementary and early junior high school students. Materials needed include a blindfold and a marker/chalk. Classroom tips: Encourage students to be clear and concise with their instructions. Provide assistance if needed. Use this as a fun warm-up activity!","content_type":"activity","name":"Draw a Face","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Blindfold","Marker/Chalk"],"topic_tags":["Parts of the face","Directions","Speaking"]},
  {"id":"scraped-altcir-handbook-body-parts-drawing-363","text":"This activity focuses on body parts vocabulary and encourages creativity. Begin by teaching basic body part vocabulary, allowing students to ask questions. Be prepared for potentially sensitive questions and have appropriate responses ready. Divide students into teams. Select one student from each team to be the drawer. Give drawing commands, such as \"Draw ten faces\" or \"Draw a foot with ten toes.\" After the drawing, have the class vote on the weirdest or most creative drawings. This activity targets listening comprehension and speaking (when students ask questions), and also supports creative thinking and art skills.","content_type":"activity","name":"Body Parts Drawing","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Paper","Pencils/Markers"],"topic_tags":["Body Parts","Vocabulary","Drawing","Teamwork"]},
  {"id":"scraped-altcir-handbook-introduction-bingo-364","text":"This activity encourages students to move around and interact, while also helping them learn about their classmates. Students ask each other questions, record the answers, and try to get \"Bingo\" by marking off boxes on their sheets. \n\n**How to Play:**\n1.  Each student receives a worksheet with a grid (e.g., 5x5). The boxes contain prompts like \"What's your favorite food?\" or \"Do you have any pets?\" You can create a sheet, or have the students make their own.\n2.  Students move around the classroom, asking different classmates a question from their sheet. They write the classmates' names and answers in the corresponding boxes.\n3.  Once the grid is filled (or time is up), students return to their seats.\n4.  The teacher calls out names from the class. If a student has that name and answer recorded on their sheet, they mark the box with an \"X\".\n5.  The first student to get five \"Xs\" in a row (horizontally, vertically, or diagonally) shouts \"Bingo!\" and wins.\n\n**Language Skills:** Speaking (asking questions, giving answers), Listening (understanding answers), Writing (recording names and answers). \n\n**Suitable Grade Levels:** Grade 5-7. It might be challenging for lower levels.\n\n**Materials:** Worksheet with question prompts, pens/pencils.\n\n**Classroom Tips:** Create some sample questions and model how to ask and answer them before the activity. Vary the questions to keep the students engaged.","content_type":"activity","name":"Introduction Bingo","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Worksheet with question prompts","Pens/pencils"],"topic_tags":["Introductions","Classmates","Communication"]},
  {"id":"scraped-altcir-handbook-where-is-she-he-365","text":"Before the lesson, the JTE prepares name cards (in romaji) for the students. The ALT holds the name cards and asks, \"Where is [student's name]?\" The JTE gives directions to the ALT, such as, \"Go straight, turn left, stop, turn right, stop, turn around…\" The ALT follows the directions. When the ALT reaches the student, they give the student their nametag. The student then puts the nametag on their shirt. After a few rounds, students may be able to give directions. After the ALT gives out all the tags, the JTE should pause the game to review directional vocabulary and pronunciation (no katakana English!).  An alternative option is to simply read the names, have students respond \"Here,\" find them, give the nametag and say \"Nice to meet you.\" The student responds \"Nice to meet you, too!\" Keep greetings simple. Remember to clarify first or last name when calling names.","content_type":"activity","name":"Where is She/He?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Name cards (romaji)"],"topic_tags":["Directions","Greetings","Pronunciation"]},
  {"id":"scraped-altcir-handbook-quiz-time-366","text":"Divide the class into teams. Prepare a set of questions appropriate for the students' English level and the lesson's topic. Read out each question clearly, allowing time for teams to discuss and write down their answers. Award points for correct answers. The team with the most points at the end wins. This activity targets listening comprehension and, depending on the questions, can indirectly encourage speaking and reading skills. It's suitable for reinforcing vocabulary, grammar, or general knowledge related to a unit. Materials needed: prepared quiz questions, a point system (e.g., whiteboard/markers or a pre-made scoring sheet), and pens/paper for students to write answers. Classroom tip: Vary the types of questions (multiple choice, true/false, short answer) to keep students engaged. Consider providing hints or partial points for partially correct answers, particularly for lower-level learners.","content_type":"activity","name":"Quiz Time","activity_type":"Review","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Prepared quiz questions","Whiteboard/markers or scoring sheet","Pens/paper"],"topic_tags":["Review","Vocabulary"]},
  {"id":"scraped-altcir-handbook-trivia-challenge-367","text":"This activity tests students' knowledge of various topics. Divide the class into teams. Present a series of questions across different categories like history, sports, animals, and food (examples provided). Teams take turns answering. Award points for correct answers. Alternatively, present the answers and have students formulate the questions in a 'Jeopardy' style. This targets vocabulary and general knowledge. Adapt the question difficulty to the students' level. Use the example categories provided or create your own. Materials needed: Questions written on the board or on cards, points system. Classroom Tip: Encourage collaboration within teams.","content_type":"activity","name":"Trivia Challenge","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Question cards or written on board","Points system (optional)"],"topic_tags":["Trivia","Vocabulary","General Knowledge"]},
  {"id":"scraped-altcir-handbook-talking-to-foreigners-intro-368","text":"This activity introduces basic phrases for interacting with foreigners, useful for building confidence and preparing students for future interactions. \n\n1.  **Preparation:** Before class, choose phrases like \"Hello,\" \"Excuse me,\" \"Do you speak English?\" \"Where is...?\" and \"Thank you.\" Write each phrase on a separate flashcard or prepare a digital presentation with images.  Provide example contexts for each. For example: \"Excuse me\" while gently tapping someone on the shoulder; \"Where is the restroom?\" while pointing to a restroom sign.\n2.  **Introduction:** Present each phrase, modeling the pronunciation clearly. Have the students repeat after you, as a whole class, in pairs, and then individually.  Use gestures and visual aids (pictures, drawings, or realia) to clarify the meaning. Demonstrate the proper intonation and stress.\n3.  **Practice:**  After introducing a few phrases, create short, simple role-playing scenarios. For example: \"Student A: You need the restroom, what do you say?\"  \"Student B: You are lost. Ask where the school is.\"\n4.  **Wrap-up:** Review all phrases at the end of the lesson. Have the students brainstorm other phrases they might need. Encourage them to practice with each other. This activity targets pronunciation, basic speaking, and listening. It is suitable for elementary and early junior high students. Materials needed are flashcards/digital presentation and realia. Classroom tips include keeping the scenarios simple and fun, and to encourage student participation by praising their efforts.","content_type":"activity","name":"Talking to Foreigners Intro","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Flashcards or digital presentation","Real objects (optional)"],"topic_tags":["Greetings","Communication","Basic Phrases"]},
  {"id":"scraped-altcir-handbook-do-i-have-to-board-game-369","text":"This activity is a board game designed to practice asking and answering questions about Japanese culture and customs using 'have to' and 'should'. Students work in small groups, with one student acting as a 'foreigner' and another asking a question based on where they land on the board game. The questions are about topics like food, holidays, customs, and landmarks in Japan. Students must then answer the question using appropriate vocabulary and grammar. The teacher can monitor and provide corrections or support as needed. The activity targets speaking and listening skills, as well as cultural awareness. \n\nMaterials needed: A board game with question prompts (examples provided), dice.\n\nClassroom tips: Keep groups small (3-4 students). Circulate and provide support. Encourage natural conversation and focus on fluency rather than perfect grammar.","content_type":"activity","name":"Do I Have to...? Board Game","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Board game with question prompts","Dice"],"topic_tags":["Culture","Speaking","Questioning"]},
  {"id":"scraped-altcir-handbook-what-s-in-the-bag-370","text":"This activity involves students guessing an object hidden in a bag through Yes/No questions. First, the teacher places several objects (coin, ball, pencil, etc.) in a bag, choosing one to be the target. Students then ask Yes/No questions to identify the object. For junior high, the teacher can introduce and practice relevant sentence patterns, often aligning with textbook grammar to help students refine their questions. Examples include, \"Is it a coin?\" and \"Yes, it is, what kind of coin is it?\"  Alternatively, objects can be displayed, names reviewed, and then hidden. One student secretly selects an object, and the class asks questions to guess it. Cue cards with question prompts can guide students. Examples of question prompts are, What color is it?, What shape is it? and Can you eat it? Advanced students can ask more complex questions, such as Tell me about ____, Is it ____? (small, heavy, etc.), Is it made of ____? (wood, paper, etc.), Is it bigger than a ____? and Is it smaller than a ____?. This activity targets listening and speaking skills, encouraging question formation and deduction. It is suitable for various levels and types of students.","content_type":"activity","name":"What's in the Bag?","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Objects","Bag","Cue cards"],"topic_tags":["Questioning","Describing objects","Guessing game"]},
  {"id":"scraped-altcir-handbook-picture-story-chain-371","text":"This activity encourages collaborative writing and story-telling. Begin by drawing a funny picture on the board, or have a student draw one. Divide the class into teams, with each row representing a team. Each student receives a piece of paper and a pencil. The first student in each row writes a sentence about the picture and then passes the paper to the next student behind them. The subsequent students must read the sentences written by the previous students and add their own sentence to build a cohesive story. The first team to finish their story, within a time limit, wins. Emphasize the importance of creating a logical narrative, not just a series of disconnected sentences. After all teams have finished (or the time is up), read the stories aloud to the class, rewarding creativity and coherent storytelling. Classroom Tip: Circulate to check for understanding and help teams stay on track. This activity is a great way to improve writing skills and build a sense of teamwork.","content_type":"activity","name":"Picture Story Chain","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Blackboard & chalk","Paper","Pencil"],"topic_tags":["Storytelling","Writing","Teamwork"]},
  {"id":"scraped-altcir-handbook-humorous-guide-to-our-town-372","text":"Students will create a short, humorous guide to their town in English. First, introduce the activity and brainstorm some funny ideas for sightseeing spots, local specialties, or historical events. Students will then work individually or in pairs to write a brief description of these places or events. Encourage them to be creative and use descriptive language. They should also include a simple, easy-to-read map marking the locations they describe. Finally, students can share their guides with the class, either presenting them orally or displaying their written work. This activity targets writing and speaking skills. It's suitable for elementary to early junior high school students. Materials needed include paper, pens/pencils, and potentially colored markers for the maps. A good classroom tip is to provide a template or example guide to help students. Encourage students to be creative with their content. Reviewing basic sentence structures such as 'There is/are...' or 'The best part about...' is useful before students start.","content_type":"activity","name":"Humorous Guide to Our Town","activity_type":"Production","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Paper","Pens/Pencils","Markers (optional)"],"topic_tags":["Town","Writing","Speaking","Descriptive Language"]},
  {"id":"scraped-altcir-handbook-translation-practice-373","text":"Provide students with words, kanji, sentences, paragraphs, or short stories for translation from English to Japanese or vice versa. This activity focuses on reading and writing skills, allowing students to practice vocabulary and sentence structure. Choose materials appropriate to the students' level. For example, younger students might translate simple words, while older students can tackle more complex sentences or short passages. Use Eikaiwa books or textbooks for source material. This activity can be used as a stand alone task or used for a bulletin board display after students complete it, by separating the phrases from their translations. \n\nMaterials needed: Translation source material (e.g., Eikaiwa book pages, vocabulary lists, short stories) and writing utensils.","content_type":"activity","name":"Translation Practice","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Individual","materials":["Translation source material (Eikaiwa book pages, vocabulary lists, short stories)","Writing utensils"],"topic_tags":["Translation","Vocabulary","Reading Comprehension","Writing"]},
  {"id":"scraped-altcir-handbook-expressive-reading-374","text":"This activity focuses on understanding how emphasis changes meaning. Write a simple sentence on the board, such as \"This is a book.\" Explain that the students will read the sentence aloud, but each time they should emphasize a different word. Model the activity by reading the sentence four times, each time stressing a different word and explaining how the meaning changes. For example, stressing \"THIS\" implies you are pointing out the book, while stressing \"BOOK\" emphasizes the item itself. Have students practice individually or in pairs, taking turns stressing different words in the sentence. Encourage students to think about how the meaning changes. After a few minutes, have students share their observations. The aim is to improve speaking and listening skills by focusing on how intonation can change the message, building their awareness of stress and meaning. \n\nMaterials needed: Whiteboard or paper. \n\nClassroom tips: Start with simple sentences, and consider providing the sentences in advance. Encourage students to exaggerate their emphasis for clearer demonstration. Monitor to ensure all students are participating.","content_type":"activity","name":"Expressive Reading","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Whiteboard or paper","Markers or pens"],"topic_tags":["Pronunciation","Speaking","Intonation","Meaning"]},
  {"id":"scraped-altcir-handbook-feeling-reading-375","text":"This activity focuses on understanding and expressing emotions through reading. First, write the statements on the board or provide a worksheet. Students first read each statement in a neutral tone, without any expression. Next, students read each statement again, this time adding the appropriate feeling to their voice and facial expressions. The teacher can model the correct feeling before the students practice. This activity targets listening and speaking skills, as students must interpret the context and then express the correct emotion. It is suitable for elementary to junior high school students. Materials needed include the written statements (board or worksheet). Classroom tip: Encourage students to exaggerate their expressions to help them differentiate between the different emotions. Monitor the students carefully to ensure they are using the correct intonation and facial expressions for each sentence.","content_type":"activity","name":"Feeling Reading","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Board or worksheet","Markers or pens"],"topic_tags":["Feelings","Pronunciation","Expression"]},
  {"id":"scraped-altcir-handbook-emotion-charades-376","text":"This activity focuses on expressing emotions through reading and speaking. Students are given sentences and asked to read them out loud, conveying a specific emotion. Start by introducing a set of emotions (happiness, jealousy, boredom, anger, disappointment, shock) and writing them on the board with associated facial expressions or gestures. Divide the class into pairs. Provide each pair with a set of sentences (e.g., \"You're very pretty.\"). Each pair takes turns reading a sentence aloud, focusing on conveying a different emotion each time. The other student guesses the emotion. Then, reverse roles. Encourage students to exaggerate their expressions and use appropriate tone of voice. This targets speaking and listening skills, specifically pronunciation and understanding of emotional cues. Use as many sentences as you want. \nClassroom tips: Start by modeling the emotions for the whole class. Focus on one or two emotions per lesson for the first run of this activity.","content_type":"activity","name":"Emotion Charades","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Printed sentences","Whiteboard/Chalkboard"],"topic_tags":["Emotions","Speaking","Pronunciation"]},
  {"id":"scraped-altcir-handbook-how-to-say-rain-377","text":"This activity focuses on expressive language and situational vocabulary. The teacher presents five different scenarios related to rain (e.g., walking without an umbrella, after a drought). Students are challenged to express how they would say the word 'rain' in each situation, considering their feelings or the context. This encourages them to use intonation and other vocal cues to convey meaning. The teacher should model the responses initially, emphasizing different tones and expressions. For example, 'Walking without an umbrella' might be said with a sigh and a downcast voice. Encourage students to be creative and use their imaginations. Afterwards, the teacher can have students practice the scenarios in pairs. Language skills targeted are speaking and listening comprehension. Suitable for elementary and lower-level junior high students. Materials needed: none. Classroom tips: Encourage creativity and emphasize the importance of non-verbal communication. Model different expressions clearly, and offer a variety of scenarios to keep the activity engaging. Monitor student interactions and provide feedback on their use of tone and expression.","content_type":"activity","name":"How to Say 'Rain'","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":[],"topic_tags":["weather","vocabulary","emotions"]},
  {"id":"scraped-altcir-handbook-soba-situations-378","text":"This speaking activity encourages students to consider how their tone and expression change depending on the context. The teacher presents different scenarios related to eating soba (a type of Japanese noodle). Students practice saying the word \"soba\" in various ways to convey their feelings and situation. \n\n**Procedure:**\n1.  Introduce the concept: Explain that the same word can be said differently depending on the situation. Use a simple example like \"hello\" to demonstrate this.\n2.  Present the scenarios: Write the scenarios on the board or project them. Examples like \"You haven’t eaten all day,\" \"You’ve had soba everyday for a week,\" etc.\n3.  Model the first scenario: The teacher models saying “soba” in the first situation to give an example of the appropriate tone of voice.\n4.  Student practice: Students then take turns repeating the word “soba” in each of the given situations.\n\n**Language Skills:** Speaking (pronunciation, expression), Listening (to understand the scenarios).\n\n**Suitable Grades:** Grade 5-7\n\n**Materials:** Board or projector, scenarios written on paper or slides.\n\n**Classroom Tips:** Encourage students to be expressive. The focus is on communication, not perfect pronunciation. Consider having students act out their responses for added fun.","content_type":"activity","name":"Soba Situations","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Board or projector","Prepared scenarios"],"topic_tags":["Food","Pronunciation","Expression"]},
  {"id":"scraped-altcir-handbook-what-s-that-roleplay-379","text":"This activity focuses on situational language use and tone. Students are presented with scenarios and asked to respond to the prompt \"What's that?\" in a way that suits the given role. First, introduce the phrase \"What's that?\" and review its basic meaning. Then, present the scenarios, either written on the board or displayed on a projector. Students can work individually, in pairs, or as a whole class. For individual work, students write down how they would say \"What's that?\" in each situation. In pairs, students can roleplay the scenarios, taking turns asking and answering the question. As a whole class, the teacher can call on students to act out the scenarios. The language skills targeted are speaking (pronunciation, fluency), and listening (understanding the scenarios and responses). Encourage students to use different tones and expressions based on the situation. The activity is suitable for grades 5-7. Materials needed are paper/pen if writing is involved, and the scenarios (prepared beforehand). A classroom tip is to model the first scenario yourself to give examples.","content_type":"activity","name":"What's That? Roleplay","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Paper","Pen","Prepared Scenarios (written or projected)"],"topic_tags":["Roleplay","Questioning","Situational Language","Speaking"]},
  {"id":"scraped-altcir-handbook-video-production-380","text":"This activity involves students creating a short video to practice speaking and listening skills. Students first prepare a script based on their own ideas or materials from textbooks. They then gather visual materials like pictures, advertisements, or family photos. The video is filmed, often with one teacher handling the equipment. Students record their voices over the video footage. The final product can be anything from a mock newscast to a pop video. The activity targets both speaking and listening skills, as students must write scripts, speak their lines, and listen to the final product. It boosts student confidence and encourages them to speak English. This activity is best suited for students who have some basic English proficiency. For example, a group of English Club members created a 15-minute video over six weeks. This required weekly meetings to script, gather materials, film, and edit. Incorporate listening comprehension checks by pausing the video and asking questions. \n\nMaterials Needed: Script templates, visual materials (magazines, pictures, etc.), video recording equipment, microphone (optional).","content_type":"activity","name":"Video Production","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":3,"interaction":"Groups","materials":["Script templates","Visual materials","Video recording equipment","Microphone (optional)"],"topic_tags":["Video","Speaking","Listening","Production"]},
  {"id":"scraped-altcir-handbook-using-realia-381","text":"This activity focuses on using real objects (realia) to enhance engagement and understanding in the classroom. Begin by gathering a collection of interesting items such as food items, blindfolds, pictures of pop stars or TV characters, stuffed toys, telephones, souvenirs, microphones, hats, glasses, or clothes. The goal is to select items that will provoke a reaction and capture students' attention. \n\nBefore the activity, ensure the objects are visible from the back of the classroom. If the items are used for role-play, make sure they are durable. If you are using pictures of famous people, make sure the students know who they are. \n\nPossible activities include \"Who is it?\" using pictures of TV characters, \"Whose is it?\" with parts of the body, show-and-tell with souvenirs, or role-playing activities where students use props to act out scenarios. The key is to select items that are interesting and a bit unusual. \n\nThis activity is useful for introducing new vocabulary or language structures, providing a visual aid, and encouraging active participation and is great for motivating students. \n\nSuitable grades range from upper elementary through junior high.\n\nMaterials needed are the realia objects. \n\nClassroom tips: Make sure to check the items for suitability and relevance to the students' interests, and ensure visibility for all students. Choose items that students would find interesting and that would naturally encourage language use. Remember to encourage the students to interact with the items.","content_type":"activity","name":"Using Realia","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["various objects (food items, blindfolds, pictures, stuffed toys, telephones, souvenirs, microphones, hats, glasses, clothes)"],"topic_tags":["vocabulary","speaking","visual aids","role-play"]},
  {"id":"scraped-altcir-handbook-drawing-dictation-pronunciation-382","text":"This activity combines listening comprehension and pronunciation practice. First, before students listen to a song, the teacher dictates a scene related to the song's topic, asking students to draw what they hear. For example, before playing \"I Left My Heart in San Francisco,\" the teacher might say, \"Draw a home. Draw a cable car.\" This part targets listening and can be used as a warm-up or a transition. After the initial drawing activity, the teacher introduces the song. Students listen to the song. Then, the teacher distributes the song's lyrics. For particularly tricky sections, IPA transcription can be included. Students then listen again, following along with the lyrics (and IPA if provided). Next, students read the song aloud. The teacher models the pronunciation, emphasizing the correct articulation. Students then try to match the teacher's pronunciation. This section focuses on pronunciation and receptive/expressive skills.","content_type":"activity","name":"Drawing Dictation & Pronunciation","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Lyrics to a song","Paper","Pencils/Crayons","IPA transcription (optional)"],"topic_tags":["songs","listening comprehension","pronunciation","drawing"]},
  {"id":"scraped-altcir-handbook-singing-review-383","text":"This activity utilizes songs to review vocabulary and reinforce language acquisition. Twice a week, dedicate a portion of class time to singing. Begin by selecting age-appropriate songs that incorporate target vocabulary. First, introduce the song and its meaning. Next, sing the song together, encouraging students to follow along. During the singing, emphasize pronunciation and intonation. After singing, you can play games related to the song's vocabulary, or have students create actions to accompany the song. This activity is effective for vocabulary recall, pronunciation practice, and fostering a positive classroom atmosphere. The songs can be used to revisit familiar vocabulary from previous lessons. For instance, after a unit on animals, a song incorporating animal names could be used to reinforce learning. Classroom Tip: vary the ways you use the song. Use it as a quick warm-up, or a more involved activity. Change the speed you sing, and vary the emphasis and the types of actions.","content_type":"activity","name":"Singing Review","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Vocabulary","Songs","Pronunciation"]},
  {"id":"scraped-altcir-handbook-singing-activities-384","text":"This activity aims to encourage students to sing and practice various listening comprehension skills using songs. The core principle is to create a safe and fun environment. Start by singing the song yourself, repeatedly if needed. Avoid criticism; instead, use a karaoke microphone or have students sing facing windows to reduce self-consciousness. \n\n**DRILL 1: Multiple Choice Lyrics:** Provide lyric alternatives (one correct). Students choose the correct option before or during listening.\n**DRILL 2: Lyric Identification:** Give grammatically correct and meaningful lyric alternatives. Students identify the lyric used in the song.\n**DRAW A PICTURE:** After or during listening, students draw a picture inspired by the song, then discuss it. Works well with instrumental music.\n**SONG SURVEY:** Students poll classmates to find favorite songs and compare preferences within the class and with other classes.\n**CATEGORIES:** In small groups, students brainstorm songs and categorize them. Groups compare their categorizations.\n**COUNT THE WORDS:** Students count how many times they hear a specific word.\n**PARTS OF SPEECH 1:** Students count instances of a word used as different parts of speech (noun, verb, etc.).\n**PARTS OF SPEECH 2: Cloze:** Use a cloze exercise focusing on a particular part of speech. Students predict or fill in the cloze while listening to the song.","content_type":"activity","name":"Singing Activities","activity_type":"Main Game","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Pairs","materials":["Song lyrics","Karaoke microphone (optional)","Paper","Crayons/Colored Pencils"],"topic_tags":["songs","listening","grammar","vocabulary"]},
  {"id":"scraped-altcir-handbook-bingo-song-385","text":"This activity focuses on listening and pronunciation. The teacher sings the Bingo song, which students likely already know. The teacher starts by singing the whole song. Then, the teacher sings it again, replacing the first letter of \"Bingo\" with a clap. The teacher continues, clapping two letters, then three, etc., until the song is all claps. Students sing along, focusing on the sounds they can hear. This activity targets listening comprehension and pronunciation, particularly of the sounds of individual letters. The activity is suitable for elementary school grades, especially those familiar with the song. No materials are needed, just the teacher's voice. A tip is to vary your tone and use gestures to make it more engaging.","content_type":"activity","name":"Bingo Song","activity_type":"Warm-up","skill":"Listening","duration_minutes":5,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["songs","pronunciation","listening comprehension"]},
  {"id":"scraped-altcir-handbook-head-shoulders-knees-and-toes-386","text":"This is a simple, whole-class activity to get students moving and listening. Start by singing the song \"Head, Shoulders, Knees, and Toes\" together, pointing to the corresponding body parts. Repeat the song several times. Then, instruct students to touch the body parts as you sing. Gradually remove body parts, replacing them with a hum. For example, the first time, you might hum the word \"head\" and students would no longer touch their heads. Continue until the students are humming the entire song. This activity targets listening comprehension and physical response. It's a great warm-up to energize the class. Materials needed are none. Classroom tip: Be enthusiastic and encourage the students to sing along and participate.","content_type":"activity","name":"Head, Shoulders, Knees, and Toes","activity_type":"Warm-up","skill":"Listening","duration_minutes":10,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["body","song","warm-up"]},
  {"id":"scraped-altcir-handbook-hokey-pokey-387","text":"This is a fun, active song-and-dance activity perfect for warming up the class and reviewing body parts. First, the teacher models the Hokey Pokey, using clear gestures and pronunciation. The teacher sings the first verse, substituting 'right hand' with other body parts like 'left hand,' 'right foot,' 'left foot,' 'head,' 'hip,' and 'whole body.' Students then join in, singing and doing the actions with the teacher. The song is repeated, and students can be encouraged to lead the class. This activity targets listening comprehension and speaking, specifically body part vocabulary and action verbs. It's suitable for elementary school students. Materials needed include nothing but the song's lyrics or, if desired, a visual aid with body part pictures. Classroom tip: keep the pace upbeat and encourage enthusiastic participation. For an additional challenge, students can create their own verses using new body parts or actions.","content_type":"activity","name":"Hokey Pokey","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["body parts","actions","music"]},
  {"id":"scraped-altcir-handbook-if-you-re-happy-388","text":"This is a simple, high-energy warm-up song activity based on the classic \"If You're Happy and You Know It.\" The teacher sings the first verse, \"If you're happy and you know it, clap your hands.\" The students then clap their hands. The teacher continues with the second verse, \"If you're happy and you know it, stomp your feet,\" and the students stomp their feet. Next is \"shout 'hooray'\" and finally \"do all three\". The teacher can introduce additional verses using different actions and emotions, such as \"Hungry-Rub your tummy,\" \"Sad-Cry Boo-hoo,\" \"Scared-Run and hide,\" \"Tired-Go to bed,\" \"Hot-Wipe your head,\" and \"Silly-Run around.\" This activity targets listening comprehension and speaking as students respond to instructions. It is suitable for elementary and lower junior high school students. No materials are needed, just the lyrics. A classroom tip is to sing with exaggerated motions and facial expressions to make it more engaging.  Encourage the students to sing along and participate actively to keep the class energized.","content_type":"activity","name":"If You're Happy","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Emotions","Actions","Songs"]},
  {"id":"scraped-altcir-handbook-old-macdonald-389","text":"This is a fun, repetitive song activity that reinforces animal vocabulary and sound production. \n\n1.  Introduce the song: 'Old MacDonald Had a Farm.' Sing the first verse with the class, emphasizing the rhythm and the animal sound.\n2.  Model the replacement: Explain that you will change the animal and its sound each time. For example, instead of a cow, you might sing about a cat ('meow, meow').\n3.  Class Participation:  Choose an animal (e.g., dog) and its sound (e.g., 'bow wow'). Sing the verse together, replacing 'cow' with 'dog' and 'moo' with 'bow wow.'\n4.  Student Contributions: Invite students to suggest animals and sounds.  Write the words on the board as they contribute. Encourage actions for each animal.  \n5.  Sing through the song again, changing animals and sounds.\n\nThis activity targets listening and speaking skills. It is perfect as a warm-up or a filler activity. Minimal materials are needed - just the lyrics written on the board or a printed copy.\n\nClassroom Tip: Vary the pace; go fast for more fun, or slower for greater understanding. This activity is effective for lower grades where repetition is key.","content_type":"activity","name":"Old MacDonald","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Whiteboard or Paper","Markers or Pens"],"topic_tags":["Animals","Songs","Vocabulary"]},
  {"id":"scraped-altcir-handbook-row-row-row-your-boat-390","text":"This activity utilizes the classic English nursery rhyme \"Row, Row, Row Your Boat\" to practice pronunciation and intonation. The teacher leads the class in singing the song together. Start by singing the song slowly, emphasizing each word. Then, gradually increase the tempo. Encourage students to sing loudly and clearly. For younger learners, you can add actions like rowing a boat. This activity targets listening and speaking skills, focusing on pronunciation and rhythm. It's suitable for elementary school students. Materials needed: none. Classroom tip: Make it fun by varying your tone of voice and encouraging enthusiastic participation.","content_type":"activity","name":"Row, Row, Row Your Boat","activity_type":"Warm-up","skill":"Speaking","duration_minutes":5,"min_grade_numeric":3,"max_grade_numeric":6,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["songs","pronunciation","rhymes"]},
  {"id":"scraped-altcir-handbook-sukiyaki-song-comparison-391","text":"This activity explores the cultural exchange of music. Begin by playing the Japanese song \"Ue o muite aruko\" (Sukiyaki) and gauging student familiarity and enjoyment. Briefly introduce Kyu Sakamoto, the singer. Then, reveal that there's an English version called \"Sukiyaki\" that was popular in the US. Play both songs for the students once. Distribute a handout containing the lyrics and have students listen again, focusing on the words and comparing the two versions. This activity targets listening comprehension and cultural awareness. Materials needed include the two songs (MP3 or streaming access) and a printed handout with the lyrics. Classroom tip: Encourage discussion about the similarities and differences between the two versions, and the singer's tragic story to engage students.","content_type":"activity","name":"Sukiyaki Song Comparison","activity_type":"Review","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Audio recordings of \"Ue o muite aruko\" and \"Sukiyaki\"","Lyrics handout"],"topic_tags":["Music","Culture","Listening"]},
  {"id":"scraped-altcir-handbook-self-introduction-quiz-392","text":"This activity uses a quiz format to introduce the ALT to the students. Prepare a multiple-choice quiz with questions about yourself, your job, your country, and the day's theme. Include basic self-introduction information like name and origin. Incorporate questions about your country, and include general questions to introduce the day's theme. For the multiple-choice options, include incorrect choices that are actual facts about other countries, including Japan. The quiz can be handed out as students enter the classroom. After students complete the quiz, review the answers as a whole class, providing correct answers and elaborating on each topic. This activity targets listening comprehension and reading skills, and also encourages speaking as students share answers.","content_type":"activity","name":"Self-Introduction Quiz","activity_type":"Warm-up","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Prepared quiz sheets","Pens/Pencils"],"topic_tags":["Introduction","Culture","Quiz"]},
  {"id":"scraped-altcir-handbook-matching-pairs-393","text":"This activity focuses on pair work to promote communication and matching skills. Divide the class into pairs using different methods. For 'Matching Halves,' prepare a set of items split in half, such as proverbs translated into Japanese and English, map pieces, or related words/concepts. Distribute one half of each item to each student. Students mingle and find their match by communicating and comparing their halves. Alternatively, use 'String Pairing,' which involves giving each student the end of a string. Students find their partners by following the string to its other end. This activity targets speaking and listening skills, encourages communication and collaboration. Suitable for 5th to 7th grade, it requires prepared materials like split items (proverbs, maps, etc.) or string. Classroom tips: clarify instructions, provide sentence frames for communication, and monitor pairs for correct matching.","content_type":"activity","name":"Matching Pairs","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Prepared matching halves (proverbs, map pieces, etc.)","String (for string pairing)"],"topic_tags":["Pair work","Communication","Matching"]},
  {"id":"scraped-altcir-handbook-animal-groups-394","text":"This activity helps students practice non-verbal communication and forming groups. Distribute cards, each with the name of an animal (e.g., dog, cat, bird, elephant). Students silently imitate their animal's sound and movement to find others with the same animal. Once they believe they've found their group, they can sit or stand together. The teacher can then ask each group to identify their animal. This activity targets listening comprehension and non-verbal communication. Suitable for elementary and lower junior high grades. Materials needed: Animal name cards. Classroom tips: Emphasize the rule of no talking and the importance of only using sounds and actions to find their groups. Prepare a variety of animals to create varied group sizes.","content_type":"activity","name":"Animal Groups","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Groups","materials":["Animal name cards"],"topic_tags":["Animals","Communication","Grouping"]},
  {"id":"scraped-altcir-handbook-name-badge-recall-395","text":"This activity aims to improve memory and listening skills while reinforcing self-introduction. \n\n1.  **Initial Self-Introductions:** Students begin by participating in a standard self-introduction activity. They share their names and some basic information. This step sets the context.\n2.  **Name Badge Challenge:** After the introductions, students cover their name badges. \n3.  **Recall and Review:** Students try to recall as much information as possible about their classmates. The teacher can then prompt them to repeat their own introduction and other introductions from earlier.\n4.  **Throw and Catch - Name Game**: Students are divided into groups with a ball, and must say their own name as they throw to someone else.  Later, they say the name of the person they are throwing to.\n5.  **Snowball Introduction**: The first student states their name and a piece of personal information. The next student repeats the first student's name and information, then adds their own. This continues around the circle. Repeat the information after the first round.\n\nThis activity targets listening comprehension and speaking, memory, and helps solidify social interaction skills. \n\n**Classroom Tips:** Encourage active listening during self-introductions. Monitor the recall/repeat steps to ensure understanding. Break into small groups for the snowball activity. \n\nSuitable for Grades 5-7.","content_type":"activity","name":"Name Badge Recall","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["ball (optional)"],"topic_tags":["Introductions","Names","Memory"]},
  {"id":"scraped-altcir-handbook-potato-introductions-396","text":"This activity encourages students to practice speaking and listening while exploring the concept of individuality. First, provide each student with a potato from a box (ensure there's at least one potato per student). In pairs, students examine their potato, imagining its background and history (e.g., origin, journey, future). They then share their potato's “story” with their partner and why they chose it. Next, collect all the potatoes, mix them up, and have the students try to find their original potato. This leads into a discussion about individuality, how people are unique, and the challenges of stereotyping. The activity targets speaking and listening skills, suitable for grades 5-7. Materials needed: A box of potatoes (one per student). Classroom tip: Encourage imaginative storytelling about the potatoes.","content_type":"activity","name":"Potato Introductions","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Potatoes","Box"],"topic_tags":["Individuality","Speaking","Describing"]},
  {"id":"scraped-altcir-handbook-hidden-agenda-bingo-397","text":"This activity works best after self-introduction warm-up games. Distribute bingo sheets with introduction prompts. Explain the game. Secretly give some students slips with hidden instructions, e.g., to interrupt, stand very close, or other unusual behaviors. Play the game as normal bingo. After the game, ask students how they felt about the unexpected behaviors. This prompts discussion about cultural differences, what is considered rude in different cultures, and the challenges of unexpected behavior.","content_type":"activity","name":"Hidden Agenda Bingo","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Bingo sheets","Secret instruction slips"],"topic_tags":["Cultural awareness","Behavior","Speaking"]},
  {"id":"scraped-altcir-handbook-proverb-karuta-398","text":"Divide students into small groups and provide each group with a set of proverb cards. Each card contains half of a proverb, with the first halves in one color and the second halves in another. The goal is to match the halves to form complete proverbs. Initially, groups have time to discuss and match the halves. Next, play karuta with only the second halves visible. The teacher (or a student) reads the first half of a proverb, and students race to find the matching second half. The first student to correctly identify the match keeps the pair. Continue until all proverbs are matched. The student with the most cards at the end wins.\n\nAfter the game, facilitate a discussion about the proverbs' meanings, the cultural values they represent, and comparisons to Japanese proverbs. Consider which values are shared or different, and explore any corresponding Japanese sayings.\n\nThis activity targets speaking and listening skills, vocabulary development, and cultural awareness.","content_type":"activity","name":"Proverb Karuta","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Proverb cards (halves of proverbs)"],"topic_tags":["Proverbs","Culture","Speaking"]},
  {"id":"scraped-altcir-handbook-alts-online-worksheet-399","text":"This activity utilizes the ALTs Online website (http://alts-online.wikispaces.com/japan) where students explore self-introduction pages created by ALTs. Students are given a worksheet to complete, gathering information about the ALTs' backgrounds, countries, and experiences. The website provides authentic English materials and encourages interaction with native speakers. \n\n**How to run the activity:**\n1.  Introduce the website and the worksheet to the students.\n2.  Students individually or in pairs browse the website, visiting different ALT self-introduction pages.\n3.  As they explore, students fill in the worksheet with information from the pages (e.g., country of origin, hobbies, favorite foods, travel experiences).\n4.  The ALT checks the worksheets for accuracy and provides feedback.\n\n**Language Skills Targeted:** Reading comprehension (extracting information from text), Listening comprehension (if videos or audio are included), and potentially writing (if the worksheet requires sentence completion or short answers).\n\n**Suitable Grade Levels:** Primarily designed for junior high students, but could be adapted for upper elementary.\n\n**Materials Needed:** Computers or tablets with internet access, the ALTs Online website, student worksheets.\n\n**Classroom Tips:**\n*   Pre-teach relevant vocabulary or question words.\n*   Provide a model worksheet or example for students.\n*   Encourage students to take notes while browsing.\n*   If time permits, have students share what they learned about their favorite ALT.","content_type":"activity","name":"ALTs Online Worksheet","activity_type":"Main Game","skill":"Reading","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Individual","materials":["Computers/Tablets","Internet Access","Student Worksheets"],"topic_tags":["Culture","Internet","Self-introduction"]},
  {"id":"scraped-altcir-handbook-classroom-commands-400","text":"This activity teaches and reinforces basic classroom commands. The teacher starts by explaining a command, such as 'Stand up!' or 'Open your book!' and demonstrating the action. The students then repeat the command and do the action. Gradually, the teacher only says the command and students respond with the action. To make it more fun, the teacher can add actions and instructions together. For example, 'Stand up and clap your hands!' or 'Open your book and look at page 10!' This activity targets listening comprehension and speaking, and can be adapted to suit all age levels. It’s easily modified by using Japanese commands when students have difficulty understanding. Materials needed are nothing other than the teacher's voice and possibly a textbook. Classroom tip: use actions to make the activity more engaging and break up the monotony. Introduce new commands gradually to avoid overwhelming students.","content_type":"activity","name":"Classroom Commands","activity_type":"Warm-up","skill":"Listening","duration_minutes":15,"min_grade_numeric":3,"max_grade_numeric":9,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["Classroom Commands","Instructions","Actions"]},
  {"id":"scraped-altcir-handbook-one-shot-buddies-401","text":"This activity introduces students to sharing information about their daily lives with an 'e-pal' in a low-pressure, one-off format. First, introduce the concept: a person or group wants to know about your students' lives! Students then create a short note, card, letter, or drawing to share. The content should focus on everyday experiences. This could include descriptions of hobbies, favorite foods, family, or anything else they'd like to share. Encourage simple language and focus on the message. Suitable for grade 5-7. Students can work individually or in pairs to brainstorm ideas. Once completed, have students share their 'messages' with each other or display them around the classroom. Focus on encouraging them to be proud of what they have shared. Materials needed: paper, pens/pencils, and potentially art supplies (crayons, markers). Classroom tip: Keep it short and sweet, and focus on simple language to ensure accessibility for all students.","content_type":"activity","name":"One-Shot Buddies","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Individual","materials":["paper","pens/pencils","art supplies (optional)"],"topic_tags":["daily life","writing","sharing"]},
  {"id":"scraped-altcir-handbook-pen-pal-project-402","text":"This activity focuses on creating and sending messages to a pen pal, fostering communication and cultural awareness. \n\n**How it works:** \n1.  **Preparation:** Identify potential pen pals (friends, contacts, or even professors overseas). Prepare pre-cut paper and envelopes. For lower grades (1-4), provide pre-written messages or greetings for copying. For grades 5-6, have students copy a message. Junior high students write their own messages. \n2.  **Execution:** Students create cards or letters. Younger students can draw pictures. Guide students in writing their messages in English (or simple phrases). Collect the cards and address them to the pen pal. \n3.  **Follow-up:** When the pen pal replies, share the response with the class, highlighting any personal messages to individual students. Consider having older students research the pen pal's country. \n\n**Language Skills:** Writing, Reading (of the reply), Cultural Awareness\n\n**Suitable Grades:** 5-9\n\n**Materials:** Stock paper, envelopes, pens/pencils, (optional) pre-written messages, contact information for pen pal.\n\n**Classroom Tips:**\n*   Match pen pals with similar interests or commonalities to make the connection more meaningful.\n*   Emphasize the importance of clear communication.\n*   Use the activity as a starting point for discussions about different cultures and careers.","content_type":"activity","name":"Pen Pal Project","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Individual","materials":["paper","envelopes","pens/pencils"],"topic_tags":["culture","writing","communication"]},
  {"id":"scraped-altcir-handbook-class-survey-my-favorite-things-403","text":"This activity aims to practice speaking and listening skills while building rapport within the class. First, prepare a simple survey sheet with questions like: 'What's your favorite food?', 'What's your favorite color?', and 'What's your favorite sport?'. The number of questions should be manageable, about 5-7 questions. Distribute the survey sheets to the students. Model the activity by interviewing the JTE or a student, demonstrating how to ask and answer the questions. Then, have students mingle and interview their classmates. They should write down their classmates' answers on the survey sheet. After a set time (e.g., 5-7 minutes), bring the class back together. Students take turns reporting what they learned about their classmates, such as, 'Tomoko's favorite food is ramen!' This activity can also be modified by having students find someone with a specific favorite thing, then writing the name on the board or making a simple class graph. Use simple and clear language. Monitor and correct pronunciation as necessary, but focus on communication. Keep it light and fun!","content_type":"activity","name":"Class Survey: 'My Favorite Things'","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":1,"interaction":"Pairs","materials":["Survey sheets","Pencils"],"topic_tags":["Favorites","Interviewing","Speaking practice"]},
  {"id":"scraped-altcir-handbook-supply-share-404","text":"This activity encourages students to consider global disparities in access to education and promote environmental awareness. First, introduce the concept of school supplies and ask students to list common items in English (e.g., pencils, notebooks, erasers). Then, explain that not all children have access to these necessities. Show pictures or videos depicting students in other countries with limited resources. Next, divide students into pairs or small groups. Each group brainstorms a list of 3-5 essential school supplies. Afterward, have them discuss the idea of 'sharing' their extra supplies, perhaps by recycling used items or donating unused ones. Encourage discussions about waste reduction. Finally, have each group share their ideas with the whole class, emphasizing the importance of resourcefulness and empathy. This activity targets vocabulary related to school supplies and basic English speaking skills. Adapt the language to the appropriate grade level. For materials, bring pictures of school supplies and resource-limited students. Classroom tip: pre-teach key vocabulary, and model the brainstorming process.","content_type":"activity","name":"Supply Share","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Pictures of school supplies","Pictures of students with limited supplies"],"topic_tags":["Culture","Environment","Vocabulary"]},
  {"id":"scraped-altcir-handbook-classroom-compare-405","text":"This activity uses photographs to compare and contrast a classroom in Papua New Guinea with the students' own classroom. First, show students enlarged pictures of a classroom in Papua New Guinea. Explain you visited this school and took the photos. Then, as a whole class, brainstorm a list of differences between the PNG classroom and their own classroom. Encourage students to use descriptive language. Discuss aspects like electricity, desks, windows, shelves, books, school supplies, cafeteria, library, and gym. The focus is on comparing physical attributes and using descriptive vocabulary. Encourage teachers to participate too. This activity targets listening and speaking skills, as well as descriptive vocabulary. It's a great way to introduce a lesson on other cultures or comparing/contrasting.","content_type":"activity","name":"Classroom Compare","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":["Pictures of a classroom in Papua New Guinea","Whiteboard or paper"],"topic_tags":["Culture","Comparison","Vocabulary"]},
  {"id":"scraped-altcir-handbook-2000-yen-question-406","text":"This activity begins with a brainstorming session. As a whole class, ask students to list everything they can buy with 2000 Yen. Encourage diverse answers, from snacks and entertainment to small gifts and stationery. Once a comprehensive list is compiled, introduce the contrast: explain that 2000 Yen can fund a year of education for a student in Papua New Guinea (PNG). Highlight the disparity by sharing the statistic that over 25% of PNG students cannot afford school. Further emphasize the global education challenge by stating that less than 2% of PNG students who start first grade graduate high school. The activity aims to foster awareness of global economic inequalities and the value of education, linking everyday spending to a broader context. It targets listening and critical thinking skills. It can be adapted to other currencies for local relevance. A whiteboard or projector is needed to list student responses.","content_type":"activity","name":"2000 Yen Question","activity_type":"Production","skill":"Listening","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard or projector","Markers or pens"],"topic_tags":["Culture","Economics","Critical Thinking","Global Issues"]},
  {"id":"scraped-altcir-handbook-pencil-case-count-407","text":"This activity encourages students to practice counting and comparing quantities. Start by having students count the total number of pens, pencils, and any other writing instruments in their pencil cases. Next, introduce the comparison. Explain that the students with a high number of items have more than a whole class in a developing country. This prompts a quick discussion about resources. Target language skills: Numbers, quantity vocabulary, and comparative adjectives (more/less). Suitable for grades 5-7. No special materials are needed; the students' pencil cases are the main resource. Classroom tip: Write a few example numbers on the board to guide students as they count. You can also vary the comparison (e.g., 'more than the teacher's collection').","content_type":"activity","name":"Pencil Case Count","activity_type":"Warm-up","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Whole class","materials":[],"topic_tags":["counting","comparison","numbers"]},
  {"id":"scraped-altcir-handbook-byoc-chopstick-awareness-408","text":"This activity aims to raise awareness about deforestation and waste. Begin by explaining the issue of disposable chopsticks (waribashi) and their impact on rain forests, using Papua New Guinea as a specific example.  Engage students to count how often they use wooden chopsticks in a month. Have students report their findings to the class.  Present the collected data in an understandable way, such as comparing the number of chopsticks to building a house or circling the school. Encourage students to start bringing their own chopsticks to reduce deforestation and waste. This activity focuses on critical thinking and understanding the environmental impact of everyday choices. It encourages students to consider sustainable practices.  \n\nLanguage skills targeted: Listening (comprehension of the initial explanation and classmates' reports), Speaking (reporting the findings, participation in discussion). Suitable for grades 5-7.  \n\nMaterials: Whiteboard or projector, markers or pens to write down the data.  \n\nClassroom Tips: Keep the presentation concise and the comparisons simple for students to grasp. Encourage participation with praise, not criticism. Emphasize the positive impact of using reusable chopsticks.","content_type":"activity","name":"BYOC - Chopstick Awareness","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard/Projector","Markers/Pens"],"topic_tags":["Environment","Sustainability","Speaking"]},
  {"id":"scraped-altcir-handbook-school-introduction-409","text":"Divide the class into groups and assign each group to focus on one or two aspects of a Japanese school to explain.  Students will draw pictures and write simple English descriptions of their school for students in Papua New Guinea (or another location chosen by the ALT). The aim is to introduce aspects of Japanese school life to those unfamiliar with Japan. The activity targets basic descriptive writing and speaking skills while promoting cross-cultural understanding.  This activity is ideal for fostering empathy and practicing descriptive English. \n\nMaterials needed are paper, pencils, colored pencils/markers. Encourage creativity in the illustrations.  Classroom tip: Encourage students to use simple English and focus on clarity. Circulate and assist with vocabulary as needed.","content_type":"activity","name":"School Introduction","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Paper","Pencils","Colored pencils/markers"],"topic_tags":["School","Culture","Writing"]},
  {"id":"scraped-altcir-handbook-pen-pal-exchange-410","text":"This activity involves a pen pal exchange with students in an American junior high school. Students are assigned a specific pen pal to personalize the interaction. Students write rough drafts of letters in their notebooks. The ALT and JTE check the drafts, correcting only essential misunderstandings to prioritize communication. The letters are mailed, and students collect Japanese cultural items (manga, toys, etc.) to include in a \"culture box\" sent to their pen pals. Upon receiving replies (about a month and a half later), the class translates the letters and writes new responses using the same rough draft approach. The process repeats, ideally resulting in multiple exchanges before the end of the year. The teacher also helps to distribute any items received from the US pen pals. This activity targets both writing and reading comprehension. It's designed to promote intercultural exchange. \n\nSuitable Grade Levels: 5-7. \n\nMaterials needed: Notebooks, pens/pencils, items for cultural boxes, letters from American students (returned), American cultural box (returned).\n\nClassroom tips: Encourage students to personalize their letters and be patient with the wait time for replies. Focus on communication over perfect grammar. This is an excellent activity to use after establishing an email exchange and learning about various cultures.","content_type":"activity","name":"Pen Pal Exchange","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["Notebooks","Pens/Pencils","Japanese cultural items (manga, toys, etc.)","Letters from American Students","American cultural box"],"topic_tags":["Culture","Writing","Communication","Exchange"]},
  {"id":"scraped-altcir-handbook-culture-comparison-411","text":"This activity aims to broaden students' understanding of different cultures, moving beyond the simplistic view of 'foreign = American' prevalent in Okinawa. The activity focuses on comparing and contrasting Okinawan culture with Western cultures, and also explores differences among Western countries themselves. \n\n1.  **Preparation**: Before the lesson, gather images or short videos representing various aspects of Okinawan and Western cultures (food, clothing, festivals, customs, etc.). Select a few Western countries to compare.\n2.  **Introduction (Whole Class)**: Start by asking students what they know about the selected countries. Write their initial ideas on the board (in Japanese or English, as appropriate).\n3.  **Presentation (Whole Class)**: Show images/videos, and briefly describe each culture. Use simple English and visuals. Encourage students to listen to the new vocabulary and compare them to Okinawan culture.\n4.  **Pair/Small Group Discussion**: Divide students into pairs or small groups. Provide them with a simple worksheet with comparison prompts, such as: 'What do people eat?', 'What do they wear?', 'What festivals do they have?'.\n5.  **Pair/Group Report (Whole Class)**: Each pair/group shares their findings with the class. Encourage them to use simple English phrases (e.g., 'In Okinawa, they eat... But in America, they eat...').\n6.  **Wrap-up (Whole Class)**: Summarize key differences and similarities. Ask students what they found interesting or surprising. Reiterate the use of English as a means of communication.\n\nThis activity targets listening, speaking, and basic cultural awareness. Adapt the complexity of vocabulary and the depth of the comparison based on the grade level. Use simple and direct English. Provide visual aids to supplement language and encourage engagement.","content_type":"activity","name":"Culture Comparison","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Images","Videos","Worksheet"],"topic_tags":["Culture","Comparison","Speaking"]},
  {"id":"scraped-altcir-handbook-email-exchange-project-412","text":"This activity involves a 90-minute (split into two class periods) integrated learning project. In the first period, students email junior high school students in different locations (e.g., Texas, Hawaii, Montreal, Quebec). Students are encouraged to write about specific topics such as self-introductions, school life, and celebrations. They can exchange cards and videos. In the second period, students learn more about the locations mentioned in the emails and reflect on the information they have received. The activity includes a lesson where students write down their stereotypes about Canada, followed by a discussion with a Canadian ALT about the validity of those stereotypes. Teachers can also show photos and discuss world issues. This promotes cross-cultural understanding and language practice through writing and speaking.","content_type":"activity","name":"Email Exchange Project","activity_type":"Main Game","skill":"Mixed","duration_minutes":90,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":3,"interaction":"Pairs","materials":["Computers with internet access","Email accounts","Stationery for card exchange","Photos or videos of locations and issues"],"topic_tags":["Culture","Emailing","Writing","Speaking"]},
  {"id":"scraped-altcir-handbook-passport-exchange-413","text":"This activity involves creating and exchanging \"passport\" booklets between students in Japan and a school in the UK. The Japanese students create a booklet containing information about themselves, such as a local map, favorite food, favorite sport, and a self-portrait. This booklet is then shared with a school in the UK, fostering cultural exchange and understanding. The activity aims to improve cultural awareness and build connections between students. Materials needed include paper, pens/pencils, and potentially a camera or access to photos for the booklets. Classroom tips: Encourage students to be creative and include personal details. Focus on clear and concise language. This activity helps students learn about different cultures, promoting curiosity and understanding. This project has the potential for on-going pen pal exchanges.","content_type":"activity","name":"Passport Exchange","activity_type":"Main Game","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Paper","Pens/Pencils","Camera/Photos (Optional)"],"topic_tags":["Culture","Pen Pals","Writing"]},
  {"id":"scraped-altcir-handbook-image-exploration-414","text":"This activity aims to promote cultural understanding and English language skills through a discussion of image and personal presentation. First, the ALT should share some personal experiences about how their appearance is perceived by the students. Then, the teacher can guide a discussion about the students' own perceptions of image, using questions like: \"What do you think of when you see someone wearing...?\" \"What do you like to wear?\" \"What do your friends wear?\" The ALT can introduce vocabulary related to clothing, hairstyles, and fashion trends. The activity targets speaking and listening skills, encouraging students to express their opinions and understand different viewpoints.  It's suitable for grades 5-7. Materials needed are a whiteboard or projector to write key vocabulary and questions. Classroom tip: Encourage students to be respectful of diverse opinions and avoid judgmental language.  Consider showing pictures or short video clips of fashion trends in Japan or other countries to stimulate discussion.","content_type":"activity","name":"Image Exploration","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Whiteboard or projector","Markers or pens"],"topic_tags":["Culture","Speaking","Fashion","Discussion"]},
  {"id":"scraped-altcir-handbook-image-opinions-collage-415","text":"This activity encourages students to express opinions and practice writing simple sentences. First, show students images from African-American magazines, and ask for their opinions about the people in the pictures. Then, transition to images of Japanese people and elicit opinions again. Next, students will create collages from Japanese magazines, cutting out images they find appealing. Finally, they write short sentences explaining why they like the chosen images. This activity targets speaking and writing skills, allowing students to practice descriptive language and opinion giving. It is suitable for elementary to junior high school students. Materials needed are African-American magazines, Japanese magazines, scissors, glue, and paper. Classroom tip: Encourage students to be respectful of diverse opinions. Provide sentence starters like 'I like... because...' or 'I think...'.","content_type":"activity","name":"Image Opinions & Collage","activity_type":"Production","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Pairs","materials":["African-American magazines","Japanese magazines","scissors","glue","paper"],"topic_tags":["culture","opinions","writing"]},
  {"id":"scraped-altcir-handbook-image-opinion-posters-416","text":"This activity involves students creating posters based on images from magazines, fostering discussion and writing about cultural trends and personal opinions.\n\nFirst, define the word \"image\" and brainstorm a list of popular trends/activities for young people in Japan. Next, the teacher shows images from magazines, discussing trends in another culture (e.g., African-American). Compare the lists, noting similarities and differences, then prompt students to express opinions about the images, modeling your own. In the following class, students gather photos/images and paste them onto poster board, writing short sentences explaining their preferences. The teacher provides grammar and spelling support.\n\nThis targets speaking and writing skills, encouraging vocabulary use, opinion expression, and basic sentence construction. It also promotes cultural awareness and comparison.\n\nSuitable for Grades 5-7. Requires magazines (teacher and student-provided), dictionaries, poster board, glue, and scissors.\n\nClassroom Tips: Allow multiple sessions for completion to give students time to become comfortable with the vocabulary and express themselves freely. Focus on positive feedback to encourage participation.","content_type":"activity","name":"Image & Opinion Posters","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Magazines (various types)","Dictionaries","Poster board","Glue","Scissors"],"topic_tags":["Culture","Opinions","Writing","Vocabulary"]},
  {"id":"scraped-altcir-handbook-classroom-scavenger-hunt-417","text":"This activity aims to get 7th graders using known grammatical patterns in a practical way. First, prepare a set of clues related to objects in the classroom. Each clue should use target language such as \"It's on the...\" or \"It's next to the...\". The clues should be simple enough for the students to understand. Divide the class into groups of 4-5 students. Give each group a starting clue. Students read the clue, find the object, and then write down the next clue hidden near it. They continue solving clues until they find the final object. This activity targets listening and reading comprehension, and production (speaking/writing) skills as students discuss the clues and report their answers. Teachers can move around the room to help and assess the use of target language. Materials needed include pre-written clues and pens/pencils. Ensure the clues are at an appropriate level for the students. This will motivate them and help them build confidence.","content_type":"activity","name":"Classroom Scavenger Hunt","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Clue Sheets","Pens/Pencils"],"topic_tags":["Classroom","Instructions","Grammar"]},
  {"id":"scraped-altcir-handbook-classroom-news-commercials-418","text":"Divide the class into groups of six students. Give each group a picture from a magazine or a set of pictures on a specific topic. The groups work together to create either a news story or a commercial related to the picture(s). Each student in the group must write at least one line of dialogue for the story/commercial. After writing, the groups practice their scripts and then film their presentations using a phone or tablet. The ALT can act as the anchor person. Edit the videos together, adding music and effects if desired, to create a final program. This activity targets speaking and writing skills. It encourages collaborative storytelling and provides opportunities for creative expression. For younger students, the scripts can be simplified. Encourage students to use target vocabulary and grammar structures. The final videos can be shared with other classes or used as a review tool.","content_type":"activity","name":"Classroom News/Commercials","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Magazine pictures","Paper and pens","Phone or tablet for filming","Editing software (optional)"],"topic_tags":["News","Commercials","Storytelling","Video production"]},
  {"id":"scraped-altcir-handbook-extracurricular-activities-skit-419","text":"This activity involves students creating and performing skits related to extracurricular activities. Initially, students plan their stories in Japanese, focusing on interesting but complex ideas. The JTE and ALT review drafts, simplifying the language to match the students' English proficiency. Students create flashcards for new vocabulary. The implementation phase involves filming the skits, which students often enjoy. Editing can be done using a video camera and VCRs, with Powerpoint used for visual elements and transitions. The goal is to allow students to see and hear themselves using English. This activity targets speaking and listening skills, allowing for repeated practice. The videos can be reused for listening comprehension practice later. Variations include writing a drama instead of a news program, or conducting interviews about school activities.","content_type":"activity","name":"Extracurricular Activities Skit","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Video camera","VCRs","Flashcards","Powerpoint"],"topic_tags":["Speaking","Performance","Production","Video"]},
  {"id":"scraped-altcir-handbook-classroom-compliments-420","text":"This activity aims to boost student confidence and provide positive reinforcement. Begin by having students write their names on a piece of paper. Collect the papers and redistribute them randomly, ensuring each student receives a paper that is not their own. Students then write a compliment on the paper they receive, focusing on something positive about the person whose name is on it, for example, 'You are good at drawing.' or 'You always try your best.' The compliment should be written in English. After a few minutes, have students pass the papers to the next student. This continues for a set time or until each student's paper has been written on by several classmates. Finally, give the papers back to the original owners. This targets writing skills through short sentence creation and encourages positive speaking skills through encouragement. Suitable for grades 5-7. No materials are needed beyond paper and pencils/pens. Classroom tip: pre-teach simple compliment phrases like 'You are good at...' or 'You have a nice...' to provide scaffolding.","content_type":"activity","name":"Classroom Compliments","activity_type":"Warm-up","skill":"Writing","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":1,"interaction":"Pairs","materials":["Paper","Pens/Pencils"],"topic_tags":["Classroom Management","Positive Reinforcement","Writing"]},
  {"id":"scraped-altcir-handbook-skits-421","text":"This activity helps students practice speaking and build confidence. Students are given short skit scripts (e.g., ordering food, asking for directions) that use simple vocabulary and grammar learned in the first year of junior high. The skits should last between 5-10 minutes. Students work individually or in pairs/small groups to memorize their lines and rehearse. Encourage students to personalize the scripts, add actions, props, costumes, and overact to make the skits more engaging. The activity reinforces fluency and pronunciation while building confidence in speaking. It can be adapted to various themes and language points.\n\nInstructions:\n1.  Introduce the activity and explain the goal of the skits.\n2.  Distribute the scripts and explain any difficult vocabulary.\n3.  Allow students time to read and practice their roles.\n4.  Encourage students to add their own ideas and props.\n5.  Each group/individual performs their skit in front of the class.\n6.  Provide positive feedback and praise their efforts.","content_type":"activity","name":"Skits","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Skit scripts","Props (optional)","Costumes (optional)"],"topic_tags":["role-play","speaking","fluency"]},
  {"id":"scraped-altcir-handbook-miyagi-skit-koshien-422","text":"This is a whole-class, extracurricular activity involving students creating skits. The activity begins with students working together to write and rehearse short skits in English. The ALT takes a hands-off approach, guiding students with English usage and encouraging participation. After the skits are performed, the ALT helps the students film their skits. Then the students receive a copy of the movie. Afterward, students can participate in listening quizzes or awards. Finally, students write a brief report on their role. This activity targets speaking, writing, and listening skills. It is suitable for 7th-9th grade students. Materials include scripts, filming equipment, and writing materials. Classroom tips: Encourage collaboration and provide support, particularly with English usage. Ensure all students have a role and participate.","content_type":"activity","name":"Miyagi Skit Koshien","activity_type":"Production","skill":"Mixed","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Scripts","Filming Equipment","Writing Materials"],"topic_tags":["Extracurricular","Performance"]},
  {"id":"scraped-altcir-handbook-classroom-question-race-423","text":"This activity is a fast-paced question-and-answer game to review previously learned vocabulary or grammar. Divide the class into teams. Write vocabulary words or grammar points on the board. One student from each team comes to the board. The ALT or a student leader calls out a definition, prompts a question, or provides a sentence stem related to the target language. The students race to write the correct word or complete the sentence on the board. The first student to correctly answer earns a point for their team. Rotate students frequently to ensure everyone gets a chance. This game targets speaking and writing skills, reinforcing vocabulary and sentence construction. It's adaptable for various grade levels by adjusting the complexity of the questions. Materials needed include a whiteboard or blackboard, markers or chalk, and a list of target vocabulary or grammar. For younger learners, use pictures instead of written words. Vary the questions to keep students engaged. Encourage teamwork and provide positive reinforcement for effort.","content_type":"activity","name":"Classroom Question Race","activity_type":"Review","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":2,"interaction":"Groups","materials":["Whiteboard or Blackboard","Markers or Chalk","Vocabulary/Grammar List"],"topic_tags":["Vocabulary","Grammar","Review Games"]},
  {"id":"scraped-altcir-handbook-pantomime-production-424","text":"This activity involves students creating and performing a short English pantomime. \n\n1.  **Preparation:** The teacher selects a simple story appropriate for the grade level (e.g., a fairy tale like 'Goldilocks and the Three Bears' or a simple modern story).  \n2.  **Script Development:**  Students, in groups, collaboratively write a very simple script, focusing on key dialogue and actions. Encourage students to use high-frequency vocabulary and simple sentence structures.  \n3.  **Rehearsal:** Groups practice their scenes, focusing on clear pronunciation, exaggerated expressions, and physical comedy.  The teacher can offer guidance on pronunciation and intonation. \n4.  **Performance:** Each group performs their scene for the class. Encourage audience participation (e.g., shouting out phrases, cheering). \n\nThis activity targets speaking and listening skills. Students practice pronunciation, vocabulary, and sentence construction while developing their confidence and creativity. This also promotes teamwork and public speaking skills. \n\nMaterials needed: Paper, pens/pencils, simple props (optional), and the script. Classroom tip: Start with a familiar story to build confidence. Encourage the use of gestures and facial expressions.  Keep the language simple, and focus on the fun.","content_type":"activity","name":"Pantomime Production","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Paper","Pens/Pencils","Simple props (optional)"],"topic_tags":["Drama","Storytelling","Performance"]},
  {"id":"scraped-altcir-handbook-cinderella-pantomime-425","text":"This activity involves performing a simplified version of the Cinderella story as a pantomime. The story is divided into three acts, with short summaries in Japanese between acts to help students understand the plot. The pantomime requires a team of approximately 15 people for acting, lighting, music, and set design. The focus is on audience participation, with helpers using signs like \"It's behind you!\" and \"Oh, no you're not!\" to prompt students. The aim is to get students involved in the performance and bring it to life.","content_type":"activity","name":"Cinderella Pantomime","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Signs with phrases (It's behind you!, Oh, no you're not!, etc.)","Costumes/Props"],"topic_tags":["Drama","Storytelling","Performance"]},
  {"id":"scraped-altcir-handbook-pantomime-performance-426","text":"Organize and perform a short pantomime with students, incorporating key English sentences from textbooks. Start by selecting a simple story and creating a script using familiar vocabulary and sentence structures. Design costumes and sets, utilizing readily available materials like old clothes and cardboard. Rehearse the pantomime with students, focusing on pronunciation, intonation, and basic acting skills. The activity targets speaking skills through memorization and performance, as well as listening skills to follow directions. This activity is best suited for grades 5-7. Materials needed include costumes, set pieces (cardboard, paint), and basic props. Classroom tips: Encourage creativity in costume and set design. Focus on student participation and enjoyment over perfection. Consider involving other teachers or ALT's to help with planning, set construction, or performance. This activity can be adapted by selecting a story appropriate for different grades and language levels. For younger students, focus on simple actions and repetitive phrases. Older students can handle more complex plots and dialogue. Consider performing the pantomime for other classes or even parents.","content_type":"activity","name":"Pantomime Performance","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Groups","materials":["Costumes","Set pieces","Props"],"topic_tags":["Performance","Speaking","Drama"]},
  {"id":"scraped-altcir-handbook-skits-competition-427","text":"This activity involves a school-wide English skit competition. Teams of three students are formed to write, practice, and perform a short skit in English. The skits are recorded on video along with a written script and submitted to the Prefectural Board of Education (BOE). The BOE judges select the top teams from both Junior High School (JHS) and Senior High School (SHS) for a final contest in the summer. The final contest involves live performances and awards are given to the top three teams in both divisions. This activity targets speaking and writing skills. The activity encourages collaborative work and allows students to practice using English in a creative and engaging way. Before the skit competition, teachers should review the criteria and provide practice materials to help students understand the scoring rubric, and they can offer feedback to ensure the skits are appropriate for the competition. Furthermore, the teacher can provide vocabulary related to the skit to help the students.","content_type":"activity","name":"Skits Competition","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":3,"interaction":"Groups","materials":["Video recording equipment (e.g., smartphone)","Script writing materials (paper, pens/pencils, or computers)"],"topic_tags":["Speaking","Writing","Performance","Collaboration","Competition"]},
  {"id":"scraped-altcir-handbook-skit-contest-428","text":"This activity involves students writing and performing English skits. The ALT and JTE collaborate to initiate enthusiasm, help students with script development, and provide guidance throughout the process. \n\n**Process:**\n1.  **Recruitment:** The ALT and JTE generate interest by making posters, talking to teachers and students, and performing a sample skit.\n2.  **Script Writing:** Students create original scripts, focusing on grammar, wording and organization. Multiple drafts may be necessary. The ALT and JTE should check the scripts against evaluation criteria.\n3.  **Selection:** Select the representative skit. This can be done through class script writing and auditions, or by having groups write and perform their own skits, and competing.\n4.  **Rehearsals:** The ALT and JTE work closely with selected performers, providing feedback on expressiveness, intonation, body language, and ensuring the skit meets guidelines.\n\n**Targeted Skills:** Speaking, Writing, Listening\n**Suitable Grades:** 5-9\n**Materials:** Paper, pens/pencils, (optional) costumes and props\n**Classroom Tips:** Encourage creativity and focus on student expression and meaning. The use of costumes and props is optional, but should not overshadow the importance of the spoken word and body language.","content_type":"activity","name":"Skit Contest","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":9,"complexity_max":3,"interaction":"Groups","materials":["Paper","Pens/Pencils"],"topic_tags":["Speaking","Writing","Performance"]},
  {"id":"scraped-altcir-handbook-cultural-festival-food-demo-429","text":"This activity involves preparing a foreign dish for a school cultural festival to demonstrate cultural exchange. The class chooses a simple, palatable dish (e.g., Shepherd's Pie) from the ALT's home country. Students practice preparing the dish a few times. During the festival, the class demonstrates the cooking process in English and Japanese to an audience. They explain ingredients and steps while cooking. Finally, they sell portions of the prepared food. This targets speaking and listening skills as students describe the recipe and answer questions from the audience, as well as cultural awareness. Requires a kitchen area or access to cooking facilities, ingredients for the chosen dish, and cooking utensils. The teacher can assist students with more difficult cooking steps and guide their explanations. Encourage students to research the dish's origin and significance.","content_type":"activity","name":"Cultural Festival Food Demo","activity_type":"Production","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":2,"interaction":"Whole class","materials":["Ingredients for chosen dish","Cooking utensils","Cooking area"],"topic_tags":["Culture","Food","Speaking"]},
  {"id":"scraped-altcir-handbook-cooking-show-430","text":"This activity involves students preparing a dish (pie in this example) in a cooking show format. First, the teacher prepares a simplified recipe and vocabulary sheet. The first session involves the teacher demonstrating the cooking process while explaining in English, incorporating some cultural context. In the second session, students assist, with the teacher directing them in English. The third session has students independently preparing the dish, communicating in English as much as possible. For a school festival, designate student speakers and practice their lines. Set up a cooking area and seating for the audience. On the day, students cook a batch to sell and demonstrate the process. The audience receives recipes (English/Japanese), tastes the food, and can purchase it. This activity targets speaking, listening, and reading skills, along with practical application of vocabulary. Classroom tips include designating roles to maximize participation and incorporating a clear structure for the cooking show to keep the activity flowing.","content_type":"activity","name":"Cooking Show","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":7,"max_grade_numeric":9,"complexity_max":3,"interaction":"Groups","materials":["Recipe (English & Japanese)","Ingredients","Cooking equipment","Vocabulary sheet"],"topic_tags":["Cooking","Culture","Speaking"]},
  {"id":"scraped-altcir-handbook-countries-and-activities-431","text":"This activity aims to introduce students to different countries through engaging cultural experiences. \n\n**Australia:** Students engage in a craft activity, painting in the style of Aboriginal art on bamboo-shaped cards. Toothpicks and disposable chopsticks are used as brushes to enhance the authenticity.\n\n**America:** Students learn about Judaism in America and participate in a short lesson followed by a traditional Barmitzvah dance.\n\nThis activity targets listening comprehension during explanations and cultural presentations, speaking skills for participating in the discussions and dance, and potentially creative expression during the art activity. This is suitable for elementary school students and may require modification for older students. \n\n**Materials:** Bamboo-shaped cards (or similar), paint, toothpicks, disposable chopsticks, music for dancing.\n\n**Classroom Tips:** Adapt the craft activity based on available materials. Keep the religious aspects of the activity sensitive and age-appropriate. Ensure the dance lesson is broken down into easily manageable steps for the students to follow.","content_type":"activity","name":"Countries and Activities","activity_type":"Main Game","skill":"Speaking","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["Bamboo-shaped cards","Paint","Toothpicks","Disposable chopsticks","Music for dancing"],"topic_tags":["Culture","Craft","Dance","Countries"]},
  {"id":"scraped-altcir-handbook-culture-showcase-432","text":"This activity introduces students to different cultures through sports, food, games, language, and dance. The teacher presents short introductions to the selected cultures, which could include New Zealand (rugby and the Haka), Thailand (Thai cooking and spices), the UK (playground games and rhymes), and Jamaica (Creole language and dance). Students can participate in brief demonstrations of the sports or games, or taste samples if possible. The activity targets listening comprehension and builds vocabulary related to different cultures. Encourage student participation by having them attempt a few phrases in a new language or copy a short dance move. Suitable for grades 5-7. Materials needed: examples of sports equipment (ball, jump rope), small samples of spices (Thai), audio or video of dances or language snippets. Classroom tips: Keep introductions brief. Actively encourage students to try new things and participate. Use clear pronunciation when introducing language elements. The competitive element helps maintain student engagement.","content_type":"activity","name":"Culture Showcase","activity_type":"Main Game","skill":"Mixed","duration_minutes":15,"min_grade_numeric":5,"max_grade_numeric":7,"complexity_max":2,"interaction":"Whole class","materials":["sports equipment (ball, jump rope)","spice samples","audio/video of dances/language"],"topic_tags":["culture","sports","language","dance"]}
];
